window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26865749"]={"book":{"id":26865749,"title":"所谓情商高，就是会说话","author":"佐佐木圭一","translator":"程亮","publisher":"北京联合出版公司","pubdate":"2016-9-16","isbn":"9787550286092","tags":["情商","沟通","社交","口才","所谓情商高","就是会说话","说话","我想读这本书","好书","值得一读"],"memCount":27},"np":1,"pb":[56],"idx":[{"i":18400,"t":"投其所好措辞技巧","l":"TF3-1","c":"林文杰","g":1,"p":1},{"i":15654,"t":"如何提出让人欣然接受的请求 ","l":"TF2-3","c":"Sunny-黄丽","g":1,"p":1},{"i":15505,"t":"降低被人拒绝的概率，只需3招","l":"TF1-1","c":"丁大鹏","g":1,"p":1},{"i":15104,"t":"用“措辞菜谱”训练说话水平，把NO变成YES","l":"TF2-4","c":"心连心","g":1,"p":1},{"i":14030,"t":"利用被认可欲获得帮助","l":"TF2-3","c":"Wendy温蒂","g":1,"p":1},{"i":13904,"t":"把NO变成Yes的说话情商","l":"TF2-2","c":"Wendy温蒂","g":1,"p":1},{"i":13517,"t":"所谓情商高就是会说话","l":"TF2-2","c":"陈宇星","g":1,"p":1},{"i":12692,"t":"用“措辞菜谱”打好沟通基础","l":"TF1-1","c":"紫雨飘扬","g":1,"p":1},{"i":11705,"t":"“措辞菜谱”","l":"TF2-1","c":"六弦","g":1,"p":1},{"i":11462,"t":"掌握语言的措辞","l":"TF2-2","c":"陈宇星","g":1,"p":1},{"i":11375,"t":"把“NO”的回答变成“YES”的三个步骤","l":"TF1-1","c":"以晴","g":1,"p":1},{"i":11374,"t":"把“NO”的回答变成“YES”的三个步骤","l":"TF1-1","c":"以晴","g":1,"p":1},{"i":11053,"t":"利用被认可欲来获得帮助","l":"TF2-3","c":"iriszou","g":1,"p":1},{"i":10827,"t":"把“No”变成“Yes”的三个步骤","l":"TF1-2","c":"陈羽西","g":1,"p":1},{"i":10252,"t":"把“No”变“Yes”的三步法","l":"TF1-2","c":"echo-cj","g":1,"p":1},{"i":9352,"t":"把NO变成YES的说话神器。","l":"TF2-3","c":"许曼","g":1,"p":1},{"i":9328,"t":"把“NO”变成“YES”的说话技巧","l":"TF2-1","c":"Yoyo Zhang","g":1,"p":1},{"i":9126,"t":"把“NO”的回答变成“YES”的三个步骤","l":"TF1-1","c":"阅良","g":1,"p":1},{"i":8942,"t":"用投其所好的措辞技巧达成双赢","l":"TF3-1","c":"littledl2019","g":1,"p":1},{"i":8935,"t":"让别人对你Say YES的说话神器","l":"TF2-4","c":"许曼","g":1,"p":1},{"i":8815,"t":"把NO变成YES的说话神器","l":"TF2-3","c":"许曼","g":1,"p":1},{"i":8782,"t":"把“No”的回答变成“Yes”的3个步骤","l":"TF1-2","c":"01","g":1,"p":1},{"i":8719,"t":"措辞技巧","l":"TF1-2","c":"April房","g":1,"p":1},{"i":8651,"t":"朱晓丹：投其所好，达成双赢","l":"TF3-1","c":"littledl2019","g":0,"p":1},{"i":8574,"t":"变成Yes的三步法","l":"TF1-1","c":"戒森哥","g":1,"p":1},{"i":8339,"t":"投其所好，达成双赢","l":"TF3-1","c":"littledl2019","g":0,"p":1},{"i":8311,"t":"人际之间","l":"TF2-1","c":"憨商猎人","g":1,"p":1},{"i":8190,"t":"把“No”的回答变成“Yes”","l":"TF1-2","c":"李竹兰","g":1,"p":1},{"i":8156,"t":"No变YES的技巧","l":"TF1-1","c":"小面包","g":1,"p":1},{"i":7511,"t":"用反差法制造感动","l":"TF2-1","c":"littledl2019","g":0,"p":1},{"i":7343,"t":"如何让对方的回答从No变为Yes","l":"TF1-1","c":"张梦婷","g":1,"p":1},{"i":7016,"t":"如何让对方答应我们的请求","l":"TF1-2","c":"派派","g":1,"p":1},{"i":6628,"t":"向别人提请求","l":"TF1-1","c":"陈成","g":1,"p":1},{"i":6563,"t":"换位思考1","l":"TF1-1","c":"小马哥SH","g":1,"p":1},{"i":6524,"t":"完美掌握，把No变成Yes的技巧！","l":"TF1-1","c":"张松","g":1,"p":1},{"i":6326,"t":"在表达想法的同事更好的将对话利益最大化","l":"TF1-2","c":"胡英","g":1,"p":1},{"i":6260,"t":"把“No”的回答变成“Yes的三个步骤","l":"TF1-1","c":"黄小鸭","g":1,"p":1},{"i":5886,"t":"把“NO”变成“YES”的技巧","l":"TF1-2","c":"杨欢","g":1,"p":1},{"i":5125,"t":"允许自己请求的沟通技巧","l":"TF1-1","c":"gaogao高高","g":1,"p":1},{"i":4834,"t":"投其所好，轻松让No变Yes","l":"TF2-2","c":"唐波","g":1,"p":1},{"i":4667,"t":"完美掌握，把“No”变成\"Yes\"","l":"TF1-2","c":"瞌睡的猫","g":1,"p":1},{"i":4617,"t":"提出请求的技巧","l":"TF1-2","c":"孙颖","g":1,"p":1},{"i":4501,"t":"一起学说话","l":"TF2-2","c":"豆豆0701","g":1,"p":1},{"i":4145,"t":"教你轻松让对方说 yes","l":"TF3-1","c":"xgm","g":1,"p":1},{"i":3941,"t":"把“No”的回答变成“Yes”的技巧（2过）","l":"TF1-2","c":"张诗悦","g":1,"p":1},{"i":3812,"t":"如何更有效说服别人","l":"TF2-3","c":"茶舍小语","g":1,"p":1},{"i":3689,"t":"透过表达看思维哟","l":"TF3-1","c":"羽美人","g":1,"p":1},{"i":3620,"t":" 学习 把“No”变成“Yes”的技巧   ","l":"TF1-2","c":"张诗悦","g":1,"p":1},{"i":3503,"t":"学习在沟通的时候让对方的回答从NO变成YES的方法","l":"TF1-2","c":"宋福珍（豆豆）","g":1,"p":1},{"i":3250,"t":"最短的时间掌握说话技巧，把“NO”变成“YES”","l":"TF1-2","c":"小煜","g":1,"p":1},{"i":3242,"t":"把“No”变成“Yes”的技巧之“非你不可”","l":"TF1-1","c":"追逐1","g":1,"p":1},{"i":3189,"t":"把NO变成YES的技巧","l":"TF3-2","c":"吴迪","g":1,"p":1},{"i":2846,"t":"如何将对方“NO\"的回答变成”YES“的回答","l":"TF1-1","c":"茶舍小语","g":1,"p":1},{"i":2475,"t":"3步骤，让对方的回答从“NO”变成“YES”","l":"TF2-1","c":"燕丽娜","g":0,"p":1},{"i":1808,"t":"好好说话","l":"TF2-3","c":"植聪","g":1,"p":1},{"i":1477,"t":"把“No”的回答变为“Yes”","l":"TF3-2","c":"陈庆","g":1,"p":1}],"ms":[{"id":18400,"topic":"投其所好措辞技巧","learn_goal":"","remark":"3-1过级","level":"TF3-1","duration":25,"status":30,"type":0,"chaishujia":{"username":"林文杰","city":"福州市"},"club":{"name":"福州闽江分舵","city":"福州"},"prologue":"\u003cp>【开场】1分钟\u003c/p>\u003cp>各位伙伴，大家晚上好，我是杰弗里，欢迎来到拆书现场，三个标签做个自我介绍，\u003c/p>\u003cp>第一，二级拆书家，2023年花了4个月左右每周一拆过的；\u003c/p>\u003cp>第二，图书爱好者，平常比较喜欢看增长智慧类书籍，所谓人和人不同就是脖子以上脑袋的区 别，所以要加智慧；\u003c/p>\u003cp>第三，拆书小强，不怕过级失败，敢重新再来的拆书小强\u003c/p>\u003cp>【分组】技能点\u003c/p>\u003cp>本次我要进行3-1的过级拆，时长15-30分钟之间。因为是线上拆书，所有小伙伴为一组。\u003c/p>\u003cp>【学习目标】（技能点-观察项目）\u003c/p>\u003cp>本次学习的目标是：学习者面对需要拜托别人做事的场景时，可以运用（澄清）投其所好的措辞技巧，以一种对方容易接受且符合其利益的方式表达自己的想法，达到让对方愿意接受（界定）自己的请求。\u003c/p>\u003cp>【学习者场景法图书介绍】（技能点-观察项目）2分钟\u003c/p>\u003cp>【场景】\u003c/p>\u003cp>我们公司是大小周上班制，上周是双休，巧的是周六有菊花展，公司在菊花展有个活动，我们部门负责活动，需要活跃氛围，但人手不够得找其他部门帮忙，可这不是强制任务，不能让行政发通知要求大家来，这可把我们愁坏了。\u003c/p>\u003cp>【提问】\u003c/p>\u003cp>各位，如果换作是你，你会如何与其他部门进行沟通，以促使他们愿意支持我们的活动？回想一下，我们之前是否有遇到过需要拜托别人做事的情况？你是否还记得当时我们采取了哪些沟通策略，以及这些策略的效果如何？\u003c/p>\u003cp>【影响】\u003c/p>\u003cp>这类型的沟通在我们生活或工作中非常常见，如处理不当的话可能产生矛盾、信任受损，协作积极性受挫，影响凝聚力等负面影响。\u003c/p>\u003cp>【解决】\u003c/p>\u003cp>《所谓情商高就是会说话》这本书中提到7种措辞沟通方法，可以帮我们解决类似的问题，甚至比你想象的更好。尤其是第一种“投其所好措辞”沟通技巧。\u003c/p>\u003cp>（过渡句）下面请读来自书本第16-17页原文片段，读完的小伙伴给我回复1。\u003c/p>","ratings_count":2,"texts":[{"id":22693,"quote":"\u003cp>【R原文片段】摘自《情所谓情商高就是会说话》1分钟\u003c/p>\u003cp> P16-17\u003c/p>\u003cp>电影《快乐飞行》里曾出现令人不禁点头赞许的巧妙揩辞。在该影片中，绫濑遥饰演某航空公司的新人空姐。在分配供餐的一幕，由于乘客大多优先选择牛肉，所以导致鱼大量剩余。\u003c/p>\u003cp>就在新人空姐面临重大危机的关头，经验丰富的前辈说道:“像平时一样平均分配！看好了。”然后展现了高超的措辞技巧：\u003c/p>\u003cp>“机内供应以优质香草、富含矿物质的天然岩盐和粗制黑胡椒嫩煎而成的白身鱼，以及普通牛肉。”\u003c/p>\u003cp>由于是电影，其中自然存在表演成分，但前辈空姐这样一说，乘客确实会觉得鱼更好吃。后来，当前辈空姐询问乘客的选择时，绝大多数乘客都主动选择了鱼。这里就使用了“\u003cstrong>投其所好\u003c/strong>”的“措辞菜谱”：\u003c/p>\u003cp>“对不起，只剩鱼了。”\u003c/p>\u003cp>如果空姐这样说，乘客就会觉得自己简直成了废品回收站，哪里还有吃东西的心情，而像前辈那样说，乘客就会心甘情愿地主动选择鱼。这就是措辞的力量。\u003c/p>","explains":"\u003cp>【I拆书家讲解】\u003c/p>\u003cp>拆书家：大家都已经读完了吗？这个片段讲的是？技巧\u003c/p>\u003cp>学习者：投其所好的措辞技巧\u003c/p>\u003cp>拆书家：那什么是“投其所好的措辞技巧呢？\u003c/p>\u003cp>书中对“投其所好措辞技巧”的定义为：\u003cu>不直接说出\u003c/u>自己内心的想法，而\u003cu>以对方\u003c/u>的爱好、需求、关注点等为先，通过将对方的喜好与自己的想法\u003cu>相结合\u003c/u>的方式来表达，这样既能获得对方的好感，又能实现自己的愿望。\u003c/p>\u003cp>过度句：这么讲是不是还不能很好理解，那就来几个案例一起分析一下吧\u003c/p>\u003cp>【概念与案例相互参照】\u003c/p>\u003cp>案例一、小李的亲戚从老家寄来很多柑橘，家人都吃腻了，小李不想让剩下的柑橘白白烂掉。他打算这么和家人说：“大家继续吃啊，不然柑橘放久就坏了”\u003c/p>\u003cp>请问小李这个想法算投其所好的措辞技巧吗？。\u003c/p>\u003cp>学习者：不是（引导，是的打1，不是打2）\u003c/p>\u003cp>拆书家：是的，这个不算，小李只是把脑中想法直接说出来了，属于直白表达内心想法的沟通技巧。\u003c/p>\u003cp>案例二、小张是卖鞋的营业员，近期店铺换季做活动，鞋子优惠力度比较大，小张觉得所有的客户不买买鞋子都是因为价格太高，所以做活动的话所有进来的人都会买，小张就打算对所有的客人都去说：“店铺鞋子做活动，年度最低价，可以多带几双回家”\u003c/p>\u003cp>请问：小张这个想法是投其所好的措辞技巧吗？\u003c/p>\u003cp>拆书家：是的，这个也不是，他没有找到对方需求，只站在自己角度去思考，可能部分客户会买单，但这个操作不是投其所好措辞技巧\u003c/p>\u003cp>案例三、小红要出差一周，他家里养的小猫想拜托邻居小王帮忙照顾一下，他知道邻居也比较喜欢小动物，家里也养了一只，他就想这么和邻居说：“小王，你这么喜欢小动物，这么有爱心，我要出差一周我家的小猫宠物你一起带一下吧，反正一只是带，两只也是带，在家闲着也是闲着，多带一下也不会掉层皮，你说对吧”\u003c/p>\u003cp>问：小红这个沟通的想法算不算投其所好措辞技巧\u003c/p>\u003cp>学习者：不是\u003c/p>\u003cp>拆书家：是的，也不算，小红虽然有结合了双方的需求，但计划的表达没有用符合对方利益的措辞话术表达，有点不顾对方感受，不尊重对方的味道。\u003c/p>\u003cp>案例四、我们来看看原文案例，经验丰富的空姐在面对剩下一堆白身鱼套餐的时候，她的想法和需求是“让客户多选择白身鱼套餐”，但她没有直接说：“对不起，只剩下鱼了”而是思考了一下客户选餐的时候，一般会选营养价值高，更新鲜，更高档的食物，最后弄了一个沟通的话术为：“机内供应以优质香草、富含矿物质的天然岩盐和粗制黑胡椒嫩煎而成的白身鱼，以及普通牛肉。”\u003c/p>\u003cp>这个经验丰富的空姐是否用了投其所好的沟通方式\u003c/p>\u003cp>学习者：是的\u003c/p>\u003cp>HOW\u003c/p>\u003cp>拆书家：所以根据前面的几个案例我们可以得出“投其所好措辞技巧”比较重要的三个步骤\u003c/p>\u003cp>1. 找到自己需求，但不直白说出来。\u003c/p>\u003cp>2. 找到对方需求，对方会因为什么而答应你的请求。\u003c/p>\u003cp>3. 结合前面两步，构思出符合对方利益的措辞话术。\u003c/p>\u003cp>Where：\u003c/p>\u003cp>这种“投其所好”措辞沟通技巧适用于工作、生活、社交等需要拜托别人做事的场景，沟通之前可以用三个步骤做好构思，如果我们表达请求的时候对方说“NO”的概率比较大用这个技巧可以大大提升对方变“NO”为“YES”，如果我们表达请求的时候对方说“YES”的概率比较大，那用这个技巧能起到锦上添花的效果，让对方说“YES”更加的坚定。\u003c/p>\u003cp>个人A1分享\u003c/p>\u003cp>回到刚开始的场景案例给大家分享一下\u003c/p>\u003cp>双休时间需要其他部门来协助自己，如何用“投其所好”措辞技巧呢\u003c/p>\u003cp>一、找到自己需求，但不直白说出来。——内心需求是大家都过来打卡加班，帮忙搞起活动氛围。\u003c/p>\u003cp>二、找到对方需求，对方会因为什么而答应你的请求。——1.如果有3倍工资可能会答应，2.如果是团建过来玩可能会答应，3.如 \u003cbr> 果是比较轻松的活动可能会答应，4.如果没3倍工资，但有加班时长可以抵扣后面的急事请假可能会答应，5.如果有人请吃大 \u003cbr> 餐可能会答应。6.如果能得到领导认可给月底绩效加分可能会答应\u003c/p>\u003cp>三、结合对方需求和自己需求，然后构思出符合对方利益的措辞话术。——对方的需求中，第3、第4和第6和自己需求最匹配， \u003cbr> 构思出符合对方利益的措辞话术为：“各位，本周六公司有弄了一个活动，在这也隆重邀请大家一起参与，活动比较轻松不用 \u003cbr> 在办公室，现场配合玩下游戏活跃下氛围即可，大家过来的话可以打下卡，可以增加一些请假抵扣的时长，后面碰到急事要 \u003cbr> 请假可以直接抵扣不用扣钱，这场活动领导也比较重视，到时候会和大家一起参加的”。\u003c/p>\u003cp>那看了这么多案例，也了解了“投其所好”措辞技巧如何操作，我们上手来操作一下吧\u003c/p>","interaction":"\u003cp>A2 催化学习者应用 【技能点：教学习者编剧本】5-10分钟\u003c/p>\u003cp>为了大家更好的吸收和运用，接下来邀请学习者来编一小段故事。\u003c/p>\u003cp>1. 大家想一个未来可能会遇到需要求人做事的场景\u003c/p>\u003cp>2. 这个场景要有时间，人物……框中的几个元素\u003c/p>\u003cp>3. 故事需要使用“投其所好”措辞技巧三步骤来构思话术解决问题（第一步和第二步为思考， 第三步为弄出话术，不用把问候寒暄等内容加入其中，思考部分可以用旁白方式说出）。\u003c/p>\u003cp>4. 给大家5分钟的时间，5分钟后我会请1-2两位伙伴演绎你们的故事。\u003c/p>\u003cp> 【学习者剧本记录】 时间关系，我们先到这里，我看大多数小伙伴都差不多已经完成了故事的编写。那我请******来给我们做分享吧。 \u003c/p>\u003cp>学习者子落分享： \u003c/p>\u003cp>时间是在下周一，地点在公司领导办公室，事情就是我公司总经理要求制定一个关于完善付款手续的一个考核办法。\u003c/p>\u003cp>我的需求就是需要让分管领导帮助我召开考核办法研讨会，把相关部门召集在一起，让大家共同讨论，共同决议，这样的话我的考核办法的实施就阻力会比较小。\u003c/p>\u003cp>领导的需求关注点，就是省事简单，不要给他找过多麻烦，同时这个工作推行的话也有利于公司的管理。\u003c/p>\u003cp>把我的关注点和领导这个关注点合在一起，然后用一个领导听着比较舒服的语言：“领导向您汇报一下，目前我们这个考核办法基本是研究出来了，但是考虑到大家肯定都有抗拒心理，为了便于推进公司的这个管理让这个付款手续正常的推进，也为了让公司总经理更加信任我们这个口的工作，就想请您！这周帮抽一个时间。帮我召开一个考核办法的研讨会，大家共同研讨这个考核办法，让考核办法更好的一个实施，领导您有没有时间，如果有了时间的话，我们可以进一步讨论一下细节。\u003c/p>\u003cp> 技能点：【反馈】 1分钟\u003c/p>\u003cp>非常感谢子落老师的故事演绎，刚才的案例非常的生动形象，特别是对“投其所好”措辞技巧的运用部分，成功的把“NO”变成了“YES”。相信通过我们不断地训练和运用我们的技能能够越来越熟，更上一层楼。\u003c/p>\u003cp>技能点：【强有力的结语】1分钟\u003c/p>\u003cp>我今天的拆书活动到这里就结束了，做个总结，今天和大家分享的是“投其所好措辞”技巧，一共3个步骤，（1、找到自己需求，但不直白说出来。2、找到对方需求，思考对方会因为什么而答应你的请求。3、结合前面两步，构思出符合对方利益的措辞话术）谢谢大家的聆听和参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1732801372000,"updated_at":1732803320000,"ria":true},{"id":15654,"topic":"如何提出让人欣然接受的请求 ","learn_goal":"","remark":"如果我们提出请求总是遭受拒绝，那么，今天的拆书片段可以教会我们，如何提出请求，并让对方欣然配合。 ","level":"TF2-3","duration":35,"status":30,"type":0,"chaishujia":{"username":"Sunny-黄丽","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>\u003cem>自我介绍\u003c/em>\u003c/p>\u003cp>Hello，大家好，我是Sunny。曾经是一名7年教学经验的英语老师，目前是一位两岁孩子的妈妈。\u003c/p>\u003cp>今天我要过的级别是2-3。\u003c/p>\u003cp>\u003cem>用FAB法介绍图书，，并清晰分辨出F、A、B\u003c/em>\u003c/p>\u003cp>Feature(特征，是什么):\u003c/p>\u003cp>今天我要拆解的这本书叫做《所谓情商高就是会说话》作者是来自日本的沟通专家佐佐木圭一。\u003c/p>\u003cp>本书作者认为就像烹饪有食谱一样，说话也有它的&quot;秘方&quot;的。\u003c/p>\u003cp>作者通过自己多年来掌握的语言措辞技巧告诉大家该如何修炼说话能力，如何提高自己的说话水平。\u003c/p>\u003cp>Advantage（优势，是干什么）:。\u003c/p>\u003cp>与市面上其他沟通类书籍相比较，本书通过图文结合以及大量案例故事的方式把看似简单的道理掰开揉碎讲给读者听，让人快速掌握书中讲解的技巧。\u003c/p>\u003cp>同时，非常有特色的一点是，这本书每个章节后面都有一个技巧复习和检测，让读者可以牢牢地记住每个知识点。\u003c/p>\u003cp>Benefit（利益，好处是什么）:\u003c/p>\u003cp>B1: \u003c/p>\u003cp>你有没有试过，在表达自己的想法时，不仅达不到自己想要的结果，还惹得对方一脸不高兴？\u003c/p>\u003cp>不知道在座的有没有跟我一样，很喜欢表达，却又害怕自己说话不讨喜的小伙伴。\u003c/p>\u003cp>那么，我想这本书应该就可以帮助我们了，这本书介绍的沟通技巧和方法，只需要我们在平时说话时做出一点点地调整就可以收获到完全不一样地效果。\u003c/p>\u003cp>B2： 比如我今天即将要讲解地这个拆页，在向对方提出建议或者请求时只需要稍微地思考一下对方的需求，得到yes回复的概率就会大大提高哦！\u003c/p>\u003cp> \u003cem>学习目标包含学习者可被观察到/可测量的行为或动作\u003c/em>\u003c/p>\u003cp>今天的学习目标是，在跟随我完成本次现场的RIA学习后，大家以后在向他人提出建议和请求时，可以使用今天学习到的\u003cstrong>提出建议和请求的三步法\u003c/strong>，从而让对方不会对我们的请求产生厌烦，抵抗情绪。\u003c/p>","ratings_count":1,"texts":[{"id":19717,"quote":"\u003cp>\u003cem>阅读原文片段引导：\u003c/em>\u003c/p>\u003cp>好的，现在请小伙伴们花两分钟时间阅读一下刚刚发下去的原文片段，阅读完毕请在聊天区扣“1”\u003c/p>\u003cp>\u003cem>原文片段： 所选拆页包含how的内容,且内容不超过2页图书\u003c/em>\u003c/p>\u003cp>某公司做的是向汽车厂商提供导航系统的生意，也就是所谓的外包公司，但厂商的条件非常苛刻，去年把价格压低了3%，今年更要求降价5%。尽管降价会导致该公司的纯利润减少，但社长不得不接受，所以很是犯愁。最后，社长觉得必须做些改变才行，就向厂商提出了一个关于高价商品的方案：\u003c/p>\u003cp>“让我们制作高价的高规格型号吧。”\u003c/p>\u003cp>厂商对此的回答是“No”。社长大伤脑筋。今年春天，当他正想再次提案时，突然想起并使用了\u003cstrong>“措辞菜谱”\u003c/strong>。这次\u003cstrong>他并没有直接说出自己的请求\u003c/strong>，而是在仔细\u003cstrong>研究了厂商的经营状况后\u003c/strong>，使用了下面的措辞：\u003c/p>\u003cp>“让我们制作贵公司的旗舰型号吧。”\u003c/p>\u003cp>说出口的一瞬间，社长感到无比紧张。厂商的部长则一拍大腿：“好，早就在等你提出这个方案呢！！ ”\u003c/p>\u003cp>于是双方很快签了合同。\u003c/p>\u003cp>原来，厂商虽然有好几种导航系统，但缺少代表性的旗舰型号。正因为社长充分\u003cstrong>揣摩了对方的心理\u003c/strong>，才\u003cstrong>找到了这个“投其所好”的突破口\u003c/strong>。\u003c/p>\u003cp>至于商品本身，其实与此前的提案一样，就是高价的高规格型号\u003cstrong>。在充分揣摩对方心理的基础上所做出的提案，不仅事关高价商品，更关系到企业经营，所以能打动对方。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cem>给出了比原书拆页更加细化的行动步骤，或者将书中的案例进行了意译\u003c/em>。\u003c/p>\u003cp>好的，看到大部分小伙伴已经阅读完毕了，没有阅读完的也没关系，在这边我也会跟大家来分享一下我对于这个拆页的理解。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>在我们提出请求之前，如果可以充分揣摩对方心理，更容易打动对方，让对方配合我们的请求或者建议。\u003c/p>\u003cp>举个大家熟悉的例子，刚下班回到家，你葛优躺着刷手机，另外一半对你说、说：“你赶紧去冲凉吧！”\u003c/p>\u003cp>为你去冲凉的欲望打分，总分10分，你会打几分呢？（互动）\u003c/p>\u003cp>\u003cem>学习者COCO:0\u003c/em>\u003c/p>\u003cp>那如果另外一半对你说 “亲爱的，你上次说想看的电影我已经下载好了，你先个舒服的澡，一会儿跟我们躺着一起看，你觉得怎么样？！”\u003c/p>\u003cp>如果这样，总分10分，你会为去冲凉的欲望打几分呢？（互动）\u003c/p>\u003cp>\u003cem>学习者COCO:9\u003c/em>\u003c/p>\u003cp>大家发现没有，就是同样一个意思，只要稍微改变一下我们表达方式就会是让结果发生完全不同的一个改变，对吧！\u003c/p>\u003cp>那么，我们具体应该如何来做才会让对方欣然接受我们的建议和请求呢？我们来看看今天要学习的这个“表达请求和建议的三步法”的具体操作步骤。\u003c/p>\u003cp>\u003cem>【How】细化的行动步骤\u003c/em>\u003c/p>\u003cp>第一步：闭嘴巴，当我们对某人有一个建议或者请求时，先不要直接说，紧紧地把嘴部闭上。\u003c/p>\u003cp>第二步：挖需求：仔细想想这样一个建议，对方答应请求、建议的益处是什么？不答应的阻力是什么？对方喜欢的是什么？期待什么？需要什么？\u003c/p>\u003cp>第三步：整合措辞：把自己的请求或建议跟对方的需求进行整合后进行表达。\u003c/p>\u003cp>【A1案例】\u003c/p>\u003cp>为了帮助大家更好地理解这个方法，我这边也跟大家来分享一个我自己的案例。\u003c/p>\u003cp>我之前在一个小区租了个房子来进行教学，当时是签了两年合同。\u003c/p>\u003cp>但是由于我这个教学点要提前撤掉了，所以就需要找房东沟通是否能够提前退租。\u003c/p>\u003cp>我当时打电话跟房东说：“房东，您好！你这房子我们不用了，能不能提前退租？”\u003c/p>\u003cp>对方冷冷地回复了我一句：“一切按合同办！”\u003c/p>\u003cp>那按照合同每到租期是不给退押金的，所以当时我感到挺烦恼的，不知道到底该怎么办才好。\u003c/p>\u003cp>后来我看了这个片段的方法，茅舍顿开，最后用这个方法也成功地让房东答应了我的请求。\u003c/p>\u003cp>那为了让大家跟我一起来练习一下这个方法，我想请大家来跟我一起来练习一遍，那具体当时我怎么说动房东的一会再跟大家继续分享。\u003c/p>\u003cp>好，如果当时按照这个方法\u003c/p>\u003cp>我第一步应该做什么？\u003c/p>\u003cp>学习者：闭嘴吧\u003c/p>\u003cp>第二步呢？大家跟我一起想想看，提前退租这件事对房东可能会有什么益处呢？\u003c/p>\u003cp>学习者：找不到下一个租客\u003c/p>\u003cp>第三步，怎么来说呢？\u003c/p>\u003cp>学习者：我帮你找下一个租客，可以提前退租吗？\u003c/p>\u003cp>好的，感谢各位小伙伴出谋划策哈。\u003c/p>\u003cp>其实当时我是这样的，\u003c/p>\u003cp>第一步，闭嘴巴：我就没再一直请求她让我提前退租。\u003c/p>\u003cp>第二步，挖需求：当时那套房子所在小区房价升了不少，所以房租也涨了，提前退租，把房子租给另外一个人，房东的收益反而增加的。\u003c/p>\u003cp>阻力是，房东可能不太愿意费神重新找租客。\u003c/p>\u003cp>第三步，整合措辞：经过上面的思考，我当时是这么说的：“房东，最近房租涨价了，刚好我又需要不用这个房子，我可以跟你一起找新的房客的话，是否可以提前给我退租呢？”\u003c/p>\u003cp>房东立马就同意了我的请求。\u003c/p>\u003cp>【WHY】【不这样做的坏处】\u003c/p>\u003cp>我们在给他人建议或者对他人提出请求时，尤其是面对我们最亲密的人的时候，往往会把自己的需要脱口而出，完全没有考虑到对方当下的状态，需求。\u003c/p>\u003cp>这样我们很可能会遭受拒绝或者对方即便答应了也不是那么乐意的状态。\u003c/p>\u003cp>长此以往，不利于良好稳定关系的维系。\u003c/p>\u003cp>【这样做的好处】\u003c/p>\u003cp>采用表达建议和请求的三步法不仅更容易达到我们自己的目的，让对让答应我们的建议或者请求。\u003c/p>\u003cp>长期地立足于对方需求出发的表达方式和思考方式，可以让关系更加融洽，让自己的说话走向更高的艺术水平。\u003c/p>\u003cp>\u003cem>【适用边界】\u003c/em>\u003c/p>\u003cp>这个方法基本适用于大部分场景，但是当我们的请求本身比较简单，只是一个小小的动作，可能就不需要这么复杂了。比如请助手帮我们印一份文件。\u003c/p>\u003cp>\u003cem>【预防异议】\u003c/em>\u003c/p>\u003cp>有些小伙伴可能会说，那如果挖需求时，没有把握准，一开始没法找到能打动对方的利益该怎么办呢？\u003c/p>\u003cp>跟小伙伴们一样，一开始我也有这样的疑问，但是当我自己多次尝试后发现，但凡我需要请求别人帮助我或者给人提建议时，只要同时提及对对方的利益，对方答应的概率都会高很多。\u003c/p>\u003cp>当然，如果我们沟通的对象是一个难以搞定的客户或者我们原本不熟悉的人，就需要我们更仔细调查和挖掘啦！\u003c/p>\u003cp>小伙伴们也不用担心会找不准利益，即便第一次不成功，通过刻意练习一定会越来越好的。\u003c/p>","interaction":"\u003cp>\u003cem>能够设计现藏演练案例，以促进学习者在安全的情景下第一次应用新学技能。\u003c/em>\u003c/p>\u003cp>今天我们学习了提出建议和请求的三步法，他们分别是，第一步，闭嘴巴；第二步：挖需求；第三步：整合表达。\u003c/p>\u003cp>为了帮助各位小伙伴更好地掌握这个方法，我们现在来进行一个好玩地角色扮演环节。请各位小伙伴用五分钟时间，在刚刚开始时地分组，在小组内进行角色扮演，今天的两位角色分别是小明和小红。\u003c/p>\u003cp>来，我们来看看具体场景是怎么样的。\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>小明是公司项目组的小组长，最近公司要搞年会了，公司规定每个项目小组要出两个人来策划开办公司年会，由于年底，大家工作比较忙，而且策划年会的确是个辛苦活儿，大家都不愿意去。\u003c/p>\u003cp>所以，这个时候小明就盯上了刚来公司不久的小红，想请求小红作为小组代表跟自己一起帮忙策划年会。\u003c/p>\u003cp>请各位小伙伴就以上场景，在自己小组内，一个扮演小明，一个扮演小红，进行一下角色扮演。要求是，小明要使用今天学习到的方法让小红答应自己去帮忙策划年会。\u003c/p>\u003cp>【预防】\u003c/p>\u003cp>提醒下大家的是，表达建议和请求的方法可能有很多，但是今天是为了训练今天学习到的表达建议和请求的三步法，。\u003c/p>\u003cp>所以请大家用这3个步奏来表达请求.讨论事件是五分钟，大家都清晰吗？有哪里不明白的可以提出来哈！\u003c/p>\u003cp>【搜集案例】\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>鸿/小明：小红，你刚来公司还习惯吗？公司的朋友都认识了吗\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>叶子/小红： 还可以\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>鸿/小明：公司的朋友都认识遍了没有呀？\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>叶子/小红：其实还有很多不认识的。只是见过几次面，没有打过交道\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>鸿/小明：嗯，你总是坐在自己办公室做自己的工作，没有机会跟他们交流就是会这样的了。你这样做几个月都还是不会有太大改进。有一个事情可以让你提高跟同事们的交流，甚至在老板面前表现一下，有这样的机会，要不要争取一下？\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>叶子/小红：我想尝试的，这样一个机会应该很多同事想要做吧！\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>鸿/小明：的确这个机会很多人想要，但是因为看到你是一个新员工，我觉得应该交给新员工，其实我的想法是要准备做一个年会。你要知道这个做年会过程中，你就可以跟同事有更多沟通交流，到时候还可以在老板面前表现一下。你想跟我一起搞这个年会吗》\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>叶子/小红：我觉得还是挺有挑战性的，我试一下吧！\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>拆书家反馈：\u003c/p>\u003cp>感谢两位小伙伴地角色扮演演练，两位在短时间分享的很棒。\u003c/p>\u003cp>结尾： \u003c/p>\u003cp>好，今天我的拆书到此为止就要告一段落啦！感谢各位小伙伴地积极参与，希望今天的拆页对大家有所帮助。 在大家未来生活工作中如果需要表达建议和请求可以用今天学到的三步法，坚持去做，一定会有意想不到的收获哟！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1682010477000,"updated_at":1682403200000,"ria":true},{"id":15505,"topic":"降低被人拒绝的概率，只需3招","learn_goal":"","remark":"过级活动","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"丁大鹏","city":""},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好！我是丁大鹏，大鹏展翅的大鹏。\u003c/p>\u003cp>我有三个标签\u003c/p>\u003cp>1、工地搬砖人：因为有7年的工地现场管理经验。\u003c/p>\u003cp>2、佛系单身Go：我曾用3个月时间，骑行近4000公里去西藏，这是Go；曾到都江堰般若寺，闭关修行过一段时间，这是佛系；至今还是单身，所以叫佛系单身Go。\u003c/p>\u003cp>3、打油诗小王子：我曾用写打油诗的方式，同时为4家头马演讲俱乐部做活动推广，因此得了这个绰号。\u003c/p>\u003cp>我能为大家带来的是，通过写打油诗的方式来娱乐大家，为此我也写了打油诗一首：\u003c/p>\u003cp>大鹏今日来过级，\u003c/p>\u003cp>乐享分舵群助力。\u003c/p>\u003cp>从此踏上拆书路，\u003c/p>\u003cp>一步一步变牛逼。\u003c/p>\u003cp>因为这是我的首次过级，因此我要先为大家先介绍一下什么是拆书帮？\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>说到拆书帮，它是一个通过拆书法来训练拆书家的学习爱好者社群，目标是帮助更多的学习爱好者成长为合格的拆书家。\u003c/p>\u003cp>\u003cbr>那什么是拆书家呢？拆书家是引导大家运用拆书法，让你通过读一本书来达到参加同主题培训效果的人。\u003c/p>\u003cp>那什么叫拆书法呢？拆书法又叫做RIA便签阅读法，强调运用书中的知识片段，来激活自己的过往经验，帮助自己解决生活中的问题，从而达到提升自我能力的一种读书方法。\u003c/p>\u003cp>其中R是阅读原文片段；I是用自己的话重述原文片段；A是拆解原文中的知识和技巧，并运用到自己未来的生活中去。其中A又分为A1激活自己的经验，A2规划未来的运用，这种方法既可以运用到平时自己读书的过程中，又可以运用到我们现在这样的读书活动里。\u003c/p>\u003cp>【过渡语】\u003c/p>\u003cp>那么现在，就由我来带领大家拆解一下今天的知识片段，\u003c/p>\u003cp>《所谓情商高，就是会说话》第39-41页。\u003c/p>\u003cp>下面让我们花1到2分钟时间看一下原文片段，大家看完后举手示意一下。\u003c/p>","ratings_count":2,"texts":[{"id":19549,"quote":"\u003cp>第1章 完美掌握！把“No”变成“Yes”的技巧\u003c/p>\u003cp>把“No”的回答变成“Yes”，有3个步骤。\u003c/p>\u003cp>步骤1：“不要直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法，这就是步骤1。 \u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。\u003c/p>\u003cp>在这种时候，请不要直接说：“大家继续吃啊！”\u003c/p>\u003cp>步骤2：“揣摩对方的心理”\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。”这应该就是家人的想法。\u003c/p>\u003cp>此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。\u003c/p>\u003cp>到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。\u003c/p>\u003cp>想达到这一点，就要基于对方的心理来考虑措辞。关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”\u003c/p>\u003cp>这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>Why：读完这个片段，大家可以想一想，平时你对别人提出请求时，你是直接说出自己的想法？还是思考一下再说话？而哪一种被别人拒绝的概率会更大？肯定是后者对不对？那么我们该怎样降低别人说No的概率，提升对方说Yes 的几率呢？今天我们的拆页就是来解决这个问题的。\u003c/p>\u003cp>What：作者通过这个片段告诉我们：如果你知道对方会答应你的请求，那么就直接说出来也是OK的；如果知道别人会反感甚至拒绝你的请求，那就请不要直接说出来你的想法，如果实在忍不住想要说，也千万不要说这个请求对我很重要。对你很重要，又关我什么事？因此我们要站在对方的角度考虑，并根据对方的性格喜好来做分析后告诉对方，我的请求中对你也有好处，这会极大地提高对方答应你的概率。\u003c/p>\u003cp>How：这个方法可以分为三步走：\u003c/p>\u003cp>1、不直接说出自己的想法：比如你想让玩得正起劲儿的孩子把垃圾拿下楼扔了，这时你一定不要直接说：孩子，赶紧把垃圾拿下楼扔了，你看，都快满了！\u003c/p>\u003cp>2、揣摩对方的心理：孩子玩得正起劲儿，这时你直接说，孩子一般会又什么样的反应？肯定不愿意，除非有更好玩的东西，对吧？3、考虑符合对方利益的措辞：如果你孩子喜欢到楼下找朋友玩，那你就可以这样说，待会你下楼找朋友玩儿的时候，顺便把垃圾也带下去扔了，好吗？\u003c/p>\u003cp>这样是不是会大大提高孩子答应你请求的概率？\u003c/p>\u003cp>Where：当然，如果你的请求不能给别人带来好处，甚至会损害对方的利益，那么你的请求不说也罢，除非对方是你爸，当然，这种情况下，他也不一定会答应你，对吧？如果对方喜欢简单直接的说话方式，这也不适用。\u003c/p>","interaction":"\u003cp>【A1联系具体经验】\u003c/p>\u003cp>记得在3月18日的时候，我家里面给我推了一个相亲对象过来，对方父母看了我的照片后很满意，要求我马上请假飞回成都和女生见面，而我想要先通过微信先了解一下女生，结果直接被对方父母给拒绝了，他们说我爸妈已经答应了他们请求，这让我很生气。\u003c/p>\u003cp>我立即就给我爸妈打了电话，要求他们以后不要在不经过我同意的情况下，就随便答应相亲对象的一些无理要求，这已经不是我第一次要求我父母了，但一直没有效果。反思我失败的原因，就是我一直在和我父母提我的要求，没有考虑他们的想法，更没有从我们的共同利益出发去说服他们。\u003c/p>\u003cp>【A2具体应用】\u003c/p>\u003cp>这周末，给父母打电话，使用把No变成Yes的技巧，让父母在以后给我相亲时，先听听我的意见，步骤如下：\u003c/p>\u003cp>1、不要直接说出自己的想法：打电话前提醒自己，不要直接对他们说，我要你们以后怎么做。\u003c/p>\u003cp>2、揣摩对方的心理：想想他们可能的反应，直接说的话，他们肯定会对我一顿批评加教育，然后说担心我以后找不到媳妇这样的话。\u003c/p>\u003cp>3、考虑符合对方利益的措辞：说出我们都想要的是什么，我们都想要我能找个好媳妇，而不想找那种结了婚没多久，就闹离婚的那种媳妇。而那种喜欢一上来就提过分要求的女生，很容易在结婚后提更过分的要求，一旦我满足不了她，就很容易闹离婚，离婚就要分家产，那我很容易人财两空，然后就更难找媳妇了，为了避免这样的情况发生，我希望你们能多为我把把关，帮我选个好的，或者在答应对方的要求前，先问问我的意见，好吗？\u003c/p>\u003cp>相信通过这样一番劝说，我父母一定会慎重考虑我的请求，当然，这样还不够，我需要反复提醒他们，这个方法用到其他人身上也一样，需要反复告诉对方，我的请求对你也有好处，这样效果更好。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>最后，我们来总结一下今天的知识，大家还记得把No变成Yes的技巧，有哪三步吗？\u003c/p>\u003cp>1、不要直接说出自己的想法\u003c/p>\u003cp>2、揣摩对方的心理\u003c/p>\u003cp>3、考虑符合对方利益的措辞\u003c/p>\u003cp>大家学会了吗？希望这个技巧能对大家有所帮助，也希望大家回去能把这个方法用起来。我今天的分享到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1680481963000,"updated_at":1680699405000,"ria":true},{"id":15104,"topic":"用“措辞菜谱”训练说话水平，把NO变成YES","learn_goal":"","remark":"拆书家在拆解“投其所好”“被认可欲”两个片段过程中，能够熟练运用二级拆书家所有技能，能够设计两个有逻辑关系的拆页搭配，及时回应反馈，并给出简明有力的总结。","level":"TF2-4","duration":70,"status":30,"type":0,"chaishujia":{"username":"心连心","city":"杭州市"},"club":{"name":"杭州雷峰塔筹备分舵","city":"杭州"},"prologue":"\u003cp>\u003cstrong>【开场】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>各位小伙伴，大家晚上好，欢迎大家参加今晚的拆书练级活动。今天是我的TF2-4晋级，拆书主题是：用“措辞菜谱”训练说话水平，把NO变成YES，来自《所谓情商高就是会说话》这本书。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我是心连心。我的标签有三个：\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 1、体制内属牛人，今年满五十了；\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 2、节能领域从业者；\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 3、雷峰塔分舵一级拆书家。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>考虑到今天是线上活动，在线人数不多，为了方便接下来的讨论分享，我们就不分组了，直接在腾讯会议主界面讨论，这个符合二级拆书家的标准。所以，也请大家尽量把摄像头设置为开启状态。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 今天这两个片段都是来自于日本超人气沟通专家佐佐木圭一的《所谓情商高就是会说话》这本书。下面我先来介绍一下这本书。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>〖Feature特征〗核心是&quot;书“，用于满足好奇心\u003c/strong>\u003c/p>\u003cp>\u003cstrong>本书作者是左左木圭一\u003c/strong>\u003c/p>\u003cp>\u003cstrong>从一个原本不擅长沟通和表达的人\u003c/strong>\u003c/p>\u003cp>\u003cstrong>成为日本顶级沟通专家、广告鬼才、方案写作大师\u003c/strong>\u003c/p>\u003cp>\u003cstrong>并成为首位获得美国广告大奖“金铅笔奖”的日本人\u003c/strong>\u003c/p>\u003cp>\u003cstrong>被视为亚洲最成功的广告策划人\u003c/strong>\u003c/p>\u003cp>\u003cstrong>他是取得这些成就的呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>本书中“7个突破口”和“8个技巧”是他成功方法的浓缩\u003c/strong>\u003c/p>\u003cp>\u003cstrong>是世界各大知名企业员工的人际沟通方面指定培训教材\u003c/strong>\u003c/p>\u003cp> \u003cstrong>〖Advantage优势〗重点是”比较“，用于建立安全感\u003c/strong>\u003c/p>\u003cp>\u003cstrong>与其他沟通类书籍相比\u003c/strong>\u003c/p>\u003cp>\u003cstrong>本书在表达上更通俗、更直观\u003c/strong>\u003c/p>\u003cp>\u003cstrong>每个突破口和技巧后面\u003c/strong>\u003c/p>\u003cp>\u003cstrong>用措辞示意图表达方法步骤\u003c/strong>\u003c/p>\u003cp>\u003cstrong>用实践故事让读者模拟体验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>形成的“措辞菜谱”拿来就能用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>让读者在阅读时如同亲身经历\u003c/strong>\u003c/p>\u003cp>\u003cstrong>让读者仅靠阅读就能获得模拟体验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>〖Benefit利益〗强调的是”你“，用于引发兴趣\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 【B1】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果你觉得自己情商不高\u003c/strong>\u003c/p>\u003cp>\u003cstrong>社交中不知道如何说话\u003c/strong>\u003c/p>\u003cp>\u003cstrong>你的请求总是被拒绝\u003c/strong>\u003c/p>\u003cp>\u003cstrong>你总是一说话就得罪人\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我强烈建议你照着这本教人说话的“菜谱”多练几次\u003c/strong>\u003c/p>\u003cp>\u003cstrong>本书准备了足够多的优质菜谱\u003c/strong>\u003c/p>\u003cp>\u003cstrong>能让你在短时间内增加经验，达到随时使用的水平\u003c/strong>\u003c/p>\u003cp>\u003cstrong>搞定不分担的爱人、不听话的孩子、不合作的同事……\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【B2】\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 通过学习选择的自由、被认可欲这两个突破口\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在面对可能的拒绝时\u003c/strong>\u003c/p>\u003cp>\u003cstrong>让对方的回答从NO变成YES\u003c/strong>\u003c/p>\u003cp>\u003cstrong>接下来我们开始进入第1个拆页的学习，先说一下本环节的学习目标。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【环节 1 学习目标】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在跟随我完成第1个拆页的RIA现场学习后，学习者能够用给对方“选择的自由”三步法，即：定主题、列选择、加问号，现场将被拒绝经历的措辞，反思加工成为NO变YES的措辞。\u003c/strong>\u003c/p>","ratings_count":3,"texts":[{"id":19112,"quote":"\u003cp>\u003cstrong>接下来我们一起学习第1个拆页。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>下面请大家花2分钟的时间看一下原文片段，看完后用语音示意我，或者在聊天区回复1。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现在请大家开始阅读。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【主题】\u003c/strong> \u003cstrong>掌握“选择的自由”三步法，让“NO”变成”YES” \u003c/strong>\u003c/p>\u003cp>\u003cstrong>【图书】《所谓情商高就是会说话》P.29-30\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 让不愿穿鞋的幼儿下意识穿上鞋的措辞\u003c/strong>\u003c/p>\u003cp>\u003cstrong>坂井惠美（化名）有个两岁的女儿。她每天都会送女儿去幼儿园，但女儿不愿穿鞋，她又不能送光着脚的女儿去幼儿园，所以很伤脑筋。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>“穿鞋。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>就算她这么说，女儿也根本没有穿鞋的意思，反而跑回房间玩起了积木。迟到是家常便饭。坂井很犯愁。一天，她试着使用了从朋友那里听来的&quot;措辞菜谱&quot;。坂井拿着两双鞋问女儿：\u003c/strong>\u003c/p>\u003cp> \u003cstrong>“蓝色的鞋和红色的鞋，你想穿哪双？”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结果女儿用手指着说：&quot;蓝色的鞋！&quot;然后主动开始穿鞋。从女儿的角度来说，她不喜欢被迫穿鞋，而通过自主选择，就变得愿意穿鞋了。这就是利用了&quot;选择的自由&quot;这一措辞突破口。从那以后，坂井在育儿时经常使用这样的措辞。\u003c/strong> \u003c/p>\u003cp>\u003cstrong>不直接说“穿衬衫”，而是问“有花纹的衬衫和有小熊的衬衫，你想穿哪件？”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>措辞在育儿方面尤其有效，高明的措辞能让孩子变得主动自愿。不过，如果一直使用“选择的自由”，难免千篇一律，所以应该尝试经常换不同的“措辞菜谱”。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>〖what〗\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这个拆页向我们展示了妈妈用“选择的自由”措辞方法，即通过定主题、列选择、加问号三个环节，让孩子主动自愿的开始穿鞋和穿衣服的案例。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>〖why〗\u003c/strong>\u003c/p>\u003cp>\u003cstrong>通过“选择的自由”措辞，就能从符合对方利益的角度说出自己的想法，提高得到“YES”回答的可能性。经常让对方有“选择的自由”，也会让对方觉得你的性格很有亲和力，善于为对方考虑。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>人都容易不假思索地把想法直接说出来，如果直接说出自己的想法，这样不仅仅事与愿违，让对方觉得不舒服，拒绝你的请求，而且还容易招致反感，不利于以后的交往。比如：片段中如果直接说出“穿鞋。”，女儿觉得是被迫穿鞋，就会选择拒绝。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【意译原书案例】（更贴近实际的例子）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>原文的案例，是日本妈妈育儿过程中的例子。很多小伙伴没结婚，还没有这方面的经验。其实，我们生活中这样的例子还有很多，为了让大家更好理解，我举一个身边的例子：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>让不爱做家务的丈夫愉快做家务的措辞\u003c/strong>\u003c/p>\u003cp>\u003cstrong>婚姻中，“家务活到底由谁来做”，是每个家庭都会出现的问题。这看似是小事，却能深深影响夫妻感情和家庭幸福。晓梅今年28岁，宝宝刚两岁，结婚以来，丈夫很少做家务，天天就知道玩游戏，为此经常吵架。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>“你去把垃圾倒一下。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在晓梅多次要求之后，丈夫会说过一会儿再做之类的话，然后时间到了事情还是放在那里，他给的理由是忘记了。多次这样之后晓梅觉得非常累，也不愿意再要求了，甚至想过离婚，可是宝宝还小，她感到很苦恼。一天，朋友推荐她一本《所谓情商高就是会说话》这本书，学习了里面的“措辞菜谱”。有一天，晓梅一边锤着腰一边对老公说：\u003c/strong>\u003c/p>\u003cp> \u003cstrong>“洗碗和倒垃圾，你想做哪一样？”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>丈夫稍微一愣，说：“那我倒垃圾吧”。然后放下鼠标，就去倒垃圾了。从晓梅丈夫的角度说，他不喜欢做家务，更不喜欢被迫做家务，通过自主选择，就变得心态好多了。尽管可能因为懒、男女不平等观念、做家务曾遭到妻子批评等因素的影响，还有不情愿，但是毕竟已经有了行动了。这就是“选择的自由”这一措辞突破口的力量。从那以后，晓梅经常使用“措辞菜谱”对待丈夫。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>不直接说“你把地板拖一拖”，而是问“拖地板和晾衣服，你选哪一样？”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>措辞不仅在育儿方面有效，在处理家庭关系，特别是男女方面关系也有效。高明的措辞能放对方变得情绪和谐、平和。相信晓梅经过熟练运用“措辞菜谱”，能够随时使用高明的措辞，与丈夫的关系也会变得更加和谐。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>〖how〗\u003c/strong>\u003c/p>\u003cp>\u003cstrong>那么怎么用“选择的自由”这个“措辞菜谱”呢？我觉得应该是三步法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：定主题。想一想经常被拒绝的是什么事情，明确一个主题，但是不要直接说出来。案例中“你去把垃圾倒一下。”这个就是主题（家务活），下面的“你把地板拖一拖”也是主题。直接说出来，被丈夫拒绝了。命令式的口吻也会让人不舒服。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：列选择。根据主题，再想一个或者几个相似的主题，我们案例都是再选一个就可以了，案例中洗碗和倒垃圾，这是两个选择，下面的拖地板和晾衣服，也是两个选择，当然你也可以三个选择，比如洗碗、倒垃圾、晾衣服，就是相似主题，组成选择题。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：加问号。精准说法是加句号，加问号好记。把两个相似的分主题，用提问的方式让对方选择。“洗碗和倒垃圾，你想做哪一样？”这就是加问号。改变命令式的口吻，用提问的方式，给对方选择的自由。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>〖where〗\u003c/strong>\u003c/p>\u003cp>\u003cstrong>适用场景：这个适用比较亲近的人际关系，比如亲子教育、家庭关系、朋友同事等。在生意洽谈、销售产品过程中也常常有应用。比如，想让对方消费，不直接问买什么，而是直接给出两个产品让顾客挑选，顾客购买的概率会加大。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不适用场景：不适合在安全警示、法规制度、推行管理等刚性、严肃的场景，很多时候不容拒绝，在提出要求的时候，就要简单明了的提出注意事项，使用“不准、必须”等大家不喜欢的措辞。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp> \u003cstrong>讲到这里，可能小伙伴心里就会有异议：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“选择的自由”这个技巧也不可能百分之百管用吧？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这个说法是对的。经常使用这个技巧，也会使对方感觉千篇一律，会产生厌烦情绪。即使你读完了这本书，实践了所有的技巧，也不能让以前所有“NO”的回答都变成“YES”，但是却是能够提高可能性。按照作者的经验，如果原来的可能性为0.，那么本书能够帮助你提高2-3成；如果原来的可能性为5成，那么就能版主提高到7-8成。结果是叠加的，只要持续使用，就能达到前所未有的境界。\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>A1:激活经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 【显像提问】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>听过了我个人对拆页的讲解，大家应该了解了通过“选择的自由”这个突破口，把“No”的回答变成“Yes”的“措辞菜谱”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现在请各位小伙伴想一想，在没有学习这个“菜谱”之前\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.、你是如何在亲子教育中对孩子提出要求的（比如：穿鞋、吃饭等）？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、如何让爱人（老公）分担家务的（比如：扔垃圾、擦玻璃、洗碗等）？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3、如何请心仪的对象吃饭的？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>有没有被拒绝的经历呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果是被拒绝的负面案例，当时什么情况呢？事情的起因，时间、经过、结果？有什么教训呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果是被答应的正面案例，当时是怎么说的，具体的事情起因，时间、经过、结果？有没有三步法中相关的内容呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请大家思考4分钟，然后请小伙伴用分享一下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现在开始思考。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>…………\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间到，下面请大家的分享自己的故事。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、亦欣：我说一个失败案例，大家会经常经历。我跟孩子讨论，“今天中午吃什么？”然后孩子回答，“随便”。到最后也不知道吃什么。反思一下，中午吃什么是一个很宽泛的概念，我没有列出目标性的内容给出选择。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>心连心：亦欣的这个例子很多人都遇到过，很好。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、小庄：我说一个成功的案例。我向领导提建议，都会根据具体的工作内容提供两个方案。比如，领导问我要搞一个活动，去准备一下。我都会根据活动的要求，准备两个活动方案，A方案和B方案，然后我会问领导，是A方案好还是B方案好？最后还要领导还有什么补充意见？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>心连心：就像亦欣聊天框中说的那样，小庄非常优秀，看出来工作中非常用脑，这个方法在工作中也很管用。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>感谢两位小伙伴的分享！\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【反思加工经验】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>你想到的故事经验如果是个反向案例，那么再遇到这样情况，你会怎样应用”选择的自由“三步法去说话呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>你想到的故事经验如果是个正向案例，那么想想看，根据”选择的自由“三步法，还有没有更好的说法呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请大家思考3分钟，然后大家把自己的“反思加工”分享一下时间到了，我将邀请2名小伙伴来跟大家一起分享一下它的“反思加工”，现在开始计时！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>………\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间到，邀请小伙伴分享一下。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、夕惕若：每年过年都发福利，我都会向领导建议，去年我建议给大家发个火腿好不好，结果领导否定了。今年我提建议的时候，说给大家发劳保用品、还是发一点咸肉、香肠，还有去年说的火腿，大家也觉得不错。结果领导选了咸肉、香肠和劳保用品。这个问题就解决了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【回应或反馈】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>心连心：这个案例更好了，不仅是两个选择，还加了两样东西，最后领导选择了3个东西，这个很好。其实，夕惕若三个步骤虽然没有说出三个步骤中的前两个步骤，但是后面的建议里面都有了。过年发福利就是定主题，咸肉、香肠、火腿和劳保用品就是列选择，加问号以后，得到了领导肯定的回答，效果非常好。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、亦欣。首先中午吃饭是定主题。之后是列选择，刚好冰箱里有食材，儿子也喜欢吃饺子和汤面。最后，加问号，我们中午是吃汤面还是吃饺子呢？儿子说，那我们就吃饺子吧。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>心连心：亦欣分享的很精彩，自己亲身做饭的经历，也取得了圆满的成果。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【环节一小结】（强有力的结语）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天我们学习了“选择的自由”三步法，就是定主题、列选择、加问号，也做了分享。做一个小总结。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>通过第一个拆页的学习，我们就记住“选择的自由”三步法，即：定主题、列选择、加问号就可以了。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":19113,"quote":"\u003cp>\u003cstrong>接下来，我们开始第2个拆页学习，先把本拆页的学习目标告诉大家，希望大家带着目的和问题学习。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【环节 2 学习目标】\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 在跟随我完成第2个拆页的RIA现场学习后，学习者能够用满足对方“被认可欲”四字法，即：想（意图）、猜（心理）、找（优长）、说（双赢），现场演练设计场景，并现场写出化解未来可能被拒绝场景的目标和行动计划。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆页逻辑关系】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天给大家带来的两个拆页片段，分别是把”NO“变成”YES“的7个突破口中的第3、4个突破口，两者是并列关系，都是打动人心、实现把NO变成YES的技巧。如果两个技巧叠加使用，这样能够帮助我们更容易地把NO变成YES。时间关系，今天我们不讨论如何叠加使用。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆页 1 的例子，告诉我们如何运用“选择的自由”三步法让”NO“变成”YES“。作者提倡应该尝试经常换不同的“措辞菜谱”。所以，我们接下来看第 2 个拆页。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>下面请大家花2分钟的时间看一下原文片段，看完后用语音示意我，或者在聊天区回复1。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>说明一个问题，书中文字片段后面还有一个措辞示意图，前面介绍图书的时候，这本书就是通过措辞示意图来揭示方法步骤。我已经把图中的步骤用文字复制出来了。看图上面的文字：三个步骤。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现在请大家开始阅读2分钟。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【主题】\u003c/strong> \u003cstrong>“被认可欲”四字法，让“NO”变成”YES” \u003c/strong>\u003c/p>\u003cp>\u003cstrong>【图书】《所谓情商高就是会说话》P.35-36\u003c/strong>\u003c/p>\u003cp>\u003cstrong>突破口4：被认可欲\u003c/strong>\u003c/p>\u003cp> \u003cstrong>对于生意和家人效果极大！人际关系也会改善。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>“你把窗户擦擦！我忙不过来。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>妻子对从不干家务活儿的丈夫这样说，丈夫会主动开始擦窗户吗？答案当然是“No”。丈夫会产生被迫做麻烦事的感觉，只想立刻逃开。就算肯擦窗户，也必定极不情愿，会边擦边想：“我每天也有工作要做啊。”那像下面这样说呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“你能够到高的地方，能把窗户擦得更亮。拜托了！”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这样一说，丈夫就会跃跃欲试。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这里就利用了“被认可欲”这一措辞突破口。当然，这样说并不能百分之百保证丈夫会擦窗户，但至少不会令他感到不快。 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>这种“被认可欲”，也可以解释为心理学上的“尊重需求”，即“一个人能做出与他人的期待相对应的成果”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>商务人士自不用说，主妇、学生、老人统统如此。一个人得到别人的认可，就会产生回应期待的欲望。在这种情况下，哪怕是有些麻烦的请求，对方也会欣然接受。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这个措辞示意图给出了具体步骤：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>步骤1：不直接说出自己的想法。“你把窗户擦擦！我忙不过来”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>步骤2：揣摩对方的心理。“我每天也有工作要做啊”，喜欢夸自己个子高。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>步骤3：考虑符合对方利益的措辞。“你能够到高的地方，能把窗户擦得更亮。拜托了！”\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>〖what〗\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这个拆页讲的是通过”被认可欲“的技巧，能够让对方欣然同意你的请求，把NO变成YES。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>〖why〗\u003c/strong>\u003c/p>\u003cp>\u003cstrong>人无完人，但是人人都希望被认可、被尊重。通过这个措辞菜单，就能满足对方被认可、被尊重的心理，让寻求帮助变得更顺利。哪怕是有些麻烦的请求，对方也会欣然接受。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果不这么做，直接说出你的请求，就会遭到对方的拒绝。即使对方勉为其难地做了，内心也肯定极不情愿，给两人之间的关系带来不和谐。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【反面案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>前段时间我的电脑中毒厉害，我自己清理比较简单，没有解决问题。周六早上接到领导电话，要我准备一个稿子，第二天把初稿发给他。但是电脑问题没有解决，时间已经不多了，我就有点着急了。所以上周六上午9点左右，儿子还在睡觉，我推开他房间的门，说：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>”儿子，起床吧，帮我把电脑杀杀毒，我要编辑个文稿。“\u003c/strong>\u003c/p>\u003cp>\u003cstrong>儿子说：”我好困呀，等我睡醒了再弄。“\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结果到了睡到下午一点才帮我弄，还一脸的不高兴。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>实际上，我被他委婉地拒绝了，而且还很不情愿。\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 我也很不满意。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【细化行动步骤】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>〖how〗\u003c/strong>\u003c/p>\u003cp>\u003cstrong>通过分析给出的内容和措辞示意图，满足对方”被认可欲“需要四字法：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、想（意图）。就是想清楚自己的目的或意图，但是不要直接说出来。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、猜（心理）。就是猜测对方的心理，主要根据对方的平日表现，以及对方的性格、好恶等因素，猜测对方是否会拒绝。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3、找（优长）。就是找对方的优长，看对方哪些方面容易被人认可，从中选出1-2个与自己的目的关联度最高的线索，作为对方希望被认可的措辞内容。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4、说（双赢）。在搞清楚对方优长的基础上，创造出符合双方利益的措辞，并说出来。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这里说明一下，原文案例给出了三个步骤，第三个步骤找（优长），是行动步骤的细化。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【正面案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习了满足被认可欲四字法，我感觉我让儿子帮电脑杀毒的措辞还是有很大问题的，我觉得我应该这么处理。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>首先，想（意图），让儿子起床帮我电脑杀毒。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二，猜（心理），儿子属于夜猫子，不喜欢早起，上午9点肯定不起床，叫他杀毒，应该是会说NO，即使起来了，也不情愿。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三，找（优长），儿子大学专业是电子信息类，电脑技术比较好，晚上学习还是比较勤奋的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第四，说（双赢），为了达成让儿子修电脑的目的，我觉得应该这么组织上下文：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“儿子，昨晚又搞到很晚吧，真勤奋，我电脑自己杀毒了半天都没弄好，你的电脑技术好，起床帮我杀杀毒吧”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我想这么说，他应该会很乐意帮我杀毒，即使不会立即起床，心里也会高兴。即使不能保证100%，效果还是不错的。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>〖where〗\u003c/strong>\u003c/p>\u003cp> \u003cstrong>适用场景：适用于比较亲近的朋友家人间，或者你对对方有一定程度的了解，就可以使用这个方法。同时，在生意、职场等方面的效果也不错，既可以是上级对下级的认可，也可以是下级对上级的认可。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不适用场景：在事关安全方面的严肃场景中不适用，比如，今年春节烟花燃放的限制性要求，政府机关提出要求就不会考虑被认可欲，直接提要求。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>需要注意的地方：第3个字是关键，难度相对大一点，通过找优长把符合对方利益的点列出来，要多加练习。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp> \u003cstrong>有人可能会觉得一个措辞要4个步骤是不是有点太麻烦？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>其实想和猜都是较短时间完成的，相对比较难的是第三步，也是原文拆页示意图中没有明确的内容，我感觉很重要，在找优长的过程，找到了认可对方的线索，再把线索编入到符合对方利益的措辞中。如果能够让NO变成YES，还是很值得的。复杂点没有关系，一点成了呢。\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3促动参与】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【演练场景设计】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现场的小伙伴呢，大家都是非常爱学习的，刚才我们学习了满足”被认可欲“四字法，即：想（意图）、猜（心理）、找（优长）、说（双赢）。现在让我们来看一个场景，我特别情调一下，这个情境展示的措辞，一般是大家很少想到的，但是很重要，很管用，做的好，可能会让你的生活不一样。所以，我在说场景的时候，大家注意体会：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王海大学毕业后到一家软件公司上班，性格比较内向，和同事说话不多，尤其是部门主管张总每天非常忙，两个人交流很少，工作了半年以后，工作不得要领，后来听说张总在同批进入公司的员工中技术最好、进步最快；工作经验丰富、先后呆过3个部门，王海也很崇拜他。王海很想让张总对他的工作给与指导，但是怕说了请求被张总拒绝，不知道该怎么办，为此苦恼了近半个月。周末同学小聚的时候，情商高会说话的班长方亮也来了，王海找个机会把方亮拉到一边，讲了自己的烦恼，希望方亮能教教他，怎么向上司张总发出请求，才不会被拒绝。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>刚好，方亮刚学习了《所谓情商高就是会说话》这本书，告诉王海说，其实上司更想得到认可，可以利用”被认可欲“这个措辞突破口，创造符合张总利益的措辞。紧接着就手把手将四字法交给了王海。王海听了以后，很快就学会了，并知道了应该怎么措辞，请张总对王海的工作给与指导，进一步密切上下级关系。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【角色扮演】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong> \u003cstrong>给出清晰指令】考虑到人数不是很多，就不分组演练了，就在主界面进行角色扮演。在此之前，先请大家酝酿思考角色的对话内容，酝酿思考的时间3分钟。具体的角色，在线的小伙伴请自行选择一个，可以是王海，也可以是方亮，选择一个即可。模拟演练的场景是：周末小聚的时候王海把方亮拉到一边请教，如何用高明的措辞向上司表达请求，不会被拒绝。期间，方亮根据自己从书本上学来的想、猜、找、说四字法表达请求，教会王海向主管张总发出给与工作指导的请求，演练时间5分钟。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>下面，我提供了场景中的线索。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>………\u003c/strong>\u003c/p>\u003cp>\u003cstrong>5分钟时间到，请大家开始模拟演练，看看哪位小伙伴扮演王海？哪位小伙伴扮演方亮？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>演练之前，特别强调一点，演练的时候方亮不要一口气把四个字全部说完，说完一个字要和王海做一个互动，看他学会了没有，不要到最后才问。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>还有，演练的目的不是解决场景中的问题，而是要在场景中应用到四字法。解决场景中的问题，可以有很多办法，但今天我们只用今天所学的方法来演练就可以了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>下面由永忠演王海，小庄演方亮。非常感谢两位小伙伴，现在开始演练，时间5分钟。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王海（永忠）：老同学，我最近遇到了问题，很想去请教领导，但是我不知道该怎么说，最怕他决绝我，你有没有什么办法？教教我呢。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方亮（小庄）：我最近从一本书里学到了一个方法，，这个方法能够满足对方“被认可欲”的四字要诀，就是想、猜、找、说。首先，第一步你要想一想，你的意图是什么？你说一下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王海（永忠）：我的意图就是希望，我的领导对我的工作给予指导。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方亮（小庄）：很好。我们的第二步就是猜张总是否拒绝。你觉得张总平时的表现是怎么样的？根据平时表现判断是否会拒绝你。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王海（永忠）：张总每天都很忙，虽然工作半年了，但是我跟他工作交流也很少，我特别害怕他拒绝我。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方亮（小庄）：我们进行第三步：找（优长），你觉得张总的优点是什么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王海（永忠）：他的优点比较多，有两点特别突出。一是在同批进入公司的员工中技术最好、进步最快；二是先后呆过3个部门，工作经验特别丰富。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方亮（小庄）：嗯，好的，到时候你可以以这个为突破口创造措辞。下面进行第四步，说（双赢），创造出符合双方礼仪的话。那么，你需要张总帮助你什么呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王海（永忠）：我目前就是工作上遇到点问题，我就想让他给我指导一下，工作上给一个思路就可以。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方亮（小庄）：好的，那我简单给你捋一下。第一，意图是想让张总给你指导。第二，他工作很忙，你很怕他拒绝你。第三，发现张总优点很突出。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王海（永忠）：你看我这么说行不行“张总，我有个问题想请教一下您，听说您是同批进入公司员工中技术最好、进步最快，而且先后呆过三个部门，工作经验非常丰富，我非常想请教工作中遇到了很多问题，您一定得给我指导指导，你看可以吗”。我这样说行吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方亮（小庄）：我觉得你还要把你的现状说一下，要产生对比。比如你工作了半年了，因为工作不得要领，这样可以更加体现出来要想一想。想清楚之后，我再去找他请教。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王海（永忠）：好的，那我把要问的具体情况，再想一想。想清楚了以后，我再去找张总。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方亮（小庄）：好的，相信你已经掌握了四字要诀。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王海（永忠）：我觉得这个方法确实也不错。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方亮（小庄）：好的，那你到时候用一下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 王海（永忠）：谢谢你，老同学。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【回应或反馈】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>心连心：两个小伙伴扮演的很精彩，我感觉比我设计的案例还要好。小庄提醒说，你要把现状说一下，要产生对比才行。永忠很快就拿出了上下文，我觉得基本到位了，符合双赢的话，也是领导爱听的话，我相信领导肯定会给予指导。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>感谢小伙伴的分享！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>之【分布催化1】\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【显像提问】\u003c/strong>\u003c/p>\u003cp> \u003cstrong>在座的各位小伙伴，请大家想象一下，马上过春节假期了，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>①你想要另一半陪你去看一场电影，而另一半可能觉得还不如在家从电脑上看舒服；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>②或者你想约上好友聚个餐吃烤肉，对方在减肥，不想陪你吃高卡路里的菜品；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>③或者你想让另一半陪你去1小时车程的亲戚家拜年，但是想去呆一天，另一半觉得时间太长了，希望去了就回。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>大家结合自己的实际情况想一想，你的请求可能会遇上哪些被拒绝的场景？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>…………\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请大家思考并想出情境后，请加工一个具体例子写在便签上，写好的语音提示我，或者在聊天框中扣“1”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现在开始边思考边写出情境（不要行动计划），写起来相对麻烦，时间4分钟。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>…………\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间到，下面请小伙伴分享具体的例子。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、郭郭：去年12月份因为疫情，外甥女上初中，提早上网课，成绩不是很好，自制力不好，网课基本没怎么学。春节我比较空，想利用春节期间给外甥女补课，会被拒绝。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、永忠：春节想去1小时车程的我的亲戚家拜年，妻子大概率是不想去，会被拒绝。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3、亦欣：春节还没有给孩子买新年礼物，但是孩子是夜猫子，白天陪我去逛街，100%会被拒绝。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4、小庄：我还没有 想到春节被拒绝的场景。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【回应或反馈】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>心连心：刚才小庄没有想到场景，可能是我的场景案例还不够多，或者是我的指令还不是很明确，除了看电影、吃烤肉、去拜年这三个场景，大家看看是否还可以考虑一下，请另一半去民俗住三天、另一半感觉时间太长了；除夕夜很冷，向让怕冷的另一半陪你午夜的时候放烟花等场景，请小庄开动脑筋，想想有没有类似场景。小庄可以发在聊天框中，或者以后在讨论。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>感谢3位小伙伴的分享。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在结束之前，小庄在分布催化2中，聊天框中分享了自己的可能遭到拒绝的场景：我想要老婆陪我去看阿凡达，老婆不喜欢看这样打打杀杀的场面，我就夸她，你就跟电影里的女主角一样漂亮，咱们一起去看看吧，怎么样？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>之【分布催化2】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>那么再请大家思考一下，如果不想在未来的场景中被拒绝，应该采取什么行动呢，请大家写出行动计划。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请注意，行动计划要包括两个部分：目标+具体行动，具体、可衡量、有特定时限，比如，我准备年初五下午去看电影，准备采取如下行动方案，要包括如下四字法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>希望大家写下来，发到聊天框，如果感觉写下来麻烦，可以在脑子里形成腹稿，一会分享给大家。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>写下来还是比较复杂的，现在开始边思考边写行动方案，时间5分钟。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现在开始思考。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>………\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间到，邀请小伙伴分享。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp> \u003cstrong>一、主界面语音分享\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、永忠：在过年的时候初六，让爱人陪我去亲戚家拜年。我可以这样说：你开车水平高，路也认的好，和我一起去拜年，对我这里路盲来说简直就是遇到了救星。怎么样，陪我去一趟吧？\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【回应或反馈】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>心连心：永忠发言时间不长，已经把四个字都已经明确了。想（意图）：年初六去亲戚家拜年；猜（心理）：爱人会拒绝；找（优长）：开车水平高，路也认的好，像救星一样；说（双赢）：你开车水平高，路也认的好，和我一起去拜年，对我这里路盲来说简直就是遇到了救星。怎么样，陪我去一趟吧？我想你的爱人肯定不舍得让你一个人去，即使不大情愿，也会答应你去。很不错，符合四字法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、亦欣：我明天上午就要约儿子上街买新年礼物，再不逛街到年三十商场就关门了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>想：买年货和新年礼物，通过逛街与孩子有相处的时光。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>猜：孩子不大相逛街，而且很晚起床，不愿意白天逛街，会非常不乐意，大概率会拒绝我。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>找：优长是眼光特别棒，能发现美的物品。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>说：孩子，你的眼光特别棒，能发现一些美的物品，你能不能发挥你的特长，帮助妈妈买一些东西，这样我觉得要比妈妈靠谱。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这么说，他可能会洋洋得意，最后他会答应。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>心连心：刚才亦欣把前面可能拒绝的场景，用四字法捋了一遍，说出符合双方利益的话，这样大概率会同意。这个例子非常好。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>二、聊天框文字分享\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、夕惕若：（我的朋友很喜欢让人说他长得帅）“朋友，最近我碰到上次我们一起聚会时的小张了，他说你一点也不像快50的人，又高又帅（找），很久没有在日常生活中碰到这么帅的人了。但就是抽烟不喜欢，还让候吸了二手烟，身上一股难闻的味道。朋友，这个抽烟我也是觉得很不好，那谁谁得了肺气肿，都是烟给抽的，我看你最好还是把烟戒了（意图）。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、小庄：我想要老婆陪我去看阿凡达，老婆不喜欢看这样打打杀杀的场面，我就夸她，你就跟电影里的女主角一样漂亮，咱们一起去看看吧，怎么样？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我看到夕惕若和小庄已经把行动方案，发到聊天框里了，其他小伙伴可以通过微信或者聊天框发给我，我会整理到实录里面。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>感谢小伙伴的分享！今天这两个拆页就学完了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【强有力的结语】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>感恩大家接近1个小时的陪伴，接下来，我们回顾一下，刚才我们学习了给对方”选择的自由“三步法和满足对方”被认可欲“四字法，就是让对方心甘情愿接受你的请求。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>记住，给对方”选择的自由“三步法是：定主题，列选择、加问号；满足对方”被认可欲“四字法是：想（意图）、猜（心理）、找（优长）、说（双赢）。如果两个技巧叠加，这样能够帮助我们更容易地把NO变成YES。\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 今天的线上拆书到此结束，感谢各位小伙伴的聆听和支持！谢谢!\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1674232958000,"updated_at":1676209805000,"ria":true},{"id":14030,"topic":"利用被认可欲获得帮助","learn_goal":"","remark":"拆书主题二：利用被认可欲获得帮助\n拆书家： Wendy\n书籍名称：《所谓高情商，就是会说话》\n书籍介绍：本书作者是左左木圭一，是日本顶级沟通专家、广告鬼才、文案写作大师。\n                  书中作者通过自己多年来掌握的语言措辞技巧告诉大家如何修炼说话能力，提高说话水平。\n\n个人介绍：为头部教育品牌服务14年；\n                   服务学员10000 ；\n                   星球之家联合创始人；\n                   拆书帮准二级拆书家\n\n挑战等级：TF2-3\n拆书时长：20-25分钟\n学习者收获：现场学习后，学习者能够在遇到需要请求帮助的时候；通过满足人们被认可欲的三步法，从而得到自己需要的帮助\n\n结缘拆书:刻意搜索，庆幸相识，与一群谦逊爱学习的人在自我成长的路上结伴同行。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"Wendy温蒂","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>大家好，我是Wendy\u003c/p>\u003cp>喜欢用演讲传递价值、拆书法阅读学习、长期主义践行者\u003c/p>\u003cp>今天我挑战的拆书等级是TF2-3 主题是：《利用被认可欲获得帮助》\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够在遇到需要请求帮助的时候；通过满足人们被认可欲的三步法（先分析、找期待、巧结合）从而得到自己需要的帮助\u003c/p>\u003cp>\u003cstrong>F: \u003c/strong> 本期为大家推荐拆页来自《所谓情商高，就是会说话》。本书作者是左左木圭一，他是首位获得美国广告大奖“金铅笔奖”的日本人。本书是世界各大知名企业员工的人际沟通方面指定培训教材。 \u003c/p>\u003cp>A: 本书和其他书相比，以大量的实践案例，以更加可视化的形式，让读者仅靠阅读，就能产生模拟实战的效果。\u003c/p>\u003cp>B1: 如果你总感觉自己说话不过脑子；如果你总是一说话就得罪人；如果你总是容易把天聊死；如果你具有社交恐惧，我强烈建议你读一读这本书。\u003c/p>\u003cp>B2: 而通过我今天讲解的利用被认可欲获取帮助的方法，将使你在（向他人提出请求或）寻求他人帮助时更顺利。\u003c/p>","ratings_count":1,"texts":[{"id":18044,"quote":"\u003cp>突破口4：被认可欲\u003c/p>\u003cp>对于生意和家人效果极大！人际关系也会改善\u003c/p>\u003cp>“你把窗户擦擦！我忙不过来。”\u003c/p>\u003cp>妻子对从不干家务活儿的丈夫这样说，丈夫会主动开始擦窗户吗？答案当然是“No”。丈夫会产生被迫做麻事的感觉，只想立刻逃开。就算肯擦窗户，也必定极不情愿，会边擦边想：“我每天也有工作要做啊。”那像下面这样说呢？\u003c/p>\u003cp>“你能够到高的地方，能把窗户擦得更亮。拜托了！”\u003c/p>\u003cp>这样一说，丈夫就会跃跃欲试。\u003c/p>\u003cp>这里就利用了“被认可欲”这一措辞突破口。当然，这样说并不能百分之百保证丈夫会擦窗户，但至少不会令他感到不快。\u003c/p>\u003cp>这种“被认可欲”，也可以解释为心理学上的“尊重需求”，即“一个人能做出与他人的期待相对应的成果”。\u003c/p>\u003cp>商务人士自不用说，主妇、学生、老人统统如此。一个人得到别人的认可，就会产生回应期待的欲望。在这种情况下，哪怕是有些麻烦的请求，对方也会欣然接受。\u003c/p>","explains":"\u003cp> Why: 人无完人，平时生活中我们少不了需要别人的帮忙，每当这些时候，你会怎么做呢？为了让寻求帮助变得更顺利。这里我想介绍一个小技巧，使用人类共有的愿望来帮助你实现你的愿望。人类共有的愿望是什么呢？那就是人人希望被尊重、被看见，希望得到他人的认可。\u003c/p>\u003cp>What: 这是一个在寻求帮助时使用认可欲来获取他人帮忙或向他人提出请求时，让对方欣然接受的小技巧\u003c/p>\u003cp>\u003cstrong>H\u003c/strong>OW（细化原文步骤）： 大家都已经看过了拆页，妻子刚开始直接提出让丈夫帮忙擦窗户，结果怎么样？遭到了拒绝对吧？所以我们从这里开始：我们的要求被对方拒绝了之后我们要怎么办？它分为三个步骤\u003c/p>\u003cp>1、先分析，先从客观情况去分析一下对方为什么会拒绝我？有没有客观因素的影响？如果没有，那就进行第2步。\u003c/p>\u003cp>2、找期待，每个人都期待被认可，妻子找到了丈夫的期待：那就是丈夫喜欢别人夸自己个子高\u003c/p>\u003cp>3、巧结合，一旦明确了对方的期待，要怎么说呢？这个表达要把对方的期待和我们的想法联系在一起，让对方觉得你的认可让他来做这件事，正好！所以妻子假装说自己够不到高的地方，希望丈夫能施以援手，这样就充分满足了丈夫被看见和被尊重的期待，于是跃跃欲试。\u003c/p>\u003cp>Where：这个小技巧只适用于比较亲近的朋友家人间，或者你对对方有一定程度的了解，就可以使用这个方法\u003c/p>\u003cp>\u003cstrong>EXAMPLE（意译原文案例）：\u003c/strong>\u003c/p>\u003cp>上个星球六上午家里人都出门了，就我和儿子在家。看着时间已经很晚了，孩子还不肯起来。我就有点头大。我就对他说：“儿子，快点起床了，已经很晚了”。儿子有点不耐烦的翻了身：“哎呀，让我再睡一会。”\u003c/p>\u003cp>这个时候我想起了书中的技巧。我就对他说：“儿子，今天早上我们俩吃什么呀？“我看到冰箱里还有两款牛排，要不咱们吃牛排怎么样？就是我上次煎的牛排不好吃，你煎的很好吃，来起来教一下妈妈，我们一起煎牛排好吗？”这时虽然儿子还是有点不情愿的从床上起来，但是眉宇之间很明显的感觉到一丝丝骄傲。\u003c/p>\u003cp>儿子喜欢煎牛排，他希望好手艺被认可，这样认可孩子身上的闪光点。我呢在孩子面前示弱，从而也达到了目的。\u003c/p>","interaction":"\u003cp>A3促动参与（场景设计）\u003c/p>\u003cp>下面我们来做一个演练，请大家仔细听一下要演练的场景：你叫小迪，在一个周末的上午，你正在家里给全家人准备午餐，这个时候发现家里的菜不多了，而此时此刻你的老公正在沙发上埋头沉浸在手机游戏中，你跟老公说，中午在家里自己做饭吃，让他赶紧去超市卖点菜回来，被老公以“我很累”拒绝了。\u003c/p>\u003cp>线索如下：\u003c/p>\u003cp>1) 喜欢别人夸自己挑螃蟹的技术好；2）在意儿子视他为榜样；3）喜欢被肯定是顾家爱家的人\u003c/p>\u003cp>下面，请小伙伴们两两一组，一个扮演妻子，一个扮演丈夫，请妻子运用今天的方法和丈夫再进行沟通。\u003c/p>\u003cp>这里需要做两个动作：1、设计对话，2、角色扮演，设计对话时需要运用今天的利用认可欲三步法：1、先分析，2、找期待，3、巧结合。大家有6-8分钟的时间来进行演练，一会儿我们请一个小组来展示一下他们的演练成果。\u003c/p>\u003cp>学习者演练：小意和吴磊\u003c/p>\u003cp>小意扮演小迪，吴磊扮演丈夫\u003c/p>\u003cp>小迪：今天菜不够了，你去超市买点菜吧\u003c/p>\u003cp>丈夫：哎呀，我很累，不想去\u003c/p>\u003cp>小迪：我看到了，你确实在忙，儿子特别喜欢你挑的螃蟹，你可会选螃蟹了，每次选的螃蟹又好又大。再去超市买点螃蟹吧，顺便再带点其他的菜回来。\u003c/p>\u003cp>丈夫：也是，你每次买的螃蟹又瘦又没肉，行行行，这事还得我去买。买几个？\u003c/p>\u003cp>小迪：你做主吧，交给你放心。\u003c/p>\u003cp>丈夫：好吧，那我去了。\u003c/p>\u003cp>好的。谢谢大家的参与。相信今天的”利用被认可欲“的三步方法，可以帮大家更好的在生活中用高情商方式获得需要的帮助\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1661222289000,"updated_at":1661959034000,"ria":true},{"id":13904,"topic":"把NO变成Yes的说话情商","learn_goal":"","remark":"拆书主题一：《把NO变成Yes的说话情商》\n拆书家： Wendy\n书籍名称：《所谓高情商，就是会说话》\n书籍介绍：\n本书作者是左左木圭一，是日本顶级沟通专家、广告鬼才、文案写作大师。书中作者通过自己多年来掌握的语言措辞技巧告诉大家如何修炼说话能力，提高说话水平。\n个人介绍：为头部教育品牌服务14年；\n                   服务学员10000 ；\n                   星球之家联合创始人；\n                   拆书帮准二级拆书家\n挑战等级：TF2-2\n拆书时长：15-20分钟\n学习者收获：现场学习后，在面对可能的拒绝时，能投其所好，使用符合双方利益一致的措辞来与对方沟通。 \n结缘拆书:刻意搜索，庆幸相识，与一群谦逊爱学习的人在自我成长的路上结伴同行。\n","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"Wendy温蒂","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>大家好，我是Wendy \u003c/p>\u003cp>一位用演讲传递价值；用拆书法阅读学习；用脚步丈量生活的教育人\u003c/p>\u003cp>今天我带来的拆书行动是TF2-2\u003c/p>\u003cp>各位小伙伴在跟随我完成本次RIA现场学习后，能在面对可能的拒绝时，【具体可测量的行为要求/可被观察的行动】不直接说出自己的想法，而是能够投其所好，使用符合双方利益一致的措辞来与对方沟通。\u003c/p>\u003cp>\u003cstrong>F: \u003c/strong> 本期为大家推荐拆页来自《所谓情商高，就是会说话》。本书作者是左左木圭一，是日本顶级沟通专家、广告鬼才、文案写作大师。书中作者通过自己多年来掌握的语言措辞技巧告诉大家如何修炼说话能力，提高说话水平。\u003c/p>\u003cp>A: 和市面上沟通类的书相比本书在表达上更通俗。作者说：“说话如做菜有谱可循，只要掌握了基本菜谱，任何人都能做出美味佳肴。”书中例举了大量的实践故事，便于理解容易掌握，拿来就能用.\u003c/p>\u003cp>B1: 你是否想尽快掌握说话精髓，搞定犹豫不定的客户、不肯合作的同事、不肯做家务的老公、捣乱的熊孩子?书中的7大突破口，如投其所好、选择的自由、被认可欲等，总有一款适合你。\u003c/p>\u003cp>B2: 今天我们一起来使用“投其所好”法，让别人心甘情愿对你说“Yes”\u003c/p>","ratings_count":1,"texts":[{"id":17916,"quote":"\u003cp>突破口1 ：投其所好。既是最基本的，也是最管用的。“抱歉，这种衬衫只剩这一件了。”听到店员这样说，你会怎么想？可能会一下子产生“是别人挑剩的吧”“恐怕有很多人试穿过”的印象。如果店员换一种说法，例如：“这种衬衫卖得特别快，这是最后一件了。”\u003c/p>\u003cp>你又会怎么想？大概会产生“要是流行，我也想买”“最后一件了，不买就没了”的印象。这样的措辞就是成功利用了“投其所好”的突破口。如此一来，拿着衬衫去收银台结账的人也会变多。传达同样的内容，如果使用不同的措辞，对方的接受方式和行为就会发生变化。店员的目的是“希望顾客消费”，但不能直接说出来，而是要揣摩顾客的心理，采用“投其所好”的措辞。\u003c/p>\u003cp>以“投其所好”的形式提出请求，对方也会乐于接受。只要意识到这个突破口，就能让对方高兴地听取自己的请求。\u003c/p>\u003cp>在“7个突破口”中，我也会从“投其所好”这个突破口最先开始考虑。只要养成考虑“投其所好”的习惯，就能让对方觉得你连性格都变好了。不，正因为你会主动考虑“投其所好”，所以性格是真的变好了。\u003c/p>\u003cp>下面是几则利用“投其所好”的实践故事。\u003c/p>\u003cp>STORY “投其所好”实践故事。飞机供餐的鱼剩下很多时，怎样措辞才能顺利调整配量\u003c/p>\u003cp>电影《快乐飞行》里曾出现令人不禁点头赞许的巧妙措辞。在该影片中，绫濑遥饰演某航空公司的新人空姐。在分配供餐的一幕，由于乘客大多优先选择牛肉，所以导致鱼大量剩余。\u003c/p>\u003cp>就在新人空姐面临重大危机的关头，经验丰富的前辈说道：“像平时一样平均分配！看好了。”然后展现了高超的措辞技巧：\u003c/p>\u003cp>“机内供应以优质香草、富含矿物质的天然岩盐和粗制黑胡椒嫩煎而成的白身鱼，以及普通牛肉。”\u003c/p>\u003cp>由于是电影，其中自然存在表演成分，但前辈空姐这样一说，乘客确实会觉得鱼更好吃。后来，当前辈空姐询问乘客的选择时，绝大多数乘客都主动选择了鱼。这里就使用了“投其所好”的“措辞菜谱”。\u003c/p>\u003cp>“对不起，只剩鱼了。”如果空姐这样说，乘客就会觉得自己简直成了废品回收站，哪里还有吃东西的心情，而像前辈那样说，乘客就会心甘情愿地主动选择鱼。这就是措辞的力量。\u003c/p>","explains":"\u003cp>Where: 在日常生活工作中会遇到，明明表达不是这个意思，为什么别人会曲解，有种无力感；但身边有人说话就能左右逢源，听起来还特别舒服。\u003c/p>\u003cp>What: 书中讲到第一个突破口就是“投其所好”，按照作者的说法，这个既是最基本的，也是最管用的。这也是我们常说的“听众思维”\u003c/p>\u003cp>Why: 拆页中的例子向我们展示了如何通过‘投其所好’的措辞，让对方高兴地听取自己的请求，将有可能的NO变成YES。\u003c/p>\u003cp>How：我们可以从拆页的例子中提炼出三个步骤：\u003c/p>\u003cp>第一：避免直接了当（想到什么就想脱口而出的时候，先暂停）\u003c/p>\u003cp>第二：揣摩对方心里（什么情况拒绝，什么情况会答应）\u003c/p>\u003cp>第三：使用恰当措辞（打消对方顾虑，符合对方利益）\u003c/p>\u003cp>A：为了让大家更好理解，我举例子\u003c/p>\u003cp> 去年10月我坐高铁，过安检的时候那个排的队伍特别长。这个时候就有一个工作人员走出来大声的喊， “大家往右边走，往右边走啊”,可是很多的乘客依然无动于衷，于是他又提高了嗓门，甚至生气的喊:“诶，我说了，往右边走，往右边走！”乘客们还依然是挤在左边不为所动，甚至有人还冲他白了一眼。这个时候我就主动走到右边的安检通道看了一眼，然后转过头去跟左边的旅客说了一句:“这边没有人，不用排队” 话音刚落，就有很多人跟了过来。\u003c/p>\u003cp>第一步：避免直截了当：我想让大家往右走，直接说出这句话仍然不会有效果。 \u003c/p>\u003cp>第二步：揣摩对方心里：不容易排到现在这个位置，一定要坑占稳，没有比尽快通关上车更重要\u003c/p>\u003cp>第三步：使用恰当措辞：当告诉我告诉乘客，“这边没人，不用排队”一下就让大家意识到往右边走能提高通关效率节省时间，所以都愿意跟过来了。\u003c/p>\u003cp>【预防异议+讲解】：可能小伙伴会问，这样技巧也不可能百分之百管用吧。\u003cstrong>一个方法肯定不能解决所有问题的。这个方法帮助我们把“No”变成“Yes”的概率。\u003c/strong>\u003c/p>","interaction":"\u003cp>A2 分步催化一：\u003c/p>\u003cp>接下来请大家设想一下，你在接下来的一周或者一个月可能会面临的一个情景：\u003c/p>\u003cp>你和同事协调工作，同事犹豫不决迟迟不回复；邀请另一半陪你参加活动，增进感情，TA觉得累不想去；或者你希望家人改变一种不好的习惯，但家人不以为然\u003c/p>\u003cp>大家结合自己的情况想一想，有哪些场景。讨论时间2-3分钟\u003c/p>\u003cp>学习者圈圈的案例：\u003c/p>\u003cp>今天就发生了一件类似的事情：我们公司的图纸设计是外包给一家公司做的，因为我们明天就要用到那张图纸。我就开始催促对方早点交稿，但是对方丝毫没有受到我的催促影响，还是慢慢的改。我就想尝试用这种方式，让他可以早点完成，我可以在今天拿到图纸。\u003c/p>\u003cp>A2 分步催化二：\u003c/p>\u003cp>现在请大家根据刚才想到的场景，结合今天的拆页，想想我如何运用这个方法能投其所好让对方说YES呢？讨论时间是5分钟。我会请1位或者2位学习者分享自己的案例。\u003c/p>\u003cp>学习者涛涛的案例：\u003c/p>\u003cp>我想组织一场老同学聚会，如果直接邀请可能很多人碍于工作和家庭都不会参加（想法）；\u003c/p>\u003cp>我这群同学都是篮球爱好者，借着最近有一场大型的比赛来邀约。（对方“好”）。\u003c/p>\u003cp>我就以约大家观看比赛的是由组织同学会，这些球迷爱好者出席的概率就会比较高了（符合双方意愿）。\u003c/p>\u003cp>学习者加一的案例：\u003c/p>\u003cp>我想换一个不忙的专业，留给自己时间做喜欢的事情（想法）；\u003c/p>\u003cp>领导还是想要我在自己的专业上发挥作用，不要摆烂躺平（对方“好”）\u003c/p>\u003cp>我想要做专业的培训，可以更好的协助你打造一个精英专业团队。就切换现在的工作方向王培训这个方面发展（符合双方意愿）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1659768515000,"updated_at":1660119917000,"ria":true},{"id":13517,"topic":"所谓情商高就是会说话","learn_goal":"","remark":" 很多时候，我们希望通过表达让对方同意我们观点，或者在观点上达成一致，往往事与愿违，那么如何才能让对方从心理真的认可你的想法，并且你们能够在同一件事上，达成一致呢？\n\n欢迎和小星星一同开启学习之旅~","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"陈宇星","city":"株洲"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>各位亲爱的小伙伴们，大家上午好，我就是宇宙中最亮的星，小星星，一闪一闪亮晶晶。\u003c/p>\u003cp>下面用三个标签简单的介绍自己：\u003c/p>\u003ch2>1、 拆书帮的活跃的小达人，为什么说我是拆书帮活跃小达人呢？因为喜欢和各个分舵小伙伴友好交流以及拆书游学，甚至经常参与拆书帮的大型活动，担任线上线下幕后工作人员，所以，拆书帮活跃小达人，非我莫属啦！\u003c/h2>\u003ch2>2、 拆书帮移动宣传大使，为什么会有这个称号呢？ 前任舵主，芳姐封的，哈哈哈哈，因为，我不管走到哪，或者参加什么线上训练营也好，还是在什么APP上认识的小伙伴，瞬间………..等等，都会安利一波拆书帮。\u003c/h2>\u003ch2>3、 拆书帮的链接小达人，小星星总是会在不经意间，链接到一些拆书帮的大咖，各分舵舵主、教育长老等，和大咖交流，会让你整个身心灵都很放松。浑身充满着能量，想知道如何链接拆书帮大咖吗？感兴趣的小伙伴，欢迎在活动之后，找我来聊。\u003c/h2>\u003cp>\u003cstrong>在今天开始我的拆书练级之前，为了让大家更好的学习和讨论，我先给大家简单的分一下组，今天一共是12个人，分为2组。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>随机分组讨论。\u003c/strong>\u003c/p>\u003ch2>\u003cstrong>书籍介绍（2分钟）\u003c/strong>\u003c/h2>\u003cp>【F】今天我给大家带拆的书籍片段来自于名《所谓情商高就是会说话》，这是一本沟通类书籍，作者佐佐木圭一，他被称为日本顶级沟通专家、广告鬼才、亚洲最成功的广告策划人。这本书是他成功方法的浓缩。\u003c/p>\u003cp>【A】 和其他沟通类书籍相比，这是一本实战型的书，可以直接拿来就用。并且它的销量已达百万册。\u003c/p>\u003cp>【B1】书中把措辞比喻成菜谱，措辞就像做菜，有谱可循，只要掌握了菜谱，任何人都能做出美味佳肴。这本书，可以让我们在短时间内提升高情商说话技巧。\u003c/p>\u003cp>【B2】今天的片段学习，教大家在面对可能的拒绝时，用片段中三步骤，让对方的回答从NO变成YES。\u003c/p>\u003cp>\u003cstrong>接下来，请大家花一分钟时间阅读原文片段，看完的小伙伴，请向我举手示意。\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":17539,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页（2分钟）\u003c/strong>\u003c/p>\u003cp>把“No”的回答变成“Yes”，有3个步骤。\u003c/p>\u003cp>步骤1：“不直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。在这种时候，请不要直接说：“大家继续吃啊！”\u003c/p>\u003cp>步骤2：“揣摩对方的心理”\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。”这应该就是家人的想法。此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>\u003cp>好，看到小伙伴们，基本上都看完了。\u003c/p>","explains":"\u003cp>【Why】\u003c/p>\u003cp>语言表达是我们每个人与生俱来的技能，\u003c/p>\u003cp>而这项技能看似简单，要把它用好，实则不易\u003c/p>\u003cp>现实生活中，许多人受着不同程度的语言表达困扰\u003c/p>\u003cp>这其中就包括：\u003c/p>\u003cp>因为不懂语言表达，产品卖不出去\u003c/p>\u003cp>因为不懂语言表达，找不到合适的工作\u003c/p>\u003cp>因为不懂语言表达，找不到合适的人生伴侣\u003c/p>\u003cp>因为不懂语言表达，迟迟不能升职加薪\u003c/p>\u003cp>因为不懂语言表达，人际关系一团糟\u003c/p>\u003cp>而总有那么一小部分人，在人际关系中能够如鱼得水，收放自如\u003c/p>\u003cp>我们总是羡慕他们能够有这么强的语言表达能力，能说会道，希望有一天也能像他们一样，拥有着超强的表达能力，他们并不是天生就这么能说会道，而是他们有着一套说话的技巧。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>其实，说话就像我们做菜，他是有谱可循的，只要你掌握了这套菜谱，你也能够做出美味佳肴，这套说话技巧的名字，就叫“措辞菜谱”\u003c/p>\u003cp>【How】\u003c/p>\u003cp>从NO 到Yes 的措辞菜谱呢，主要有三个步骤：\u003c/p>\u003cp>1、 克制自己的表达欲\u003c/p>\u003cp>2、 揣摩对方心理\u003c/p>\u003cp>3、加上符合对方利益的措辞\u003c/p>\u003cp>为了让大家更好的理解： 举个例子\u003c/p>\u003cp>19年12月，在行动派线上课程认识一个北京地区小姐姐，而且颜值很高，再一次与她交流的过程中，得知她想参加拆书帮北京分舵活动，于是我给她推荐北京分舵一位小伙伴微信号，当我推荐的时候，发现他的大号已经，加满，而小号的朋友圈，全是非主流的一些图片，和我们拆书帮的Style不太符合，这时候，怎么办呢？我又不能直接跟他说 删朋友圈对吧？\u003c/p>\u003cp>所以，1、我需要克制自己的表达欲【不直接和他说 让他删除朋友圈与拆书帮无关的内容】\u003c/p>\u003cp>2、 揣摩对方的心理【如果我直接和他生活，会造成什么样的影响呢？\u003c/p>\u003cp>我要是直接和他说 ，让他删朋友圈，对方可能会觉得我越界了，从而导致我们俩的关系破裂，对吧。】\u003c/p>\u003cp>3、 加上符合对方利益的措辞，所以，我是这么说的： 小哥哥，最近在行动派课程认识一位北京地区的小姐姐，她想参加你们北京分舵的活动，并且人家颜值很高哦，你的大号已经加满了，只能推荐你的小号，你小号的朋友圈要不要考虑和大号风格统一一下呢？\u003c/p>\u003cp>1、两个微信号朋友圈更新一样的内容，会显得你更专业，更贴合拆书家的身份。\u003c/p>\u003cp>2、有身份的人都有一种独特的魅力，人家自然而然愿意靠近你，更何况是美女小姐姐呢？\u003c/p>\u003cp>于是这位小哥哥，不仅把小号朋友圈非主流图片全给删了，还更新了他们分舵最近的活动照片，甚至连头像 都给整成了很有逼格的 拆书家形象。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>当然 有人会说，用了这个方法对方的回答一定会 从no的回答 变成yes 吗？\u003c/p>\u003cp>\u003cstrong>一个方法肯定不能解决所有问题的。这个方法帮助我们更好的达成自己的目的，达成请求。\u003c/strong>\u003c/p>","interaction":"\u003cp>【A2】催化应用\u003c/p>\u003cp>（分步催化1）\u003c/p>\u003cp>接下来请大家设想一下，你在接下来的一周或者一个月可能会面临的一个情景：\u003c/p>\u003cp>你和同事协调工作，又或者约朋友出来吃饭，亦或是约闺蜜逛街………….但是被别人拒绝的场景（请大家思考并想出具体场景）\u003c/p>\u003cp>有小伙伴举手了，邀请海英同学分享：\u003c/p>\u003cp>我想邀请老公和我一起去散步，但是他觉得，哎我又不胖是吧，我为什么要出去散步呢？\u003c/p>\u003cp>就是我明天可能我还喊他去散步，他有可能要拒绝我。\u003c/p>\u003cp>给大家1-2分钟讨论，一会邀请小伙伴分享：\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>（分步催化2）\u003c/p>\u003cp>接下来，请大家结合刚刚思考出来的场景结合今天学到的三个步骤，加工一个具体的案例，在下一周、一个月之内，你在该场景下会如何应用呢？\u003cbr>海英同学分享：\u003c/p>\u003cp>1、 克制自己的表达欲 【老公你陪我去散步吧，不直接说】\u003c/p>\u003cp>2、 揣摩对方心理【前段时间，老公腰椎不是不太好吗】\u003c/p>\u003cp>3、加上符合对方利益的措辞 【老公，我听医生说这个走路对那个对腰椎啊，颈椎都有好处的，你要不要尝试一下呀？】\u003c/p>\u003cp>好的，非常感谢海英同学的分享，运用了我们这三个步骤，晚上邀请老公和她一起去散步，希望这是一个温馨的夜晚。\u003c/p>\u003cp>今天的拆书过级，到这来就结束了，感谢各位小伙伴的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1654494457000,"updated_at":1654501149000,"ria":true},{"id":12692,"topic":"用“措辞菜谱”打好沟通基础","learn_goal":"","remark":" 吉淑娟\n宣传语:\n是否还在因没有个人魅力而苦恼，还在因语言苍白而苦乏味，拜托别人做事，总是事与愿违.\n如何让“NO”变成“YES”,《所谓情商高，就是会说话》的“投其所好”，让我们完美掌握，把“NO”变成“YES”的三步法。\n\n学习目标:能够根据对方投其所好三步法，“NO”变成“YES”","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"紫雨飘扬","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>大家好，我是吉淑娟，是正在转型培训师路上的一名IT产品人，加入拆书帮，是一次无意间在读书会上听彭小六介绍了他的成长之路，发现那就是我们成人想要学习的拆为己用方法，后来接触身边不少拆书家，发现他们不仅学习能力超群，而且对提升学习效率和对事物深刻理解践行的方法，是我迫切希望获得的，有幸加入拆书帮，希望在这里可以认识更多优秀的伙伴，向优秀的人靠拢，成为更优秀的自己。\u003c/p>\u003cp>今天我要拆的是1-1.\u003c/p>\u003cp>首先我对拆书和拆书帮做个简单的介绍。\u003c/p>\u003cp>“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。\u003c/p>\u003cp>拆书分为个人学习的拆书法和组织学习的拆书法：个人学习的应用就是便签法；组织学习的应用就是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，拆书帮分舵是拆书帮生命的载体，是非营利性组织，它的使命是释放学习促进者的能量，帮助更多的学习爱好者成长为拆书家。\u003c/p>\u003ch3> 我今天要分享的拆页是来自《所谓情商高就是会说话》，用认可欲三步法，成功将话说在心坎上。\u003c/h3>","ratings_count":1,"texts":[{"id":16621,"quote":"\u003cp>\u003cstrong>例子“你把窗户擦擦，我忙不过来”\u003c/strong>\u003c/p>\u003cp>儿的丈夫这样说，丈夫会主动开始擦窗户吗？答案当然是“No”，丈夫会产生被迫做麻烦事的感觉，只想立刻逃开，就算肯擦窗户，也必定极不情愿，会边擦窗户边想：“我每天也有工作要做啊”。那像下面这样说呢？\u003c/p>\u003cp> \u003cstrong>“你能够到高的地方，能把窗户擦得更亮。拜托了！”\u003c/strong>\u003c/p>\u003cp>这样一说，丈夫就会跃跃越试。\u003c/p>\u003cp> 这里就利用了\u003cstrong>“被认可欲”\u003c/strong>这一措辞借口，当然，这样说并不能百分之百保证丈夫会擦窗户，但至少不会令他感到不快。\u003c/p>\u003cp> \u003cu>这种\u003cstrong>“被认可欲”\u003c/strong>也可以解释为心理学上的“尊重需求”\u003c/u>，即“一个人能做出与他人的期待相对应的成果”。\u003c/p>\u003cp>\u003cu>一个人得到别人的认可，就会产生回应期待的欲望，在这种情况下，哪怕是有些麻烦的请求，对方也会欣然接受。\u003c/u>\u003c/p>\u003cp>具体的步骤：\u003c/p>\u003cp>\u003cstrong>1：不直接说出自己的想法\u003c/strong> \u003c/p>\u003cp> 如：你把窗户擦擦，我忙不过来。（×）\u003c/p>\u003cp>\u003cstrong>2：揣摩对方的心理\u003c/strong>\u003c/p>\u003cp> 如：我每天也有工作要做啊！（×）\u003c/p>\u003cp> 喜欢别人夸自己个子高 （√）\u003c/p>\u003cp>\u003cstrong>3：考虑符合对方利益的措辞\u003c/strong>\u003c/p>\u003cp> 如：你能够到高的地方，能窗户擦得更亮，拜托了。\u003c/p>","explains":"\u003cp>【What】很多时候，要和他人达成一致的意见，需要根据特定的场景下，换种说话方式，从认可别人的角度出发，让事情朝着自己想要的方向走，让我们来一场高效率的谈话，达成事半功倍的效果。\u003c/p>\u003cp>【Why】我们在进行一场谈话时是否会出现以下3种情况：\u003c/p>\u003cp>1、听我说，照着做，但实际上会适得其反？\u003c/p>\u003cp>2、明明是为你好，为什么就不领情？\u003c/p>\u003cp>3、明知道你说的都对，偏向虎山行。\u003c/p>\u003cp>为了解决以上这些问题，如何能达成有效的沟通，朝自己设定的方向达成效果，有了三步骤，再也不用担心达不成沟通目标了。\u003c/p>\u003cp>【How】具体步骤为：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>不直接说出自己的想法，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>注意：\u003c/strong>针对可能直接说出结果性语言会带来副作用时，在类似的场景下，可以不要直接说出自己的想法。\u003c/p>\u003cp>例如：“对女儿写字潦草，特别生气，批评话到嘴边先咽下去。”\u003c/p>\u003cp>\u003cstrong>2、\u003c/strong>\u003cstrong>揣摩对方的心理，\u003c/strong>例如：“她可能也知道，但是肯定不希望你直接批评她，因为她也不知道该怎么办，能不能陪她一起改进”\u003c/p>\u003cp>\u003cstrong>3、\u003c/strong> \u003cstrong>考虑符合对方利益的措辞，\u003c/strong>\u003cstrong>“\u003c/strong>今天写字有较大进步满满一页还是比较不错的，比如这里的语、听、耳”三个字，大方、开阔、整齐，”，便于建立完成目标的信心和成就感。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>沟通中的不是让你在讲任何话时，都要三思而后行，而是在遇到你希望通过沟通达到一定效果时，可以用它沟通出效果，比如教育孩子，向优秀的方向进步可以通过语言引导，让孩子变得更加优秀，请同事帮忙，让人愉快的答应等。\u003c/p>","interaction":"\u003cp>A1：今天我们的一个项目要交付客户，但是在测试阶段发现产品出现了质量问题，找到小刘，就给他说，限你在三个小时整改完成，当我下达命令后，原来是希望他说，保证完成任务，没想到他居然给我说，今天他很忙没有空，当时就感觉他不听我的安排，违抗公司命令，特别生气，于是就给理论起来，结果闹的大家都特别不开心，事情也没有做，导致项目也没有按时完成交付。\u003c/p>\u003cp>反思：根据上面的步骤，发现自己根本就完全没有考虑当事人现状，也没有揣摩下或者考虑下人家现在在做什么，能不能设身处地为想下他人，而是直接表达自己的想法，伤害到了他人的情绪，导致别人根本就不接受自己的意见，最后导致不良的后果。\u003c/p>\u003cp>\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【目标】下周一开个成功的冲刺会，运用认可欲三步法顺利达成行动计划\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【步骤】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>不直接说出自己的想法\u003c/strong>\u003c/p>\u003cp>首先\u003cstrong>不要直接说出自己想法\u003c/strong>，虽然我的目标是要大家按时完成计划内的任务，但是要克制向会场给大家下达各种命令的语气，毕竟是跨部门协作的会议，应该是一起协商的结果\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>揣摩对方的心理\u003c/strong>\u003c/p>\u003cp>比如他们的任务通常安排的特别饱满，我如果告诉他们需求点是什么，逻辑讲清楚，而不是让他们猜，知道他们在专业能力上也需要肯定和认可。\u003c/p>\u003cp>\u003cstrong>3.考虑符合对方利益的措辞\u003c/strong>\u003c/p>\u003cp>在沟通环节，要多听他们讲，时不时给出自己的鼓励和表达出对他们的决定认可，如：“你的原因分析的不错，这样安排很合理也很专业，我认可这样的做法”类似这样的话语，鼓励他们表达欲和自己做决策，顺利召开冲刺会。\u003c/p>\u003cp>通过上面的三个步骤，从认可欲的角度出发，有商有量，鼓励大家各抒己见，发挥大家的优势，相信这次的冲刺会将会一次非常有成效的会议。\u003c/p>\u003cp> 这就是我此次带来的用被认可欲三步法，将话说在心坎上的完整内容，希望大家在以后工作或者生活中也能发挥认可欲，实现高效率的沟通，达成既定的结果。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1637579238000,"updated_at":1638186343000,"ria":true},{"id":11705,"topic":"“措辞菜谱”","learn_goal":"","remark":"《所谓情商高就是会说话》，作者是日本顶级沟通专家佐佐木圭一。这本书主要教我们“怎么说话”。说话并不难，难的是把话说好。这本书的作者通过自己多年掌握的语言措辞技巧，给大家总结了一些列说话技巧与方法，很适合被语言困扰的每一个人。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"六弦","city":"徐州市"},"club":{"name":"徐州筹备分舵","city":""},"prologue":"\u003cp>（提前把原文拆页发给大家）\u003c/p>\u003cp>大家好，我叫六弦，目前从事生涯规划工作。\u003cbr>这份工作主要是帮助即将入职的朋友和准备转型的朋友提供咨询和测评服务。\u003cbr>大家如果想测试一下自己的兴趣、能力和动力，或者有职业选择的困惑，都可以联系我，我一定会知无不言言无不尽！谢谢！\u003c/p>\u003cp>为了方便大家更好的学习探讨，我现在先提前给大家分一下小组。\u003c/p>\u003cp>今天来现场一共5人，我们将分成2小组，每组2人......\u003c/p>\u003cp>\u003cstrong>用FAB法介绍图书\u003c/strong>\u003c/p>\u003cp>今天我和大家拆的这本书叫做《所谓情商高就是会说话》，作者是日本顶级沟通专家佐佐木圭一。这本书主要教我们“怎么说话”。\u003c/p>\u003cp>说话并不难，难的是把话说好。这本书的作者通过自己多年掌握的语言措辞技巧，给大家总结了一些列说话技巧与方法，很适合被语言困扰的每一个人。\u003c/p>\u003cp>如果你总感觉自己情商偏低；如果你总是一说话就得罪人；如果你总是很难说服别人；如果你具有社交恐惧，我强烈建议你读一读这本“教人说话”的书。\u003c/p>","ratings_count":1,"texts":[{"id":15654,"quote":"\u003cp>把“No”的回答变成“Yes”的“措辞菜谱”，有3个步骤。\u003c/p>\u003cp>步骤1：“不直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。\u003c/p>\u003cp>在这种时候，请不要直接说：\u003c/p>\u003cp>“大家继续吃啊！”\u003c/p>\u003cp>步骤2：“揣摩对方的心理”\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。\u003c/p>\u003cp>“不能光吃柑橘。”这应该就是家人的想法。此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。\u003c/p>\u003cp>到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>既然家人不想感冒，就可以对他们说：\u003c/p>\u003cp>“多吃柑橘就不会感冒了。”\u003c/p>\u003cp>这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>why———\u003c/p>\u003cp>这世上多数人都在不同程度地受着语言的困扰——\u003c/p>\u003cp>因为不会说话，总找不到合适的伴侣；\u003c/p>\u003cp>因为不会说话，工资、职位总是难以提升；\u003c/p>\u003cp>因为不会说话，人际关系一塌糊涂；\u003c/p>\u003cp>因为不会说话，创业了产品却总是卖不出去......\u003c/p>\u003cp>这世上也有那么一小部分人，他们与人相处时总能收放自如、说服别人时总能如愿以偿。\u003c/p>\u003cp>我们羡慕着他们能说会道的本领、情商极高的天赋，却不知道，其实他们大多数人并非拥有什么超能力或者高情商，而只是因为掌握了一套说话的技巧而已。\u003c/p>\u003cp>what———\u003c/p>\u003cp>其实说话就像做菜一样，是有谱可循的，这种说话技巧的“菜谱”，我们把它叫做“措辞菜谱”。\u003c/p>\u003cp>how———\u003c/p>\u003cp>让对方把“No”的回答变成“Yes”的措辞菜谱，共分为三个步骤：\u003c/p>\u003cp>第一步：不要直接说出自己直观的想法\u003c/p>\u003cp>比如，你是一名服装店售货员，客人挑到的衣服只剩下一件时，如果按照直观的想法你肯定会说：“抱歉，这种衬衫就只剩下一件了。”\u003c/p>\u003cp>表面上是实话实说，却没有考虑到对方的感受。\u003c/p>\u003cp>所以一定不要直接说出来你想说的话，而应该进入下一步。\u003c/p>\u003cp>第二步：揣摩对方的心理\u003c/p>\u003cp>对方在知道这是剩下的最后一件时，一定会想到“是别人挑剩下的吧！”、“恐怕有很多人试穿过吧！”这些想法肯定不利于销售，所以我们一定要打消顾客的这些顾虑。\u003c/p>\u003cp>第三步：考虑符合对方利益的措辞\u003c/p>\u003cp>当我们想要打消顾客的顾虑时，要知道每个人都喜欢流行畅销的产品、每个人都不希望挑别人剩下的东西、每个人都希望自己的眼光好。当有了这些突破口之后，就可以说：“这种衬衫卖得特别快，这是最后一件了。”\u003c/p>\u003cp>“你挑的这件衣服卖得特别快”，说明了衣服流行畅销、顾客眼光好；\u003c/p>\u003cp>因为流行畅销才剩下最后一件，可以打消对“挑剩”的厌恶。\u003c/p>\u003cp>有了这些“措辞”，顾客定会欣然接受。\u003c/p>\u003cp>where———\u003c/p>\u003cp>“措辞菜单”适用于销售产品时、亲子教育时、人际交往时、开会演讲时、说服对方时。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1激活经验---显像提问\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>好了，大家读完了这个拆页、听过了我个人对片段的理解之后，应该了解了\u003cstrong>把“No”的回答变成“Yes”的“措辞菜谱”。\u003c/strong>\u003c/p>\u003cp>请想想自己在没学习这个概念之前，是如何销售产品？是如何教育孩子？是如何下达命令？是如何说服他人的呢？\u003c/p>\u003cp>有没有“一上来就直接说出来自己的想法”？有没有“揣摩过对方的心理”？有没有“考虑符合对方利益的措辞”呢？\u003c/p>\u003cp>比如，如果孩子不愿意拉家长的手过马路，那能不能说“我一个人很害怕，你能不能拉着我的手一起过马路呢？”孩子被认可了，必然责任感爆棚，必然会拉着家长过马路了......大家先在小组内互相分享一下，分享自己的故事、经验时，尽量加上时间、起因、经过、结果和反思。\u003c/p>\u003cp>本次分享时间为2分钟，每人1分钟，时间到了，我将邀请一名小伙伴来跟大家一起分享一下，现在开始计时！\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>兔子：两个人去吃饭，我想吃菜煎饼，同事想吃牛肉面。\u003c/p>\u003cp>这个时候，我如果直接要求他去和我一起吃菜煎饼，他肯定不乐意。如果我用上其它措辞，比如说：“这两天吃的大鱼大肉太多了，要不要咱今天一起去吃点纤维含量高的菜煎饼刮刮油？”这样同事就会更容易接受———从因为我的喜欢而被动接受到他的主动愿意了。\u003c/p>\u003cp>我：你用的措辞就是“投其所好”，用他喜欢的东西引导到自己想达到的目的，非常棒！\u003c/p>\u003cp>\u003cstrong>A1+反思加工\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>非常感谢兔小灰小伙伴的分享（鼓掌）\u003c/p>\u003cp>不知道各位小伙伴分享的故事经验是正向的还是反向的案例。\u003c/p>\u003cp>你想到的故事经验如果是个反向案例，那么“再遇到这样情况，你会怎样应用刚才学的方法去说话呢？”\u003c/p>\u003cp>你想到的故事经验如果是个正向案例，那么“想想看，根据刚才拆页中讲的建议，还有没有更好的说法呢？”\u003c/p>\u003cp>大家把自己的“反思加工”先在小组内互相分享一下，本次时间为6分钟，每人3分钟，时间到了，我将邀请一名小伙伴来跟大家一起分享一下它的“反思加工”，现在开始计时！\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>兔子：我还听说那个菜煎饼店里最近在搞活动，咱一块过去看看吧！\u003c/p>\u003cp>那家牛肉面好像换了个厨师，口味已经不如以前那么好吃了。\u003c/p>\u003cp>我：又加上了“儆其所恶”的措辞，这样的说服力就更强了！很好！\u003c/p>\u003cp>非常感谢兔小灰小伙伴的分享。\u003c/p>\u003cp>这期的RIA拆书课就此结束了，不知道大家有没有新的收获呢？非常感谢小伙伴的参与，下期再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1623634524000,"updated_at":1623634695000,"ria":true},{"id":11462,"topic":"掌握语言的措辞","learn_goal":"","remark":"语言是人际交往的润滑剂，你是否有过这样的经历？\n\n想让对方配合你的工作，对方听完你的措辞，纹丝不动？\n\n想邀请中意的女生出去吃饭，对方却说没时间，想找朋友一起去看家具，朋友却说不感兴趣？ \n\n是你真的邀请不动吗？还是你不会措辞？ \n如果你遇到过以上这些情况，那么今天这场《所谓情商高就是会说话》的拆书之旅，就是为你量身打造的，让你学会这招沟通的武林秘籍，打遍天下无敌手！","level":"TF2-2","duration":19,"status":30,"type":0,"chaishujia":{"username":"陈宇星","city":"株洲"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>各位亲爱的小伙伴们，大家上午好，我就是宇宙中最亮的星，小星星，一闪一闪亮晶晶。\u003c/p>\u003cp>下面用三个标签简单的介绍自己：\u003c/p>\u003ch2>1、 拆书帮的活跃的小达人，为什么说我是拆书帮活跃小达人呢？因为喜欢和各个分舵小伙伴友好交流以及拆书游学，甚至经常参与拆书帮的大型活动，担任线上线下幕后工作人员，所以，拆书帮活跃小达人，非我莫属啦！\u003c/h2>\u003ch2>2、 拆书帮移动宣传大使，为什么会有这个称号呢？ 昨晚 舵主封的，哈哈哈哈，因为，我不管走到哪，或者参加什么线上训练营也好，还是在什么APP上认识的小伙伴，瞬间………..等等，都会安利一波拆书帮，刚刚从株洲到长沙来的火车上，还给一位在上海工作的小姐姐安利拆书帮，小姐姐转车回怀化了，所以，拆书帮移动宣传大使，这个称号，可以说是 名副其实，哈哈！\u003c/h2>\u003ch2>3、 拆书帮的链接小达人，小星星总是会在不经意间，链接到一些拆书帮的大咖，各分舵舵主、教育长老等，和大咖交流，会让你整个身心灵都很放松。浑身充满着能量，想知道如何链接拆书帮大咖吗？感兴趣的小伙伴，欢迎在活动之后，找我来聊。\u003c/h2>\u003cp>\u003cstrong>在今天开始我的拆书练级之前，为了让大家更好的学习和讨论，我先给大家简单的分一下组，今天一共是4个人，分为2组。左手边的2位一组，右手边的2位一组。\u003c/strong>\u003c/p>\u003ch2> \u003cstrong>书籍介绍（2分钟）\u003c/strong>\u003c/h2>\u003cp>【F】今天我给大家带拆的书籍片段来自于名《所谓情商高就是会说话》，这是一本沟通类书籍，作者佐佐木圭一，他被称为日本顶级沟通专家、广告鬼才、亚洲最成功的广告策划人。这本书是他成功方法的浓缩。\u003c/p>\u003cp>【A】 和其他沟通类书籍相比，这是一本实战型的书，可以直接拿来就用。并且它的销量已达百万册。\u003c/p>\u003cp>【B1】书中把措辞比喻成菜谱，措辞就像做菜，有谱可循，只要掌握了菜谱，任何人都能做出美味佳肴。这本书，可以让我们在短时间内提升高情商说话技巧。\u003c/p>\u003cp>【B2】今天的片段学习，教大家在面对可能的拒绝时，用片段中三步骤，让对方的回答从NO变成YES。\u003c/p>\u003cp>\u003cstrong>接下来，请大家花一分钟时间阅读原文片段，看完的小伙伴，请向我举手示意。\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":15388,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页（2分钟）\u003c/strong>\u003c/p>\u003cp>把“No”的回答变成“Yes”，有3个步骤。\u003c/p>\u003cp>步骤1：“不直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。在这种时候，请不要直接说：“大家继续吃啊！”\u003c/p>\u003cp>步骤2：“揣摩对方的心理”\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。”这应该就是家人的想法。此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>\u003cp>好，看到小伙伴们，基本上都看完了。\u003c/p>","explains":"\u003cp>【What】\u003c/p>\u003cp>那么，在我们日常工作、生活中，经常会遇到有求于人的时候，当然，有时候我们提出的请求会得到对方 yes 的答复，有的则是no。而文中的这个方法，能让我们在和对方提出请求的时候，大大提升对方说出yes的几率。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>不论你身处何方，沟通都是一个无法避免的课题，而请求他人帮助，一个人平均每天至少不低于5次，而想要让对方接受自己的表达，并且做出行动，这一系列动作，都和你的表达措辞，息息相关。【简而言之，你的表达让对方感受到舒服，对方回答yes以及做出行动意愿的概率也就随之增加】\u003c/p>\u003cp>那么具体怎么做呢？\u003c/p>\u003cp>【How】\u003c/p>\u003cp>文中讲了三个步骤： \u003c/p>\u003cp>1、 克制自己的表达欲\u003c/p>\u003cp>2、 揣摩对方心理 \u003c/p>\u003cp>3、加上符合对方利益的措辞\u003c/p>\u003cp>为了让大家更好的理解： 举个例子\u003c/p>\u003cp>19年12月，在行动派线上课程认识一个北京地区小姐姐，而且颜值很高，再一次与她交流的过程中，得知她想参加拆书帮北京分舵活动，于是我给她推荐北京分舵一位小伙伴微信号，当我推荐的时候，发现他的大号已经，加满，而小号的朋友圈，全是非主流的一些图片，和我们拆书帮的Style不太符合，这时候，怎么办呢？我又不能直接跟他说 删朋友圈对吧？\u003c/p>\u003cp>所以，1、我需要克制自己的表达欲【不直接和他说 让他删除朋友圈与拆书帮无关的内容】\u003c/p>\u003cp>2、 揣摩对方的心理【如果我直接和他生活，会造成什么样的影响呢？\u003c/p>\u003cp>我要是直接和他说 ，让他删朋友圈，对方可能会觉得我越界了，从而导致我们俩的关系破裂，对吧。】\u003c/p>\u003cp>3、 加上符合对方利益的措辞，所以，我是这么说的： 小哥哥，最近在行动派课程认识一位北京地区的小姐姐，她想参加你们北京分舵的活动，并且人家颜值很高哦，你的大号已经加满了，只能推荐你的小号，你小号的朋友圈要不要考虑和大号风格统一一下呢？\u003c/p>\u003cp>1、两个微信号朋友圈更新一样的内容，会显得你更专业，更贴合拆书家的身份。\u003c/p>\u003cp>2、有身份的人都有一种独特的魅力，人家自然而然愿意靠近你，更何况是美女小姐姐呢？\u003c/p>\u003cp>于是这位小哥哥，不仅把小号朋友圈非主流图片全给删了，还更新了他们分舵最近的活动照片，甚至连头像 都给整成了很有逼格的 拆书家形象。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>当然 有人会说，用了这个方法对方的回答一定会 从no的回答 变成yes 吗？\u003c/p>\u003cp>\u003cstrong>一个方法肯定不能解决所有问题的。这个方法帮助我们更好的达成自己的目的，达成请求。\u003c/strong>\u003c/p>","interaction":"\u003cp>【A2】催化应用\u003c/p>\u003cp>（分步催化1）\u003c/p>\u003cp>接下来请大家设想一下，你在接下来的一周或者一个月可能会面临的一个情景：\u003c/p>\u003cp>你和同事协调工作，约朋友出来吃饭，约闺蜜逛街………….但是被别人拒绝的场景（请大家思考并想出具体场景）\u003c/p>\u003cp>给大家1-2分钟讨论，一会邀请小伙伴分享：\u003c/p>\u003cp>小伙伴： 51假期有个去广州培训的机会，老妈可能不会同意，因为平时在家是老妈带孩子，51怎么也轮到我带孩子了。\u003c/p>\u003cp>感谢小伙伴的分享，非常贴切的场景。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>（分步催化2）\u003c/p>\u003cp>接下来，请大家结合刚刚思考出来的场景结合今天学到的三个步骤，加工一个具体的案例，在下一周、一个月之内，你在该场景下会如何应用呢？\u003c/p>\u003cp>小伙伴分享： 未来两天，我在老妈做饭的时候，和她提去广州培训的事，运用文中的三个步骤\u003c/p>\u003cp>1、克制自己的表达欲（不直接和老妈说，51假期要去广州参加培训）\u003c/p>\u003cp>2、揣摩对方的心理（直接和老妈说的话，老妈可能会觉得我51休息期间不想带崽）\u003c/p>\u003cp>3、加上符合对方利益的措辞（老妈，你希望我进步吗？希望我过的越来越好不?希望我能力越来越强不？ 老妈肯定会回答： 当然\u003c/p>\u003cp>我和你说，现在有个很好的机会，51有个去广州培训的机会，对我以后的事业有很大的促进作用，我自己想去，但我还是要尊重您的意见，毕竟51放假我应该在家管孩子的，平时也管的少，但是呢这个机会难得，还要辛苦妈妈几天帮忙带孩子，我掌握了这些本事以后，生活条件也会变的更好，您的孙子，我也能带的更好。\u003c/p>\u003cp>非常感谢小伙伴的分享，这个案例很贴合文中的三个步骤，相信这位小伙伴对文中的这三个步骤，已经熟练掌握。希望在今后的工作和生活中可以多多练习，把知识拆为己用，变成自己的能力，今天的分享就到这里，非常感谢小伙伴们的陪伴！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1619598833000,"updated_at":1620272206000,"ria":true},{"id":11375,"topic":"把“NO”的回答变成“YES”的三个步骤","learn_goal":"","remark":"所谓情商高，就是会说话","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"以晴","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>环节1：自我介绍（1分钟）\u003c/p>\u003cp> 各位伙伴大家晚上好，欢迎来到我们贵阳分舵第1次线下拆书现场，很高兴大家能在周末的时间与你们相聚在这里，为着我们一个共同的学习目标。我是今天的拆书人吴以晴，我的性格相对比较容易失落和缺乏自信，所以我给自己改名以晴，告诉自己可以的，晴朗的。我的标签是\u003c/p>\u003cp> 我从事建材行业生意，瓷砖零售和批发，让我有成就感就是能都得到那么多客户的认可和信任。如果有这方面需求可以与我联系。\u003c/p>\u003cp>生活中我热爱读书、瑜伽和追剧。读书让我更加沉静，快乐和充实；瑜伽使我更加健康美丽，精力充沛；追剧可以让我的思想放松，缓解压力\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>环节2：拆书帮介绍（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>接下来我为大家介绍一下什么叫“拆书”以及“拆书帮”是什么?\u003c/strong> 很多人都会有一种感觉就是读了很多书，可读完就忘了，读的时候很激动，可看了那么多道理却依然过不好这一生。这是为什么呢？就是没有做到知行合一，而“拆书”就恰恰能够解决这个问题。\u003c/p>\u003cp>“拆书”就是提取书中的一个片段，把知识关联学习者的过往经验、规划未来的具体行动，从而达到提升能力，解决问题的目的，它是以学习者为中心，而不是以知识为中心的一种成人学习方法。\u003cstrong>个人学习的拆书法\u003c/strong>：：个人学习的应用是RIA便签法（R表示阅读原书拆页，I表示讲解引导，A表示拆为己用）；\u003c/p>\u003cp>\u003cstrong>组织学习的拆书法\u003c/strong>：组织学习的应用是一位拆书家将一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来看呢，一位拆书家所创造的价值可不亚于一位培训师！\u003c/p>\u003cp>拆书帮是一个公益的青年学习组织，它的使命是培养更多的拆书家，它表现为各地的分舵，像我们贵阳第二分舵就是其中之一。\u003c/p>","ratings_count":3,"texts":[{"id":15302,"quote":"\u003cp>环节3:R便签（1分钟）：\u003c/p>\u003cp>我今天的拆书主题是关于沟通表达，今天拆书的片断选自：所谓情商号，就是会说话，下面，我们有两分钟的时间阅读片断，阅读完的小伙伴请举手给我一个反馈\u003c/p>\u003cp>【主题】把“NO”的回答变成“YES”的三个步骤  【片段来源】所谓情商高，就是会说话 \u003c/p>\u003cp> 【R：阅读原文】  把“No”的回答变成“Yes”，有3个步骤。  \u003c/p>\u003cp>步骤1：“不直接说出自己的想法”  一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。  当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。在这种时候，请不要直接说：“大家继续吃啊！” \u003c/p>\u003cp> 步骤2：“揣摩对方的心理”  请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。  直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。”这应该就是家人的想法。此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。  \u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”  提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。  关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>环节4:I便签（5分钟）\u003c/p>\u003cp>\u003cstrong> 对于刚才这个片段，我谈一下我的理解：\u003c/strong>\u003c/p>\u003cp>What \u003c/p>\u003cp>片段告诉我们如何好好说话，才能让对方原本说“No”改成说“Yes ”，让对方同意我们的观点。\u003c/p>\u003cp>Why \u003c/p>\u003cp>我常常因为说话太直接，生活中让家人感到有压力感，在工作中影响人际关系，导致单子的流失。通过这个方法，我们可以通过了解对方，来达到自己真正想解决的问题。\u003c/p>\u003cp>How\u003c/p>\u003cp>1，“不要说出自己真实的想法”，当我们一开口目的性就太强，给人的感觉就很反感。例如，你像让朋友或则老客户给你转介绍，如果太直接，就会很难在谈下去。\u003c/p>\u003cp>2，“揣摩对方心理”，我们可以在聊天当中慢慢的揣摩对方的心里，例如，可以通过聊天，来了解对方的需求。\u003c/p>\u003cp>3，“考虑对方利益的措辞”，可以了解对方的喜好，利益一致的情况下可以表达你的真实目的。\u003c/p>\u003cp>Where \u003c/p>\u003cp>在生活中与孩子和家人之间得沟通，在工作中与同事和客户之间需要得他们的帮助和需求的时候。\u003c/p>","interaction":"\u003cp>环节5:A1便签（2分钟）\u003c/p>\u003cp>3分钟\u003c/p>\u003cp>\u003cstrong>下面分享一下这个知识点我经历的一件事：\u003c/strong>\u003c/p>\u003cp>A1故事\u003c/p>\u003cp>前年年底店面升级去年受疫情的影响，直到5月份才开始营业，自己的生意也遇到的瓶颈期，我决定主动出击，昨天，我给客户发了一个信息，“你好！李师，今年让你支持一下我的生意呀”。可一直没有得到李师的回复。这就是我太直接的关系，没有做好铺垫了解对方的信息。\u003c/p>\u003cp>反思\u003c/p>\u003cp>太过直接让客户觉得我的目的性太强，应该了解对方的需求，慢慢揣摩对方的心理，婉转的表达自己的想法。\u003c/p>\u003cp>环节6:A2便签（3分钟）\u003c/p>\u003cp>3分钟\u003c/p>\u003cp>\u003cstrong>下面，我想谈一下这个知识点的具体应用：\u003c/strong>\u003c/p>\u003cp>A2\u003c/p>\u003cp>目标：在本周六前，我要用“沟通三步法来”与老公进行一次沟通，并让老公做一次饭。\u003c/p>\u003cp>行动\u003c/p>\u003cp>1，不要说出真实想法：我感觉不舒服，头有点晕。\u003c/p>\u003cp>2，揣摩对方心理：观察对方的表情，行动。\u003c/p>\u003cp>3，对方有利的措辞：当对方开始行动的时候，你上次煮的咖喱鸡饭突然好想吃，让我回味很久呢，你煮来我们一起吃吧。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1618654451000,"updated_at":1618727863000,"ria":true},{"id":11374,"topic":"把“NO”的回答变成“YES”的三个步骤","learn_goal":"","remark":"所谓情商高，就是会说话","level":"TF1-1","duration":15,"status":19,"type":0,"chaishujia":{"username":"以晴","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>环节1：自我介绍（1分钟）\u003c/p>\u003cp> 各位伙伴大家晚上好，欢迎来到我们贵阳分舵第1次线下拆书现场，很高兴大家能在周末的时间与你们相聚在这里，为着我们一个共同的学习目标。我是今天的拆书人吴以晴，我的性格相对比较容易失落和缺乏自信，所以我给自己改名以晴，告诉自己可以的，晴朗的。我的标签是\u003c/p>\u003cp> 我从事建材行业生意，瓷砖零售和批发，让我有成就感就是能都得到那么多客户的认可和信任。如果有这方面需求可以与我联系。\u003c/p>\u003cp>生活中我热爱读书、瑜伽和追剧。读书让我更加沉静，快乐和充实；瑜伽使我更加健康美丽，精力充沛；追剧可以让我的思想放松，缓解压力\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>环节2：拆书帮介绍（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>接下来我为大家介绍一下什么叫“拆书”以及“拆书帮”是什么?\u003c/strong> 很多人都会有一种感觉就是读了很多书，可读完就忘了，读的时候很激动，可看了那么多道理却依然过不好这一生。这是为什么呢？就是没有做到知行合一，而“拆书”就恰恰能够解决这个问题。\u003c/p>\u003cp>“拆书”就是提取书中的一个片段，把知识关联学习者的过往经验、规划未来的具体行动，从而达到提升能力，解决问题的目的，它是以学习者为中心，而不是以知识为中心的一种成人学习方法。\u003cstrong>个人学习的拆书法\u003c/strong>：：个人学习的应用是RIA便签法（R表示阅读原书拆页，I表示讲解引导，A表示拆为己用）；\u003c/p>\u003cp>\u003cstrong>组织学习的拆书法\u003c/strong>：组织学习的应用是一位拆书家将一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来看呢，一位拆书家所创造的价值可不亚于一位培训师！\u003c/p>\u003cp>拆书帮是一个公益的青年学习组织，它的使命是培养更多的拆书家，它表现为各地的分舵，像我们贵阳第二分舵就是其中之一。\u003c/p>","ratings_count":3,"texts":[{"id":15301,"quote":"\u003cp>环节3:R便签（1分钟）\u003c/p>\u003cp>拆书预备表在这里要有指令：\u003c/p>\u003cp>我今天的拆书主题是关于沟通表达，今天拆书的片断选自：所谓情商号，就是会说话，下面，我们有两分钟的时间阅读片断，阅读完的小伙伴请举手给我一个反馈\u003c/p>\u003cp>【主题】把“NO”的回答变成“YES”的三个步骤  【片段来源】所谓情商高，就是会说话 \u003c/p>\u003cp> 【R：阅读原文】  把“No”的回答变成“Yes”，有3个步骤。  \u003c/p>\u003cp>步骤1：“不直接说出自己的想法”  一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。  当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。在这种时候，请不要直接说：“大家继续吃啊！” \u003c/p>\u003cp> 步骤2：“揣摩对方的心理”  请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。  直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。”这应该就是家人的想法。此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。  \u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”  提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。  关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了\u003c/p>","explains":"\u003cp>环节4:I便签（5分钟）\u003c/p>\u003cp>\u003cstrong> 对于刚才这个片段，我谈一下我的理解：\u003c/strong>\u003c/p>\u003cp>What \u003c/p>\u003cp>片段告诉我们如何好好说话，才能让对方原本说“No”改成说“Yes ”，让对方同意我们的观点。\u003c/p>\u003cp>Why \u003c/p>\u003cp>我常常因为说话太直接，生活中让家人感到有压力感，在工作中影响人际关系，导致单子的流失。通过这个方法，我们可以通过了解对方，来达到自己真正想解决的问题。\u003c/p>\u003cp>How\u003c/p>\u003cp>1，“不要说出自己真实的想法”，当我们一开口目的性就太强，给人的感觉就很反感。例如，你像让朋友或则老客户给你转介绍，如果太直接，就会很难在谈下去。\u003c/p>\u003cp>2，“揣摩对方心理”，我们可以在聊天当中慢慢的揣摩对方的心里，例如，可以通过聊天，来了解对方的需求。\u003c/p>\u003cp>3，“考虑对方利益的措辞”，可以了解对方的喜好，利益一致的情况下可以表达你的真实目的。\u003c/p>\u003cp>Where \u003c/p>\u003cp>在生活中与孩子和家人之间得沟通，在工作中与同事和客户之间需要得他们的帮助和需求的时候。\u003c/p>","interaction":"\u003cp>环节5:A1便签（2分钟）\u003c/p>\u003cp>分享A1便签\u003c/p>\u003cp>3分钟\u003c/p>\u003cp>\u003cstrong>下面分享一下这个知识点我经历的一件事：\u003c/strong>\u003c/p>\u003cp>A1故事\u003c/p>\u003cp>前年年底店面升级遇到了去年受疫情的影响，直到去年的五月份才营业，自己的生意也遇到的瓶颈期，我决定主动出击，昨天，我给客户发了一个信息，“你好！李师，今年让你支持一下我的生意呀”。可一直没有得到李师的回复。这就是我太直接的关系，没有做好铺垫了解对方的信息。\u003c/p>\u003cp>反思\u003c/p>\u003cp>太过直接让客户觉得我的目的性太强，应该了解对方的需求，慢慢揣摩对方的心理，婉转的表达自己的想法。\u003c/p>\u003cp>环节6:A2便签（3分钟）\u003c/p>\u003cp>分享A2便签\u003c/p>\u003cp>3分钟\u003c/p>\u003cp>\u003cstrong>下面，我想谈一下这个知识点的具体应用：\u003c/strong>\u003c/p>\u003cp>A2\u003c/p>\u003cp>目标：在本周六前，我要用“沟通三步法来”与老公进行一次沟通，并让老公做一次饭。\u003c/p>\u003cp>行动\u003c/p>\u003cp>1，不要说出真实想法：我感觉不舒服，头有点晕。\u003c/p>\u003cp>2，揣摩对方心理：观察对方的表情，行动。\u003c/p>\u003cp>3，对方有利的措辞：当对方开始行动的时候，你上次煮的咖喱鸡饭突然好想吃，让我回味很久呢，你煮来我们一起吃吧。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1618653859000,"updated_at":1618728000000,"ria":true},{"id":11053,"topic":"利用被认可欲来获得帮助","learn_goal":"","remark":"这本书使用了3个心理步骤，7个突破口和8种实用技能由内而外的巧妙让沟通变得更简单了。","level":"TF2-3","duration":21,"status":30,"type":0,"chaishujia":{"username":"iriszou","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\u003cstrong>【分组】\u003c/strong>3-6人一小组，每一组指定一位组长，并请组长组织大家进行讨论和练习。\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>大家好，我叫邹海琳。关于我自己，我给自己的三个标签是：终身学习者、热爱生活者、心理咨询师。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者（A）能够在遇到需要请求帮助的时候（C）通过满足人们被认可欲的三步法（不直说、找期待、想措辞）来获取帮助的方法（B）从而得到自己需要的帮助（D）\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Feature：\u003c/strong> 《所谓情商高就是会说话》是由日本作家佐佐木圭一所著的一本教授日常沟通技巧和方法的书，属于实用型图书。它使用了3个心理步骤，7个突破口和8种实用技能由内而外的巧妙让沟通变得更简单了。\u003c/p>\u003cp>\u003cstrong>Advantage：\u003c/strong> 和其他同类书相比，它更落地，从非常常见的沟通场景中给出了具体的操作建议，让沟通更轻松。\u003c/p>\u003cp>\u003cstrong>Benefit：\u003c/strong> （B1)这本书敏锐地抓住了日常沟通场景中常见但容易被我们忽略的卡点，让你觉得：我的沟通之所以疙疙瘩瘩，原来是这个原因“。(B2）而通过我今天讲解的利用被认可欲获取帮助的方法，将使你在寻求他人帮助上更顺利。\u003c/p>","ratings_count":1,"texts":[{"id":14969,"quote":"\u003cp>现在我给大家1-2分钟的时间阅读拆页，阅读完毕的小伙伴请举手示意我一下\u003c/p>\u003cp>\u003cstrong>【阅读原文拆页】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>摘自《所谓情商高就是会说话》第一章—完美掌握把“NO”变成“YES”的技巧\u003c/strong>\u003c/p>\u003cp>\u003cstrong>突破口4：利用认可欲\u003c/strong>\u003c/p>\u003cp>两个人站在变绿的信号灯下，却不过马路，在旁人看来可能显得很奇怪，下田婧子想领着三岁的外甥过马路，可是外甥不愿意牵手，而那条马路上车来车往，甚至还有大卡车。\u003c/p>\u003cp>”这里很危险，拉住我的手。“\u003c/p>\u003cp>下田说了很多遍，可外甥每次都说”不“，就是不牵手。看来外甥不想被当成小孩子对待，尽管他明明就是一个小孩子······\u003c/p>\u003cp>信号灯又变绿了，可两个人仍然站在原地。下田望着再度变红的信号灯犯愁。然后，她尝试使用“措辞菜谱”\u003c/p>\u003cp>“我一个人很害怕，你能不能拉着我的手一起过马路？\u003c/p>\u003cp>她反过来把外甥当作大人对待了。结果，外甥很开心地牵住了她的手。这里就利用了“被认可欲”这一措辞突破口。外甥被当成大人对待，于是就变得主动牵手了，而下田也如愿地牵起小外甥的手，放心地过了马路。\u003c/p>\u003cp>当然，下田也可以强行拽着外甥的手过马路，但通过使用”措辞菜谱“，外甥和下田不仅顺利牵着手过了马路，而且两个人都很开心。\u003c/p>\u003cp>这就是措辞的力量。\u003c/p>","explains":"\u003cp>\u003cstrong>WHAT：\u003c/strong>这是一个在寻求帮助时使用认可欲来获取他人帮忙的小技巧\u003c/p>\u003cp>\u003cstrong>WHY: \u003c/strong>人无完人，平时生活中我们少不了需要别人的帮忙，每当这些时候，你会怎么做呢？为了让寻求帮助变得更顺利。这里我想介绍一个小技巧，使用人类共有的愿望来帮助你实现你的愿望。人类共有的愿望是什么呢？那就是人人希望被夸赞，人人都希望得到他人的认可。 \u003c/p>\u003cp>\u003cstrong>HOW（细化原文步骤）：\u003c/strong> 大家都已经看过了拆页，婧子开始直接提出要牵小外甥的手过马路，结果怎么样？遭到了拒绝对吧？所以我们从这里开始：我们的要求被对方拒绝了之后我们要怎么办？它分为三个步骤 \u003c/p>\u003cp>\u003cstrong>1、先分析\u003c/strong>，先从客观情况去分析一下对方为什么会拒绝我？有没有客观因素的影响？如果没有，那就进行第2步。\u003c/p>\u003cp>\u003cstrong>2、找期待\u003c/strong>，每个人都期待被认可，婧子找到了小外甥的期待：那就是希望被当成大人，\u003c/p>\u003cp>\u003cstrong>3、巧结合\u003c/strong>，一旦明确了对方的期待，要怎么说呢？这个表达要把对方的期待和我们的想法联系在一起，让对方觉得你的认可让他来做这件事，正好！所以婧子假装说自己很害怕，希望得到小外甥的保护，这样就充分满足了小外甥想要被当作大人的期待，于是小外甥就满意地牵着婧子的手过了马路。 \u003c/p>\u003cp>适用边界：这个小技巧只适用于比较亲近的朋友家人间，也就是你对对方有一定程度的了解，就可以使用这个方法。\u003c/p>\u003cp>\u003cstrong>EXAMPLE（意译原文案例）：\u003c/strong>\u003c/p>\u003cp>为了帮助大家更好的理解，我举一个例子：头马这个演讲组织一年一度的大区峰会明年将在成都举行，我作为公关负责人，需要物色两个小助手去负责一些小的版块，然后我找到了有一定公关经验又很上进的小伙伴RAY, 开始我直接问他愿意来成都峰会的公关团队不？结果他拒绝了我，第二天我就对他使用了这个技巧, 由于我们是网上沟通，我没办法分析他拒绝的原因，所以我就直接问了（先分析)结果他回答说害怕自己不能达到峰会的期待和水准，由于前期我们已经经过了一些沟通，所以我梳理了他的期待--他希望能够提高组织筹划能力但又担心能力不足，（这是找期待），我把自己的想法和对方的期待结合在了一起，于是我说：我看过你在你们俱乐部策划发布的推文，结构清晰而且亮点很突出，很符合明年成都峰会的头马风采这个版块的风格，我觉得你完全可以来发挥一下，当然如果你还想有所突破去锻炼一下策划组织能力，我会找资源来协助你的，你愿意来试试吗？（这是巧结合）而结果也与我的预期相同：他爽快的答应了。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】促动参与（场景设计）\u003c/strong>\u003c/p>\u003cp>下面我们来做一个演练，请大家仔细听一下要演练的场景：你叫李静，你们有一个三年级的儿子，某天你因为加班回来晚了，匆忙做饭的时候儿子叫你去辅导语文作业，本来你们分工是你辅导语文，丈夫辅导数学，而这时你走不开，儿子又很急，所以你想请丈夫去辅导儿子作业。你已经直接跟老公说过了，老公以”我很累“为由拒绝了你。下面，请小伙伴们两两一组，一个扮演妻子，一个扮演丈夫，请妻子运用今天的方法和丈夫再进行沟通。\u003c/p>\u003cp>这里需要做两个动作：1、设计对话，2、角色扮演，设计对话时需要运用今天的利用认可欲三步法：1、先分析，2、找期待，3、巧结合。大家有6-8分钟的时间来进行演练，一会儿我们请一个小组来展示一下他们的演练成果。\u003c/p>\u003cp>\u003cstrong>小伙伴的分享：\u003c/strong>\u003c/p>\u003cp>忆C：爸爸，现在有一件事情，特别火急火燎的，需要你帮我解决一下。两件事儿，第一件事儿我现在要做饭，孩子现在马上应该做作业的时间了，他需要我去辅导监督有人作业，可是我抽不开身。我说你帮我解决，只有你帮我解决，其实帮我想想办法怎么办，我该怎么办？\u003c/p>\u003cp>小A：我可以帮你做饭。\u003c/p>\u003cp>忆C：你帮我做饭我有一个问题，今天语文作业里面讲的是历史，而且是近代史，我记不清楚年份什么的，你每次就理的特别清楚，所以你能不能帮我解决一下这个问题，我觉得这是你最擅长的。\u003c/p>\u003cp>小A：好吧，我就好。\u003c/p>\u003cp>好，谢谢两位小伙伴。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>今天我们学习了一个沟通中的小技巧：那就是在你需要帮助的时候如何提高成功率呢？1、不直说，2、找期待，3、想措辞。希望通过今天的学习让大家的沟通更顺利，更简单。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1612515425000,"updated_at":1614677838000,"ria":true},{"id":10827,"topic":"把“No”变成“Yes”的三个步骤","learn_goal":"","remark":"一个人平均每天会求人22次。当然，有的请求得到的回答是“Yes”，有的则是“No”。如果原来\"Yes\"的可能性为0，那么本书应该能帮助你提高到2～3成；如果原来的可能性为5成，那么本书就能帮助提高到7～8成。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"陈羽西","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>各位拆书帮的小伙伴们大家下午好，很高兴在这里和大家一起拆书学习，首先给大家做一个自我介绍，我叫陈羽西，大家可以叫我羽西，“羽西”两个字和一个化妆品品牌碰巧同字。蹭一下品牌知名度希望大家记住我，我的三个标签：\u003c/p>\u003cp>第一个标签是“生物技术”我的本职工作是一家生物公司的技术人员。\u003c/p>\u003cp>第二个标签是“企业内训”我也是公司的一名企业内训师，所以我在不断锻炼自己的培训能力。\u003c/p>\u003cp>第三个标签是“拆书帮的品宣小助手”。大家有关于拆书帮的活动介绍，或宣传需要可以来找我哦~\u003c/p>\u003cp>【分组】 \u003c/p>\u003cp>在今天开始我的拆书练级之前，我先给大家简单的分一下组，今天一共是6个人，分为3组。左手边的三位一组，右手边的三位一组。\u003c/p>","ratings_count":1,"texts":[{"id":14715,"quote":"\u003cp>我今天拆解的片段来自《所谓情商高 就是会说话》这本书，本书主要讲了作者亲身实践中总结出的关于如何高情商说话的技巧。 \u003c/p>\u003cp>大家有过这样的经历吗，你向别人提出请求或建议，却遭到对方拒绝？你说的话别人听到一半就开始不耐烦？我今天拆解的片段，教大家如何提高别人答应你请求的概率，让对方把对你say NO的情形变成对你say YES。\u003c/p>\u003cp>好，现在请大家先阅读手中的原文片段，1～2分钟时间，阅读完后请用眼神示意下我。\u003c/p>\u003cp>把“No”的回答变成“Yes”，有3个步骤。\u003c/p>\u003cp>步骤1:“不直接说出自己的想法”\u003c/p>\u003cp> 一般来说,人都容易不假思索地把脑中的想法直接说出来。然而,这样不仅常常事与愿违,而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1\u003c/p>\u003cp>当然,我们都是凡人,不可能保证所有事都不直接说出来,但至少请记住,不要直接说出“这是很重要的请求!”之类的话。\u003c/p>\u003cp> 例如:有人从老家寄来很多柑橘,家人甚至都吃腻了,而你不想让剩下的柑橘白白烂掉。在这种时候,请不要直接说:“大家继续吃啊!”\u003c/p>\u003cp>步骤2:“揣摩对方的心理”\u003c/p>\u003cp> 请揣摩对方的心理,并根据其平日表现,猜测对方会对你的请求作何想法。直接说出请求,对方会作何反应?如果对方回答“Yes”的可能性很大,当然可以直接说……如果对方回答“No”的可能性很大,就不能直接说了。请暂时忘记自己的请求,揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。 “不能光吃柑橘。”这应该就是家人的想法。\u003c/p>\u003cp>此时,请再次忘记自己的请求,想想家人的喜恶。例如:“不想感冒。”没人愿意生病。到了容易感冒的季节,身边就会出现感冒患者,家人都很在意这一点。\u003c/p>\u003cp>步骤3:“考虑符合对方利益的措辞”\u003c/p>\u003cp> 提出的请求,要让“对方的利益”和“自己的利益”趋于一致。想达到这一点,就要基于对方的心理来考虑措辞。关键在于,要创造符合对方利益的上下文关系。即使措辞有所改变,只要最终达成目的就行。\u003c/p>\u003cp> 既然家人不想感冒,就可以对他们说:“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益,家人就会变得乐意吃柑橘,而你的目的也就达到了。\u003c/p>","explains":"\u003cp>我看大家都基本上完成了阅读，接下来我和大家一起学习一下这个拆页内容，我选择的拆页片段是把“No”变成“Yes”的三个步骤。\u003c/p>\u003cp>\u003cstrong>（what）\u003c/strong>把“No”变成“Yes”的三个步骤，是一种对他人提出请求时使用的三步法，用这个三步法可以提高别人答应你请求的概率，并且用这个三步法会使得你提出的请求带给人的感受度更好，不那么容易遭到对方反感。\u003c/p>\u003cp>\u003cstrong>（why）\u003c/strong>我们在每天的工作生活中，都会很多对别人提出请求的场景，据书中的统计，一个人平均每天要求人22次，使用把“No”变成“Yes”的三个步骤，可以让别人更乐于答应你的请求，并提高别人答应你请求的概率，从而更容易得达到你的沟通目的。如果原本说YES的可能性为0，那么能提高2-3成；如果原本的可能性为5成，就能提高到7-8成。\u003c/p>\u003cp>如果不用这三个步骤，可能会受到别人的反感或拒绝，达不到你的沟通目的，还有可能影响到你的人际交往。\u003c/p>\u003cp>（how）把“No”变成“Yes”的三个步骤：\u003c/p>\u003cp>\u003cstrong>第一步：不要直接说出你的想法。\u003c/strong>\u003c/p>\u003cp>说话之前先停下来，想一想，想好了再说，避免脱口而出的言语只考虑自己的感受和需求而忽略了对方的需求或利益。\u003c/p>\u003cp>\u003cstrong>第二步：揣摩对方的想法。\u003c/strong>\u003c/p>\u003cp>根据平日对对方的了解，如果直接说出请求，对方回答YES的可能性极大，则可以直接说请求，如果回答NO的可能性很大，那么进行下一步。\u003c/p>\u003cp>\u003cstrong>第三步：调整自己的措辞使其更符合对方的利益。\u003c/strong>\u003c/p>\u003cp>暂时忘记自己的请求，通过你对对方的喜恶、关心和在意的是什么，站在对方角度去分析。调整自己的措辞，使得你的措辞既能达到你的沟通目的，也能符合对方利益。\u003c/p>\u003cp>\u003cstrong>（where）\u003c/strong>这一方法试用于对方可能会拒绝你的请求时，提高对方答应你的概率，如果对方100%会答应你的请求则可以不用说的这么复杂。\u003c/p>","interaction":"\u003cp>给大家举一个例子：\u003c/p>\u003cp>【起因】：我在疫情期间买了很多牛奶，而我的老公不太喜欢喝牛奶，我想让他喝牛奶\u003c/p>\u003cp>【经过】：我对老公说，喝牛奶吧！\u003c/p>\u003cp>我老公对我说，我不喝，你自己喝吧！\u003c/p>\u003cp>我说，都给你热好了，你喝一瓶嘛！\u003c/p>\u003cp>我老公说热好了你喝掉。\u003c/p>\u003cp>我说我喝过了，这是给你的！\u003c/p>\u003cp>我老公说那你给你妈妈喝吧！\u003c/p>\u003cp>我说我妈喝了，你也帮忙一起喝，我买太多了不然放坏了！\u003c/p>\u003cp>我老公说那你买这么多干嘛。\u003c/p>\u003cp>【结果】：回顾一下我们刚刚的对话，首先一个祈使句“你喝吧”，人可能本身就不太喜欢祈使句被命令和指使感觉，何况他又是他不喜欢的事，兜来兜去我老公就是不想喝牛奶，不是要塞给我就是要塞给我母亲。我说“热好了”有符合他的利益么？“买太多了放坏了” 有符合他的利益么？没有，甚至还引起他追问我为什么要买这么多牛奶又喝不完的埋怨。\u003c/p>\u003cp>【反思】：如果我不要直接说出我的请求，先思考下他的想法，疫情期间大家都很关注身体健康，我可以调整自己的措辞，老公你看这疫情期间专家说了，喝喝牛奶补充蛋白质可以增强抵抗力，还是喝点牛奶好。我帮你热了一瓶，你喝点，增强体质。可能比我刚刚的措辞表达的是不是更有可能使他答应我的请求，毕竟他也是关心和在意自己的健康的。\u003c/p>\u003cp>接下来请大家回想一下，最近你生活或工作中有没有对对方提出请求的场景呢？你是怎么表达的？请大家在小组内分享，时间为3min，小组分享完成后我会请一个小伙伴分享他的经历。\u003c/p>\u003cp>下面我邀请秀秀给大家分享一下她请求别人的经历，请先说一下场景，再说一下你当时是怎么说的？\u003c/p>\u003cp>秀秀：前几天有天晚上我想让室友一起陪我去拿快递。我直接说你陪我去拿一下快递吧，时间有点晚，天有点黑之类的，室友拒绝了我，她不想出去。\u003c/p>\u003cp>好的，谢谢秀秀的分享，接下来请大家运用到今天我们分享的把“No”变成“Yes”的三个步骤，做一个关于未来你请求别人时的具体的行动方案。看看你具体是怎么做使得对方更容易接受你的请求，达到你的沟通目的。请大家写到你的便签上，写便签的时候注意，要有下一次具体的时间点和场景以及运用这个步骤的具体内容。\u003c/p>\u003cp>感谢小伙伴的参与，写完的小伙伴可以把便签给我，希望大家在未来工作生活中，可以用到这个把“No”变成“Yes”的三个步骤，更好地达到我们的沟通目的，今天我的分享就到这里。谢谢大家~\u003c/p>\u003cp>秀秀A2便签：\u003c/p>\u003cp>下一次晚上我有快递到了，我想请求室友跟我一起去拿快递，我会按把“No”变成“Yes”的三个步骤来表达：\u003c/p>\u003cp>1.不直接说出，太黑太晚了，你陪我去拿快递吧。\u003c/p>\u003cp>2.揣摩下对方想法，对方会不会想去外面吃个宵夜，我室友喜欢去操场上散散步。\u003c/p>\u003cp>3.调整自己的措辞，使其更符合对方利益：你想不想出去吃点好吃的？我们一起去吃个宵夜，吃完还可以去操场散散步，我顺便拿个快递回来吧。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1608529117000,"updated_at":1609728088000,"ria":true},{"id":10252,"topic":"把“No”变“Yes”的三步法","learn_goal":"","remark":"古往今来，但凡不懂说话之道者，都难成大事，而能成事者，一定在语言方面具有其独特的能力。一句恰到好处的话，甚至可以改变一个人的命运。人际沟通中怎样措辞？怎样快速说服对方？一起来了解把“NO”变成“YES”的3步法吧！","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"echo-cj","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>各位小伙伴们，上午好，我叫陈娟，是一位新手拆书家。我今天进行1-2的拆书分享。在开始今天的拆书之前，我先对咱们今天现场的小伙伴们进行一个分组。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>今天要给大家分享的书籍叫《所谓情商高就是会说话》，书如其名，这是一本讲述说话技巧的书。沟通类的书籍很多，那这本书有什么不一样的呢？我个人认为有3点：\u003c/p>\u003cp>\u003cstrong>第1，简单。\u003c/strong>本书总共只有2章，内容不多，文字也很简单易懂，并且书中列举了大量生活/职场中的案例帮助读者理解，是一本很好的沟通类入门书籍。\u003c/p>\u003cp>\u003cstrong>第2，实用。\u003c/strong>这本书的2章内容，第1章是介绍说服对方的技巧；第2章介绍怎么让你说的话更打动人心，这些技巧应用范围都非常广，都非常实用。\u003c/p>\u003cp>\u003cstrong>第3，独辟蹊径。\u003c/strong>在作者看来，高明的表达并不是只能来自天生的语感，而是像做菜一样，只要掌握了菜谱，任何人都可能做出美味佳肴。所以，他独辟蹊径，把高明的说话技巧，总结成菜谱式的“技术”，通过这本书向大家详细介绍了这套“说话菜谱”。\u003c/p>\u003cp>那么最后说下这本书的作者，作者叫佐佐木圭一，是一位日本人，是日本顶级沟通专家、文案写作大师。佐佐木圭一本人原本特别不擅长沟通表达，后面摸索出书中的这套“措辞菜谱”，语言与文字表达水平突飞猛进，他被视为亚洲最成功的广告策划人。\u003c/p>","ratings_count":1,"texts":[{"id":14091,"quote":"\u003cp>\u003cstrong>把“No”的回答变成“Yes”的3步法\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“No”的回答变成“Yes”，有3个步骤。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>步骤1：“不直接说出自己的想法”\u003c/strong>\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。\u003c/p>\u003cp>在这种时候，请不要直接说：\u003c/p>\u003cp>“大家继续吃啊！”\u003c/p>\u003cp>\u003cstrong>步骤2：“揣摩对方的心理”\u003c/strong>\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。\u003c/p>\u003cp>“不能光吃柑橘。”\u003c/p>\u003cp>这应该就是家人的想法。\u003c/p>\u003cp>此时，请再次忘记自己的请求，想想家人的喜恶。例如：\u003c/p>\u003cp>“不想感冒。”\u003c/p>\u003cp>没人愿意生病。\u003c/p>\u003cp>到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>\u003cstrong>步骤3：“考虑符合对方利益的措辞”\u003c/strong>\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>既然家人不想感冒，就可以对他们说：\u003c/p>\u003cp>“多吃柑橘就不会感冒了。”\u003c/p>\u003cp>这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>首先，什么是让对方从“No”的回答变成“Yes”，非常好理解，就是怎么说服对方，通过掌握一定的说话方法，让原本可能被拒绝变成同意。这在我们日常工作、生活等各种场景中都能用得上。\u003c/p>\u003cp>这段文字介绍了让对方从“No”的回答变成“Yes”的3个步骤，步骤非常简单，第1步是“不直接说出自己的想法”，第2步是“揣摩对方的心理”，第3步是“考虑符合对方利益的措辞”。\u003c/p>\u003cp>第1步“不直接说出自己的想法”，很好理解。\u003c/p>\u003cp>第2步“揣摩对方的心理”，我觉得就有点难度了，究竟怎么揣摩对方的心理呢？我又不是对方肚子里的蛔虫，对吧？而且，我们所揣摩到的对方的心理还要对说服对方有帮助，而不是不相关的，要把对方的利益与我们的利益趋于一致，形成双赢。这里很常用的一种方法就是“投其所好”，一会儿我举个例子详细进行解释。\u003c/p>\u003cp>第3步“考虑符合对方利益的措辞”就需要在成功揣摩对方心理的基础上，选择合适的词语形成你的最终表达。\u003c/p>\u003cp>为了让大家熟练掌握把“NO”变“YES”的3步法，尤其是第2步“揣摩对方的心理”，我给大家举个例子。\u003c/p>\u003cp>比如说，你的下属小明，不喜欢向你汇报工作，他可能是觉得麻烦、或者不想被管。那怎么说才能让小明好好向你汇报工作呢？\u003c/p>\u003cp>最直接的说法是“小明，某某工作你要跟我汇报一下。”这样单刀直入，效果并不明显，可能这次他跟你汇报了，以后的工作只要你不主动提要求、他又不会汇报。\u003c/p>\u003cp>我们应用今天学到的3个步骤：\u003c/p>\u003cp>步骤1：“不要直接说出自己的想法”。不要直接说“某某工作你要跟我汇报一下。”\u003c/p>\u003cp>步骤2：揣摩对方的心理。结合你对小明的了解，假如小明通常都害怕工作出错。\u003c/p>\u003cp>步骤3：考虑符合对方利益的措施。结合小明害怕工作出错，投其所好，跟小明说“为了确保出问题之前我能保持跟进，请及时跟我报告。”是不是效果会好很多？\u003c/p>\u003cp>关于揣摩对方的心理，我们要结合对对方的了解，灵活运用。刚刚的例子里是假设小明害怕工作出错，但是如果小明并不害怕工作出错，而是比如说，希望提高对他的绩效考核评价，那么你就应该这么说“我想提高对你的考核评价，请多想我汇报，也便于我了解你所做的工作，给你好评。”\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>我们已经学习了“把“No”变成“Yes”的3个步骤”，接下来，请大家回忆一下，近期有没有过类似被对方拒绝、或者与对方沟通未能达到预期的经验？比如说，有没有过跟家人、同事、身边的朋友等提出某个请求/要求，对方拒绝了你？或者对方虽然没有直接拒绝，但是并没有按照你期待的去做？回忆一下看看，你当时是怎么跟对方说的？\u003c/p>\u003cp>请大家先在小组内与同伴进行分享，分享时间4分钟，4分钟后咱们邀请1-2位小伙伴把自己的经验跟大家进行分享。 \u003c/p>\u003cp>【现场学员分享】\u003c/p>\u003cp>学员A：妈妈喜欢吃剩菜剩饭，我直接跟妈妈说“我不想吃剩饭剩菜”，效果不好，妈妈也不听。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>谢谢两位小伙伴的精彩分享，我相信通过今天的学习，大家已经充分掌握了“把“No”的回答变成“Yes”的3步法”。接下来，请大家在便签纸上写上一个未来的应用计划，比如说你近期要尝试说服某个人做某件事，你应该怎样应用今天学到的3步法，投其所好，成功说服对方。请大家花1分钟的时间写下你的应用计划。\u003c/p>\u003cp>【现场学员的计划】\u003c/p>\u003cp>学员A：\u003c/p>\u003cp>1）不直接说出我的想法“我不想吃剩饭剩菜”\u003c/p>\u003cp>2）揣摩妈妈的心理：妈妈很关注家人健康。\u003c/p>\u003cp>3）考虑符合妈妈利益的措施：“妈，我今天看到书上说剩饭剩菜对身体很不健康，尤其是亚硝酸盐偏高、容易导致心血管疾病，为了健康考虑，咱们以后就不吃剩饭剩菜了吧！”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1596987556000,"updated_at":1597024458000,"ria":true},{"id":9352,"topic":"把NO变成YES的说话神器。","learn_goal":"掌握让对方接受提议的方法","remark":"","level":"TF2-3","duration":22,"status":30,"type":0,"chaishujia":{"username":"许曼","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍】\r\n大家好！我叫许曼，大家可以叫我馒头。用三个标签介绍自己，都和书有关。\r\n第一个标签：图书。我在一家书店工作，每天都和图书打交道。\r\n第二个标签：读书。我也很喜欢读书，因为我和图书接触实在是太便利了，店内藏书有近10万册。每当我发现一本心仪的书都会欣喜好一阵。\r\n第三个标签：拆书。近几年看实用类的书比较多，很幸运遇到了拆书帮•麓山分舵，开启我全新的看书模式。\r\n【图书介绍】\r\n（F）：我今天拆解的片段来自《所谓情商高 就是会说话》这本书，作者佐佐木圭一，他是日本沟通专家、广告鬼才、文案写作大师。本书主要讲了作者亲身实践中总结出的关于如何高情商说话的技巧。\r\n（A）：和其他书相比它像一本指南，更注重实操性，所以它是一本拿来用而不是拿来读的书。情商高系列的开山之作！销量已达上百万册。\r\n（B1）：大家有过这样的经历吗，你向别人提出请求或建议，却遭到对方拒绝？你说的话别人听到一半就开始不耐烦，这本书教给大家关于说话的“7个突破口”和“8个技巧”，可以解决沟通中的多种难题。\r\n(B2):我今天拆解的片段，教大家如果搞定可能会拒绝你的人，让对方把NO变成对你说YES。\r\n【分组】\r\n等会会有小组讨论和分享的环节，我们的分组仍沿用前面的分组方式。\r\n好，现在请大家先阅读手中的原文片段，1～2分钟时间，阅读完后请用眼神示意下我。","ratings_count":1,"texts":[{"id":13145,"quote":"\u003cp>把“No”的回答变成“Yes”，有3个步骤。\u003c/p>\u003cp>步骤1:“不直接说出自己的想法”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 一般来说,人都容易不假思索地把脑中的想法直接说出来。然而,这样不仅常常事与愿违,而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1\u003c/p>\u003cp>当然,我们都是凡人,不可能保证所有事都不直接说出来,但至少请记住,不要直接说出“这是很重要的请求!”之类的话。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 例如:有人从老家寄来很多柑橘,家人甚至都吃腻了,而你不想让剩下的柑橘白白烂掉。在这种时候,请不要直接说:“大家继续吃啊!”\u003c/p>\u003cp>步骤2:“揣摩对方的心理”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 请揣摩对方的心理,并根据其平日表现,猜测对方会对你的请求作何想法。直接说出请求,对方会作何反应?如果对方回答“Yes”的可能性很大,当然可以直接说……如果对方回答“No”的可能性很大,就不能直接说了。请暂时忘记自己的请求,揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。 “不能光吃柑橘。”这应该就是家人的想法。\u003c/p>\u003cp>此时,请再次忘记自己的请求,想想家人的喜恶。例如:“不想感冒。”没人愿意生病。到了容易感冒的季节,身边就会出现感冒患者,家人都很在意这一点。\u003c/p>\u003cp>步骤3:“考虑符合对方利益的措辞”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 提出的请求,要让“对方的利益”和“自己的利益”趋于一致。想达到这一点,就要基于对方的心理来考虑措辞。关键在于,要创造符合对方利益的上下文关系。即使措辞有所改变,只要最终达成目的就行。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 既然家人不想感冒,就可以对他们说:“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益,家人就会变得乐意吃柑橘,而你的目的也就达到了。\u003c/p>","explains":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>今天，在跟随我学习完此片段的拆解后，大家能够在说出提议时，运用不要直说、猜测回应、分析需求、达到双赢四个步骤，大大提升对方回复“YES”的几率，实现对方接受自己提议的目的。\u003c/p>\u003cp>\u003cstrong>【I\u003c/strong>\u003cstrong>：讲解引导】\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 我们总习惯把脑海中的想法直接说出来。比如打扫卫生，想让正在看电视的老公帮忙时，很多人会这样说：“去把垃圾扔了。”得到的回答很有可能是：“我正在看电视呢”。再比如邀请意中人约会，很多人会说：“这周六有空吗？”，结果呢？对方直接回复：“没空”。其实只要换种说法，就能大大提升对方回复YES的几率。\u003c/p>\u003cp>这里的YES是指对方同意、接受的肯定回答，NO指拒绝、不同意的否定回答。\u003c/p>\u003cp>【举例】我举个例子，我小孩经常吃了晚饭就坐在房间看电视，我想要他饭后和我一起去跑步锻炼身体。这件事我认为非常重要，需要想好措辞再提出来。我如果直接说：“橙橙，你以后晚饭和我一起去跑步吧。”依我对孩子的了解他肯定会拒绝；拒绝跑步提议的原因是因为他觉得跑步比看电视无聊，没兴趣；接着我去分析他的需求，他非常喜欢去乐之书店看书。于是我说：“橙橙，每天晚饭后我们一起跑步去乐之书店看半个小时书怎么样?” 我把我和他的需求结合在一起提了出来。他一听开心的说：“太好了！”大家是不是感受到把NO变成YES这个方法的神奇之处了?从这个例子，可以看出是按下面这四个具体步骤来进行。\u003c/p>\u003cp>\u003cstrong>【细化行动建议步骤】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：防止脱口而出。\u003c/strong>和对方提出请求，开口前都先跟自己说：“stop”。越是重要时刻，措辞对结果的影响越大，越要想好了再说。这一步可以成功避免只考虑自己的感受和需求而忽略了对方。\u003c/p>\u003cp>\u003cstrong>第二步：猜测对方回应。\u003c/strong>根据对方平日表现，假设直接说出请求，猜测对方会对你的请求作出什么回应。无外乎出现两种情况：\u003c/p>\u003cp>1、对方回答YES的可能性大，可以直接说请求；\u003c/p>\u003cp>2、如果回答NO的可能性大，进行到下一步。\u003c/p>\u003cp>\u003cstrong>第三步：分析原因找需求。\u003c/strong>暂时忘记自己的请求，通过你对对方喜好、行为、性格的了解，站在对方角度去分析，是因为什么原因对你回复NO呢。比如我刚提议晚饭后去跑步的例子中，孩子拒绝是因为对跑步不感兴趣。\u003c/p>\u003cp>那么想一想对方在意的、关心的、感兴趣的人或事物是什么。这一步是为了站在对方的角度考虑，把对方的心理需求拿捏得越准确，得到YES的几率就越大，所以这一步很最关键。\u003c/p>\u003cp>\u003cstrong>第四步：双方需求达一致。\u003c/strong>这一步是要找出双方需求的一致点，比如刚才那个例子，孩子的需求是可以去书店看书，而我的需求是“晚饭后和我一起去跑步”，需求一致点就是：“每天晚饭后我们一起跑步去乐之书店看半个小时书。”满足了他的需求自然会回复YES，而我的目的也达到了。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>这个方法适用于认识的人，越是熟悉的人越能把握对方真正的需求，成功率更高。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【预防异议1\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>老实说，用这个方法并不能使所有NO的回答都变成YES，但它确实能提高可能性。如果原本说YES的可能性为0，那么能提高2-3成；如果原本的可能性为5成，就能提高到7-8成。\u003c/p>\u003cp>\u003cstrong>【预防异议2\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>有人可能会觉得四步有些麻烦，一、二步在大多情况下很快就完成了，更何况对于我们在意的事，多想一下就可以得到想要的回应，还是很值得的。\u003c/p>","interaction":"\u003cp>好的，这么一个实用又好用的方法，大家是不是很想练练手了呢？我现在出一个场景，请大家按小组进行现场演练，请大家认真听下。\u003c/p>\u003cp>\u003cstrong>【A3\u003c/strong>\u003cstrong>：场景演练】1\u003c/strong>0～15分钟\u003c/p>\u003cp>\u003cstrong>【场景设计】\u003c/strong>佳丽是一个12岁孩子的妈妈，这几年开始注重家庭教育，阅读了不少非常好的家教类图书。老吴是佳丽的老公，对待孩子的方式有些简单粗暴，孩子犯错会指责甚至动手。现在孩子进入青春期，出现了一些问题，佳丽看在眼里急着心里，希望老公能有正确的家教理念和教育孩子的方法，共同帮孩子平稳度过青春期。\u003c/p>\u003cp>于是她想要老吴看看《解码青春期》这本家教书，如果你是佳丽，你会怎么措辞，说服不爱阅读的老公接受这个提议呢？大家可按下面四步进行思考：\u003c/p>\u003cp>第一步：防止脱口而出。（想一想这件事对你的重要程度）\u003c/p>\u003cp>第二步: 猜测对方回应。（直接说对方会是什么反映）\u003c/p>\u003cp>第三步：分析原因找需求。（拒绝接受你的提议的原因是什么，对方在意的事物有哪些）\u003c/p>\u003cp>第四步：双方需求达一致。（找出双方利益的一致之处，提出满足双方需求的提议）\u003c/p>\u003cp>请大家一位扮演佳丽，另一位扮演老吴，根据给出的场景设计进行对话，演练时间6～8分钟，请大家开始，等会我会请小伙伴跟大家分享一下。\u003c/p>\u003cp>好，看到每组都讨论得很热烈，我也听到大家都很好的运用了以上步骤，我请肖肖这组跟大家分享一下。\u003c/p>\u003cp>小燕扮演佳丽，肖肖扮演老吴\u003c/p>\u003cp>小燕：\u003cstrong>（第一步防止脱口而出）\u003c/strong>孩子进入青春期后叛逆特征越来越明显，我需要老公改变他之前对待小孩简单粗暴的方式，学习科学的育儿方法。如果老公能看完《解码青春期》这本书，一定会有改变，所以这件事对我非常重要，所以我要想好了怎么说。\u003c/p>\u003cp>\u003cstrong>（第二步猜测对方回应）\u003c/strong>我如果直接拿着书跟他说：“你看下这本书吧，教你怎么带小孩。”估计他看都不看就拒绝我，然后丢我一句他常说的：“尽信书不如无书。”\u003cstrong> \u003c/strong>\u003c/p>\u003cp>\u003cstrong>（第三步分析原因找需求）\u003c/strong>他没有阅读习惯，不喜欢看书，而且觉得看书学习太费劲，效果来得慢。但是他内心还是很喜欢和孩子能友好相处，把孩子培养成优秀出色的人，如果能让他相信这本书很有针对性的解决他平常拿孩子没办法的那些问题，他一定有兴趣。\u003c/p>\u003cp>\u003cstrong>（第四步：双方需求达一致）\u003c/strong>老公，有没有发现儿子最近有不少进步？最近一次英语考试成绩也提升了？\u003c/p>\u003cp>老吴：对呀，最近是还不错。\u003c/p>\u003cp>小燕：告诉你，我就是看了《解码青春期》这本书，学到了很多方法，这些方法浅显易懂，很具实操性。\u003c/p>\u003cp>老吴：是吗？\u003c/p>\u003cp>小燕：对呀，而且这本书还有听书的音频，你可以在上下班的路上，在车里听听音频，不知不觉就学到育儿方法了。\u003c/p>\u003cp>老吴：那不错，你把音频发给我。\u003c/p>\u003cp>小燕：好嘞。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>感谢两位小伙伴的分享，灵活运用了这四个步骤，我们在听的过程都感受到了强有力的说服。\u003c/p>\u003cp>希望大家在提请求时能多使用今天学到的方法，不仅可以帮我们实现目的，还可以帮助我们发展人际关系，感受到生活中更多的美好。\u003c/p>\u003cp>今天我的分享就到这里，再次感谢伙伴们的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1574932030000,"updated_at":1574932030000,"ria":true},{"id":9328,"topic":"把“NO”变成“YES”的说话技巧","learn_goal":"通过措辞技巧，给出“选择的自由”，完美掌握把“NO”变成“Y","remark":"工作汇报，生活沟通中，你羡慕那些高情商，会说话的人精吗？你希望对方能愉快的对你有求必应，只说“YES”吗？\t 那么一起学习把把“NO”变成“YES”的措辞菜谱吧！","level":"TF2-1","duration":15,"status":29,"type":0,"chaishujia":{"username":"Yoyo Zhang","city":"无锡"},"club":{"name":"无锡太湖分舵","city":"无锡"},"prologue":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;大家好我是今天的一级拆书家YOYO，用三个标签介绍一下我自己：工作上是一位通讯行业 外贸创业者；生活里的运动爱好者，喜欢徒步、瑜伽、跑步等；自我管理层面的英语学习精进者，目前英语专业八级，为了自由的灵魂，每天学习一点英语。\r\n今天是我的TF2-1分享，后面会有小组讨论和分享的环节，所以我们先来分一下组，右边的毛世佳，李虎野人和许杰你们三位一组，友爱和张文师姐你们一组。\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 【F】今天给大家分享《所谓情商高就是会说话》这本书，作者是佐佐木圭一，他被称为日本顶级沟通专家、广告鬼才、亚洲最成功的广告策划人。这本书告诉我们讲话不只是一种“感觉”，还是一门“技术”！就像烹饪有食谱一样，是有谱可循的。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 【A】相较于市面上常见的沟通类图书，本书行文简单，案例更鲜活和容易落地，介绍了“7个突破口”和“8个技巧”的“措辞菜谱”，就像一本烹饪教材，随学即用，让我们不走弯路，以最短的时间掌握说话技巧。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;【B】本书作者原本不擅长沟通和表达，他是在历经无数次失败之后发现了打动人心的语言奥秘，掌握了这个语言法则之后他的人生一下子发生翻天覆地的变化。你想能驾驭任何聊天场合，和任何人都聊得来吗？希望在面试中用一个高情商的回答来赢得一次职场机会吗？希望约会时用一个优雅的措辞，抱得美人归吗？ 那么这本书可以帮助我们学会人际沟通中的措辞菜谱；领悟说话精髓，悟透说话之道很快在人群中脱颖而出。今天分享是让我们在沟通中不再被拒绝的措辞菜谱，能让对方主动选择“YES”，轻松修炼我们的说话能力，成为说话高手。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 我现在把原文拆页发给大家，请大家花两分钟时间自己阅读一下这段文字，读完的小伙伴麻烦举手示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":13114,"quote":"\u003cp>\u003cstrong>原文拆页【P28-29】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【选择的自由】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>关键在于，要给出两个合适的选项，无论对方选择哪个，自己都能达到目的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“要不要来份甜点?\u003c/strong>\u003c/p>\u003cp>在餐厅刚吃完饭的客人，听到侍者这样问，如果是喜欢甜食的人，可能就会叫份甜点，但不是特别喜欢甜食的人大概就不会叫。在这种场合，有种措辞能顺利卖出甜点，从而提升销售额。那就是：\u003c/p>\u003cp>\u003cstrong>“甜点有芒果布丁和抹茶冰激凌，您要哪种?”\u003c/strong>\u003c/p>\u003cp>这样一问，有些人就会不假思索地做出选择，比如“要哪种呢…芒果布丁!”\u003cstrong>面对两个乃至更多的选项，一般人都会下意识地从中做出选择。\u003c/strong>甜点的利润较高，所以餐厅希望尽可能多的客人叫甜点吃。只要稍微改变店员的措辞，就能提高销售额。\u003c/p>\u003cp>想找到“选择的自由”这个突破口，关键是要给出两个合适的选项，无论对方选择哪个，自己都能达到目的。\u003c/p>\u003cp>“吃甜点还是喝茶?” \u003c/p>\u003cp>如果是这样的选项，一旦对方选择“茶”，自己就赚不到钱了，而无论是“芒果布丁”还是“抹茶冰激凌”，都有赚头，所以要让客人从这两个选项中做出选择。\u003c/p>\u003cp>\u003cstrong>归根结底，这种“选择的自由”是由对方决定如何选择，所以对方能产生“自主选择”的意识，被迫的感觉就会减少。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>步骤1不直接说出自己的想法\u003c/strong>\u003c/p>\u003cp>à要不要来一份甜点？\u003c/p>\u003cp>\u003cstrong>步骤2 揣摩对方的心理\u003c/strong>\u003c/p>\u003cp>Xà不大爱吃甜食\u003c/p>\u003cp>Oà对选择哪种甜点感兴趣\u003c/p>\u003cp>\u003cstrong>步骤3 考虑符合对方利益的措辞\u003c/strong>\u003c/p>\u003cp>Oà甜点有芒果布丁和抹茶冰激凌，您要哪种？\u003c/p>","explains":"\u003cp>好的，我看到大部分小伙伴都已经阅读完了，如果有还没读完的小伙伴也不要紧，下面我会带领大家一起来解读这段文字。&nbsp;\u003c/p>\u003cp>【What】沟通中需要别人做肯定回应时，可以利用“选择的自由”来引导对方在两个合适的选项中自主选择，来达成我们自己的目的。\u003c/p>\u003cp>【Why】人们总是倾向于做选择题而不是问答题，当被问到“A和B选哪个”的时候，一般人都会从中选择一种。选择的自由是由去对方决定如何选择，所以对方能产生“主动选择”的意识。\u003c/p>\u003cp>【How】这个方法的关键环节是要事先准备好两个能满足我们目标的选项，具体可以参考如下三步措辞法：\u003c/p>\u003cp>第一步：按下不表，即不要直言不讳的出自己的想法；像片段中的不直接说“要不要来一份甜点？”\u003c/p>\u003cp>第二步：揣摩对方想法，揣摩一下对方的心理是怎么想的； 比如片段中琢磨“可能不爱吃甜点，但是对选择甜点感兴趣呢？”\u003c/p>\u003cp>第三步：选择合适双方的有利的措辞，能符合对方的利益，又能满足我们的目标； 比如“芒果布丁和抹茶冰激凌，您要哪种？”\u003c/p>\u003cp>\u003cstrong>【强调不按拆页行动建议去做的坏处】\u003c/strong>\u003c/p>\u003cp>那如果不这样做有什么坏处呢？如果不给对方选择的自由，而是直接表达自己的想法，对方会有被迫接受的压力，会抗拒或者拒绝我们的提议，不能达到我们想要的结果还伤了和气。\u003c/p>\u003cp>举个例子：孩子每天放学回来进家门之后不喜欢穿拖鞋，而我希望他能在回来后自己主动换上拖鞋，我的做法是大喊去命令他回来换鞋，或者揪着他过来穿鞋，经常因为这个事情伤脑筋或者生气。\u003c/p>\u003cp>如果用到上述“选择的自由”的方法，可以这样做：不直接叫儿子或者揪着他回来穿拖鞋，而是说：“米奇拖鞋和驴头拖鞋，你想穿哪一双？”我想他会主动选择他喜欢的米奇拖鞋。这样从儿子的角度，没有人强迫他，而是自己主动选择穿了自己喜欢的鞋子，达到了我希望他换上拖鞋的目的。&nbsp;&nbsp;\u003c/p>","interaction":"\u003cp>【显像提问，激活经验】\u003c/p>\u003cp>如下这些场景，大家一起看看熟悉吗？\u003c/p>\u003col>\u003cli>\u003cp>晚饭后希望老公能主动去把垃圾扔了，却被拒绝了；\u003c/p>\u003c/li>\u003cli>\u003cp>餐桌上你想让孩子多吃点蔬菜，而他却当做耳边风；\u003c/p>\u003c/li>\u003cli>\u003cp>工作中你邀请大家开会时，总有一些人会有各种理由借口不参加会议…总是各种事与愿违。\u003c/p>\u003c/li>\u003c/ol>\u003cp>那么请大家也一起来回顾一下，最近一周或者一个月内，你有没有眼巴巴的希望对方能肯定回答，却被拒绝的经历呢？回顾一下那时候你是怎么说的？请想一想，在小组内分享一下。\u003cbr>\u003c/p>\u003cp>好的，感谢大家的积极讨论，那么如果时光回到那时，用今天的措辞菜谱，你会怎么说呢？给大家5分钟时间，先在小组内讨论分享。5分钟过后我会请一位小伙伴来给大家做分享。\u003c/p>\u003cp>\u003cstrong>（5分钟过后）\u003c/strong>\u003c/p>\u003cp>好，时间到，刚才看到大家都讨论得很热烈！有哪位小伙伴可以来给我们分享一下呢？先给大家介绍一下你想起的那次难忘的被拒绝的经历，然后假设现在又回到了那个时点，你会怎样措辞，给对方以“选择的自由”来获得对方“YES”的回答呢？\u003c/p>\u003cp>【案例分享】\u003c/p>\u003cp>蠡湖野人说：他自己喜欢跑步，女朋友却不怎么爱运动，他希望女朋友晚上能陪她一起出去运动。学了这个方法，会这样去用：不直接要求，推测女朋友可能不想跑步，可能愿意去百米喷泉广场拍照，所以他会说“晚上出去一起出去运动时，你选择跟我一起跑步去百米喷泉拍照，还是你骑自行车我跑步追你一起去百米喷泉呢？”这样引导女朋友主动选择一起出门，达到了蠡湖野人让女朋友出门运动的目的。\u003cbr>\u003c/p>\u003cp>友爱说：她儿子写作业时会说想先看动画片再写作业，而自己希望儿子先写作业，以前的做法是让儿子选择先做英语还是先做数学作业，但是效果不太好。她会换个方法：不直接要求，而是猜测儿子想看电视的心理，这样说：儿子，先看5分钟电视再开始做数学作业，和先做作业，完成之后可以看10分钟动画片，你选择哪一个啊？她想儿子一定会选先做作业再看10分钟，这样就能满足儿子看动画片的愿望同时满足自己让儿子先完成作业的目的。\u003c/p>\u003cp>好的，非常感谢两位小伙伴的分享！时间关系，我们今天的分享就到这里了。希望大家学会了今天的“选择的自由”这道菜谱，未来工作生活中多多运用，沟通中能多多如愿以偿。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":13115,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1574579630000,"updated_at":1574580312000,"ria":true},{"id":9126,"topic":"把“NO”的回答变成“YES”的三个步骤","learn_goal":"通过学习，将回答“YES”的可能性提升2-3成。","remark":"说话不只是一种“感觉”，还是一门“技术”！就像烹饪有食谱一样，说话也有它的‘秘方“。古往今来，但凡不通说话之道者，都难成大事，而能成事者，一定语言方面具有独特的能力。一句恰到好处的话，甚至可以改变一个人的命运。人际沟通中怎样措辞？怎样把握说话的场合和时机？如何领略说话精髓，悟透说话之道，很快在众人中脱颖而出？\r\n作者通过自己多年来掌握的语言措辞技巧告诉大家该如何修炼说话能力，如何提高自己的说话水平。在本书中，你可以通过熟悉”7个突破口“和”8个技巧“，并阅读大量实践故事，更好地掌握运用语言措辞的技巧，使自己成为说话高手。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"阅良","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>&nbsp; &nbsp; 大家好，我叫阅良。下面我用三句古诗作为标签来介绍一下我自己。\u003c/p>\u003cp>&nbsp; &nbsp; 第一个标签是：采菊东篱下，悠然见南山。作者陶渊明，我们家族祠堂供奉的就是他。\u003c/p>\u003cp>&nbsp; &nbsp; 第二个标签是：落霞与孤鹜齐飞，秋水共长天一色。这是王勃描写滕王阁的美景，滕王阁位于南昌，那是我的家乡。\u003c/p>\u003cp>&nbsp; &nbsp; 第三个标签是：衣带渐宽终不悔，为伊消得人憔悴。这是王国维先生描写的读书三个境界之一，作为学习者，这也是我一直追求的学习态度。\u003c/p>\u003cp>&nbsp; &nbsp; 今天来的小伙伴，有几位是第一次参加活动的，让我简单介绍一下拆书法和拆书帮。\u003c/p>\u003cp>&nbsp; &nbsp; 首先，我来谈谈什么是拆书法。\u003c/p>\u003cp>&nbsp; &nbsp; 在中国，“拆”字有着特别的意义，尤其是我们经常在一堵墙上看到拆字，然后划了一个圈，这就代表着财富。同样，这里的“拆书”的“拆”也是提升能力、获得财富的重要手段之一。“拆书法”就是将书中的片段或者知识转化与内化，形成能力为学习者所用的一种方法。就像我们自己构建自己知识能力大厦时，需要的砖头，通过一种方法从许多书本中拆解出来，偏大偏小都不适合自己。这种以学习者为中心的方法称为“RIA”便签学习法。\u003c/p>\u003cp>&nbsp; &nbsp; R：代表原文，就是学习者受启发的知识片段。\u003c/p>\u003cp>&nbsp; &nbsp; I：代表理解，就是用自己的话复述知识。\u003c/p>\u003cp>&nbsp; &nbsp; A：代表运用，一是联系经验，将知识与以往经验建立连接；二是规划运用，将知识运用在未来场景当中，制订行为计划。\u003c/p>\u003cp>&nbsp; &nbsp; 接下来，我来介绍一下什么是拆书帮。\u003c/p>\u003cp>&nbsp; &nbsp; 拆书帮是基于拆书法的学习爱好者社群，是一个非营利性青年自组织，其使命是释放学习促进者的能量，帮助更多学习爱好者成为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":12884,"quote":"\u003cp>把“No”的回答变成“Yes”，有3个步骤。\u003c/p>\u003cp>步骤1：“不直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。在这种时候，请不要直接说：“大家继续吃啊！”\u003c/p>\u003cp>步骤2：“揣摩对方的心理”\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。”这应该就是家人的想法。此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>已经阅读完了的小伙伴可以举手示意一下。刚刚大家都看了拆页，那么我来谈谈我的理解。\u003c/p>\u003cp>大家回想一下，我们工作、生活中经常遇到一些沟通的场景，比如你想约心仪的女孩共进晚餐，或者是你想要家里孩子帮做家务等，很多时候回应都是“NO”，其中就有措辞的原因。好的措辞可以使对方配合，达到我们的目的。不懂得措辞或者表达不当，不仅不会达到我们的目的，甚至导致误解或者矛盾。当你想向对方提出请求，对方有可能回答“NO”时，采取以下“N2Y三步法”，可以增加“YES”回答的可能性。那么是哪三步呢？\u003c/p>\u003cp>第一步，不要明说自己的请求。比如：我想请家里小孩去倒垃圾，如果预判他会拒绝，就不要明说要她去倒垃圾。\u003c/p>\u003cp>第二步，猜测对方对此的想法。在提出请求前，猜测对方可能的想法是什么？如叫她去倒垃圾，她的想法肯定是，倒垃圾那么累，我才不去呢。\u003c/p>\u003cp>第三步，将自己的请求符合对方的利益来措辞。比如，她觉得倒垃圾很累，那么就找一个更累的家务给她选择，如拖地。可以问她：现在每个人都要做家务，你是愿意倒垃圾还是愿意拖地呢？她很有可能会选择最轻松的倒垃圾，那么你的目的就达到。\u003c/p>\u003cp>&nbsp; &nbsp; 这就是N2Y三步法的魔力。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1:\u003c/strong>\u003c/p>\u003cp>我们日常生活中可能会遇到许多类似的情形，比如我们向朋友、向领导、向家人提出请求时，希望得到肯定的回答，但往往事与愿违。现在我分享一个我与我女儿的例子。我女儿YOYO今年5岁半，平时特别挑食，也不轻易尝试新的食物。上个月的一天，我们在家吃晚餐，煮了一道猪肝汤，之前YOYO也没吃过，所以根本没有动筷。我跟YOYO说：快吃点猪肝，对眼睛好。YOYO一眼嫌弃地看着，还做了个恶心想吐的动作说：不吃！我说：你尝一下，很好吃的，不信你问妈妈。YOYO继续说，不吃不吃，好吃你们多吃点。\u003c/p>\u003cp>没有办法，我沉默了一会，想有什么办法让她吃点，然后说：YOYO，你喜欢看IPAD，但看IPAD很伤眼睛咯，如果吃了猪肝，看IPAD眼睛就不会那么累了，可以多看一会儿了。YOYO一听，说：那我试一小块吧。吃过一小块后，她觉得味道不错，继续说还要吃了……\u003c/p>\u003cp>通过这件事情，对比N2Y三步法进行反思，我似乎说错了一些内容，然后无意识地说对了一些内容，主要存在以下三个问题：\u003c/p>\u003cp>1、直接说出了我的请求，叫YOYO吃猪肝，由于她一直不敢尝试新食物的特点，肯定是会拒绝的。\u003c/p>\u003cp>2、没有猜测她对此的想法。她年纪小，根本不懂，所以没有去考虑她对吃猪肝这件事情的想法。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 3、没有将自己的请求符合她的利益来措辞。我只是单方面要她补充营养，她是拒绝的，但是后来我将她关心的看IPAD眼睛不累，可以多看一会儿，与吃猪肝联系在一起，利益趋同，她就是同意了。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>由此看出，N2Y三步法是一种比较有效的方法，本周计划用此方法与YOYO沟通主动收拾玩具的事项。\u003c/p>\u003cp>主要行动有：\u003c/p>\u003cp>1、不要明说自己的请求。我的请求就是让她能收拾玩具，先不明确告诉她。\u003c/p>\u003cp>2、猜测对方对此想法。如果叫她收拾玩具，她的想法肯定是，收拾玩具一点都不好玩。\u003c/p>\u003cp>3、将自己的请求符合对方的利益来措辞。什么是好玩的呢？YOYO平常喜欢跟我玩围棋，我将提出在她房间玩，她肯定说好。我就说，但房间这么乱，都没地方下脚，要不先收拾房间再玩吧。玩围棋是她的利益所在，将我的请求“收拾玩具”与她的利益“玩围棋”绑定起来，她应该会同意的。\u003c/p>\u003cp>如果目标达成，奖励自己看一部电影；如未达成目标，继续研读本书。\u003c/p>\u003cp>&nbsp; &nbsp; 今天我的分享到此，希望大家对N2Y三步法有所了解，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1571804393000,"updated_at":1573709793000,"ria":true},{"id":8942,"topic":"用投其所好的措辞技巧达成双赢","learn_goal":"运用投其所好的措辞，提高对方说“YES”的成功率","remark":" 大家有没有过这种经历，向对方请求帮助，或提出建议，却遭到拒绝?有没有方法可以提高我们的成功率呢？这本书教我们运用“7个突破口”和“8个技巧”搭配出感人的语言，提高我们表达的成功率！","level":"TF3-1","duration":50,"status":30,"type":0,"chaishujia":{"username":"littledl2019","city":"大连"},"club":{"name":"大连知行分舵","city":"大连"},"prologue":"\u003cp>【学习目标】\u003c/p>\u003cp>通过这个片段的学习，学习者在向别人提出建议或请求帮助时（where），能够运用（行为）投其所好的措辞技巧，表达出对方容易接受且符合对方利益的措辞（澄清），并能区分出个人视角和投其所好的措辞的差别（界定），避免因直接说出自己的想法而被拒绝或误解。\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>&nbsp;大家好，我是朱晓丹，非常感谢大家来参加我的拆书练级活动。用三个标签介绍一下我自己，第一个标签是工程设计，第二个标签是学习爱好者，第三个标签是成长，我参加拆书帮也是挑战自我选择成长的过程。\r\n现在先分组下组，这边两位小伙伴一组，这边两位小伙伴一组。\r\n【图书介绍】\r\n【事件场景】前阵子，我们公司有个项目要的比较急，领导就和大家说：“大家最近加加班，把活儿赶一赶。”但是公司里那些90后完全不听，下班就走，领导着急和他们一点关系都没有。但是因为部门现在缺人手，也不太深说他们。&nbsp;\u003c/p>\u003cp>【提问】你们如果遇到这种下属会怎么和他们进行沟通呢？在不考虑物质激励的情况下，有没有办法说服他们？\r\n【影响】我们每天都会向别人提出很多请求，比如向同事、家人给出一些建议，或者请他们帮些忙，如果我们没有一种适当的表达方式，有时就会很容易遭到拒绝，严重的还会导致误解，影响我们的人际关系。\r\n【解决】我今天分享的片段选自《所谓情商高就是会说话》，作者佐佐木圭一，是日本顶级沟通专家、文案写作大师。这本书把措辞的技巧比喻为菜谱，教我们运用“7个突破口”和“8个技巧”搭配出感人的语言。如果你在生活当中经常会遭到别人的拒绝，今天这个片段可以提高对方说“Yes”的成功率。\r\n下面请大家阅读一下原文片段，时间是1分钟。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":12675,"quote":"\u003cp>P16-17\u003c/p>\u003cp>电影《快乐飞行》里曾出现令人不禁点头赞许的巧妙揩辞。在该影片中，绫濑遥饰演某航空公司的新人空姐。在分配供餐的一幕，由于乘客大多优先选择牛肉，所以导致鱼大量剩余。\u003c/p>\u003cp>就在新人空姐面临重大危机的关头，经验丰富的前辈说道:“像平时一样平均分配！看好了。”然后展现了高超的措辞技巧：\u003c/p>\u003cp>“机内供应以优质香草、富含矿物质的天然岩盐和粗制黑胡椒嫩煎而成的白身鱼，以及普通牛肉。”\u003c/p>\u003cp>由于是电影，其中自然存在表演成分，但前辈空姐这样一说，乘客确实会觉得鱼更好吃。后来，当前辈空姐询问乘客的选择时，绝大多数乘客都主动选择了鱼。这里就使用了“投其所好”的“措辞菜谱”：\u003cbr>\u003c/p>\u003cp>“对不起，只剩鱼了。”\u003c/p>\u003cp>如果空姐这样说，乘客就会觉得自己简直成了废品回收站，哪里还有吃东西的心情，而像前辈那样说，乘客就会心甘情愿地主动选择鱼。这就是措辞的力量。\u003c/p>","explains":"\u003cp>拆书家：大家都已经读完了吗？这个片段介绍的是什么技巧？\u003c/p>\u003cp>学习者：是投其所好的一种说话方式\u003cbr>\u003c/p>\u003cp>拆书家：那什么是“投其所好的措辞技巧”？\u003cbr>\u003c/p>\u003cp>就是要站在对方的角度，分析对方的需求，然后表达出对方容易接受的语言。\u003c/p>\u003cp>【易混淆的概念】\u003c/p>\u003cp>我们举几个例子来对比一下。\u003c/p>\u003cp>拆书家：比如说，我有一个朋友，整天沉迷游戏，如果我说：“你怎么成天打游戏，有时间看看书多好。”这是不是投其所好的措辞？\u003c/p>\u003cp>学习者：不是。\u003c/p>\u003cp>拆书家：这个属于直接建议，我没有考虑他的感受，可能他不太愿意听，这里我没有搁置自己的观点。\u003c/p>\u003cp>再比如说，我在商场看到一件衣服，问营业员这件还有没有了。营业员说：“只剩这一件了。”这是不是投其所好的措辞？\u003c/p>\u003cp>学习者：不是。\u003c/p>\u003cp>拆书家：非常好。这里她可能想表达一种稀缺营销，但是她没有分析我的需求，我虽然这么问，但其实我更想知道的是这件衣服我穿起来好不好看。\u003c/p>\u003cp>再比如说，我一个朋友想减肥，一起在外面吃饭时，我一直提醒她说：“这个菜太油了，那个热量太高了……”这是不是投其所好的措辞？\u003c/p>\u003cp>学习者：不是。\u003c/p>\u003cp>拆书家：虽然我没有直接说这个不利于减肥，但是我一直在反复强调自己的观点，这有点像是多次评判，我的观点对方不愿意接受。\u003c/p>\u003cp>那怎样才是投其所好的措辞呢？比如说，你看到家里小孩把玩具扔的满地都是，这时你跟他说：“宝宝，我们一起来做个游戏吧，我们把玩具放到篮子里，看谁放得快，好不好？“这是不是投其所好的措辞？\u003c/p>\u003cp>学习者：嗯，是。\u003c/p>\u003cp>拆书家：相对好一点。这里你首先搁置自己的观点没有直接说出来，没有去责备他；然后而是分析他的需求，他可能喜欢和别人一起玩一起做游戏；然后表达符合他利益的措辞，然后从这个角度来表达，也会让他有点兴奋，把这个当成一个游戏。\u003c/p>\u003cp>（从概念对比引出适用边界）\u003c/p>\u003cp>在我们向别人提出请求或给出建议时，我们发现有些时候直接说对方是可以答应的，这种情况下直接说就可以。当你判断你的请求容易遭到对方拒绝的时候，就可以尝试用这个方法，虽然不一定保证百分之百成功，但是能提高一定的成功率。\u003c/p>\u003cp>（how）\u003c/p>\u003cp>所以，从片段的学习和刚才的分析，我们归纳出投其所好的措辞技巧的三个步骤：\u003c/p>\u003cp>1. 搁置自己的观点：忍住不要直接说出来，实在忍不住时就数数，12345……\u003c/p>\u003cp>2. 分析对方的需求，我们最好对对方有一定的了解，判断对方看重什么、需求点在哪儿。\u003c/p>\u003cp>3. 表达出符合对方利益的措辞：要让对方很容易接受的，可以说你的请求能带给对方哪些好处、带来哪些利益。\u003c/p>\u003cp>回到前面的例子，我们领导希望大家免费加班，就可以使用这个方法。\u003c/p>\u003cp>首先搁置自己的观点，不直接说让大家加班。\u003c/p>\u003cp>然后，分析对方的需求，90后可能不喜欢重复性的工作，更喜欢有挑战性的，有发展空间的。\u003c/p>\u003cp>第三步，表达出符合对方利益的措辞，可以说，这个项目是公司以后准备重点发展的项目，它的技术在国内也是处于领先水平，大家把这个项目好好干，以后大家都是骨干，很有可能都有机会带团队。最近大家都紧张一点。\u003c/p>\u003cp>可以用这个方法试验一下。\u003c/p>","interaction":"\u003cp>接下来我们做一个练习，在未来的一个月当中，你在工作和生活当中有没有这样的场景？要说服客户购买你们公司的产品或者接受一个技术方案？或者你想建议朋友读一本书、或者建议她减肥？请每组小伙伴运用 “投其所好的措施技巧”的三个步骤编一个小剧本，要求包括时间、地点、人物、事件、动作、对话等。\u003c/p>\u003cp>请每组先在小组内讨论，把摘要写下来，时间是5分钟。一会儿要请一组小伙伴分享一下。\u003c/p>\u003cp>接下来请一组小伙伴分享一下。\u003c/p>\u003cp>时间：9月中秋节\u003c/p>\u003cp>地点：家里\u003c/p>\u003cp>人物：我和我表弟\u003c/p>\u003cp>事件：表弟谈恋爱，不学习\u003c/p>\u003cp>对白：\u003c/p>\u003cp>学习者1：首先，我要搁置我自己的观点，他不学习，我不能直接批评他。然后，我要分析对方的需求，我觉得对方很可能希望女生认可他，也希望甜蜜长久。\u003c/p>\u003cp>表弟，中秋节了，我看你交女朋友了，是不是特别开心啊？\u003c/p>\u003cp>学习者2：对呀，特甜蜜。\u003c/p>\u003cp>学习者1：是不是特别希望你女朋友特别崇拜你，然后认可你呀？\u003c/p>\u003cp>学习者2：那还用说？\u003c/p>\u003cp>学习者1：你是不是希望以后能长久的和她在一起？你女朋友是不是学习特别好？\u003c/p>\u003cp>学习者2：嗯\u003c/p>\u003cp>学习者1：有个好方法，能让你和你女朋友长久在一起，你们俩共同努力，都考上同一所大学的话，幸福就会长长久久。怎么样，表弟？\u003c/p>\u003cp>学习者2：我觉得你说的有道理，我好好考虑考虑，我会努力学习的。\u003c/p>\u003cp>学习者1：特别希望中秋佳节，你能和她聊一聊，看看怎么去学习，然后共同进步，今后能够长久的幸福噢。\u003c/p>\u003cp>学习者2：知道了。\u003c/p>\u003cp>非常谢谢两位小伙伴的分享。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>今天我们一起学习了“投其所好的措辞技巧”的三个步骤，第一，搁置自己的观点；第二，分析对方的需求；第三，表达出符合对方利益的措辞。通过这向个步骤，虽然不一定能百分之百地说服对方，但是可以提高对方接受我们观点的成功率，也可以为我们争取很多的机会，希望大家以后在工作和生活当中多练习这个方法，使用的更加自如。\u003c/p>\u003cp>我的分享就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1569462988000,"updated_at":1569467170000,"ria":true},{"id":8935,"topic":"让别人对你Say YES的说话神器","learn_goal":"掌握提升对方接受自己提议的方法","remark":"","level":"TF2-4","duration":55,"status":30,"type":0,"chaishujia":{"username":"许曼","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>&nbsp;大家好！我叫许曼，大家都叫我馒头。用三个标签介绍自己，都和书有关。\u003c/p>\u003cp>第一个标签：图书。我在一家书店工作，每天都和图书、和看书的读者打交道。\u003c/p>\u003cp>第二个标签：读书。因为喜欢读书所以进入了图书行业。每当我发现一本心仪的书都会欣喜好一阵。\u003c/p>\u003cp>第三个标签：拆书。近几年看实用类的书比较多，很幸运遇到了拆书帮·麓山分舵，开启我全新的看书模式。\u003c/p>\u003cp>\u003cstrong>（F）：\u003c/strong>我今天拆解的片段来自《所谓情商高 就是会说话》这本书，这是一本快速提升沟通能力的书，作者佐佐木圭一，从一个原本不擅长沟通和表达的人，成为拥有自己公司，在日本被称为顶级沟通专家、广告鬼才、方案写作大师，并成为首位获得美国广告大奖“金铅笔奖”的日本人，被视为亚洲最成功的广告策划人，这本书是他成功方法的浓缩，本书主要讲了作者亲身实践中总结的关于如何说话的“7个突破口”和“8个技巧”。\u003c/p>\u003cp>\u003cstrong>（A）：\u003c/strong>和市面上沟通类的书相比，更注重实操性。作者说，说话如做菜，有谱可循，只要掌握了基本菜谱，任何人都能做出美味佳肴。书中例举了大量的实践故事，所以它是一本拿来用而不是拿来读的书。\u003c/p>\u003cp>\u003cstrong>（B1）：\u003c/strong>你是否想尽快掌握打动人心的语言暗藏的规则？搞定不肯合作的同事、不肯做家务的老公、捣乱的熊孩子，这本书提供的沟通方法总有一款适合你。\u003c/p>\u003cp>\u003cstrong>（B2）：\u003c/strong>\u003cstrong>我今天拆解的两个片段，就是帮你实现不被拒绝的双重保险，让你搞定那些可能会拒绝你的人把NO变成对你说YES。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>等会会有小组讨论和分享的环节，我们的分组仍沿用前面的分组方式。\u003c/p>\u003cp>好，现在请大家先阅读手中的原文片段一，1～2分钟时间，阅读完后请用眼神示意下我。\u003c/p>","ratings_count":2,"texts":[{"id":12666,"quote":"\u003cp>\u003cstrong>听到“只有你是特别的”，人就容易被说动。\u003c/strong>\u003c/p>\u003cp>据说二十多岁的年轻人不会和上司喝酒。\u003c/p>\u003cp>我的朋友问公司的一个新人：“去喝酒吧？”\u003c/p>\u003cp>对方却反问：“为什么要去喝酒？”\u003c/p>\u003cp>朋友根本没想到对方会如此反问，慌忙回答：“啊，你要是忙就算了。”\u003c/p>\u003cp>这个时代就是这样。\u003c/p>\u003cp>朋友的烦恼还没完。部门里有酒会，朋友负责组织。\u003c/p>\u003cp>部长对他说：“上次人来得不全，这次一定要把人都叫来。”\u003c/p>\u003cp>可是大危机啊。朋友仔细考虑后，使用了这样的措辞：“市川，你不来不热闹，所以只有市川你务必得出席啊。”\u003c/p>\u003cp>他把这条信息发给了所有部门成员。当然不是群发而是对应姓名逐一发送的。结果，当天的部门酒会全员到齐。这就是利用了“非你不可”这一措辞突破口。\u003c/p>","explains":"\u003cp>好的，看到小伙伴们都已阅读完毕。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>跟随我完成本次RIA现场学习后，能在面对可能的拒绝时，通过“非你不可”措辞法：“明确自己需求——找出对方优势——突出非你不可”这三步，让对方感到被重视和优越感，从而降低拒绝你的几率。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【更贴近实际的例子】\u003c/strong>\u003c/p>\u003cp>我们日常生活很多事情都需家人、朋友或同事的帮助或一起完成，但不是每次都能顺利得到对方的支援或加入对吗，比如上个月，我们书店举办一场宫西达也系列绘本的读书分享会，想邀请亲子阅读推广人佳丽来主持，因为她非常喜欢宫西达也的绘本，主持也很有经验，于是我打电话跟她说：“佳丽，周六我们会举办一场宫西达也绘本分享会，你来做主持怎么样？”只听电话那头的佳丽回复：“我那天不一定有时间哦。”这样的回复无异于是委婉的拒绝\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【坏处】\u003c/strong>从上面的例子可以看出，我的邀请没有打动对方，她觉得来不来都无所谓，我这边还可以请其他人。对于一件非常重要的事，如果开口前没经过思考就提出，很容易导致失去很多原本可能实现目的的机会。\u003c/p>\u003cp>过了两天我不甘心，用了片段中所提的方法，为了便于理解，我把步骤进行了加工细化，我是这么做的:&nbsp;\u003c/p>\u003cp>\u003cstrong>【变成正面例子】【细化原文行动步骤】&nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：明确自己需求。\u003c/strong>我的需求是希望佳丽能来做主持人。\u003c/p>\u003cp>\u003cstrong>第二步：找出对方优势。\u003c/strong>我之所以很想请佳丽，是因为她主持功力不错，而且她很喜欢宫西达也的绘本，又和这次做分享的嘉宾曾经有过合作，配合默契，相信现场一定会擦出漂亮的火花。\u003c/p>\u003cp>\u003cstrong>第三步：突出非你不可。\u003c/strong>我又打通了她的电话说：“佳丽，我知道你是宫西达也绘本的忠实读者，又和分享嘉宾露露老师是黄金搭档，这个主持人还真只有你佳丽最最合适。”最好加上对方名字，这样更能增强效果。只听电话那头的她，笑了笑说：“好吧，我那天过来。”\u003c/p>\u003cp>佳丽从不一定有时间到满口答应，可以说“非你不可”的措辞法起到了重要的作用，让她感受到我对她的重视程度，以及言词中透漏出只有她被选中的优越感。一般人当听到“只有你才能”“只有你才是”，就很容易被说动，从而乐于做出回应。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>当然，我们提要求时，不是只要用上“非你不可”三步法，对方就一定满口答应，毕竟影响事情的因素有多种原因，但是可以肯定，同样的条件同样的内容下，用上“非你不可”的说法比直接提要求，对方同意的几率会大大提升。\u003c/p>","interaction":"\u003cp>【\u003cstrong>A1\u003c/strong>】\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;为了更好地将这个方法运用于实际，现在我们来联系一下自己的过往经验，请大家回顾一下，最近有没有被拒绝的事？\u003c/p>\u003cp>\u003cstrong>【显像提问法】\u003c/strong>比如请财务部的负责人对你做的激励方案给出意见，对方回复没时间；你组织的一个读书会，邀请某大学的读书社团团长参加，对方却没出现；做家务活的时候，请你家高个子老公帮忙擦玻璃，他跟你说现在很忙。类似这样的事发生在什么时候？具体是一个什么情况？请大家把时间、地点、人物、和事件的关键词写在纸上，欢迎小伙伴举手分享。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>学习者威丽：上个月邀请我的一位老客户黄总参加我们公司周年庆活动，当时把公司设计的统一的电子版邀请函，转发到黄总的微信，过了两天和他联系，告知我那天来不了。没能邀请他到现场，被老板批了一顿。\u003c/p>\u003cp>好，谢谢威丽的分享，类似这样的事我们经常在生活或工作中遇到，我们如果换一种邀请方法，是不是能提高对方接受的几率呢？\u003cbr>\u003c/p>\u003cp>\u003cstrong>【A1+指令】\u003c/strong>当大家再遇到这种情况，应用拆页中的方法会如何处理？请各位参照建议步骤思考一下。注意是运用“非你不可”三个步骤来处理：1.明确自己需求；2.找出对方优势；3.突出非你不可。\u003c/p>\u003cp>学习者威丽：用非你不可三步法，我会这样做：\u003c/p>\u003cp>1、明确自己需求：我的需求是一定要邀请到黄总参加周年庆活动。\u003c/p>\u003cp>2、找出对方优势：公司老客户，在我们公司有分量。\u003c/p>\u003cp>3、突出非你不可：我不会再发没有温度的邀请函模板，我会打电话和黄总直接沟通，跟他说：“黄总，您在我们公司的地位可是举足轻重啊，您要不来周年庆都少了很多色彩，只有黄总您来了，这个周年庆才叫圆满。”\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cbr>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>再次感谢威丽的分享，这样说瞬间就突出了你对黄总的重视程度以及给对方的优越感。刚才其他小伙伴提到的“非你不可”三步法运用于生活中的例子，也欢迎各位伙伴和我们一起分享使用心得，并发布在爱好者群里。\u003c/p>\u003cp>\u003cstrong>【点出两个片段之间的关系】\u003c/strong>\u003c/p>\u003cp>通过片段一的学习，我们了解到，使用“非你不可”三步法提出请求和直接说出来相比，前者能让对方感受到优越感和被重视的特殊感，从而提高了接受请求的几率，那还有什么方法可以让这个几率更大吗？当然有，如果我们在提要求的同时满足了对方的需求，对方接受的几率肯定就更大了对吗？接下来，请跟我一起阅读片段二。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":12667,"quote":"\u003cp>把“No”的回答变成“Yes”，有3个步骤。\u003c/p>\u003cp>\u003cstrong>步骤1:“不直接说出自己的想法”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;\u003c/strong>一般来说,人都容易不假思索地把脑中的想法直接说出来。然而,这样不仅常常事与愿违,而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1\u003c/p>\u003cp>当然,我们都是凡人,不可能保证所有事都不直接说出来,但至少请记住,不要直接说出“这是很重要的请求!”之类的话。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;\u003c/strong>例如:有人从老家寄来很多柑橘,家人甚至都吃腻了,而你不想让剩下的柑橘白白烂掉。在这种时候,请不要直接说:“大家继续吃啊!”\u003c/p>\u003cp>\u003cstrong>步骤2:“揣摩对方的心理”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;\u003c/strong>请揣摩对方的心理,并根据其平日表现,猜测对方会对你的请求作何想法。直接说出请求,对方会作何反应?如果对方回答“Yes”的可能性很大,当然可以直接说……如果对方回答“No”的可能性很大,就不能直接说了。请暂时忘记自己的请求,揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。 “不能光吃柑橘。”这应该就是家人的想法。\u003c/p>\u003cp>此时,请再次 忘记自己的请求,想想家人的喜恶。例如:“不想感冒。”没人愿意生病。到了容易感冒的季节,身边就会出现感冒患者,家人都很在意这一点。\u003c/p>\u003cp>\u003cstrong>步骤3:“考虑符合对方利益的措辞”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;\u003c/strong>提出的请求,要让“对方的利益”和“自己的利益”趋于一致。想达到这一点,就要基于对方的心理来考虑措辞。关键在于,要创造符合对方利益的上下文关系。即使措辞有所改变,只要最终达成目的就行。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;既然家人不想感冒,就可以对他们说:“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益,家人就会变得乐意吃柑橘,而你的目的也就达到了。\u003c/p>","explains":"\u003cp>好的，看到小伙伴们都已阅读完毕。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我学习完这个片段的拆解后，大家在提出要求、建议等的时候，就能运用“不要直说、猜测回应、找出原因、分析需求、实现双赢”这五步，大大提升对方回复“YES”的几率，实现对方接受自己提议的目的。\u003c/p>\u003cp>\u003cstrong>【I：讲解引导】\u003c/strong>\u003c/p>\u003cp>生活中，我们总是免不了要说服别人或者拜托别人做某件事情。一般情况下，我们会不假思索地直接把脑海中的想法说出来，没去考虑对方会怎么想，这样有可能事与愿违，而且还容易招致别人的反感。比如打扫卫生，想让正在看电视的老公帮忙时，很多人会这样说：“去把垃圾扔了。”得到的回答却是：“我正在看电视呢”，然后两人开始吵。\u003c/p>\u003cp>【\u003cstrong>更贴近实际的例子\u003c/strong>】我说自己的例子，暑假的时候，我想要儿子橙橙每天晚饭后和我一起去跑步锻炼身体，当我说出这个提议时，他摇头说：“我不去，跑步又热又不好玩。”我当时一听很生气，大声说：“跑步可以锻炼身体挺好的啊。”他说：“我就是不想去。”这个提议在紧张的气氛中以宣告失败而终止。【\u003cstrong>不那么做的坏处\u003c/strong>】从这个例子可以看出，直接提出要求，没有站在对方的角度去考虑他的想法和感兴趣的事物，很容易遭到拒绝。锻炼身体是这个年龄段感兴趣的吗？显然不是。如果处理不好，还有可能从一个提议升级为争吵，影响彼此的感情和关系。\u003c/p>\u003cp>那么，怎么提建议才能在友好的氛围下，让对方欣然接受呢？根据片段的建议，再遇到这类情况时，按照“不直接说——揣摩对方心理——考虑对方利益” 这三步，就能大大提升对方回复YES的几率。为了让大家更好的理解，我把上面的步骤进行细化，并按照片段建议加工成正面的案例：\u003c/p>\u003cp>\u003cstrong>【细化原文行动步骤】【变成正面例子】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：防止脱口而出。\u003c/strong>这一步能让你在说重要提议前，有一个先跟自己说：“stop”的意识。这样可以成功避免只考虑自己的感受和需求而忽略了对方。比如当我想跟橙橙提出“晚饭后去跑步”的要求时，我先跟自己说“stop”，不要急着直接提出来，先想一想再说。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：猜测对方回应。\u003c/strong>需要我们根据对方平日表现做一个假设，如果直接说出请求，猜测对方会对你的请求作出什么回应。无外乎出现两种情况：\u003c/p>\u003cp>1、对方回答YES的可能性大，那就可以直接说请求；\u003c/p>\u003cp>2、如果回答NO的可能性大，进行到下一步。\u003c/p>\u003cp>以我对橙橙的了解，他肯定会拒绝去跑步的提议，所以进入到下一步。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：找出拒绝原因。\u003c/strong>暂时忘记自己的请求，通过你对对方喜好、行为、性格的了解，站在对方角度去分析，是因为什么原因对你回复NO呢。\u003c/p>\u003cp>我认为橙橙拒绝了“晚饭去跑步”的提议，是因为他喜欢看电视，他觉得跑步没有看电视舒服和有趣。\u003c/p>\u003cp>\u003cstrong>第四步：分析对方需求。\u003c/strong>想一想对方在意的、关心的、感兴趣的人或事物有哪些。这一步是为了站在对方的角度考虑，把对方的心理需求拿捏得越准确，得到YES的几率就越大，所以这一步很关键。比如：橙橙最喜欢做的事是去乐之书店，坐在书店二楼边喝百香蜜柚边看书。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第五步：双方需求达一致。\u003c/strong>这一步要找出双方需求的一致点。橙橙的需求是：去乐之书店看书，喝饮料。我的需求是：晚饭后和我一起去跑步。所以我可以这样说：“橙橙，每天晚饭后我们一起跑步去乐之书店看书怎么样，还可以跟你点一杯百香蜜柚哦。”他肯定会开心的接受啊。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>这个方法用于你比较了解和熟悉的人身上效果更好，因为你能更清楚地知道对方的行为和性格，了解他的需求，进而有的放矢地进行表达，大大提升对方接受的几率。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>有人可能会觉得五步有些麻烦，其实一、二步在大多情况下几秒就完成了，更何况对于我们在意的事，多想一下,整理下语言，就可以让对方高兴的同时得到自己想要的回应，还是很值得的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】\u003c/strong>\u003c/p>\u003cp>为了加深大家的理解和运用，现在我们来做个现场演练。我出一个场景，请大家先听一下。\u003c/p>\u003cp>\u003cstrong>【给出具体场景】10～15分钟\u003c/strong>\u003c/p>\u003cp>小红是一位孕期3个月的准妈妈，为了安心养胎，把工作辞了，小李是她的老公，是一位足球狂热分子。最近他俩总是闹矛盾，原因是小李希望小红能在家不要到处乱跑，万一有个闪失就不得了，特别是晚上不要出去，非常担心她的安全。而小红觉得自己现在没工作，天天无所事事都快跟社会脱节了，老在家里待下去会闷出抑郁症来。所以最近非常积极参加各种社群活动，她也是一位拆书爱好者，本周四晚上的拆书课，正好是拆书家分享一本家教类的书《正面管教》，她觉得很实用所以特别想去参加，但按照以往小李反对她出去参加活动的经验来说，她知道这次小李肯定也不会同意，更何况是在晚上。所以小红要好好想想怎么跟小李说这个事，小李又会有什么反应呢？\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【给出清晰指令\u003c/strong>】现在请每两个人一组进行讨论（按照刚才的分组），一个人扮演小红，一个人扮演小李，待会请一组进行角色扮演。要求大家需用到片段中的五个步骤。我们在这里一起先来温习一下“no变yes”五步法：\u003cstrong>第一步：防止脱口而出；第二步:&nbsp;猜测对方回应；第三步:找出拒绝原因；第四步：分析对方需求；第五步：双方需求达一致。\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;请注意，解决场景中的问题，可以有很多办法，但今天我们只用今天所学的步骤来演练就可以了。\u003c/p>\u003cp>（邀请小组进行分享，提示分享者某些步骤在现实生活运用的时候，分析是在内心完成，但是现在是进行演练，所以请扮演者把内心独白和过程也表达出来。）\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>莉莉：（内心独白）我非常想去参加《正面管教》拆书课，但以我对老公的了解和对我晚上出去的态度，我敢肯定直接跟他说：“我要去”，他肯定会坚决不同意，所以我一定要好好想想怎么跟老公说。他拒绝的原因主要是不希望我总往外跑，特别是晚上。所以我会这么说：“老公，我知道周四晚上有你喜欢的足球赛，那天我们一起去MS咖啡馆吧，在那你可以看足球赛直播，很有氛围，我能在楼上去参加《正面管教》拆书课，你也不用担心我晚上出去的安全啦。”\u003c/p>\u003cp>辉雄：你真会想，真的想去？\u003c/p>\u003cp>莉莉：是啊，我要在孩子出生前多学习家教知识。\u003c/p>\u003cp>辉雄：嗯，我也挺喜欢在咖啡馆和大家一起看足球赛直播，你一个人晚上出去我也不放心，就陪你一起去吧。\u003c/p>\u003cp>莉莉：谢谢老公。\u003c/p>\u003cp>【拆书家给出反馈】\u003c/p>\u003cp>非常感谢两位精彩的分享。从莉莉和辉雄的对话清晰体现了“no变yes”五步法，首先莉莉说非常想去参加《正面管教》拆书课，但是老公不会同意，这就完成了\u003cstrong>第一步\u003c/strong>防止脱口而出和\u003cstrong>第二步\u003c/strong>猜测对方回应。接着说出老公拒绝的原因担心她的安全，完成了\u003cstrong>第三步\u003c/strong>，从对话中我们知道莉莉找到了老公的需求也就是\u003cstrong>第四步\u003c/strong>，老公想看足球赛，并且不想莉莉出现安全问题。\u003cstrong>最后\u003c/strong>莉莉说出：一起去的提议，既能满足老公看球赛，又不用担心她的安全，自己还能参加拆书课，两全其美，辉雄也表现得很真实，非常棒的演练。\u003c/p>\u003cp>\u003cstrong>【A2包含具体场景的提问】：\u003c/strong>\u003c/p>\u003cp>现场演练到此结束，让我们一起设想下，在未来的一周或是一个月的时间里，是否会出现你需要提请求、建议，但非常没有把握对方会同意的事情呢？\u003c/p>\u003cp>你可能会遇到类似的情况：向领导提议给某位下属升职加薪；向老公提出不要玩游戏的要求；向孩子提出每天阅读半小时的建议。\u003c/p>\u003cp>这个时候你想起今天的拆书，停下来问问自己，怎样说才能得到对方的同意呢？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;下面给大家8分钟时间，请写下自己的A2，并在小组内分享。大家的分享中要包括事件可能发生的时间，你想要达到的目的，具体行动步骤哦。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>&nbsp;威丽：我是做留学培训这块，下周要邀请客户来参加我们公司的大型营销活动现场，我很想邀请周总参加，但是没把握能把他邀请过来。用“no变yes”五步法我会这么做：\u003c/p>\u003cp>第一步：防止脱口而出。我要想好怎么跟周总说再开口，因为周总是我重要的潜在客户，成交的可能性很大。\u003c/p>\u003cp>第二步:&nbsp;猜测对方回应。但是之前邀请了2次他都没来，这次也很有可能不来。\u003c/p>\u003cp>第三步:找出拒绝原因。拒绝的原因觉得我们这个活动没吸引力。\u003c/p>\u003cp>第四步：分析对方需求。我知道周总一直想全面了解关于留学的内容，为他孩子的留学做好选择和准备。也希望能享受到我们的优惠政策。\u003c/p>\u003cp>第五步：双方需求达一致。我会跟周总这么说：“周总，我们这次的营销活动力度非常大，现场会请专家分享关于留学的内容，你有任何疑问都可以在现场提出来获得解答，并且我们这次促销活动是近两年力度最大的一次，能帮您省不少钱哦。”\u003c/p>\u003cp>好的，感谢威丽的分享。很好的活学活用，我听完都非常心动，只想满口答应。\u003c/p>\u003cp>【\u003cstrong>强有力的结语\u003c/strong>】\u003c/p>\u003cp>接下来，我们回顾一下，刚刚我们学习了用“非你不可”的三步法，让对方感受到优越感和特殊性，从而提高对方接受提议的几率，以及通过“no变yes”的四步法，加大对方接受的胜算。通过这两个片段的学习，不仅可以帮我们实现目的，还可以帮助我们发展人际关系，感受到生活中更多的美好。今天我的分享就到这里，再次感谢伙伴们的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1569366202000,"updated_at":1572156331000,"ria":true},{"id":8815,"topic":"把NO变成YES的说话神器","learn_goal":"掌握让对方接受提议的方法","remark":"","level":"TF2-3","duration":22,"status":29,"type":0,"chaishujia":{"username":"许曼","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>\u003cstrong>【开场】\u003c/strong>\u003c/p>\u003cp>大家好！我叫许曼，大家都叫我馒头。用三个标签介绍自己，都和书有关。\u003c/p>\u003cp>第一个标签：图书。我在一家书店工作，每天都和图书打交道。\u003c/p>\u003cp>第二个标签：读书。我也很喜欢读书，因为我和图书接触实在是太便利了，店内藏书有近10万册。每当我发现一本心仪的书都会欣喜好一阵。\u003c/p>\u003cp>第三个标签：拆书。近几年看实用类的书比较多，很幸运遇到了拆书帮·麓山分舵，开启我全新的看书模式。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（F）：\u003c/strong>我今天拆解的片段来自《所谓情商高 就是会说话》这本书，作者佐佐木圭一，他是日本沟通专家、广告鬼才、文案写作大师。本书主要讲了作者亲身实践中总结的关于如何说话的“7个突破口”和“8个技巧”。\u003c/p>\u003cp>\u003cstrong>（A）：\u003c/strong>和其他书相比它像一本指南，更注重实操性，所以它是一本拿来用而不是拿来读的书。\u003c/p>\u003cp>\u003cstrong>（B）：\u003c/strong>大家有没有过这种经历，你向别人做一些介绍、提出请求，提出建议，却遭到对方拒绝？你是否希望你的表达能够脱颖而出，瞬间打动人心？这本书都可以为你提供解决方法。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>等会会有小组讨论和分享的环节，我们的分组仍沿用前面的分组方式。\u003c/p>\u003cp>好，现在请大家先阅读手中的原文片段，1～2分钟时间，阅读完后请用眼神示意下我。\u003c/p>","ratings_count":1,"texts":[{"id":12528,"quote":"\u003cp>把“No”的回答变成”Yes“，有3个步骤。\u003c/p>\u003cp>\u003cstrong>步骤1:“不直接说出自己的想法”\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 一般来说,人都容易不假思索地把脑中的想法直接说出来。然而,这样不仅常常事与愿违,而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1\u003c/p>\u003cp>当然,我们都是凡人,不可能保证所有事都不直接说出来,但至少请记住,不要直接说出“这是很重要的请求!”之类的话。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 例如:有人从老家寄来很多柑橘,家人甚至都吃腻了,而你不想让剩下的柑橘白白烂掉。在这种时候,请不要直接说:“大家继续吃啊!”\u003c/p>\u003cp>\u003cstrong>步骤2:“揣摩对方的心理”\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 请揣摩对方的心理,并根据其平日表现,猜测对方会对你的请求作何想法。直接说出请求,对方会作何反应?如果对方回答“Yes”的可能性很大,当然可以直接说……\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 如果对方回答“No”的可能性很大,就不能直接说了。请暂时忘记自己的请求,揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 请试着揣测吃腻了柑橘的家人的心理。 “不能光吃柑橘。”这应该就是家人的想法。此时,请再次忘记自己的请求,想想家人的喜恶。例如:“不想感冒。”没人愿意生病。到了容易感冒的季节,身边就会出现感冒患者,家人都很在意这一点。\u003c/p>\u003cp>\u003cstrong>步骤3:“考虑符合对方利益的措辞”\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 提出的请求,要让“对方的利益”和“自己的利益”趋于一致。想达到这一点,就要基于对方的心理来考虑措辞。关键在于,要创造符合对方利益的上下文关系。即使措辞有所改变,只要最终达成目的就行。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 既然家人不想感冒,就可以对他们说:“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益,家人就会变得乐意吃柑橘,而你的目的也就达到了。\u003c/p>","explains":"\u003cp>好的，看到小伙伴们都已阅读完毕。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>今天，在跟随我学习完此片段的拆解后，大家能够在说出提议时，运用不要直说、猜测回应、分析需求、达到双赢四个步骤，大大提升对方回复“YES”的几率，实现对方接受自己提议的目的。\u003c/p>\u003cp>\u003cstrong>【I：讲解引导】\u003c/strong>\u003c/p>\u003cp>what：人们经常把脑海中的想法直接说出来。比如打扫卫生，想让正在看电视的老公帮忙时，很多人会这样说：“去把垃圾扔了。”得到的回答很有可能是：“我正在看电视呢”。再比如邀请意中人约会，很多人会说：“这周六有空吗？”，结果呢？对方直接回复：“没空”。其实只要换种说法，就能大大提升对方回复YES的几率。\u003c/p>\u003cp>这里的YES是指对方同意、接受的肯定回答，NO指拒绝、不同意的否定回答。\u003c/p>\u003cp>why：所以，到底如何措辞提高对方回答“YES”的几率是有方法的，片段提到：不直接说——揣摩对方心理——考虑对方利益这三步。\u003c/p>\u003cp>【举例】我举个例子，我小孩经常吃了晚饭就坐在房间看电视，我想要他饭后和我一起去跑步锻炼身体。这件事我认为非常重要，需要想好措辞再提出来。我如果直接说：“橙橙，你以后晚饭和我一起去跑步吧。”依我对孩子的了解他肯定会拒绝；拒绝跑步提议的原因是因为他觉得跑步比看电视无聊，没兴趣；同时我知道他非常喜欢去乐之书店看书，这是他的需求。我的需求是：他晚饭后和我一起去跑步。于是我说：“橙橙，每天晚饭后我们一起跑步去乐之书店看半个小时书怎么样?”他一听开心的说：“太好了！”大家是不是感受到这个方法把NO变成YES的神奇之处了?\u003c/p>\u003cp>从这个例子，可以看出是按下面这四个具体步骤来进行。\u003c/p>\u003cp>\u003cstrong>【细化行动建议步骤】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：防止脱口而出。\u003c/strong>和对方提出请求，开口前都先跟自己说：“stop”。越是重要时刻，措辞对结果的影响越大，越要想好了再说。这一步可以成功避免只考虑自己的感受和需求而忽略了对方。\u003c/p>\u003cp>\u003cstrong>第二步：猜测对方回应。\u003c/strong>根据对方平日表现，假设直接说出请求，猜测对方会对你的请求作出什么回应。无外乎出现两种情况：\u003c/p>\u003cp>1、对方回答YES的可能性大，可以直接说请求；\u003c/p>\u003cp>2、如果回答NO的可能性大，进行到下一个阶段。\u003c/p>\u003cp>\u003cstrong>第三步：分析原因找需求。\u003c/strong>暂时忘记自己的请求，通过你对对方喜好、行为、性格的了解，站在对方角度去分析，是因为什么原因对你回复NO呢。比如我刚提议晚饭后去跑步的例子中，孩子拒绝是因为跑步没看电视有趣。\u003c/p>\u003cp>再次忘记自己的请求，想一想对方在意的、关心的、感兴趣的人或事物是什么。孩子喜欢的事是去离家不远的书店看书。\u003c/p>\u003cp>这一步是为了站在对方的角度考虑，把对方的心理需求拿捏得越准确，得到YES的几率就越大，所以这一步很最关键。\u003c/p>\u003cp>\u003cstrong>第四步：明确利益达一致。\u003c/strong>这一步是要找出双方利益的一致点，这里的利益不仅指物质方面还包括精神、心理方面的需求。孩子的需求是可以去书店看书，而我的需求是“晚饭后和我一起去跑步”，需求一致点就是：“每天晚饭后我们一起跑步去乐之书店看半个小时书。”满足了他的需求自然会回复YES，而我的目的也达到了。\u003c/p>\u003cp>\u003cstrong>【预防异议1】\u003c/strong>\u003c/p>\u003cp>老实说，用这个方法并不能使所有NO的回答都变成YES，但它确实能提高可能性。如果原本说YES的可能性为0，那么能提高2-3成；如果原本的可能性为5成，就能提高到7-8成。\u003c/p>\u003cp>\u003cstrong>【预防异议2】\u003c/strong>\u003c/p>\u003cp>有人可能会觉得四步有些麻烦，其实一、二步在大多情况下几秒就完成了，更何况对于我们在意的事，多想一下就可以得到想要的回应，还是很值得的。\u003c/p>","interaction":"\u003cp>好的，这么一个实用又好用的方法，大家是不是很想练练手了呢？我现在出一个场景，请大家按小组进行现场演练，请大家认真听下。\u003c/p>\u003cp>【\u003cstrong>A3：场景演练】\u003c/strong>10～15分钟\u003c/p>\u003cp>【场景设计】佳丽是一个12岁孩子的妈妈，这几年开始注重家庭教育，阅读了不少理念和方法都非常好的家教类图书。老吴是佳丽的老公，对待孩子的方式有些简单粗暴，孩子犯错会指责甚至动手。现在孩子进入青春期，出现了一些问题，佳丽看在眼里急着心里，希望老公能有正确的家教理念和教育孩子的方法，共同帮孩子平稳度过青春期。\u003c/p>\u003cp>于是她想要老吴看看《解码青春期》这本非常不错的家教书，如果你是佳丽，你会怎么措辞，说服不爱阅读的老公接受这个提议呢？大家可按下面四步进行思考：\u003c/p>\u003cp>\u003cstrong>第一步：防止脱口而出。（\u003c/strong>想一想这件事对你的重要程度）\u003c/p>\u003cp>\u003cstrong>第二步: 猜测对方回应。\u003c/strong>（直接说对方会是什么反映）\u003c/p>\u003cp>\u003cstrong>第三步：分析原因找需求\u003c/strong>（拒绝接受你的提议的原因是什么，对方在意的事物有哪些）\u003c/p>\u003cp>\u003cstrong>第四步：明确利益达一致。（\u003c/strong>找出双方利益的一致之处，提出满足双方需求的提议）\u003c/p>\u003cp>请大家一位扮演佳丽，另一位扮演老吴，根据给出的场景设计进行对话，演练时间6～8分钟，请大家开始，等会我会请小伙伴跟大家分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>杨杨扮演佳丽、世磊扮演佳丽的老公老吴。\u003c/p>\u003cp>杨杨：（内心分析）第一步：这件事对我来说非常重要，对于孩子能否健康成长起重要作用。第二步：如果我直接要求老吴去看这本书，以我对他的了解他肯定不会看。\u003c/p>\u003cp>杨杨：老公，近段时间看你和孩子总有争吵，孩子青春期到了，有时候需要一些方法。\u003c/p>\u003cp>世磊：是啊，我也不想和他吵，感到有心无力，不知道怎么和他相处才好。\u003c/p>\u003cp>杨杨：我推荐你看《解码青春期》这本书，内容特别好，可以完全解决你的困惑。\u003c/p>\u003cp>世磊：真的吗？太好了，帮我去买一本看看。\u003c/p>\u003cp>杨杨：早就买好啦，拿去。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>好，感谢小伙伴的分享。杨杨和世磊完美演绎了四个步骤，从对话中大家也感受到，杨杨的措辞比直接说：“你去看《解码青春期》这书吧”要有说服力有吸引力得多。\u003c/p>\u003cp>希望大家能经常使用今天学到的方法去提请求。我相信会得到一个又一个的YES。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1568012959000,"updated_at":1568014331000,"ria":true},{"id":8782,"topic":"把“No”的回答变成“Yes”的3个步骤","learn_goal":"运用3个步骤，避免遭到对方拒绝，争取对方同意，把“No”的回","remark":"拜托别人做事的时候，直接说出自己的想法，总是很容易遭到拒绝。经常遭到拒绝，就会陷入不敢表达诉求的尴尬境地。怎么样去说，才能避免经常遭到拒绝，争取获得对方同意呢？\r\n        其实，说话就像做菜一样，毫无章法地开始，结果总是碰运气，很有可能不尽人意。如果我们事先了解“菜谱”，按照“菜谱”去做，可以提高“做菜”的效率，也能提高说话沟通的效率。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"01","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"发放原书拆页+递交拆书逐字稿+分组","ratings_count":0,"texts":[{"id":12489,"quote":"\u003ch4>4.复习！3个步骤\u003c/h4>\u003cp>把“No”的回答变成“Yes”，有3个步骤。\u003c/p>步骤1：“不直接说出自己的想法”\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。\u003c/p>\u003cp>在这种时候，请不要直接说：“大家继续吃啊！”\u003c/p>步骤2：“揣摩对方的心理”\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃膩了柑橘的家人的心理。\u003c/p>\u003cp>“不能光吃柑橘。”这应该就是家人的想法。\u003c/p>\u003cp>此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒”。\u003c/p>\u003cp>没人愿意生病。\u003c/p>\u003cp>到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>步骤3：“考虑符合对方利益的措辞”\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了”。\u003c/p>\u003cp>这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>\u003cstrong>Step2\u003c/strong>\u003cstrong>：自我介绍+书籍介绍（1min）\u003c/strong>\u003c/p>\u003cp>三个标签：老师、练声爱好者、拆书家\u003c/p>\u003cp>【教师】在学校教过书，也做过互联网在线教育，现在在做的是人工智能教育方向的教研工作。\u003c/p>\u003cp>【练声爱好者】因为练声结识了我们武汉拆书帮的一姐李真老师，从而认识了拆书帮。\u003c/p>\u003cp>【拆书家】我曾是一名重度“伪学习者”，爱看书而不用书，只学不练，光看不行动。现在希望成为一名拆书家，真正做到学以致用，拆为己用。\u003c/p>\u003cp>我今天要拆的片段选自日本顶级沟通专家、广告、文案写作大师佐佐木圭一的《所谓情商高，就是会说话》一书，这本书跟其他人际沟通类书籍不同，它把说话当成一门“技术”，就像做菜的食谱一样，书中介绍的方法就是其做菜的“秘方”。在书中，作者不仅介绍了把“No的回答变成Yes的3个步骤”，而且还详细讲解了“7个突破口”和“8个技巧”。阅读本书，可以从不同程度上帮助我们掌握并运用语言措辞的技巧，使自己成为说话高手。\u003c/p>\u003cp>\u003cstrong>Step3\u003c/strong>\u003cstrong>：【R】环节：让大家阅读原书拆页（2min）\u003c/strong>\u003c/p>\u003cp>我今天给大家带来的【拆书主题】是：把“No”的回答变成“Yes”，有3个步骤。今天的学习目标是：学会写有关这3个步骤的应用便签。请大家阅读自己手里的拆页内容，阅读完的小伙伴请举手示意。\u003c/p>\u003cp>→学习者阅读原文片段\u003c/p>\u003cp>\u003cstrong>Step4\u003c/strong>\u003cstrong>：【I】环节：讲解原文知识点（2-3min）\u003c/strong>\u003c/p>\u003cp>我们在跟人沟通的时候，经常需要表达自己的诉求，希望得到别人的同意。有的时候对方很爽快地就答应了，有的时候却会遭到对方的拒绝，一旦遭到对方的拒绝，很多人可能就会不敢表达自己的诉求或者是减少表达诉求的次数。其实，在向别人表达诉求或者请求的时候，我们可以通过3个步骤，避免遭到对方拒绝，争取让对方从“拒绝”变成“同意”，也就是把“No”的回答变成“Yes”。那就是：\u003c/p>\u003cp>第一步，不要直接说出自己的想法；\u003c/p>\u003cp>第二步，揣摩对方的心理；\u003c/p>\u003cp>第三步，考虑符合对方利益的措辞。\u003c/p>\u003cp>为什么要这么做呢？举个实际生活中的例子。\u003c/p>\u003cp>在家里打扫卫生的时候，有的时候想让家人帮个忙，以前的时候我都是这样说的：“去把垃圾扔了。”\u003c/p>\u003cp>这种情况下的结果一般都是：看心情！对方的回答往往都是“我在用电脑”“我在看手机”...“我在做其他什么什么事？”可想可知，大部分情况下会遭到直接或者委婉的拒绝。\u003c/p>\u003cp>上周末，我一开始并没有直接说出自己的想法，而是揣摩了对方的心理:首先，TA也不希望被人命令，不要直接要求他去做，如果倒垃圾能给他带来好处，他应该会愿意倒垃圾的，并且要注意任何时候跟TA提要求，都要注意措辞。\u003c/p>\u003cp>所以我就问TA：今天在家打扫卫生，做家务出点汗也是一种运动，我已经把客厅收拾完了，你愿意下去倒下垃圾吗？还可以缓解一下眼睛疲劳，活动活动筋骨，这样体质好了，就不容易感冒。\u003c/p>\u003cp>这样一说，本来是极有可能被拒绝的一件事情，最后却能获得对方的同意。\u003c/p>","interaction":"\u003cp>\u003cstrong>Step5\u003c/strong>\u003cstrong>：【A1】环节：请大家小组内分享各自的过往经验（5-8min）\u003c/strong>\u003c/p>\u003cp>在座的各位小伙伴们，在生活中有没有遇到像这样的例子发生的呢？\u003cstrong>在过去一周内或者一个月内的某一天，你想让别人做一件事情的时候，你当时是怎么说怎么做的呢？\u003c/strong>如果你恰好用到了这个方法，请把它写下来。如果没有用这个方法，也请把它写下来，不管是成功的经验和失败的经验都可以写下来和小组成员一起分享讨论。\u003c/p>\u003cp>→小组讨论分享\u003c/p>\u003cp>→邀请个人分享\u003c/p>\u003cp>\u003cstrong>Step6\u003c/strong>\u003cstrong>：【A2】环节：请大家在便签纸上写下各自的应用或行动步骤（1min）\u003c/strong>\u003c/p>\u003cp>感谢***给我们分享TA的故事。\u003cstrong>如果我们在今后一周或者一个月内，生活中再次遇见类似的场景时\u003c/strong>，你会怎么去用到今天学习到的三个步骤，避免遭到拒绝，争取让对方同意你的要求呢？\u003c/p>\u003cp>视学习者讨论情况提示场景：【比如说你想让老公周末开车带你和孩子去景点游玩（老公肯定会认为这么热的天出去蒸桑拿而拒绝），你想让同事下班后帮你统计目前在进行的项目进度表（同事会认为统计所有项目超出了他的责任范围而拒绝）】。\u003c/p>\u003cp>请大家在便签纸上写下自己要怎么运用今天所学到的“如何说不被拒绝”三个步骤去和对方进行沟通。\u003c/p>\u003cp>A2需要学习者分享出来最好。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1567735680000,"updated_at":1567735680000,"ria":true},{"id":8719,"topic":"措辞技巧","learn_goal":"把得到“Yes“回答的可能性提高2~3成","remark":"","level":"TF1-2","duration":15,"status":29,"type":0,"chaishujia":{"username":"April房","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>Hi，大家好，我是咱们喜乐分舵的拆书家April，我是典型的理工女风格，上学时学的是工科，毕业后也一直从事技术类的工作，目前在食品制造行业从事研发类的工作。今天给大家带来的拆页来自日本作家佐佐木圭一写的《所谓情商高，就是会说话》，这本书的内容在日本成为深受欢迎的人际沟通课程，也是世界知名企业员工指定培训教材。\r\n作者原本不擅长沟通和表达，但所从事的恰好是需要展现说话能力的工作，在历经焦虑暴食、畏惧上班的痛苦时光后，有一天，他发现打动人心的语言暗藏规则可循，从那时起，不仅表达方式，就连他的人生也随之发生巨变。本书就是作者多年职场和人生经验的总结，是一本活的“说话词典”。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":12416,"quote":"\u003cp>与意中人交谈、工作中的简报、家人的日常生活、就业面试……越是人生中的重要时刻，措辞对结果的影响越大。同样的内容，用高明的措辞说出来，就很可能使对方的回答从“No”变成”Yes“。\u003c/p>\u003cp>想必大家已经明白措辞的重要性，但还不知道怎样才能掌握措辞的方法。很多人以为，措辞是“与生俱来的天赋“，是有”天生的语感“，根本没法轻易掌握，其实不然。\u003c/p>\u003cp>措辞是有谱可循的。\u003c/p>\u003cp>步骤1：不直接说出自己的想法。一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。例如：有人从老家寄回来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白浪费掉，在这种时候，请不要直接说：“大家继续吃啊！“\u003c/p>\u003cp>步骤2：揣摩对方的心理。请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大。当然可以直接说。如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。“这应该就是家人的想法。此时请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3：考虑符合对方利益的措辞。提出的请求，要让“对方的利益“和”自己的利益“趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即时措辞有所改变，只要最终达成目的就行。既然家人都不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>日常工作和生活中，我们都希望自己向他人提出的合理请求能够得到肯定的回答。比如周末在家收拾屋子的时候，想让坐在沙发上看电视的先生一起帮忙做家务，又比如说工作中，想让忙碌的领导帮忙指导一下方案，再比如说想要约心仪的女孩一起吃饭，希望得到对方的“Yes”。在这种情况下，如果对方的意愿程度比较高，很愿意接受我们的请求当然是没有什么问题。但是如果对方对自己的请求本身不太愿意，或者关系还没有那么亲近，能不能得到对方肯定的回答就难说了。\u003c/p>\u003cp>所以针对这种情况，如何提高对方说“Yes”的概率，愉快地接受我们的请求？可以参照以下步骤：\u003c/p>\u003cp>1、不直接说出自己的请求，暂时放在心里。例如原文中案主希望家人继续吃柑橘，但家人吃腻了柑橘不想再吃了，这时候就不能直接说“大家继续吃柑橘啊”；\u003c/p>\u003cp>2、揣摩对方知道自己的请求后会作何想法，想想对方喜欢什么，讨厌什么，担心什么。比如原文中如果吃腻了柑橘的家人知道案主想要他们继续吃柑橘，第一反应应该是不能光吃柑橘，想换个口味吃点别的。想想家人有什么喜欢或讨厌的东西，哦，想到一个，不想感冒，不想在易感冒的季节感冒。\u003c/p>\u003cp>3、寻找自己和对方共同利益的结合点，在此基础上组织自己的语言，再说出自己的请求。例如原文中案主找到自己想让家人吃柑橘和家人不想感冒这两者相结合的点，最终说出：多吃柑橘就会不会感冒。家人就乐意吃柑橘了。 \u003c/p>\u003cp>这里所说的技巧并不能保证让自己的请求得到对方肯定的回答，只是将对方说“Yes“的概率提升2~3成，重要的是找到双方的利益共同点，而不是让对方觉得自己的请求完全是从自己角度出发，不顾及对方的感受。\u003c/p>","interaction":"\u003cp>接下来从我右手边开始三个人一组，分享一下自己过往有没有和家人、同事或朋友有过类似因为讲话措辞不当而造成对方直接回“No“，自己的愿望没达成，而且还闹得不愉快的事情。时间5分钟.\u003c/p>\u003cp>好，时间到，大家讨论地都很积极，下面请我们的小伙伴菜泡饭分享一下自己的经历好吗？\u003cbr>\u003c/p>\u003cp>菜泡饭：暑假即将过完，上周准备给开学的儿子把书包洗洗，出门前跟儿子说：“儿子，要开学了，待会儿把书包里的东西都掏出来，妈妈好把你的书包洗一洗。”儿子处于青春期，比较叛逆，回家前也不知道照做没有。结果回来儿子不仅把书包的东西掏出来了，而且还把其他的东西都整理好了。现在想想也是这样个道理，我是从他的角度出发，他也就照做了。\u003c/p>\u003cp>拆书家：所以你分享的是一个自己的请求得到对方“Yes”的例子，是一个成功的案例。\u003c/p>\u003cp>好，感谢菜泡饭的分享，刚刚我们小组内也分享了自己过往关于措辞不当而导致自己请求被拒的例子，现在请大家拿起桌上的便签，写下自己下周或下个月要与人沟通的一件事，用今天学到的方法在便签上写下你将如何提出自己的请求，提升对方的回答”Yes“概率的措辞。时间1分钟。\u003c/p>\u003cp>我今天的拆书就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1567088051000,"updated_at":1567088081000,"ria":true},{"id":8651,"topic":"朱晓丹：投其所好，达成双赢","learn_goal":"不直接说出自己的想法，分析对方的需求、利益，提高请求的成功率","remark":"大家有没有过这种经历，向对方请求帮助，或提出建议，却遭到拒绝?有没有方法可以提高我们的成功率呢？这本书教我们运用“7个突破口”和“8个技巧”搭配出感人的语言，提高我们表达的成功率！","level":"TF3-1","duration":40,"status":29,"type":0,"chaishujia":{"username":"littledl2019","city":"大连"},"club":{"name":"大连知行分舵","city":"大连"},"prologue":null,"ratings_count":1,"texts":[{"id":12336,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1566034879000,"updated_at":1570622934000},{"id":8574,"topic":"变成Yes的三步法","learn_goal":"让自己的请求，别人说Yes的方法。","remark":"《所谓情商高，就是会说话》，改善沟通提高情商，简单易懂的情商入门书籍。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"戒森哥","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;自我一下介绍，3个标签：跑步，跑步是一种选择，帮助我精力充沛和充满自信；读书，读书使我获得不断前行的动力与方法；坚持，持续地养成好的习惯，会拥有更多的复利。\r\n &nbsp;&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;（I）先向大家介绍一下拆书法和拆书帮。拆书法是一种学习的方法论，强调\u003cstrong>以学习者为中心\u003c/strong>。分为RIA便签读书法和RIA便签学习法。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;（II）今天介绍\u003cstrong>RIA便签读书法\u003c/strong>：R，Reading，阅读原文拆页，“拆书”目的是“拆为己用”，李敖先生就是位“拆书家”；I，Interpretation，用自己的语言表述拆页内容，目的是对新知有更清晰理解；A，Appropriation，它是内化与应用的部分，A1便签联系自己亲身经历，让新知与旧知形成联系，帮助我们更好的记忆，再使用A2便签，将具体目标写下来贴上墙，帮我们将新知应用下去，产生实际效果。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; （III）再介绍一下\u003cstrong>拆书帮\u003c/strong>：它是基于拆书法的学习爱好者社群，在全国各地都有其分舵，使命是帮助学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":12243,"quote":"\u003cp>\u003cstrong>【R-阅读原文片段】\u003c/strong>\u003cstrong>&nbsp;&nbsp;\u003c/strong>\u003cstrong>变成Yes的三个步骤\u003c/strong>\u003c/p>\u003cp>步骤1：\u003cstrong>“不要直接说出自己的想法”\u003c/strong>\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想 法直接说出来。然而，这样不仅常常事与愿违， 而且很容易招致反感。 请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>步骤2：\u003cstrong>“揣摩对方的心理”\u003c/strong>\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方 回答“Yes”的可能性很大，当然可以直接说……\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能 直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答 案就在其中。&nbsp;\u003c/p>\u003cp>步骤3：\u003cstrong>“考虑符合对方利益的措辞”\u003c/strong>\u003cbr>\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己 的利益”趋于一致 。想达到这一点，就要基于 对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>","explains":"\u003cp>\u003cstrong>【I-用自己的语言重述】\u003c/strong>\u003c/p>\u003cp>（I）“会说话”显然是我们人人向往的，\u003cstrong>增加与优质措辞接触的次数\u003c/strong>，得到Yes的机率也会增加。\u003cbr>\u003c/p>\u003cp>（II）“变成Yes的三步法”，就可以帮我们有更多优质措辞的表达，通过不断练习，得到“yes”机会也会从零提高到两三成，从5成\u003cstrong>升至7~8成的水平\u003c/strong>。\u003c/p>\u003cp>（III）具体怎么做呢？\u003c/p>\u003cp>\u003cstrong>第一，\u003c/strong>\u003cstrong>先不要直接说出自己的想法。\u003c/strong>\u003c/p>\u003cp>不假思索把想法直接讲出来，常常事与愿违，甚至招致反感。\u003c/p>\u003cp>当然我们都是凡人，不能保证所有事都不直接说出来，至少别直接说出“这是很重要的请求!”之类的话。\u003c/p>\u003cp>需要慢慢培养习惯，想表达请求时，先缓一缓，就像我们平时说的，“别让嘴快过脑子”。\u003c/p>\u003cp>举个栗子，朋友送来很多柑橘，家人都吃腻了，我不想让剩下的柑橘白白烂掉，这时先不直接说：“大家继续吃啊！”\u003c/p>\u003cp>第二，\u003cstrong>开始\u003c/strong>\u003cstrong>揣摩对方的心理。\u003c/strong>\u003c/p>\u003cp>思考对方的好恶与性格，根据平时的表现，猜测对方会对请求作出何种想法。\u003c/p>\u003cp>可以从“投其所好”或“儆其所恶”入手。\u003c/p>\u003cp>接刚刚的栗子，“不能光吃柑橘”，是家人的想法，“儆其所恶”的思考点。再想想家人的喜好，若是易感冒的季节，“家人不想感冒。” 这可以是“投其所好”的入手点。\u003c/p>\u003cp>这同样需要慢慢练习，而且揣摩对方的心理，无法做到100%猜中，但提高思考意识，成功概率会慢慢提高。\u003c/p>\u003cp>适用边界，对陌生人慎用。\u003c/p>\u003cp>第三，\u003cstrong>考虑符合对方利益的措辞\u003c/strong>\u003cstrong>来表达我们请求\u003c/strong>。\u003c/p>\u003cp>要提请求了，尽量让对方的利益与自己的趋于一致，这就要基于对方心理来考虑。\u003c/p>\u003cp>接着栗子，家人不想感冒，又想让他们继续吃，可以安排这样的措辞：“多吃柑橘就不会感冒”，这样的措辞符合家人的利益，可能乐意继续吃柑橘。\u003c/p>\u003cp>适用边界，符合对方的利益的措辞也要慢慢通过实践去习得，不过作者教授了很多人，Yes的机率都是大大提高的。\u003c/p>\u003cp>变成Yes的三步法，对于我们特别重要的请求，更值得尝试和练习的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1-联系自己的过往经验】\u003c/strong>\u003c/p>\u003cp>我有个亲身经历，回父母家，发现老爸在漆黑的房间看电视，屏幕很亮对视力不好，我立刻不假思索地对他说，“您这样看电视对视力不好，灯得开着呀”，顺手把灯给打开啦，但下次发现他还是不开灯的，劝说毫无效果，反复劝说了多次，依然如此。\u003c/p>\u003cp>正好看了这个书，我就有了新的盘算。\u003c/p>\u003cp>首先，先不直接说出：请他开着灯看电视的请求了。\u003c/p>\u003cp>然后，开始揣摩他的心理，没有开灯的习惯，也是没有任何动力让他这样做，但视力下降一定他不喜欢的，这是“儆其所恶”的恶。与之相反，若是能保持视力水平，读报、游泳都不不受影响，这就是“投其所好”的好。\u003c/p>\u003cp>最后，考虑他最重要的利益点，他风雨无阻每天都去游泳，于是准备了下面的措辞。\u003c/p>\u003cp>“老爸，您看，您要是视力下降，游泳就会极不方便了，这个房间光线暗看电视，对视力非常不好，建议您开灯看电视，这样对视力影响小，就更不会影响您游泳啦。”\u003c/p>\u003cp>寥寥数语，从那以后不用任何提醒，他都是开着灯看电视啦，问题顺利解决。\u003c/p>\u003cp>大家可以看出来，我其实就是应用了这个方法，第一，我没有直接表达我的想法，“不要在黑暗的房间中看电视”，第二，通过揣摩心理，我分析出好的视力肯定是老爸愿意的，第三，我说出了对他的利益点，视力好不影响他游泳运动。\u003c/p>\u003cp>\u003cstrong>【A2-规划未来的具体应用】\u003c/strong>\u003c/p>\u003cp>1.&nbsp;\u003cstrong>近期\u003c/strong>\u003cstrong>目标：\u003c/strong>\u003c/p>\u003cp>手下有位业务主管，非常不喜欢与供应商沟通，每次都找各种借口躲避，我的目标是从下周二开始的会议上，应用“变成Yes三步法”促进这位主管与供应商积极沟通。\u003c/p>\u003cp>2.&nbsp;\u003cstrong>具体应用\u003c/strong>\u003cstrong>:\u003c/strong>\u003c/p>\u003cp>（1）不先说“你应该积极与供应商来沟通”。\u003c/p>\u003cp>（2）分析他的心理：恶：觉得浪费时间，帮不到业务。好：供应商有额外的市场资源，可以帮助他的销售业绩提高。\u003c/p>\u003cp>（3）符合他利益的措辞：“供应商手头有些额外资源，我想让他们投到你的区域，这需要你与供应商的沟通紧密些，让他们更了解你们的区域情况，这样就好追加这些市场资源了，不过需要你多付出时间与他们沟通联络，这就需要你提高自己的时间管理能力以免浪费时间，这对于你锻炼时间管理能力应该是有帮助的，你看是否可以试一下呢？\u003c/p>\u003cp>\u003cstrong>【结语（强调核心要点/学习目标；呼应开场图书介绍/讲解内容）】\u003c/strong>\u003c/p>\u003cp>让别人多说Yes，职场路会更通畅，生活也会更美满幸福。\u003c/p>\u003cp>尝试“Yes三步法”，“先别直接说出自己的想法，好好揣摩对方的心理，用符合对方利益的措辞表达出自己的请求”，让我们都变成一个会说话的人。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1565085510000,"updated_at":1565087033000,"ria":true},{"id":8339,"topic":"投其所好，达成双赢","learn_goal":"不说出自己想法，分析对方需求，符合对方利益措辞，提供成功率","remark":"大家有没有过这种经历，向对方请求帮助，或提出建议，却遭到拒绝?有没有方法可以提高我们的成功率呢？这本书教我们运用“7个突破口”和“8个技巧”搭配出感人的语言，提高我们表达的成功率！","level":"TF3-1","duration":35,"status":29,"type":0,"chaishujia":{"username":"littledl2019","city":"大连"},"club":{"name":"大连知行分舵","city":"大连"},"prologue":null,"ratings_count":1,"texts":[{"id":11971,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1562515687000,"updated_at":1568615233000},{"id":8311,"topic":"人际之间","learn_goal":"沟通","remark":"大家有没有在向别人特别激动的推荐你特认可的东西时，别人却不感兴趣呢？来参加本次拆书活动，你可以学到如何用反差三步法来金句频出，解决让别人对我们的话更感兴趣的问题。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"憨商猎人","city":"天津市"},"club":{"name":"天津北洋分舵","city":"天津市"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>欢迎大家参加今天的拆书活动，我是今晚的拆书分享者之一齐凯。我平常喜欢用\u003cstrong>80后两个孩子的奶爸、投资理财练习者、2020年的三级拆书家\u003c/strong>，三个标签来形容我自己。我很享受拆书准备的过程和线下活动的氛围。很高兴能认识大家。\u003c/p>\u003cp>\u003cstrong>【拆书前流程&amp;分组讨论】\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>下面我来介绍下拆书前的流程\u003c/strong>\u003c/p>\u003cp>\u003cstrong>首先\u003c/strong>，我们来简单分下组，按照桌子的左右位置分成2组。一会我们大家可以分组来分享和讨论。\u003c/p>\u003cp>\u003cstrong>其次\u003c/strong>，明确本次拆书可以帮助我们解决生活中碰到的什么具体问题。\u003c/p>\u003cp>\u003cstrong>最后\u003c/strong>，是图书和作者介绍，让我们对图书和作者有基本的了解。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;不知道您是否有过这种经历呢？在你激动的给别人分享你喜欢的东西时，别人却并不太感兴趣。\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;在跟随我完成本次RIA现场学习后，\u003cstrong>你\u003c/strong>\u003cstrong>在表达自己的观点和见解时，不再只是平淡的介绍，而是能够准确运用反差三步法，可以让别人更感兴趣。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【F】\u003c/strong>下面开始介绍今天的图书，今天这个拆书片段来自于日本佐佐木圭一的《所谓情商高就是会说话》，这本书。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;他是首位获得美国广告大奖“金铅笔奖”的日本人。本书是世界各大知名企业员工的人际沟通方面指定培训教材。&nbsp;\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>本书和其他书相比，以大量的实践案例和这个\u003cstrong>“措辞示意图”（展示图片）\u003c/strong>以更加可视化的形式，让读者仅靠阅读，就能产生模拟实战的效果。&nbsp;\u003c/p>\u003cp>\u003cstrong>【B1】\u003c/strong>我们通过运用本书中的语言措辞技巧，来修炼自己说话的能力，也能成为说话的高手。&nbsp;\u003c/p>\u003cp>\u003cstrong>【B2】\u003c/strong>今天拆解的这个片段可以帮我们解决，在别人对我们的话不感兴趣时，我们也能通过反差三步法来创造出直指人心的名言 。&nbsp;\u003c/p>\u003cp>下面，请大家用1分钟时间阅读手中资料左侧的原文片段，读完后由我来给大家分享今天的拆页讲解。\u003c/p>","ratings_count":1,"texts":[{"id":11938,"quote":"\u003cp>\u003cstrong>“好像在做梦，可又不是梦”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“最好是金牌，最坏也是金牌”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“天不造人上人，亦不造人下人”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“口味深浓，兼具清爽”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《美女与野兽》\u003c/strong>\u003c/p>\u003cp>上面这些语句，无一不令人过目难忘。\u003c/p>\u003cp>很多人以为，这样的名言完全是天赐的，只会落在“极少的一部分天才”身上。我在醒悟以前也是这样想的，但事实上，这些名言存在共通点，任何人都能将其重现。\u003c/p>\u003cp>所有这些名言，都包含了\u003cstrong>反义词\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>“在做梦”--“不是梦”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“最好”---“最坏”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“人上人”--“人下人”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“深浓”--清爽”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“美女”--“野兽” \u003c/strong>\u003c/p>\u003cp>这并非偶然。创造警句的线索就藏在其中，只要将反义词组合使用，任何人都能创造出警句。心理学上有一个与这种反差法相似的法则，称为“得失效应”，该法则在人际交流方面的解释是:“最初的评价是消极的，但在不经意间看到积极的一面，评价就会猛然涨高。”\u003c/p>\u003cp>比起其他“措辞菜谱”，反差法需要掌握一些窍门。但效果非常明显，能让你创造出以前写不出来的警句。\u003c/p>\u003cp>下面介绍反差法的“指辞菜谱”，分为三个步骤;\u003c/p>\u003cp>1、确定最想传达的内容\u003c/p>\u003cp>2、在前半句加入反义词\u003c/p>\u003cp>3、自由加入其他词，使前后句连接起来\u003c/p>\u003cp>例如，用反差法写“\u003cstrong>大章鱼烧\u003c/strong>”\u003c/p>\u003cp>①确定最想传达的内容\u003c/p>\u003cp>假设这里是“\u003cstrong>大\u003c/strong>”。\u003c/p>\u003cp>②在前半句加入反义词\u003c/p>\u003cp>“大”的反义词是“\u003cstrong>小\u003c/strong>”\u003c/p>\u003cp>③自由加入其他词，使前后句连接起来\u003c/p>\u003cp>加入“\u003cstrong>显得盘子很小\u003c/strong>”，使前后句连接起来。\u003c/p>\u003cp>Before:“大章鱼绕”\u003c/p>\u003cp>After:“\u003cstrong>显得盘子很小的大章鱼烧\u003c/strong>”\u003c/p>","explains":"\u003cp>\u003cstrong>我看到大家都已经读完了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>这个片段说的是，名言或警句都存在\u003cstrong>共通点\u003c/strong>，任何人都能将其重现。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;那反差法是不是只能创造高大上的名言呢？原文中大章鱼烧的例子就很好的证明了，反差法的适用范围非常的广。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;即可创造高大上的名言，也可应用于柴米油盐的日常生活。即可应用于生活中的友情推荐、强调观点等，也可应用于工作中的零售、演讲、写文案、做广告等等场景。\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003cbr>\u003c/p>\u003cp>说完了它的应用场景和适用范围，我们再来说说它的共通点是什么呢？原文又告诉我们，共通点是都包含了\u003cstrong>反义词\u003c/strong>。那我们可以如何重现并也能创造出它们呢？原文提供了3个具体步骤：\u003c/p>\u003cp>\u003cstrong>第一步：问，\u003c/strong>问自己最想表达的内容，并找到关键的那个的字或词。\u003c/p>\u003cp>\u003cstrong>第二步：反，\u003c/strong>在前半句加入关键词的反义词。\u003c/p>\u003cp>\u003cstrong>第三步：\u003c/strong>\u003cstrong>通\u003c/strong>\u003cstrong>，\u003c/strong>自由加入其他词让句子更加通顺。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>【平常的做法】\u003c/strong>我们一般都是如何表达自己的观点或建议的呢？一般我们都非常容易会把脑中的想法，以\u003cstrong>直接的、没有修饰\u003c/strong>的形式说出来。\u003c/p>\u003cp>\u003cstrong>【平常做法举例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>举个例子：\u003c/strong>去年我们全家去海南玩，非常愉快。\u003c/p>\u003cp>回来跟身边想去海南旅游的人说：\u003cstrong>去\u003c/strong>\u003cstrong>“\u003c/strong>\u003cstrong>呀诺达\u003c/strong>\u003cstrong>”\u003c/strong>\u003cstrong>因为\u003c/strong>\u003cstrong>太好玩了\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处，平常做法的后果和影响】\u003c/strong>\u003c/p>\u003cp>上面这句话，就是用\u003cstrong>直接的、没有修饰\u003c/strong>的形式说出来，&nbsp;从而显得\u003cstrong>非常平淡\u003c/strong>，给不了别人足够的\u003cstrong>画面感和冲击力\u003c/strong>。无法更好的引起别人的兴趣。\u003c/p>\u003cp>其他还有很多运用了反差法带给我们\u003cstrong>画面感和冲击力\u003c/strong>的例子，比如：\u003c/p>\u003cp>团队不是为你而存在，你是为了团队而存在！\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ——《SLAM DUNK》(日本人气动漫《灌篮高手》安西教练)\u003c/p>\u003cp>生活不止眼前的苟且，还有诗和远方。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ——高晓松（导演、编剧、制片人、音乐人）\u003c/p>\u003cp>假如这里有坚固的高墙和撞墙破碎的鸡蛋，我总是站在鸡蛋一边。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;——《耶路撒冷文学奖获奖演说》村上春树\u003c/p>\u003cp>\u003cstrong>这些句子也都用了简单的词汇，但是因为运用了反差法，瞬间就起到了直指人心的效果。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【正面例子】\u003c/strong>那么，如果可以\u003cstrong>再回到去年\u003c/strong>海南游的场景，我会如何使用反差三步法来改进我的推荐，可以让身边的人更感兴趣呢？\u003cstrong>（展示图片）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：问\u003c/strong>\u003cstrong>，\u003c/strong>自己想表达\u003cstrong>“好玩”\u003c/strong>；\u003c/p>\u003cp>\u003cstrong>第二步：反\u003c/strong>\u003cstrong>，\u003c/strong>前半句加入反义词\u003cstrong>“无聊”\u003c/strong>；\u003c/p>\u003cp>\u003cstrong>第三步：通\u003c/strong>\u003cstrong>，\u003c/strong>加入蓝色字让句子更加通顺。\u003c/p>\u003cp>我可以这么说：\u003c/p>\u003cp>\u003cstrong>和”呀诺达“比起来，其他景点\u003c/strong>\u003cstrong>都\u003c/strong>\u003cstrong>显得极其无聊，推荐\u003c/strong>\u003cstrong>去\u003c/strong>\u003cstrong>”呀诺达“\u003c/strong>\u003cstrong>太好玩了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【对比\u003c/strong>\u003cstrong>总结\u003c/strong>\u003cstrong>】\u003c/strong>现在，对比两个例子，你是不是也觉得改进后的例子\u003cstrong>(手指图片中改进后的例子处)\u003c/strong>更能直指人心，引发别人的兴趣。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】\u003c/strong>听了我上面的分享和例子后。不知你是否也有激动的跟别人分享喜欢的东西时，别人却并不太感兴趣的经历呢？\u003cstrong>（\u003c/strong>\u003cstrong>停5秒\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【显像提问法】\u003c/strong>\u003cstrong>（语速放慢、音量轻柔）\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;现在，大家一起来随着我的声音想象一下，你现在就站在那个人面前，你特想把喜欢的东西分享给他。下面，请仔细听以下这些词\u003cstrong>（展示图片，\u003c/strong>视觉型的朋友可以看这个图片来思考一下\u003cstrong>）\u003c/strong>\u003cstrong>（裙子、鞋、包包、菜馆、招牌菜、电影、电视剧、书、演讲、网课、旅游景点）\u003c/strong>哪个词能引发你产生回忆，让你想起最近一周或一月在哪？向谁？分享了这个词，但是别人却对此不太感兴趣呢？\u003c/p>\u003cp>想到后，请大家按照\u003cstrong>(展示图片并手指向A1栏处)\u003c/strong>这栏的格式，把它写下来吧。\u003c/p>\u003cp>\u003cstrong>写完后，请大家分组分享经历，时间2分钟。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>分钟后\u003c/strong>\u003cstrong>）好的，大家先暂停一下，一会我们还有讨论的机会。下面，有\u003c/strong>\u003cstrong>请2位朋友各用1分钟跟我们大家做一下分享。\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者案例： \u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者王博：\u003c/strong>昨天晚上7点多我去耀莱成龙电影院看“玩具总动员4”，里面的新成员&quot;叉叉&quot;给我印象很深刻，回来后跟身边的人推荐这个电影。我说：\u003cstrong>玩具总动员4的新成员叉叉给了我非常新颖的感觉，推荐你去看看\u003c/strong>。但是身边的人并不太感兴趣。\u003c/p>\u003cp>\u003cstrong>学习者靳福库：\u003c/strong>上周二在宿舍，我看了“唐望系列3部曲”的第一本。这本书是写现代人学习印第安巫术的经历我非常喜欢。跟身边的人强烈推荐这套书。但是我没有用反差三步法，来强调我为啥要推荐，而只是直接、不加修饰的，非常激动的在说书中自己感兴趣的内容。并持续说了1个小时，说的我舍友都犯困想睡觉了。\u003c/p>\u003cp>\u003cstrong>非常感谢2位朋友精彩的分享。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1+】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>为了帮助大家回忆并更清晰反差法的三个步骤，我们再来重复一遍\u003cstrong>(展示图片)\u003c/strong>：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我刚才看到大家都分享了自己的过往经历。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;那么假如，可以再次回到你刚才案例中的场景\u003c/strong>，你会如何运用今天学到的反差三步法来向别人分享，来更好的引发别人的兴趣呢？\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;（展示下图，手指A1+栏），\u003c/strong>我们可以把这个问题想的简单一点，先来找到自己刚才案例中的那个最想表达的\u003cstrong>“关键字或词”（手指第一步：问）\u003c/strong>，然后在想一个它的反义词\u003cstrong>（手指第二步：反）\u003c/strong>，最后使句子通顺就可以\u003cstrong>（手指第三步：通）\u003c/strong>。不是必须要整的非常高大上也可以很贴近生活的。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;例如：我们想形容一个人\u003cstrong>幼稚\u003c/strong>，可以说他:“这个人看着高高大大的，做起事来就像一个小孩子”、想形容一个面\u003cstrong>好吃，\u003c/strong>再吃其他家的拉面我都觉得非常难吃，因为这家的豚骨拉面实在太好吃了“、这些我们日常的聊天也都是可以用反差法的。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;想到后，就请大家按照\u003cstrong>(展示图片并手指向A1+栏处)\u003c/strong>这栏的格式，把它写下来吧。\u003cbr>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;写完后，请每人分组分享步骤，时间5分钟。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（5分钟后）好的，时间已经到了。下面，有请2位朋友各用1分钟跟我们大家做一下分享。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者王博：\u003c/strong>关于给别人推荐自己喜欢的电影的问题，我可以：\u003c/p>\u003cp>\u003cstrong>第一步：问，\u003c/strong>自己想表达“\u003cstrong>新颖\u003c/strong>”；\u003c/p>\u003cp>\u003cstrong>第二步：反，\u003c/strong>前半句加入反义词“\u003cstrong>一成不变\u003c/strong>”；\u003c/p>\u003cp>\u003cstrong>第三步：通，\u003c/strong>加入连接词让句子更加通顺。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我可以这么说：\u003cstrong>玩具总动员4其他角色还是一成不变的风格，新成员叉叉给了我非常新颖的感觉，推荐你去看看。\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>学习者靳福库：\u003c/strong>关于推荐给别人自己喜欢的书的问题，我可以：\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：问\u003c/strong>\u003cstrong>，\u003c/strong>自己想表达\u003cstrong>“真实”\u003c/strong>；\u003c/p>\u003cp>\u003cstrong>第二步：反\u003c/strong>\u003cstrong>，\u003c/strong>前半句加入反义词\u003cstrong>“盲目”\u003c/strong>；\u003c/p>\u003cp>\u003cstrong>第三步：通，\u003c/strong>加入连接词让句子更加通顺。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我可以这么说：\u003cstrong>比起盲目的选择一条路去生活工作，在日常生活中发现和面对真实的自我会更幸福。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【结束】非常感谢2位朋友的精彩分享。\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 下面一起回顾一下，我们今天分享了反差法的三个具体步骤：\u003cstrong>问\u003c/strong>\u003cstrong>、\u003c/strong>\u003cstrong>反\u003c/strong>\u003cstrong>、\u003c/strong>\u003cstrong>通\u003c/strong>，并进行了分组讨论和请2位朋友做了精彩分享。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 好的，我分享到这里就全部结束了，谢谢大家的认真聆听和耐心配合。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1562212587000,"updated_at":1562544941000,"ria":true},{"id":8190,"topic":"把“No”的回答变成“Yes”","learn_goal":"通过高明的措辞，提升回答“Yes”的可能性","remark":"说话不只是一种“感觉”，它还是一门“技术”，就像烹饪有食谱一样，说话也有它的“秘方”，人际沟通中怎样措辞，怎样把握说话的场合和时机？\r\n\r\n如何领略说话精髓，悟透说话之道，在众人中脱颖而出呢？如果你也想提升自己的措辞技巧，让自己说话更得体，周二来西藏南路和竹兰一起学习沟通的技巧。\r\n\r\n","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"李竹兰","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"各位小伙伴们，大家好，我叫李竹兰，用三个标签介绍一下我自己：房地产HR，学习爱好者，新手拆书家。\r\n今天我要为大家带来的这本书叫《所谓的情商高就是会说话》。作者佐佐木圭一通过自己多年来掌握的语言措辞技巧告诉大家该如何修炼说话能力，如何提高自己的说话水平。在本书中，你可以通过熟悉的“7个关键点”和“8个技巧”，并阅读大量实践故事，更好地掌握并运用语言措辞的技巧，使自己成为说话高手\r\n今天我给大家带来的拆页是把“No”变成“Yes”回答的技巧，学习这个拆页可以提升我们的说话措辞，可以把回答“Yes”的可能性从0提升到2-3成。","ratings_count":1,"texts":[{"id":11799,"quote":"\u003cp>为便于小伙伴们今天的学习，在发拆页之前我先来分一下组：厨师大哥到Ailsa一组，青青到猫仔一组，草莓到路路一组，共分为3组。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 下面我把拆页发给大家，然后请小伙伴们用2分钟时间阅读，阅读完的小伙伴举手示意一下。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 提升“Yes”回答,有3个步骤。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 步骤1:“不直接说出自己的想法”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;一般来说,人都容易不假思索地把脑中的想法直接说出来。然而,这样不仅常常事与愿违,而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1\u003c/p>\u003cp>当然,我们都是凡人,不可能保证所有事都不直接说出来,但至少请记住,不要直接说出“这是很重要的请求!”之类的话。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;例如:有人从老家寄来很多柑橘,家人甚至都吃腻了,而你不想让剩下的柑橘白白烂掉。\u003c/p>\u003cp>在这种时候,请不要直接说:\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “大家继续吃啊!”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;步骤2:“揣摩对方的心理”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;请揣摩对方的心理,并根据其平日表现,猜测对方会对你的请求作何想法。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;直接说出请求,对方会作何反应?如果对方回答“Yes”的可能性很大,当然可以直接说……\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;如果对方回答“No”的可能性很大,就不能直接说了。请暂时忘记自己的请求,揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “不能光吃柑橘。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 这应该就是家人的想法。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 此时,请再次忘记自己的请求,想想家人的喜恶。例如:\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “不想感冒。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 没人愿意生病。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 到了容易感冒的季节,身边就会出现感冒患者,家人都很在意这一点。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 步骤3:“考虑符合对方利益的措辞”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 提出的请求,要让“对方的利益”和“自己的利益”趋于一致。想达到这一点,就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 关键在于,要创造符合对方利益的上下文关系。即使措辞有所改变,只要最终达成目的就行。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 既然家人不想感冒,就可以对他们说:\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “多吃柑橘就不会感冒了。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 这样的措辞符合对方的利益,家人就会变得乐意吃柑橘,而你的目的也就达到了。\u003c/p>","explains":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我看小伙伴们已经阅读完，接下来由我带领小伙伴们一起来学习一下原文。\u003c/p>\u003cp>（Why）有时候我们会听到身边的伙伴说：“我这人说话就是直，但我并没有恶意”，不经思考的说出自己的想法，不仅无法达到说话目的，还会给人留下这人说话怎么这样的印象。\u003c/p>\u003cp>（what）今天的片段告诉我们从对方的利益角度出发，来考虑我们的措辞，虽然不能每次都让别人回答“Yes”，但可以让我们的措辞变得高明，提升“Yes”回答的可能性。\u003c/p>\u003cp>（How）提升回答“Yes”可能性的三步骤是：\u003c/p>\u003cp>第一步：说之前先停顿一下：停顿的目的是让自己不直接说出想法，说前可以根据不同的场景、不同的对象思考几秒之后再决定说不说，如何说？\u003c/p>\u003cp>第二步：揣摩对方的心理（考虑对方的想法）：思考一下别人不愿意这样去做的原因，根据对方的喜好、性格、愿望来考虑他的想法，这一步骤的核心在于对对方心理的精准把脉，这就要求我们足够或提前了解过对方。\u003c/p>\u003cp>第三步：选择双方有利的措辞（共赢）：通过揣摩对方的心理，找寻符合双方利益的措辞。\u003c/p>\u003cp>（Where）讲到这里我要说一下的就是，即使应用以上步骤来措辞，也不能保证每次回答都是“Yes”，关键在于增加优质措辞的次数，真正掌握措辞方法，所以该片段更适用于对方回答“N0”的可能性很大的时候，你如何来准备自己的措辞。\u003c/p>\u003cp>&nbsp;说个我自己的案例：\u003c/p>\u003cp>上周天老公想让我陪他去宜家买家具，那会我正在打扫卫生，所以我想让他帮我一起打扫，以前每次叫他都装听不到，自然也不会来帮忙\u003c/p>\u003cp>按照上面三个步骤，我说服了老公答应一起帮我打扫卫生：\u003c/p>\u003cp>第一步，说之前先停顿一下：先不说出自己的想法——帮我打扫卫生\u003c/p>\u003cp>第二步，揣摩对方的心理：根据我们平日的相处，老公不喜欢太强硬的说话方式，所以我不能直接和他说“快来帮我一起打扫卫生”，出于职业爱好，老公对家居设计有独特的喜好，我揣测此刻他的心理：快点出门去看我喜欢的家具。\u003c/p>\u003cp>第三步，选择双方有利的措辞：根据老公的心理和我的想法措辞——“你刚说要去看家具的时候，我看了一下宜家今天有优惠活动，而且是最后1天，之前你一直想买的茶几也优惠了好几百呢，你看我们一起快速打扫完卫生，然后赶紧出门，怎么样？”\u003c/p>","interaction":"\u003cp>【A1】激活学习者经验\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学完今天这个拆页，我们知道了在拜托别人做事情时如何让自己的措辞变得高明，提升回答“Yes”的可能性。大家回想一下，之前拜托别人做事情时都是怎么措辞的，是不经思考的直接表达吗？有没有在措辞前思考分析过对方的心理，如果没有，反思以上步骤哪里没做到位，大家可以先在小组内分享。\u003c/p>\u003cp>分享相关经验时要有具体的时间、地点、人物、事件。讨论完后我会邀请1-2位小伙伴来分享他的经历。\u003c/p>\u003cp>（2分钟后）下面我邀请shelly伙伴为我们分享一下她的相关经验。大家欢迎！\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 昨天想让我老公等我一起回家，结果他说：哎呀，我时间不定的，不要等了，挺麻烦了，我吃了闭门羹，当时想都没想，就把自己的想法直接和他说了，所以我没有做到的是，没有停下来，直接就把自己的想法说出来了，更重要的是没有去揣摩他的需求是什么，所以很容易被拒绝。\u003c/p>\u003cp>【A2】规划应用\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;感谢shelly小伙伴为我们分享的案例，那接下来请小伙伴们想想在接下来的1-2周内有没有什么事情需要拜托家人、同事或朋友做的，根据今天的措辞技巧，你会怎么去准备自己的措辞，请写下具体场景和行动步骤。\u003c/p>\u003cp>写便签时请注意：不能仅是表决心，要有明确的目标和时间期限，并结合原文知识，制定一个详细的行动步骤。\u003c/p>\u003cp>草莓小伙伴的分享：\u003c/p>\u003cp>目标：喜乐分舵周二场因更换场地，我作为周二场的场主，想邀请崔律舵主本月参加周二场下次的拆书活动，用今天的方法我会这样准备邀请措辞：\u003c/p>\u003cp>期限：6月底前\u003c/p>\u003cp>行动步骤：\u003c/p>\u003cp>1、说之前先停顿一下：先不要直接说出我的想法，即我想让舵主本月来参加我们某周周二场的活动。\u003c/p>\u003cp>2、揣摩对方的心理（考虑对方的想法）：崔律平时工作忙，而且周三她还有专场活动，如果我只是简单邀请参加活动，并不一定能成功，从我当场主开始，崔律虽然没来过，但是每次都会很关心我们活动的效果以及拆书情况，所以舵主的心理很在乎周二场能不能办好。\u003c/p>\u003cp>3、找寻符合双方的利益措辞（共赢）：站在舵主的角度了解完她的心理之后，我会这样准备措辞：舵主好，从我当周二场的场主已经有一段时间，对拆书活动也有了一定了解，为了能做好这个活动，我做了1、2、3个方案，想邀请你6月份某周二来参加我们的活动，然后面对面的和你讨论一下这些方案，也希望你能给我一些建议，尽快让周二场越办越好，不知道你下周二或6月的某周二有时间吗？\u003c/p>\u003cp>通过这样准备措辞之后，舵主答应的几率是不是大大提升了。\u003c/p>\u003cp>时间到，请大家把便签交给我，我的分享到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1560782897000,"updated_at":1560782897000,"ria":true},{"id":8156,"topic":"No变YES的技巧","learn_goal":"使用No变YES的谈话技巧让别人答应我们的请求","remark":"说话不只是一种“感觉”，还是一门“技术”！就像烹饪有食谱一样，说话也有它的“秘方”。古往今来，但凡不通说话之道者，都难成大事，而能成事者，一定在语言方面具有其独特的能力。一句恰到好处的话，甚至可以改变一个人的命运。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"小面包","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"\u003cp>【开场自我介绍】1min\u003c/p>\u003cp>大家晚上好,非常高兴能在今天晚上认识大家，与大家一起学习，这也是我的一个荣幸。然后我再做一次自我介绍。我的第一个标签是：减肥，因为人不爱美天诛地灭，所以要在夏天来临之前减肥，穿好看的衣服。第二个标签是：少女心。全世界都在催我长大，只有迪士尼在守护我的少女心。第三个标签是JK制服。其实就是日本高中生制服这类衣服的简称。这就是对我自己的一个介绍。\u003c/p>\u003cp>【拆书帮介绍】1min\u003c/p>\u003cp>今天不是有新来的小伙本吗，新朋友可能对拆书以及拆书帮不太了解，我为大家简单的介绍一下。你第一次听到拆书帮的时候，是不是以为拆书是把书撕开、拆开吗？其实不是的，拆是拆解，转化、内化的意思。但是拆解也是有迹可循，有独特的方法的。它就是阅读拆页+讲解引导+拆为己用，一种把知识转化为能力的学习方法。它分为两种形式，分别是个人学习和组织学习，对于个人来说，你可以通过书写便签，重述原文信息，关联过往经验，来规划未来的应用；对于组织学习来说，就像今天我们这样，通过现场的一起学习与探讨，来真正地将知识学为己用。\u003c/p>\u003cp>而拆书帮，就是这样一群积极向上的学习爱好者，跨越地域的界限，聚到一起，自发的公益性青年组织，致力于帮助更多的学习爱好者一起成长。\u003c/p>","ratings_count":1,"texts":[{"id":11760,"quote":"\u003cp>【主题】NO 变 YES\u003c/p>\u003cp>【来源】所谓情商高，就是会说话 佐佐木圭一\u003c/p>\u003cp>措辞的使用有利于将“No”的回答变成“Yes”，有3个步骤。\u003c/p>\u003cp>步骤1：“不直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤一。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。在这种时候，请不要直接说：“大家继续吃啊！”\u003c/p>\u003cp>步骤2：“揣摩对方的心理”\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。”这应该就是家人的想法。此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>【I】3min 用自己的语音重述信息\u003c/p>\u003cp>WHAT:\u003c/p>\u003cp>我们刚刚读到的是是关于措辞使用的一些技巧，在人生中的很多重大的时刻，措辞对结果都起着至关重要的作用，同样的内容，用高明的措辞说出来，可能就会使对方从“No”变成“YES”。原文给我们讲述了从“No”到“YES”，需要的三个步骤。\u003c/p>\u003cp>WHY:\u003c/p>\u003cp>措辞能改变人生与意中人交谈、工作中的简报、家人的日常生活、就业面试，越是人生中的重要时刻，措辞对结果的影响越大。同样的的内容，换一种措辞，用高明的措辞说出来，却会达到不一样的效果，甚至改变人生。就很可能使对方的回答从“No”变成“Yes”，使人们的生活增加了更多的可能性，有更多的突破。\u003c/p>\u003cp>HOW:\u003c/p>\u003cp>1、&nbsp;不直接说出自己的想法\u003c/p>\u003cp>如果说话者不考虑当时的情境不顾及别人的感受，把想说的话直接地表达出来，不仅起不到应有的作用，还会引起对方的不悦，破坏相互之间的和谐关系。\u003c/p>\u003cp>讲话时不直陈本意，而用委婉之词加以烘托或暗示，让人去揣摩含义，因而也就越具有吸引力和感染力。所以不能直接暴露自己的想法，也不能直接说出请求之类的言辞。\u003c/p>\u003cp>2、&nbsp;去探寻对方心理，找出解决办法\u003c/p>\u003cp>针对某个请求，依据你对对方的了解，猜测对方对我们请求的想法。假设，直接说出请求，猜测对方的回答是“No”还是“YES”；如果回答“No”，那么就要从对方的性格、喜好以及平时的一些行为表现，去探寻如何达到“YES”。\u003c/p>\u003cp>3、&nbsp;从对方利益出发，达到双赢\u003c/p>\u003cp>基于对方的心理考虑措辞，创造符合对方利益的条件,在措辞的改变下，既能满足对方利益的需求，又能达到我们自身的目的。\u003c/p>\u003cp>WHERE:\u003c/p>\u003cp>与家人相处的日常生活、朋友之间的交谈、提意见、就业面试等环境都可以考虑措辞的使用\u003c/p>","interaction":"\u003cp>A1:3min &nbsp;描述自己的经验\u003c/p>\u003cp>去年十月份的时候我朋友提前两周和我约好了去爬香山，但是到要去的那一周的时候她告诉我说：“我导师这周找我，香山我不去了！”虽然，真的是迫不得已，可是作为被通知的一方，除了失望，我还觉得她有点不太重视我。\u003c/p>\u003cp>我原本高兴激动的心情，被阴云笼罩，计划全部被打乱，情绪非常低落。\u003c/p>\u003cp>反思：\u003c/p>\u003cp>我的朋友也是没有错的，毕竟导师找她去做课题是无法拒绝，还是以学业为重，我也能理解。但是为什么她让我产生了特别不好感觉呢？\u003c/p>\u003cp>首先第一，她用十分直接的话语通知我取消了约会，没有考虑到我的想法；\u003c/p>\u003cp>其次如果她表达的委婉一点，猜测一下我听到这个决定之后的想法，并且基于我的心理去考虑，换种措辞方式来告诉我这件事情，也许我并不会如此的低落\u003c/p>\u003cp>比方说：“对不起，我导师临时找我，虽然我很想你，但是我实在没有办法过去，等我时间确定空闲了，我去看你好不好？”\u003c/p>\u003cp>只是换了一种措辞，我的心情立刻就会变得不一样\u003c/p>\u003cp>A2：3min &nbsp;&nbsp;目标与应用\u003c/p>\u003cp>目标：\u003c/p>\u003cp>通过对这个片段的学习，我决定这个周末利用合理的措辞，让室友在以后的日常生活中注意公共卫生\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1.首先，我会通过一些刚好在一起的时间去沟通，但是不会先直接说出自己的想法，以便于可以更好的达到自己的目的\u003c/p>\u003cp>2.想一下，如果我直接向室友表达我的愿望，她以后是否会按照我的请求去做呢？当然也是有可能，但是直接表达，也可能会使室友心里上感觉到不舒服，会给让她产生一些逆反心理，反而更不想去打扫卫生了。\u003c/p>\u003cp>3.最后，我会找到我和室友利益一致的点，居住环境干净了，可以让我们每天保持愉快的心情，也可以防止细菌滋生，保证身体健康。在聊天的过程中，我可以以养生这个话题为切入点，强调健康的重要性，进而表达希望大家一起注意公共卫生的愿望。\u003c/p>\u003cp>如果我能完成这个目标，我会奖励自己吃一顿好吃的\u003c/p>\u003cp>大家生活和工作当中肯定都会遇到这种，表达请求被拒绝的情况，那不防试试这三个步骤，能够在措辞上有些变化，肯定会带给你意想不到的效果。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1560498687000,"updated_at":1560498729000,"ria":true},{"id":7511,"topic":"用反差法制造感动","learn_goal":"用反差法制造感动，迅速达成共鸣","remark":"本书是日本深受欢迎的人际沟通教程，世界知名企业员工指定的培训教材。这本书中通过大量实践故事 ，介绍了沟通中“7个突破口”和“8个技巧”的使用方法，可以更好地帮助读者掌握并运用语言措辞的技巧，使大家成为说话高手。\r\n\r\n我们生活在一个信息量倍增的时代，那些普通、没有特色的信息很容易被人们所忽略。那么，你是否希望你的表达能让听的人迅速产生共鸣？让我们一起学习反差法吧。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"littledl2019","city":"大连"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者在表达自己的观点和见解时，不再只是平淡的介绍，而是能够运用反差法，给人留下深刻的印象。\u003c/p>\u003cp>大家好，非常感谢大家来参加我的拆书练级活动。先介绍一下我自己，用三个标签，第一个标签是工程设计，第二个标签是学习爱好者，第三个标签是成长，我参加拆书帮也是挑战自我选择成长的过程。&nbsp;\u003c/p>\u003cp>我们先分下组，一会儿大家需要在小组内进行讨论，那边6个人一组，这边6个人，这边6个人一组。\u003c/p>\u003cp>【F】我今天分享的片段选自《所谓情商高就是会说话》，作者佐佐木圭一，是日本顶级沟通专家、文案写作大师，被视为亚洲最成功的广告策划人。这本书把措辞的技巧比喻为菜谱，教我们运用“7个突破口”和“8个技巧”搭配出感人的语言。\u003c/p>\u003cp>【A】这本书是日本深受欢迎的沟通教材，世界知名企业员工指定的培训教程。和其他的书相比，这本书中提供了大量实践故事，可以更好地帮助读者掌握并运用语言措辞的技巧。\u003c/p>\u003cp>【B】你有没有过这种经历，你向别人做一些介绍、提出请求，或者提出建议，却遭到对方拒绝？这本书可以帮助你提高对方说“Yes”的成功率。你是否希望你的表达能够脱颖而出，瞬间打动人心？这本书可以帮助你快速提高你表达的感染力和影响力。\u003c/p>\u003cp>下面，请大家阅读一下原文片段，时间是1分钟。\u003c/p>","ratings_count":1,"texts":[{"id":10984,"quote":null,"explains":"\u003cp>大家都已经读完了吧，这个片段看起来是不是特别简单？所谓知易行难，我们一起来学习一下。\u003c/p>\u003cp>【负面例子】\u003c/p>\u003cp>前两天我对一个朋友介绍阅读的好处的时候，我跟他说：“我们可以从书中获取大量的知识。”可是对方听着根本无感，这个已经是老生常谈，引起不了他的兴趣。\u003c/p>\u003cp>【负面一般做法】很多人在表达时都是很直接的、没有修饰的说出自己的观点。\u003c/p>\u003cp>【不这样做的坏处】但是，我们生活在一个信息量倍增的时代，那些没有特色的信息很容易被人们所忽略。如果我们的语言无法打动人心，会错失很多发展的机会。\u003c/p>\u003cp>【拆页行动建议】\u003c/p>\u003cp>那么，有没有方法可以制造出强大的、令人感动的语言呢？\u003c/p>\u003cp>其实，是有方法的，使用今天这个反差法，就可以实现。\u003c/p>\u003cp>分为三个步骤：\u003c/p>\u003cp>第一步，明确主题，我们先要明确希望表达的是什么？&nbsp;\u003c/p>\u003cp>第二步，取反义词，在主题前面加上一个反义词。\u003c/p>\u003cp>第三步，连接，把前后连贯起来，形成一个完整的句子。\u003c/p>\u003cp>举个例子，比如，苹果创始人乔布斯有一个观点，“当海盗更有趣”，他在这里用海盗比喻团队要打破常规。海盗的反义词是海军，海军代表的是纪律严明。连起来，乔帮主的原话是“加入海军还不如当海盗更有趣”。\u003c/p>\u003cp>其他的还有像：\u003c/p>\u003cp>顾城的：黑夜给了我黑色的眼睛，我却用它来寻找光明。\u003c/p>\u003cp>高晓松的一句话：生活不止眼前的苟且，还有诗和远方。\u003c/p>\u003cp>这些都是用最简单的词汇，因为使用反差法，瞬间打动人心。\u003c/p>\u003cp>【正面例子】\u003c/p>\u003cp>回到开头的例子，下次我再给别人介绍阅读的好处，可以表达，书的好处是书中有大的内涵，大的反义词是小，连成一句话就是“再小的书，也有大内涵”。这句话实际上是一句广告语，在这里借用一下。\u003c/p>\u003cp>【适应边界】\u003c/p>\u003cp>这个反差法适用在需要强调我们的观点，或者是我们需要增强表达的感染力的时候，或者是一些关键时刻，比如说演讲、写文案、做广告时。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>下面请大家回想一下近期有没有这样的经历，想给对方做推荐，但并没有引起对方足够的注意？可以是推荐一个人、比如他的特征或者职业，或者你向朋友推荐一本书、一场电影、一个餐厅、一道菜、一个景点，都可以。大家在小组内讨论一下，时间是2分钟。\u003c/p>\u003cp>学习者一：前几天，在工作中，给大家推荐《少有人走的路》这本书，我推荐时只讲了里面的一点，“推迟满足感”，当时推荐时讲的比较理论，讲推迟满足感是什么，没有打动到大家心坎里，8个人的反馈，只有2个人觉得这本书可以回去看一下。\u003c/p>\u003cp>学习者二：我几乎每天都会学习很多东西，学完了我认为对成长比较有帮助的，就分享给我爱人，有时微信发4、5个。今天开车时问她，看没看。告诉我，没怎么看。偶尔看一个两个。\u003c/p>\u003cp>我发的方式，就是比如从头条上看的，直接就转发了，什么话都没有。这个可能是个问题。\u003c/p>\u003cp>【A1+】\u003cbr>\u003c/p>\u003cp>接下来再就刚才反思的情形，运用今天的反差法，考虑一下怎么改进你们的表达方式。时间是5分钟，大家再讨论一下，每人写一个便签。\u003c/p>\u003cp>……假如我们再重来一次，重回到刚才的场景，我们要如何表达？\u003c/p>\u003cp>……比如形容一个人的特征，可以说他“外表粗狂，内心温柔”、大家先要明确主题，可以把这个问题想的简单一点，“再比如，我吃了这家拉面之后，再也不想吃其他家拉面了，因为其他家的拉面都很难吃，只有这家拉面好吃“、或者说”这个人看着高高大大的，做起事来就像一个小孩子。“这些都是反差。\u003c/p>\u003cp>学习者一：如果再介绍《少有人走的路》，我会这样说：这本书可以帮助我们告别焦虑，走向成熟。\u003c/p>\u003cp>学习者二：像昨天给我爱人推荐的文章，我会这样说：“不像那些标题党鸡汤文，这篇文章是吴小波写的，很权威。”\u003c/p>\u003cp>学习者三：我们家在对待孩子的问题上会用这个方法。昨天我们家小孩，在我回家时，作业还没写，然后我逼着她写到9点半才睡觉。如果回到昨天这种情况，我就会这么跟她说：“你看看人家龙龙，早就把作业写完了，你看看你，每次都这样！”当然这个有点暴力，如果再回到昨天的情况，我会用这种方法去说，但是不会这么暴力啊。“你看看人家小朋友，人家每天都做的那么好，每天都按时睡觉，你每天都这样，下次能不能也好好点。“（不建议这样使用，会打击小孩子的积极性，应该用在正向的方面）\u003c/p>\u003cp>每你看看人家小朋友，早，你看年尽管到我那一段，当时推荐时讲的比较\u003c/p>\u003cp>学习者四：我以前想学习，总是拉着我对象去，他有时会很不情愿。如果回到上次，我可以这样说：“哥，我最近有点懒散，这周末你勤快点带我学习一个小时怎么样？”\u003c/p>\u003cp>我分享就到这里，谢谢大家。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1554555284000,"updated_at":1562367456000},{"id":7343,"topic":"如何让对方的回答从No变为Yes","learn_goal":"通过学习三步找到高明的表达方式，得到对方肯定的回答。","remark":"","level":"TF1-1","duration":13,"status":30,"type":0,"chaishujia":{"username":"张梦婷","city":"株洲"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>【自我介绍】大家好，我是张梦婷，梦想永不停息的梦婷。对这个世界满满好奇的我，一直喜欢学习喜欢尝试新事物。下面用三个标签介绍自己，第一个标签小学数学老师，第二个标签阅读爱好者，书像是另一个世界，总会给你带来不同的收获跟乐趣，而拆书法让我更高效地读懂这个世界。第三个标签终身学习终身工作者，我计划我七老八十的时候，还要继续保持对学习的热情，还继续享受工作带来的价值感。很高兴在拆书帮这个能量场与大家相识。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>工作和生活中，我们常需要从书里借鉴方法，来解决我们碰到的一些问题。但往往拿到一本书后，却没有时间整本阅读，即便有时间从第一页读到最后一页，到用的时候也早就忘了书中的内容。拆书法，就是一种适用于有这些困惑，以提升能力、解决问题为目标的成人学习方法。你不需要花大段的时间阅读整本书，只需要在书里选出你感兴趣的片段，然后把咱们生活中的经验与书中知识相关联，这样，以规划具体的应用为目的来指导我们的阅读，阅读就变得“有用”了。\u003c/p>\u003cp>拆书法有两种应用形式，一种是可以用于个人学习的RIA便签学习法。另一种是组织学习，就是现在我们这样由拆书家加工一场现场RIA学习，引导大家把知识拆为己用。那什么是RIA呢？R（reading），指的是阅读原文片段。I（interpretation），重述知识，用自己的话将原文片段复述清楚。A（appropriation），分为A1和A2，A1描述自己的相关经验，A2规划未来的应用。\u003c/p>\u003cp>拆书帮是基于拆书法的学习爱好者社群，全国各地都分布着拆书帮的分舵，我们今天的活动组织方是拆书帮的长沙麓山分舵。每周五晚上，我们在一起拆书、一起提升能力、一起成为更好的自己。相信你会爱上这里的学习氛围，你也会爱上进步中的自己！\u003c/p>\u003cp>欢迎大家来到拆书帮一起学习成长！\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>今天我要给大家拆解的是《所谓情商高就是会说话》这本书，它的作者是佐佐木圭一，这位作者是日本的顶级沟通专家、广告鬼才、文案写作大师。这本书是日本深受欢迎的人际沟通课程教材，书里他用简洁的语言高度概括了说话技巧，能让你不走弯路，以最短的时间掌握说话技巧。书里编写了大量的实践故事，让你能边读边练，读完就能学会。到底有没有这么神奇的效果？一起来看这本书的片段。\u003c/p>","ratings_count":1,"texts":[{"id":10789,"quote":"\u003cp>日本 佐佐木圭一《所谓情商高就是会说话》p7~10\u003c/p>\u003cp>R【阅读原文片段】把“No”的回答变成&quot;Yes” ，有3个步骤。\u003c/p>\u003cp>步骤1:“不直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求!”之类的话。\u003c/p>\u003cp>例如:有人从老家寄来很多柑橘，家人甚至都吃腻了而你不想让剩下的柑橘白白烂掉。\u003c/p>\u003cp>在这种时候，请不要直接说:\u003c/p>\u003cp>“大家继续吃啊!”\u003c/p>\u003cp>步骤2:“揣摩对方的心理”\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应?如果对方回答“Yes&quot;的可能性很大，当然可以直接说....\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes” 的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。”\u003c/p>\u003cp>这应该就是家人的想法。\u003c/p>\u003cp>此时，请再次忘记自己的请求,想想家人的喜恶。例如:\u003c/p>\u003cp>“不想感冒。\u003c/p>\u003cp>没人愿意生病。\u003c/p>\u003cp>到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3:“考虑符合对方利益的措辞’\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>既然家人不想感冒，就可以对他们说:\u003c/p>\u003cp>“多吃柑橘就不会感冒了。”\u003c/p>\u003cp>这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>我分享的第一张便签是I便签，重述原文知识。\u003c/p>\u003cp>不知道你有过这样的经历吗？想请同事带个早餐，想让家人分担点家务，想让心仪的对象答应你的邀约，想让你的顾客多买点你的产品，想让供应商给你加急出货……一个人平均每天会发出22次请求，有些时候小的请求对方会同意，但很多时候在发出请求时我们内心是很忐忑的，并不确定对方是否会同意。怎样让对方的回答从No变成Yes？这里面，高明的表达方式就发挥着重要作用。而我们只需三步就能找到高明的表达方式：\u003c/p>\u003cp>1.&nbsp;&nbsp;\u003cstrong>理清并隐藏\u003c/strong>\u003cstrong>自己的想法\u003c/strong>。思考你想达到的目的是什么，但可不要直接说出你的想法，以免引起对方的反感。\u003c/p>\u003cp>2.&nbsp;\u003cstrong>换位思考：想想对方拒绝你的请求可能会有哪些原因？\u003c/strong>站在对方的角度思考问题，揣测对方的性格、喜好、价值观等因素。\u003c/p>\u003cp>3.&nbsp;\u003cstrong>找到对方在乎、关注的利益点\u003c/strong>。你要找到利益点，然后琢磨使双方利益尽可能一致的表达方式。\u003c/p>\u003cp>我们先来听个故事，来感受下高明的表达方式的魅力：餐厅里几个妈妈带着孩子用餐，几个孩子不仅吵闹，还离开座位，在地上爬来爬去。看到这一幕，新来的员工就对正在愉快交谈的妈妈们提出请求：“为了避免打扰其他客人，可否请你们让孩子们坐在座位上？”说完之后，几个妈妈若无其事地继续闲聊了。不久，店长也注意到孩子们的吵闹，就来到桌前对妈妈们说：“刚做好的菜很烫，如果端出来的时候被撞撒了，会给孩子们造成很严重的烫伤。可否请你们让孩子回到座位上？”妈妈们先是一愣，随后就喊甚至是亲自抱孩子回座位了。\u003c/p>\u003cp>这个故事中店长就是利用到书中提到的三步帮助他找到更高明的用词，让妈妈们同意他提出的请求。\u003c/p>\u003cp>1.\u003cstrong>理清并隐藏\u003c/strong>\u003cstrong>自己的想法\u003c/strong>。如果店长一上来就说请妈妈们让孩子回座位，就可能会引起妈妈们的反感。\u003c/p>\u003cp>2.\u003cstrong>换位思考：想想对方拒绝你的请求可能会有哪些原因？\u003c/strong>妈妈们正聊得起劲，不能很好地关注到孩子，也不会在乎孩子是否会打扰到其他客人。\u003c/p>\u003cp>3.\u003cstrong>找到对方在乎、关注的利益点。\u003c/strong>妈妈们害怕孩子被烫伤，店长的提议就避免了孩子被烫伤，妈妈们自然也就同意了店长的请求。\u003c/p>\u003cp>这里面，店员跟店长发出的请求目的一样，但是为什么得到不同的回应？店员说的是为了避免打扰其他客人，考虑的是其他客人的利益，而店长是真正地站在妈妈们的角度思考问题，考虑到她们孩子的安全，这样发出的请求妈妈们才愿意同意。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>我分享的第二张便签是A1便签，描述自己的相关经历。\u003c/p>\u003cp>去年夏天，爸爸体检检查出来有轻度糖尿病。医生建议除了按时吃药，还要调整饮食和加强运动锻炼。吃药、调整饮食习惯这些爸爸都挺配合的，唯独就是不愿运动。我跟妈妈多次劝他说：“去运动运动吧！”但爸爸并没有行动。\u003c/p>\u003cp>【反思】现在回想起来，劝说爸爸运动之所以失败，是因为：\u003c/p>\u003cp>第一，直接说出了我的想法：“去运动运动吧”。常年缺乏锻炼的他是有些排斥运动的。\u003c/p>\u003cp>第二，没有揣测他的心理。爸爸拒绝我的请求可能会有哪些原因？他应该是觉得运动不会对他的病起什么用，反倒麻烦，所以没有动力运动。可能有人和他一起锻炼就更有动力了。\u003c/p>\u003cp>现在，如果按照书中三步让爸爸不拒绝我的提议，我会这样说：\u003c/p>\u003cp>爸爸，我想夜跑，但一个人害怕，你能不能陪我一起跑啊？\u003c/p>\u003cp>从小爸爸都很爱护我，他会担心他的女儿一个人夜跑出现危险。一起跑步，既保护了女儿又锻炼了身体，我想他是不会拒绝我的提议。\u003c/p>\u003cp>A2\u003c/p>\u003cp>我分享的第三张便签是A2便签，规划未来的应用。\u003c/p>\u003cp>【目标】通过换位思考斟酌自己的表达，在下周一顺利拿到同事维维的积分方案参考。\u003c/p>\u003cp>【行动】\u003c/p>\u003cp>1.&nbsp;\u003cstrong>理清并隐藏\u003c/strong>\u003cstrong>自己的想法\u003c/strong>。首先，不直接说出自己的想法，以免引起维维的反感。\u003c/p>\u003cp>2.\u003cstrong>换位思考：想想对方拒绝你的请求可能会有哪些原因？\u003c/strong>揣测对方的心理：积分制度是花了心思的，是维维的劳动成果，维维应该是不会很爽快地同意我的请求。\u003c/p>\u003cp>3.\u003cstrong>找到对方在乎、关注的利益点。\u003c/strong>她应该希望自己的方案是被人认可的，是重要的，那我可以表达对她的方案的欣赏以及她对我的重要性。\u003c/p>\u003cp>应用这三步，我会这样去说：\u003c/p>\u003cp>维维，上次看到你施行的积分制度，你就通过这样一套制度把学生的积极性调动起来了，真是好厉害啊！你知道我最不擅长这个了，如果能借鉴下你这么棒的积分制度，那就是帮了我大忙了！\u003c/p>\u003cp>这样发出请求，认可了她的劳动以及她对我的重要性，是不是更容易得到Yes的回答呢？\u003c/p>\u003cp>【总结】今天我的分享：用三步就可以找到高明的表达方式，让你的请求得到Yes的回答，你掌握了吗？这么实用的技能，学习之后赶紧用起来吧。今天的分享就到这里，谢谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1551879548000,"updated_at":1551879982000,"ria":true},{"id":7016,"topic":"如何让对方答应我们的请求","learn_goal":"在沟通过程中，如何让对方答应我们的请求","remark":"《所谓高情商就是好好说话》是日本深受欢迎的人际沟通课程，世界知名企业员工制定培训教材。作者原本不擅长沟通和表达，经多年职场和人生经验总结，是一本活的“说话词典”","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"派派","city":"沈阳"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"自我介绍：\r\n 大家好！我是今天的拆书人刘派，用三个标签介绍下我自己，第一个标签：旅游达人，热爱旅行，从事旅游行业；第二个标签，美食爱好者，目标吃遍全世界美食；第三个标签：热爱学习的宝妈，坚信育儿先育己，在育儿的路上先自我成长，很高兴又能和大家聚到一起学习。\r\n图书介绍：今天我带来这本书是日本深受欢迎的人际沟通课程，世界知名企业员工指定培训教材《所谓高情商就是好好说话》，作者原本不擅长沟通和表达，但所从事的恰好是需要展现说话能力的工作，经多年职场和人生经验的总结，是一本活的“说话词典”。今天我带来的这段是如何把“No”的回答变成“Yes”","ratings_count":2,"texts":[{"id":10394,"quote":"\u003cp>\u003cstrong>主题：\u003c/strong>把“No”的回答变成“Yes”\u003c/p>\u003cp>\u003cstrong>书籍：\u003c/strong>《所谓高情商就是好好说话》\u003c/p>\u003cp>\u003cstrong>把“No”的回答变成“Yes”，有3个步骤\u003c/strong>\u003c/p>\u003cp>步骤1：“不直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>步骤2：“揣摩对方的心理”\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>","explains":"\u003cp>（what）如何让对方答应我们的请求\u003c/p>\u003cp>（why）不知道大家有没有这样的经历，有时向别人发出请求时，会接收到否定的回复，工作中，两个分别向领导申请本月部门活动经费，一人遭到拒绝，另一位却同意了，这是因为第二人懂得怎样沟通才能让对方同意。\u003c/p>\u003cp>（how）那么怎么操作才能让我们的请求得到同意呢，我们可以运用三个步骤\u003c/p>\u003cp>步骤一：思考自己的想法\u003c/p>\u003cp>我们在向别人请求一件事情时，不要当时大脑有想法就马上说出来，我们应该先思考下\u003c/p>\u003cp>步骤二：站在对方角度想问题\u003c/p>\u003cp>根据对他的了解，现在大脑里过一遍如果我这么说，对方会同意的面大还是拒绝的面大，如果说这个请求说出来可能对方会拒绝，这个时候我们就要站在对方的角度思考\u003c/p>\u003cp>步骤三：利益达到共识\u003c/p>\u003cp>根据第二步根据对方的兴趣爱好，怎样将我们的请求和对方的利益能达到一致，我们可以把自己的请求写出来，答应这个请求的优势有哪些？在把对方比较看重的利益或者喜欢列出来，选出对双方都有利的一面去说。\u003c/p>\u003cp>这让我想起自己的一个例子，上周日早上因为许多事处理，不能及时打扫房间，我就和我爱人说：“老公，帮我打扫下房间”，直接招到拒绝，现在想想，我不应该直接就说出请求，我当时如果运用这三个步骤来和爱人沟通，首先不能直接就说帮我打扫房间，第二步：揣测爱人不喜欢打扫房间心理：不爱动，但是却受不了房间乱，不爱送孩子去舞蹈班，第三步骤：利益达到共识。我可以说老公你看这个房间太乱了，我现在有紧急事需要处理下，等我处理完估计也得中午了，下午还要送孩子去舞蹈班，等我回来再打扫房间，估计你这一天待在这么乱的房间都休息不好，要不你先收拾下你受不的地方，等我回来收拾别的地方，或者我处理完事情，就在家里收拾，你送豆豆学舞蹈\u003c/p>\u003cp>这样的措辞符合对方的利益，家人就会去打扫，而你的目的也就达到了\u003c/p>","interaction":"\u003cp>现在我们已经从这个拆页上学到了如何让对方答应我们的请求，接下来请大家想一想自己有没有在生活中招到过拒绝的？或者你想请求别人办事时用过其中的一个步骤。&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003cstrong>请大家按现在座位分成2组，每组2人，左边座位一组 、右边座位一组。\u003c/strong>现在给大家3分钟的时间，请大家在小组里面分享一下自己过去经历过的的类似情景。小组分享结束后，我会请一位小伙伴当众分享一下自己的案例。\u003c/p>\u003cp>ailsa：去年同事去日本玩，都知道日本的化妆品是非常好的，我也有几款中意的面膜，得知她去日本旅行，我就跟她说：“亲，你去日本帮我带下肌美精红色袋的面膜呗”没想到她拒绝了我，他说：“让我带东西的人太多了，他不打算帮大家带东西”。\u003c/p>\u003cp>通过今天的学习，我发现我不应该直接说出自己的请求。我应该揣摩对方的想法，如果我是他，帮别人带东西可能会带错，也可能会不顺路恶意去某一个地方，更可能有很多同事需要帮忙带东西，造成负担，成为代购。考虑到对方的利益的措辞：亲爱的，出去玩都希望开心，帮太多人带东西确实会有负担，不过没关系，这次你去日本，如果你去买面膜就按我带2盒，辨识度很高的，不会买错，当然买错了也没关系，如果不顺路就不用带了，也没有关系，我也喜欢出去玩，之后出去老百姓，如果你有需要我也会当你带的。\u003cbr>\u003c/p>\u003cp>A2：\u003c/p>\u003cp>从大家刚才的分享中呢，我们可以看到，当我们请求他人时，可以先思考接下来请大家根据我今天所分享的方法，在白纸上写出自己未来的行动计划。注意是确切的行动计划，有明确的时间限定，可量化的预期结果\u003c/p>\u003cp>ailsa：\u003c/p>\u003cp>目标：拜托朋友帮忙做下活动的方案策划\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1月14日是当家活动，需要策划一场有分享有互动有休息有奖励的无缝对接的活动。\u003c/p>\u003cp>朋友小A很擅长做这方面的策划。\u003c/p>\u003cp>1.不要直接说出想法，我不能跟小A直接说，让她帮我做活动策划，因为被拒绝的可能性很大。\u003c/p>\u003cp>2.揣摩对方的想法，如果我说让小A帮我做策划，她可能年底工作比较多，也比较忙，容易没时间。也有可能做的不好，落下埋怨，所以会拒绝。\u003c/p>\u003cp>3.提出对对方有益的，我会对小A说，亲爱的，我知道你最擅长做活动策划了，你出手的活动就没有不热闹，不好评的，帮我做这个活动，肯定能出彩，当然我知道年底你的工作很忙，不然我做个简单一点的，你给我提提意见，然后我在改改。等下次你需要我帮你做什么图的时候，我肯定也义不容辞。你看可以吗？\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>通过今天学习我们知道如何运用三步骤将更多的拒绝变成可能性，大家记得多练习，谢谢\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1547104285000,"updated_at":1547104285000,"ria":true},{"id":6628,"topic":"向别人提请求","learn_goal":"学会运用三个步骤来向别人提请求","remark":"","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"陈成","city":"南宁"},"club":{"name":"南宁老友分舵","city":"南宁"},"prologue":"\u003cp>各位小伙伴，大家好。我叫陈成，来自浙江。接下来我用三个标签来介绍自己。我的第一个标签是跑步，在工作日我每天早上6点左右起床去跑步，今年12月份我报名参加了南宁马拉松。我的第二个标签是看书，看书成为我生活中一项乐趣，我非常有缘认识拆书帮，拆书帮能够让我更加实用高效的看书，并且告诉我们如何区分知识的适用边界，并如何将知识拆为己用。第三个标签就是玩游戏，最近经常玩吃鸡，现在我经常能吃到鸡，我的策略很简单，只要不输就是赢。其实拆书帮也一样，我觉得在这里没有输家，这是一个互利共赢的自组织。\u003c/p>\u003cp>拆书和拆书帮是什么：在我看来，拆书是一种学习方法，讲究简单、实用和高效。它强调以学习者为中心而不是以知识为中心。我们不需要把整本书读完，而只需要拿出对我们有用的片段，并用片段里的知识关联学习者的经验、规划具体的运用场景。拆书法有两种实践方式，一是供个人学习的RIA便签学习法，R是指原文片段，I是用自己的话重述原文片段；A分为A1和A2，A1是描述自己过去的相关经验，A2是规划我未来的应用。通过运用RIA便签读书法，一个人读一本书能达到参加一场同主题培训的效果；二是供组织学习的现场学习，由拆书家带领，引导和促进一群人把知识拆为己用。拆书帮就是一群认同拆书法的人组成的一个非营利性青年自组织。大家聚在一起，一起拆书、一起提升能力、一起帮组他人将知识拆为己用。拆书帮的使命是帮助更多的学习爱好者成长为拆书家。目前拆书帮在全国主要城市都有分舵，培养几百名三级拆书家，我们南宁有老友分舵。接下来请大家花1-2分钟时间来读一下原文拆页。\u003c/p>","ratings_count":1,"texts":[{"id":9961,"quote":"\u003cp>【R阅读原文片段】把“No”的回答变成＂Yes”，有3个步骤。\u003c/p>\u003cp>步骤1：“不直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。在这种时候，请不要直接说：\u003c/p>\u003cp>“大家继续吃啊！”\u003c/p>\u003cp>步骤2：“揣摩对方的心理”\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说。。。如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把No”变成＂Yes＂的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。\u003c/p>\u003cp>“不能光吃柑橘。”\u003c/p>\u003cp>这应该就是家人的想法。\u003c/p>\u003cp>此时，请再次忘记自己的请求，想想家人的喜恶。例如：\u003c/p>\u003cp>“不想感冒。”\u003c/p>\u003cp>没人愿意生病。\u003c/p>\u003cp>到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就会变得乐意吃橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>【I用自己的语言重述知识】好，时间到，请大家放下拆页，我们一起来学习一下拆页，在我们在向别人提出请求时，有时候效果并不好。那么，在这种情况下，该如何向他人提出请求呢？有这三个步骤：\u003c/p>\u003cp>一、不直接说出自己的想法：很多人都会不假思索的把自己的想法说出来，喜欢站在自己的立场上说话，但有时候这样的效果并不好。\u003c/p>\u003cp>二、揣摩对方的心理：你可以猜测一下如果你直接说出自己的想法后，对方会做何反应，如果觉得反应会不错，当然可以直接说出自己的想法；如果觉得被拒绝的可能性较大，这个时候就不能直接说出自己的想法了，而是要根据对方平日的表现，去揣测对方的喜好、价值观等因素；\u003c/p>\u003cp>三、说出符合对方利益的话。在揣测对方的喜好、价值观等因素后，就要说出符合对方利益的措辞。\u003c/p>\u003cp>我继续强调一下这三个步骤：一、不直接说出自己的想法；二、揣摩对方的心理；三、说出符合对方利益的话。\u003c/p>","interaction":"\u003cp>【A1过去的相关经验】接下来我讲一下我过去的经验，记得上一次回家时妈妈亲手下厨给我做了一桌的菜。我尝了后感觉菜偏咸，就希望他以后少放一点盐，就向妈妈提出了请求：“妈妈，你做的菜太咸了，我该如何下口，你能不能少放点盐。”结果妈妈的反应并不好，她不以为然的说：“我觉得一点都不咸，我就是这个口味，爱吃不吃。”现在回想起来，问题就在于我提请求的时候直接说出了自己的想法，我觉得菜太咸，盐放的太多，而没有考虑到她的感受和想法。我妈妈就是重口味，他觉得菜一点都不咸，如果我要积极运用措辞三步法，效果或许就会不一样。\u003c/p>\u003cp>【A2（将来如何应用）】接下来我讲一下我未来的运用：我姨妈家口味很重，做菜的时候也会放很多盐。周末去她家吃饭的时候，我打算运用三步法来向姨妈提出少放盐的请求，希望能和她达成积极有效的沟通并能让他答应我的请求，一、我不会直接说菜很咸；二、我知道她很关注身体健康；三、我会投其所好说出符合她心理预期的话。我会说，“姨妈，听说外婆得了高血压，现在好多了没？医生说饭菜太盐是引起高血压的重要因素，为了您的身体健康，我们能不能再菜里面少放点盐？”我想我这样的表达我姨妈一定会欣然接受的。\u003c/p>\u003cp>好了，我的1-1拆书完毕，希望大家能够记住这三个步骤，一是不直接说出自己的想法；二是揣摩对方的心理；三是说出符合对方利益的话，希望大家能够学有所用，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}},{"id":10097,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1543745545000,"updated_at":1544576898000,"ria":true},{"id":6563,"topic":"换位思考1","learn_goal":"通过婉转的表达让你的话语更中听","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"小马哥SH","city":""},"club":{"name":"上海羊角村分舵","city":"上海市"},"prologue":"\u003cp>大家好我是小马哥，三个标签介绍一下我自己:\u003c/p>\u003cp>1.&nbsp; 一名成长中的拆书家\u003c/p>\u003cp>2.&nbsp; 羊角村的宣传长老\u003c/p>\u003cp>3.&nbsp; 第8期RIA训练营的优秀学员\u003c/p>\u003cp>很高兴今天能和大家一起拆书。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;首先介绍一下“拆书”和“拆书帮”。&nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp;“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心。用到的主要是RIA便签法,R是阅读原文的意思,I是用自己的话语重述原文,A的部分分为A1和A2,A1是根据原文的知识联系过去的经验，A2是根据所学的知识规划今后的应用，达到内化和应用知识的目的。\u003c/p>\u003cp>分为个人学习的拆书法和组织学习的拆书法:个人学习的应用是便签法，让人读一本书就能达到参加同主题培训的效果;组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家制造的价值不业于一位培训师。\u003c/p>\u003cp>“拆书帮”是基于折书法的学习爱好者社群，表现为各地的拆书帮分舵(也叫拆书帮俱乐部) .拆书帮分舵是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>今天带给大家的书籍是《所谓情商高就是会说话》，这本书的作者佐佐木圭一是日本顶级沟通专家，毕业于日本顶尖国际型大学上智大学的研究生院，后进入日本知名广告公司博报堂工作。作者原本不擅长沟通和表达，在历经无数次尝试和失败后，发现了打动人心的语言奥秘，成为首位获得美国广告大奖“金铅笔奖”的日本人。他被视为亚洲最成功的广告策划人，前后共获得日本国内外51项大奖。\u003c/p>\u003cp>今天选取了书中的一个片段,希望通过今天的学习我们在与人沟通的过程中能够做到换位思考\u003c/p>","ratings_count":1,"texts":[{"id":9911,"quote":"\u003cp>片段来源《所谓情商高就是会说话》\u003c/p>\u003cp>把“No”的回答变成“Yes”的3步\u003c/p>\u003cp>步骤1：“不直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。在这种时候，请不要直接说：“大家继续吃啊！”\u003c/p>\u003cp>步骤2：“揣摩对方的心理”\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。”这应该就是家人的想法。此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>What：拆页描述了一种委婉的表达方式，让我们在与人沟通的过程中能够做到换位思考,从而避免不和谐的产生。\u003c/p>\u003cp>Why：我们习惯性的直接表达自己的想法，不考虑别人听了会是什么反应，也不考虑别人是否会接受你的观点。太直接的表达往往会招致别人的反感。通过稍微委婉一点的表达方式可以让你的话语更中听，让别人更容易接受你。\u003c/p>\u003cp>How：\u003c/p>\u003cp>1.不直接说出想法,\u003c/p>\u003cp>2.揣摩对方的心理:揣摩对方听了你的话会有什么反应或者想法。\u003c/p>\u003cp>3.考虑符合对方利益的措辞:从对方的利益、喜好等方面考虑。\u003c/p>\u003cp>例子:比如你们店里的某款衣服刚好只剩下一件，你的想法是尽快处理掉。当你说出事实时别人可能会想:“只剩下一件，那是不是别人都挑剩下的，会不会有什么瑕疵？”\u003c/p>\u003cp>与对方利益相符的措辞:“这款衣服是我们店的经典款，卖的特别好，其他都已经卖完了，现在就只剩下这一件了。”\u003c/p>\u003cp>where:适用于你的表达有可能遭到拒绝，或者让别人产生反感情绪的时候，也同样适用于你要表达自己的某个意见或者想法的时候可以做到更好的换位思考。\u003c/p>","interaction":"\u003cp>A1:\u003c/p>\u003cp>故事:去年冬天我的朋友买了一双白色的靴子，我的第一反应这个鞋子看着好怪，于是也就脱口而出“这双鞋子好怪异啊，你怎么会喜欢这样的鞋子？”听了我的话朋友很不高兴的瞪了我一眼，说“又不是你穿，再怪我也喜欢。”后来跟室友之间关系也有点僵，好几天没有说话。\u003c/p>\u003cp>用拆页的方法可以这样做:\u003c/p>\u003cp>1.不直接说出想法:\u003c/p>\u003cp>我的想法: 这双鞋子好怪异啊。\u003c/p>\u003cp>2.揣摩对方的心理:\u003c/p>\u003cp>他可能会这样想:我就喜欢这种比较特别的款式。\u003c/p>\u003cp>3.考虑符合对方利益的措辞:\u003c/p>\u003cp>我可以这样说:“你这双鞋子很特别呢，你是不是想在什么特别的场合穿呢。？”\u003c/p>\u003cp>这样室友听了反映也不会那么大，我们的关系也不至于那么僵。\u003c/p>\u003cp>A2:\u003c/p>\u003cp>舍友最近在减肥， 跟她一起吃饭的时候总会剩一点，放到第二天吃又不新鲜，倒掉又觉得可惜。每到这时候我都会说:“还剩一点点，我们每人加一点都把它吃掉吧”。但是舍友怕长胖，不愿意再多吃。 她会说:“剩下就剩下吧。”导致最后都是我一个人吃掉剩下的那点菜。\u003c/p>\u003cp>目标：接下来一周用拆页的方法跟室友沟通\u003c/p>\u003cp>行动:\u003c/p>\u003cp>1.不直接说出想法:\u003c/p>\u003cp>我的想法:剩下一点菜大家每人加一点都吃完，避免浪费。\u003c/p>\u003cp>2.揣摩对方的心理:\u003c/p>\u003cp>舍友可能会想:我才不会为了避免浪费再涨几斤肉，那也太不划算了。\u003c/p>\u003cp>3.考虑符合对方利益的措辞:\u003c/p>\u003cp>如果是青菜类的我可以这么跟舍友说:“这个菜纤维含量高，有刺激脂肪消耗的化学物质，可以增加肠道的蠕动，减少脂肪和胆固醇的吸收，对减肥很有帮助。”(措辞根据具体什么菜而定)\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1543196799000,"updated_at":1543298949000,"ria":true},{"id":6524,"topic":"完美掌握，把No变成Yes的技巧！","learn_goal":"提高情商，学会说话","remark":"完美掌握，把No变成Yes的技巧！","level":"TF1-1","duration":13,"status":30,"type":0,"chaishujia":{"username":"张松","city":"深圳"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>大家好，在拆书之前呢，我先做一下自我介绍，我叫张松，来自河南省信阳市。\u003c/p>\u003cp>如果用三个标签来介绍我自己呢，第一个就是我从事的行业：IT。我发现拆书帮有非常多的小伙伴都是从事IT行业的，我记得有一次在福田的线下拆书，竟然一次来了八个都做做IT的，好不容易出来一个做自我介绍是做销售的，最后一问，她老公是做IT的。\u003c/p>\u003cp>第二个标签的热爱户外徒步，我参加过深圳百公里，走完了敦煌玄奘丝路百公里。我是比较喜欢自虐，因为我喜欢自虐完，那种再次回到人间的感觉。\u003c/p>\u003cp>第三个标签是读书、写作，不然也不会出现在这里了。\u003c/p>\u003cp>既然谈到读书，我想先问大家一个问题，如果我们在看书时，发现觉得讲的很好的或很有用的片断，我们会怎么做？（提问）\u003c/p>\u003cp>是不是划下来或用笔记下来。（引导大家回答和思考）\u003c/p>\u003cp>然后呢？\u003c/p>\u003cp>对，所以就没有然后了。其实就这就是我们在看书学习的一个问题，看到了觉得很有道理，但做不到！\u003c/p>\u003cp>那这时候就要用到拆书了，\u003cstrong>先说一下什么是拆书\u003c/strong>。\u003c/p>\u003cp>其实我第一次听到“拆书”的时候，是在几年前了，当时赵周老师来我们公司上了两个小时的课。我的理解是就是把书拆了（开个玩笑）；\u003c/p>\u003cp>其实听完课后才知道拆书就是指“RIA便签学习法”，那它们的核心思想就是：R（Reading）阅读从书本中选取的片段；I（Interpretation）用自己的话对原文知识进行重述和讲解；A（Appropriation）再与过去经验的联结，规划将来的应用。\u003c/p>\u003cp>核心是：\u003cstrong>以学习者为中心，而不是以知识为中心\u003c/strong>，要把知识关联学习者的经验，改变行为，解决问题。\u003c/p>\u003cp>知道了什么是拆书，那拆书帮又是什么呢？ \u003c/p>\u003cp>其实拆书帮就是“基于拆书法学习爱好者的非盈利社群，是由《这样读书就够了》的作者赵周老师创立，其使命是：帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>在全国的29个省份，58座城市，分布了77个正式和筹备分舵。目前深圳的拆书帮分舵是智行分舵和智荟分舵，智行分舵的场地是龙岗和福田，智荟分舵的场地是宝安和南山，今天我们在现场的都是智行分舵的小伙伴。\u003c/p>\u003cp>“拆书”和“拆书帮”已注册商标，受到知识产权保护，属于“拆书帮”专有名词，任何人或商业机构不得非法盗用。&nbsp; &nbsp; &nbsp;\u003cbr>\u003c/p>","ratings_count":2,"texts":[{"id":9844,"quote":"\u003cp>把“No”的回答变成“Yes”，有三个步骤。\u003c/p>\u003cp>\u003cstrong>步骤1：“不直接说出自己的想法”\u003c/strong>\u003c/p>\u003cp>一般来说，人都不容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法，这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。\u003c/p>\u003cp>在这种时候，请不要直接说：“大家继续吃啊！”\u003c/p>\u003cp>\u003cstrong>步骤2：“揣摩对方的心理”\u003c/strong>\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes&quot;的可能性很大，当然可以直接说......\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes&quot;的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。\u003c/p>\u003cp>“不能光吃柑橘。”\u003c/p>\u003cp>这应该就是家人的想法。\u003c/p>\u003cp>此时，请再次忘记自己的请求，想想人家的喜恶。例如：“不想感冒。”\u003c/p>\u003cp>没人愿意生病。\u003c/p>\u003cp>到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>\u003cstrong>步骤3：“考虑符合对方利益的措辞”\u003c/strong>\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。要想达到这一点，就要基于对方的心理来考虑措施。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达到目的就行。\u003c/p>","explains":"\u003cp>其实把No变成Yes的意思就是将“拒绝”变为“同意”！如何让对方更容易的同意你的观点。\u003c/p>\u003cp>我们在说话的时候，一般都是想到什么就直接说出来，有时能够达到自己说话的目的；\u003c/p>\u003cp>但有的时候说的话，和别人产生了利益了冲突，这时就会导致对方的不满，而无法达到目的。\u003c/p>\u003cp>但是假如我们在说之前，先去揣摩一下对方的心理，再把说的话改变一下措辞，照顾到对方的心理，这样即达到自己的目的，也符合对方的利益，就完美解决了沟通的问题。（what）\u003c/p>\u003cp>具体的步骤如下：（how）\u003c/p>\u003cp>1、先不要直接说出自己的想法；\u003c/p>\u003cp>2、揣摩对方的心理；\u003c/p>\u003cp>3、考虑符合对方利益的措辞。\u003c/p>\u003cp>因为双方在沟通中，只有利益达成一致，才能保持良好的对话环境。\u003c/p>\u003cp>如果把“说话”放在“揣摩对方利益”前，如不符合对方利益，就会马上对立起来，因为对方利益是无法改变的；\u003c/p>\u003cp>而把位置互换后，先揣摩利益后，就可以机动的调整说话的方式或上下文，使之与利益相匹配，就使双方的目的达成一致。（why）\u003c/p>\u003cp>该方法适用于能够判断出对方的利益所在，或初步了解对方的心理，且双方没有非常针对性的冲突；不适用于双方完全不了解或存在不可调解的利益关系（where）\u003c/p>","interaction":"\u003cp>【A1：描述自己的相关经验】\u003c/p>\u003cp>我在家中有时候和儿子沟通时，经常是强制式的要求：比如作业没有做完时，不能看电视；每天看电视的时间不能超过1个小时；吃饭时不能够只吃肉，少吃蔬菜等等。都是发现什么问题后，直接进行要求改正，而导致的后果就是逆反心理。虽然表面上没办法接受了，但孩子心中仍然存在不愿意的情况。\u003c/p>\u003cp>反思：通过今天拆解的这个“把No变成Yes的技巧”片断，觉得不应该先直接发出命令，而是应该先去感觉一下儿子的目的和需求，然后转换一个说话的方式，用一种他能够接受的语言或方法达到我的目的。\u003c/p>\u003cp>【A2：我的应用（目标与行动）】\u003c/p>\u003cp>目标： 在晚上对孩子看电视的一些行为进行约束时，先通过揣摩他的用意，再创造一个共同利益的对话，实现达到最终目的。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1、明天晚上在儿子急着吃完饭时，先不急着说让他慢点吃；\u003c/p>\u003cp>2、揣摩他是不是想快些吃饭，去开电视看动画片；\u003c/p>\u003cp>3、十分钟后，等我吃完饭，一起去看看动画片吧？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1542635094000,"updated_at":1546055587000,"ria":true},{"id":6326,"topic":"在表达想法的同事更好的将对话利益最大化","learn_goal":"三个步骤，在说话中把NO的回答变成YES","remark":"","level":"TF1-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"胡英","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"各位拆书帮的小伙伴，大家好！我是胡英，我目前在一家互联网企业从事政府事务性工作，因为工作中常常需要与人打交道，也察觉到好的说话方式能让人际关系更融洽，工作起来事半功倍。今天带来的拆书片断选自日本沟通专家、广告鬼才、文案写作大师佐佐木圭一的书《所谓情商高，就是会说话》。这本书吸引我的一点是作者原本不擅长沟通和表达，在历经无数次尝试和失败后，发现了打动人心的语言奥秘，成为首位获得美国广告大奖“金铅笔奖”的日本人。 作者通过自己多年来掌握的语言措辞技巧告诉大家该如何修炼说话能力，如何提高自己的说话水平。就像烹饪有食谱一样，说话也有它的“秘方”。那么，作者的秘方是什么呢，下面跟随拆页学习一个很实用的说话技巧。","ratings_count":2,"texts":[{"id":9620,"quote":"\u003cp>一：把 &quot;No&quot; 的回答变成 &quot;Yes&quot; 的三步骤\u003c/p>\u003cp>步骤 1：&quot; 不直接说出自己的想法 &quot;\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤 1。当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出 &quot; 这是很重要的请求！&quot;之类的话。\u003c/p>\u003cp>步骤 2：&quot; 揣摩对方的心理 &quot;\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。直接说出请求，对方会作何反应？如果对方回答 &quot;Yes&quot; 的可能性很大，当然可以直接说。如果对方回答 &quot;No&quot; 的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把 &quot;No&quot; 变成 &quot;Yes&quot; 的答案就在其中。\u003c/p>\u003cp>步骤 3：&quot; 考虑符合对方利益的措辞 &quot;\u003c/p>\u003cp>提出的请求，要让 &quot; 对方的利益 &quot; 和 &quot; 自己的利益 &quot; 趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>","explains":"\u003cp>好的，我看到小伙伴都已经看完了。\u003c/p>\u003cp>下面进行拆页讲解前，先举个例子：\u003c/p>\u003cp>假如说你家里有很多桔子，家里人已经吃了很多了，都不想吃了，但是如果不吃，很快坏掉拉，所以你想让家人一起把桔子都吃掉，可是如果你直接说：大家应该多多吃桔子，这样就不用浪费拉。想下家里人是什么反应，因为他们都吃腻了，所以对于你的请求他们是什么想法呢？\u003c/p>\u003cp>我们经常会认为说出自己真正的想法是一种率真，坦诚，但是往往没有考虑对方听的人是否愿意，或者对这件事情的态度是怎么样，有时候会容易招人反感，反而事与愿违。在说话过程中找到自己的需求和对方需求相关联的重合部分，从共同需求出发，就能赢得对方的肯定答复，收到成功的机遇越高。\u003c/p>\u003cp>拿刚刚吃桔子的例子分析：\u003c/p>\u003cp>我的想法是想让家里人把剩下的橘子都吃掉，以免浪费，但先不要直接说出自己的想法，这是第一步。\u003c/p>\u003cp>家里人已经吃过很多了都吃腻拉，直接让他们吃肯定是不想吃的，那有什么办法是可以让他们主动愿意吃桔子呢？桔子多吃有什么好处呢？从而得出结论，多吃桔子可以美容还可以预防感冒。 第二步要揣摩对方的心理。\u003c/p>\u003cp>这是多吃桔子可以美容还可以预防感冒哦，当我们说出的话时，对方就没有反抗情绪。考虑使用符合对方利益的措辞。这就是第三步。\u003c/p>\u003cp>所以按这三个步骤来表达后，是不是就可以将对方可能回答说NO的答案变成说YES的答案呢。\u003c/p>","interaction":"\u003cp>下面请根据分组，进行讨论：\u003c/p>\u003cp>A1:&nbsp;激活经验\u003c/p>\u003cp>好的，现在我们回忆一下，在过去的一个月里，你是否也遇到过因为说话不得当，自己的请求被对方否决的时候呢？当时是怎样的一个情形呢？\u003c/p>\u003cp>下面请大家用3分钟在组内相互分享一下，每组选出一位和其他组分享。給大家2分钟时间。（时间、地点、人物、起因、过程、结果）\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>A1：上周给孩子的作业比较多，跟孩子说：“快去写作业！”孩子逆反情绪上来了，大声喊着：“不要不要！”然后就是一系列家庭战斗开始…\u003c/p>\u003cp>A2&nbsp;规划应用：\u003c/p>\u003cp>说话是人类最重要的交际工具，能够说好话是一个人最重要的基本能力。人在工作和生活中都需要与别人沟通，表达需求，请求肯定答复。今天我们学习了把“NO”的回答变成“Yes”的三个步骤后，请大家设想下在未来这一周或一个月时间内，遇到需要请求对方肯定答复的情形时，你打算如何去说呢？请大家写下来。\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>目标：明天晚上用三步法叫老婆11点睡觉。\u003c/p>\u003cp>行动：明天晚上10:30的时候跟她说，开始洗漱吧早点睡。一般情况，她说一声“哦”就没下文。\u003c/p>\u003cp>第一步：这时要忍住自己的想法，\u003c/p>\u003cp>第二步：去揣摩她的心理，老婆很在意皮肤状态，如果晚睡，就会有黑眼圈，她不喜欢黑眼圈。\u003c/p>\u003cp>第三步：用她能接受的方式表达：早点睡吧不然明天又黑眼圈了\u003c/p>\u003cp>做完这三个步骤后，观察她的反应。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1540462879000,"updated_at":1540462879000,"ria":true},{"id":6260,"topic":"把“No”的回答变成“Yes的三个步骤","learn_goal":"利用三步骤优化自己的沟通，能够将“NO”的回答变成“YES”","remark":"说话不只是一种“感觉”，还是一门“技术”！就像烹饪有食谱一样，说话也有它的“秘方”。","level":"TF1-1","duration":12,"status":30,"type":0,"chaishujia":{"username":"黄小鸭","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【开场：自我介绍】\r\n大家好，我是黄小鸭，我从事的是企业培训的工作。\r\n这段时间我很喜欢的一句话是“你必须只有内心丰富，才能摆脱这些生活表面的相似”。因此在八小时之外，我寻找并热爱着让我内心丰富的事情，比如看书、写字、码文、以及给我爱的人做饭。\r\n关于读书这件事情，我一直觉得自己是野路子。从我6月14日第一次参加橘洲线下的活动，当时杏梅拆书给了我深刻的印象，我当时就给自己默默立了一个目标。所以我今天站到了这里。\r\n我朋友曾经和我说过的一句话，“若有诗书藏于心，岁月从不败美人。”今天我也把这句话送给在场的各位。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【我来介绍拆书，拆书帮】\u003c/p>\u003cp>“折书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调 以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。\u003c/p>\u003cp>分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是便签法，让人读一本书就能达成参加同主题培训的效果，即RIA；\u003c/p>\u003cp>组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拼书帮分舵（也叫拆书帮俱乐部）。拆书帮分舵是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":9547,"quote":"\u003cp>把“No”的回答变成“Yes”，有3个步骤\u003c/p>\u003cp>步骤1:&nbsp;不直接说出自己的想法\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。\u003c/p>\u003cp>请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>&nbsp;例如：有人从老家寄来很多柑橘，家人甚至都吃腻了而你不想让剩下的柑橘白白烂掉。\u003c/p>\u003cp>在这种时候，请不要直接说：\u003c/p>\u003cp>“大家继续吃啊！\u003c/p>\u003cp>步骤2:&nbsp;揣摩对方的心理\u003c/p>\u003cp>请描摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能直接说了请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。\u003c/p>\u003cp>“不能光吃柑橘。“这应该就是家人的想法。\u003c/p>\u003cp>此时，请再次忘记自己的请求，想想家人的喜恶。例如\u003c/p>\u003cp>“不想感冒。\u003c/p>\u003cp>没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3: 考虑符合对方利益的措辞\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。\u003c/p>\u003cp>想达到这一点，就要基于对方的心理来考虑措辞。关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>既然家里人不想感冒，就可以对他们说：\u003c/p>\u003cp>“多吃柑橘就不会感冒了。”\u003c/p>\u003cp>这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>&nbsp;接下来，我将带来关于我的1-1的拆解，内容来自《所谓情商高，就是会说话》\u003c/p>\u003cp>现在我将片段发给各位，请大家开始来阅读一下。\u003c/p>\u003cp>【I重述知识】\u003c/p>\u003cp>【what】\u003c/p>\u003cp>刚才大家阅读的片段主要讲的是一个将“NO”的回答变成“YES”的方法。沟通中，我们想得到对方肯定回答时，直接表达自己的想法可能会失败，那我们可以通过将我们要沟通的内容与对方建立联系，让这件事“和他有关”，那么我们很有可能得到YES的回答。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>一个人的成功80%源自于她的人际沟通。\u003c/p>\u003cp>如果在人际沟通中，我们能将得到的1000次“NO”的回答变成“YES”，那生活会发生什么的变化呢？\u003c/p>\u003cp>首先，我们能够处理好和自己生命中重要的人的关系，例如我们的父母、伴侣和孩子，当“NO”的回答变成“YES”时，也许丈夫能够更加体恤妻子的辛苦，主动承担家务，多和妻子聊天、逗妻子开心；其次，在工作中，我们可以使工作更顺畅，同事能够更好地认可你的观点，并配合，与上级意见不同时也可以很好地解决。因此可见，掌握在人际沟通中将“NO”的回答变成“YES”的方法，我们的生活和工作都会越来越好。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>在需要得到别人的配合、理解、支持的情景下，如果我们直接说出自己的想法，有很大可能会被拒绝，这个时候我们要记住的第一步就是不要直接表达所想。\u003c/p>\u003cp>“知己知彼，百战不殆。”接下来，第二步我们要换位去思考，我们要去沟通的这件事情和对方有什么关联，去揣摩对方的想法。\u003c/p>\u003cp>第三步，让需要沟通的这件事情，能够和他产生关系，也就是和对方的利益相关，这样沟通使得沟通双方的利益趋于一致，才能得到“YES”的回答。\u003c/p>\u003cp>当你有位女性邻居经常把垃圾放在楼道公共区域忘记丢，如果你直接和她说，“麻烦你以后记得及时丢垃圾”，她可能还是会时常忘记。女性大多怕老鼠和蟑螂，如果你换一种表达“不及时丢垃圾，容易引来老鼠和蟑螂，还会跑到你房间里面，记得及时清理好垃圾哦。”我相信这样的表达效果会更好。\u003c/p>","interaction":"\u003cp>【以上就是我的I环节，接下来就是A1激活经验环节】\u003c/p>\u003cp>最近想晚上在小区附近跑跑步，觉得一天8小时上班都是对着电脑，坐在办公室，身体得不到锻炼，也希望我老公可以一起，两个人都可以锻炼身体。\u003c/p>\u003cp>于是我上周吃完晚饭趁着老公洗碗的时候，对老公说，“老公，我们待会去跑步去吧，你要和我一起去。”\u003c/p>\u003cp>然后我老公直接对我说，“为什么要去跑步呀，不去。”\u003c/p>\u003cp>于是我想夜跑的计划就被否决了。\u003c/p>\u003cp>从刚才和大家说的“NO”的回答变成“YES”的三步骤一起来回顾下这个案例。\u003c/p>\u003cp>第一步，我选择直接说出了自己的想法，“想夜跑，需要你陪我一起去”；\u003c/p>\u003cp>第二步，我并没有去琢磨他的心理，例如他最近很在意自己长胖了，跑步可以让他身材变好；或者我晚上一个人跑不安全，我需要他的陪伴等。\u003c/p>\u003cp>第三步，没有考虑符合对方利益的措辞，只提出自己的想法，而不是说，“我们一起去跑步吧，让身体健康，也可以减肥。”或者“我们一起去跑步吧，有你一起，我更加安心。\u003c/p>\u003cp>我的A1就是这样的。\u003c/p>\u003cp>【A2 -&nbsp;催化应用】\u003c/p>\u003cp>接下来是我的A2催化应用的环节。我的A2是这样的：\u003c/p>\u003cp>在以后遇到需要他人配合、理解和支持的沟通场景中，要想得到最后“YES”的回答，我需要按照以下步骤去做。\u003c/p>\u003cp>第一步，想不直接说出自己的想法；\u003c/p>\u003cp>第二步，想一想这件事和对方有什么关联，然后因此去揣摩对方的想法，例如可以投其所好、儆其所无、给对方选择的自由、提高对方的被认可欲等方式\u003c/p>\u003cp>第三步，让彼此利益趋于一致。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1539842074000,"updated_at":1540017858000,"ria":true},{"id":5886,"topic":"把“NO”变成“YES”的技巧","learn_goal":"学会运用三个步骤，把No的回答变成Yes，提高对方应允概率","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"杨欢","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"大家好，我叫杨欢，木易杨、欢乐的欢。一方面呢我比较严谨和保守，这是和七年的法学专业学习以及五年的行政类工作分不开的；另一方面呢，我又比较开朗和粗线条。思维很跳跃，兴趣爱好广泛。爱生活爱阅读爱分享。同时呢，也是一个比较上进的人，发现自己的不足就想要去改进它们。比如，我发现自己的口才不够好，为了提升自己的口才，我找到了这本很棒的书《所谓高情商 就是会说话》。\r\n 这本书的作者是日本顶级沟通专家佐佐木圭一。作者原本是不擅长沟通和表达的，在历经无数次尝试和失败后，发现了打动人心的语言奥秘，集结成这本《所谓高情商 就是会说话》。这本书通熟易懂还有趣有用。作者认为，说话不只是一种“感觉”，还是一门“技术”，就像烹饪都有食谱一样，说话也有它的“秘方”。通过“秘方”，我们能更好地掌握并运用语言措辞技巧，使自己成为说话高手。\r\n今天我想和大家拆解的是很厉害的一招，就是——把“NO”变成“YES”的三步骤。也就是说，当你向别人提出请求或者要求的时候，对方的回答是“好，可以，没问题”，而不是“不行，我没有时间，这不在我的职责范围之内”，为了尽量避免后者的回答，我们怎么办呢？请大家阅读手中的文字材料，看完的伙伴请举手示意一下。","ratings_count":0,"texts":[{"id":9108,"quote":"\u003cp>把“NO”的回答变成“YES”，有三个步骤。\u003c/p>\u003cp>步骤1：“不直接说出自己的想法”。一般来说，人都容易不假思索就地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且容易招致反感，请不要直接说出自己的想法。这就是步骤1。当然我们都是凡人，不可能保证所有的事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>步骤2：“揣摩对方的心理”。请揣摩对方的心理。并根据其平日表现，猜测对方会对你的请求作何想法。直接说出请求，对方会做何反应？如果对方回答“YES”的可能性很大，当然可以直接说。如果对方回答“NO”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“NO”变成“YES”的答案就在其中。\u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”。提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;我们先看\u003cstrong>步骤一\u003c/strong>，为什么不直接说出自己的想法？因为我们的目的是让别人说Yes。比如：家里有很多柑橘，家人都吃腻了，你想要大家再多吃点免得烂掉可惜了。这时不要直接说“大家继续吃啊”。请试着揣测吃腻了柑橘的家人的想法。这个试着揣测就是\u003cstrong>步骤二\u003c/strong>。想想家人的喜恶，大家注重健康和养生。这个季节容易感冒，橘子维C丰富。于是你可以对不想感冒的家人说“多吃柑橘就不会感冒了”这就是\u003cstrong>步骤三\u003c/strong>。这样的措辞符合对方的利益，家人会变得更加乐意吃柑橘，而你的目的也就达到了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;通过讲解步骤一二三，大家会发现最难的是步骤二。接下来我通过几个例子帮助大家从多种角度来理解和突破步骤二。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;比如：我想邀请对方一起吃饭但担心对方太忙会拒绝我。我不会直接问她可不可以一起吃饭？而是认真揣摩后说：“听说某某餐厅的糖醋排骨特别有名，我们一起去尝尝吧？”(投其所好)。因为这位朋友喜欢吃糖醋排骨，用她的喜好来邀请她，就提高她接受邀请的成功率了。或者，我说“老长沙龙虾馆和海底捞，你要去哪家一起吃顿饭？”（选择的自由）。因为这位朋友很喜欢去这两家，被我这么一问，原本繁忙的她就会想着说“那也行啊，我们就去老长沙龙虾馆吧”。这个例子中提到了揣摩对方心思时经常用到的两种方法：投其所好和选择的自由。大家可以在实践中多总结。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>在A1环节。请大家三人一组，回想一下自己的过往经验，你的请求被别人拒绝过吗？也就是说当你向别人提出请求或要求的时候，你是怎么说的？别人的反应是怎么样的？\u003c/p>\u003cp>（讨论中）\u003c/p>\u003cp>有哪位朋友愿意来分享一下吗？\u003c/p>\u003cp>开始分享：之前我工作很忙，想请求上级增加一位同事来协助这项工作。于是我找到我们领导，说：“领导，我现在工作任务重，非常忙，经常加班，您可以在我们科室增加一个人吗？”领导想了下说：“我能够理解你，但是现在公司整体任务重压力大，各个部门都人手紧张，我自己也经常在办公室加班。希望你还是能够提升效率，抓住工作重点和要点，圆满完成好工作任务。到时候公司会根据大家的表现给予奖励的。”这样我的请求被领导委婉地拒绝了。\u003c/p>\u003cp>A2\u003c/p>\u003cp>刚才我们听到大家的分享，对三步骤法有了更加深刻的印象和认识。接下来是A2环节。请大家运用三步骤法写下自己下周的一个目标。为了这个目标具有高可执行度。请大家在纸上写下四要素：一、目标（目标内容清晰不含糊）；二、期限（要有明确的完成期限）；三、具体的做法（就是步骤一是什么？步骤二是什么？步骤三是什么？）；四、结果（应该是可衡量或可观测的预期结果。）\u003c/p>\u003cp>写完的小伙伴举手示意一下。\u003c/p>\u003cp>现场案例记录：\u003c/p>\u003cp>1、&nbsp;目标：想邀请朋友一起逛街。\u003c/p>\u003cp>2、&nbsp;期限：本周末\u003c/p>\u003cp>3、&nbsp;具体做法（1、不直接说“周末一起逛街吧”；2、考虑到对方最近挺忙的周末想休息，但我们确实很久没有见面了，而且她挑选衣服的品味不错。3、于是说“好久没有见面了，想和你聊聊天。周末你有时间一起去逛街吗？我们可以边逛边聊聊天。而且你的审美那么好，在你的建议下我更能买到满意的衣服”。）\u003c/p>\u003cp>4、&nbsp;结果：朋友应该会答应一起逛街一起聊聊天。\u003c/p>\u003cp>今天的拆解就到这里，希望大家在今后的生活中常运用，越用越好用。根据本书作者的统计，运用此方法至少可以提高20%-30%的成功率。谢谢各位。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1535117832000,"updated_at":1535117832000,"ria":true},{"id":5125,"topic":"允许自己请求的沟通技巧","learn_goal":"运用三个步骤实现对方答应自己请求","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"gaogao高高","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>【分组】\u003c/p>\u003cp>大家好~我是高高，盛传的三高培训师，身高高，颜值高，智商高…喜欢学习喜欢分享，接下来将由我带领各位走进这本书，让我们一同携手，度过美好的今晚，为了让我们更好彼此分享，互相学习，现在，从我的左手边开始，两两为一组，今晚，让我们彼此结为灵魂伴侣，畅谈书中所得所感。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>此书的来历不简单，作者是一名广告鬼才。从事广告文案撰稿人的他曾经经历了“不会写”的低谷期，最终通过观察&amp;总结，得出一套说话的法则。大家是否曾因为“说话”而心生恐惧？其实不管是在生活还是工作，“说话”都显得十分重要。今天，让我们一同学习和实践“说话”法则，真正做到三好--说好话，说话好，好说话。&nbsp; &nbsp;\u003cbr>\u003c/p>","ratings_count":1,"texts":[{"id":8232,"quote":"\u003cp>【过渡】\u003c/p>\u003cp>现在，有请各位快速阅读复印的拆页，此环节时间为2分钟，当听到铃铛响的时候，请大家把注意力回到我这里，现在开始阅读片段，时间为2分钟。\u003c/p>\u003cp>【文段】\u003c/p>\u003cp>突破口5:非你不可\u003c/p>\u003cp>听到“只有你是特别的”,人就容易被说动\u003c/p>\u003cp>据说二十多岁的年轻人不会和上司喝酒。\u003c/p>\u003cp>我的朋友问公司的一个新人\u003c/p>\u003cp>“去喝酒吧?”\u003c/p>\u003cp>对方却反问:\u003c/p>\u003cp>“为什么要去喝酒\u003c/p>\u003cp>朋友根本没想到对方会如此反问,慌忙回答:“啊,你要是忙就算了。”\u003c/p>\u003cp>这个时代就是这样。朋友的烦恼还没完。部门里有酒会,朋友负责组织。\u003c/p>\u003cp>部长对他说:“上次人来得批不全,这次一定要把人都叫来\u003c/p>\u003cp>这可是大危机啊。朋友仔细考虑后,使用了这样的措辞\u003c/p>\u003cp>“市川,你不来不热闹,所以只有市川你务必得出席啊。”\u003c/p>\u003cp>他把这条信息发给了所有部门成员。当然不是群发, 而是对应姓名逐一发送的。结果,当天的部门酒会全员到齐。\u003c/p>\u003cp>这就是利用了“非你不可”这一措辞突破口。\u003c/p>\u003cp>“非你不可”就是告诉对方:别人不行,你才是被选中的人。在这种情况下,像“只有市川|你”这样加入名字能使效果倍增。一般人都喜欢“非你不可”的特殊感,听到这样的话,就会感到一种仅限自己的优越感,从而乐于回应对方。\u003c/p>","explains":"\u003cp>实在我感触颇深，在彼此对话中，只要稍微改变措辞，就可以让对话结果完全不一样…不仅是平时的邀约，针对于我们平时需要对方允诺，答应自己请求的对话沟通，我们也可以通过添加关键词“对方的名字”以及“只，仅”这些代表唯一的词语让沟通对象感觉到自己不一般的特殊待遇和被选中的优越感，从而达成沟通目的。\u003c/p>\u003cp>具体步骤：\u003c/p>\u003cp>1、切勿开门见山：不要直接说出自己想法\u003c/p>\u003cp>2、换位思考：结合当下情境，猜测对话者心里真正想法\u003c/p>\u003cp>3、添加关键词：措辞上添加“对方姓名”以及“只，仅”代表唯一词语并进行整合完成需要沟通语句\u003c/p>\u003cp>【例子】\u003c/p>\u003cp>今年初六的时候，我本来是约了我的闺蜜去吃饭看电影的，结果我约了另外一个男生初五的时候看完了…那我只能推掉我闺蜜，当时候我就是这么说的：\u003c/p>\u003cp>（1）&nbsp;&nbsp; 切勿开门见山：我忍住了想要直接告诉她“抱歉我来不了了初六的约会”\u003c/p>\u003cp>（2）&nbsp;&nbsp; 换位思考：如果我是我闺蜜的话，我最希望的肯定是对方也就是我认为自己是最重要，最好的闺蜜没有之一那种。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;（3） 添加关键词：我微信上是这样说的：“很抱歉，阿恩，你是我最好的闺蜜，只有你才会每次在我不开心时候陪着我，但这次没办法约上了，我希望以后我们可以继续约”\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>【过渡】\u003c/p>\u003cp>现在，我们已经了解到如何通过三步骤优化我们的沟通措辞，接下来让我们进入到A1激活经验的环节。\u003c/p>\u003cp>【提问设计】\u003c/p>\u003cp>在这个环节，\u003c/p>\u003cp>1、 请各位回想下，自己的生活和工作里是否曾经出现过需要沟通对象允诺的对话沟通？\u003c/p>\u003cp>2、 这个对话的结果是对方答应了你的请求还是狠心拒绝了呢？\u003c/p>\u003cp>3、 不管这个曾经的沟通的结果如何，请各位运用我们刚刚提到的三个步骤对我们曾经经历过的对话进行优化和分析。如果是成功的对话，它是如何运用了我们的三步骤？如果是失败的对话，基于这三步骤，我们可以怎么进行优化和改善？\u003c/p>\u003cp>4、 跟你的隔壁的灵魂伴侣互相分享\u003c/p>\u003cp>总共用4分钟，现在开始~\u003c/p>\u003cp>【案例记录】\u003c/p>\u003cp>接下来有请一位小伙伴给我们分享下他的案例~\u003c/p>\u003cp>A1现场分享者：我是从业银行的，经常跟银行、银监会进行沟通，我会揣测对方的想法，以什么方式去为难我，我会想好所有的情况，对方希望我做的去准备好，也就是片段中所说的第一和第二个步骤，先不要开门见山，换位思考对方会想些什么，揣测对方真正想法，那么说到第三个步骤，接着就是三缺一非你不可...\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>【过渡】\u003c/p>\u003cp>看来各位的沟通的经历都十分的深刻\u003c/p>\u003cp>【提问设计】\u003c/p>\u003cp>经过我们联系过往的经历，趁热打铁，写下我们的A2计划吧。比如最近你要跟那个人需要进行一个什么样的沟通对话呢？你想让他允诺你什么样的请求呢？我们可以看到白板上面所记录如何进行一个有效沟通三步骤.\u003c/p>\u003cp>在这里，大家一定要注意:\u003c/p>\u003cp>1、 我们书写A2步骤的时候要落实具体的时限（也就是所谓的具体的时间和时间节点，某年某月某天某时到某时）\u003c/p>\u003cp>2、 具体做法（具体步骤做些什么）\u003c/p>\u003cp>3、 如何跟踪落实效果哦（如何看出对话的有效性呢？例如对方的答应了或者心情变化等），事不宜迟，现在人手一张便签纸。\u003c/p>\u003cp>好比如我的A2便签就是，针对本周六我因为自己答应别人约会没有办法出席部门的聚餐这件事情在周三晚上发微信给到我的同事梦丹，我是这么写的：抱歉，梦丹，只有你会在工作上很忙都会义不容辞帮我，只因为你，我不想让你误会，我本周六有事没空，你不要误会。检验标准：梦丹答应我的请求并能够答应我下次的约会。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>感谢各位，本日这个片段拆解到此，如有任何有兴趣的观点，欢迎结束\u003c/p>\u003cp>后联系~谢谢~\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1526110045000,"updated_at":1526110104000,"ria":true},{"id":4834,"topic":"投其所好，轻松让No变Yes","learn_goal":"学习者使用符合双方利益一致的措辞来与对方沟通，降低拒绝概率","remark":"","level":"TF2-2","duration":17,"status":30,"type":0,"chaishujia":{"username":"唐波","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍】大家好，我是唐波，今天我分享的主题是“投其所好，把NO变成YES”,它选自《所谓情商高 就是会说话》一书。\r\n【图书介绍】\r\n【F】本书的作者佐佐木圭一，是日本顶级沟通专家、广告鬼才、文案写作大师。书中作者通过自己多年来掌握的语言措辞技巧告诉大家如何修炼说话能力，提高说话水平。\r\n【A】和市面上沟通类的书相比，本书在表达上更通俗。作者说，说话如做菜，有谱可循，只要掌握了基本菜谱，任何人都能做出美味佳肴。书中例举了大量的实践故事，便于理解容易掌握，拿来就能用。\r\n【B】你是否想尽快掌握说话精髓，搞定不肯合作的同事、不肯做家务的老公、捣乱的熊孩子?你是否想写出让朋友圈不得不赞的经典金句？书中的7大突破口与8大技巧，总有一款适合你。","ratings_count":1,"texts":[{"id":7912,"quote":"\u003cp>“抱歉，这种衬衫只剩这一件了”听到店员这样说,你会怎么想?\u003c/p>\u003cp>“可能会一下子产生是别人挑剩下的吧”“这可能是很多人试穿过”的印象,如果店员换一种说法,例如：“这种衬衫卖得特别快,这是最后一件了”。\u003c/p>\u003cp>你又会怎么想?大概会产生“要是流行,我也想买”“最后一件了,不买就没了”的印象。这样的措辞就是成功利用了“投其所好”的突破口,如此一来，拿着衬衫去收银台结帐的人也会很多,传达同样的内容,如果使用不同的措辞,对方的接受方式和行为就会发生变化。\u003c/p>\u003cp>店员的目的是“希望顾客消费”但不能直接说出来,而是要揣摩顾客的心理,采用“投其所好”的措辞。\u003c/p>\u003cp>&nbsp; 以“投其所好”的形式提出请求，对方也会乐于接受。只要意识到这个突破口，就能让对方高兴地听取自己的请求。\u003c/p>","explains":"\u003cp>【学习目标】各位小伙伴在跟随我完成本次RIA现场学习后，能在面对可能的拒绝时，【具体可测量的行为要求/可被观察的行动】不直接说出自己的想法，而是能够投其所好，使用符合双方利益一致的措辞来与对方沟通，降低被拒绝的概率。\u003c/p>\u003cp>&nbsp; &nbsp;生活中，我们总是免不了要说服别人或者拜托别人做某件事情。一般情况下，我们会不假思索地直接把脑海中的想法说出来，没去考虑对方会怎么想，这样有可能事与愿违，而且还容易招致别人的反感。对方是否能答应你的请求，很大程度上取决于 你的措辞，你的语言表达方式，是否能够基于对方的心理，是不是使用符合双方利益一致的措辞来与对方沟通。作者提出，有一种很好的表达请求的方法就是：投其所好。\u003c/p>\u003cp>第一步：理清自己的目的，但先不说。\u003c/p>\u003cp>第二步，思考对方会因什么理由拒绝，什么情况会答应。\u003c/p>\u003cp>第三步，使用双方利益一致的语言表达自己的请求。\u003c/p>\u003cp>【举例子】过年时，我需要邀请我老公陪我去一个舅妈家拜年，于是就用到了这个方法，我的目的是：想让我老公陪我一起去，但是我没有直接说。第二步，我开始思考他的想法，我想他有可能会想：“不想在别人家呆太久”、“过年天天走亲戚太累了”因而拒绝我，但如果“呆着舒服”则可能会答应。于是我就想了下，他最近挺喜欢打王者荣耀的，于是我就说：“听说那个A表哥王者荣耀打得蛮好的，今天他休息，你要不要去组个队？顺便还给舅妈拜个年，在他家中餐晚餐都解决了，还不用你洗碗呢。”\u003c/p>\u003cp>【例子有效性】他一听我这么说，觉得去拜年这个事情挺划算的，于是屁颠屁颠就跟着去了。\u003c/p>\u003cp>【预防异议+讲解】可能有的小伙伴会问，你这拐弯抹角地说话，是玩套路呀。其实这种表达只是让我们站在对方的角度多想想，换上让对方容易接受的表达方式，何乐而不为呢？\u003c/p>","interaction":"\u003cp>A2分步骤催化1：\u003c/p>\u003cp>【分步骤催化-----指向未来的显像提问法】下面请大家想象一下，到了下个周末，你想要另一半陪你参加一些活动来增进你们的感情，而另一半可能觉得累不想去；或者你想约上闺蜜、好友大吃一顿，对方在减肥，不想陪你吃吃喝喝；或者你希望家人改变一种不好的习惯，但家人觉得太麻烦。大家结合自己的情况想一想，你的请求可能会遇上哪些被拒绝的场景？\u003c/p>\u003cp>【伙伴分享】\u003c/p>\u003cp>炜：我老公在我邀请他出去吃饭时，经常拒绝我。\u003c/p>\u003cp>芳：我邀好友一起去健身，但对方以“没时间”等理由拒绝。\u003c/p>\u003cp>A2分步骤催化2：\u003c/p>\u003cp>【催化学习者加工未来的场景】现在请大家根据刚才想到的场景，结合今天的拆页，想想我如何运用这个方法能让对方可能的拒绝变成YES呢？讨论时间是5分钟。我会请1位或者2位学习者分享自己的案例。\u003c/p>\u003cp>【分享行动计划】\u003c/p>\u003cp>学习者芳：我的目的是邀请好友和我一起去健身房，这次我不直接说我的想法，因她可能会觉得自己很忙或是太累为理由拒绝我，她最近买了件特别好看的裙子很修身，相信她很想穿出来凸显身材。于是我说“你买的那件新裙子真的特别好看，显身材，要是肚子上的肉肉再少一点就更美了，你看咱们最近是不是多去运动一下?”\u003c/p>\u003cp>&nbsp;&nbsp; 非常感谢小伙伴的分享，希望大家在今后能够多多运用投其所好这一妙招，使用符合双方利益一致的措辞来与对方沟通，降低被拒绝的概率。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1521512222000,"updated_at":1521647523000,"ria":true},{"id":4667,"topic":"完美掌握，把“No”变成\"Yes\"","learn_goal":"希望大家通过这三个步骤的练习，能够学会说话，把NO变yes","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"瞌睡的猫","city":"无锡"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【开场白】\r\n大家好，我是预备拆书家瞌睡的猫。我个人的三个标签是：1.早起，我美好的一天是从早上4点钟开始的。2.个人成长，聚焦个人提升已4年，不断遇见更好的自己；3.擅长时间管理，注重效率，工作生活张弛有度。很高兴认识大家。\r\n今天我给大家分享的书，名字叫《所谓情商高，就是会说话》，作者是日本顶级沟通专家佐佐木圭一先生。这本书是世界知名企业，员工指定培训教材。书中主要介绍了如何进行技巧性对话，让对方的回答从NO变成YES，以及如何创造警句等说话技巧。\r\n下面我把原书片段发给大家，给大家2分钟的时间看一下片段，看好之后可以向我示意。","ratings_count":1,"texts":[{"id":7708,"quote":"\u003cp>\u003cstrong>【R原文片段】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>复习！3个步骤\u003c/strong>\u003c/p>\u003cp>把“No”的回答变成“Yes”，有3个步骤。\u003c/p>\u003cp>步骤1:“不直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。\u003cstrong>请不要直接说出自己的想法。这就是步骤1\u003c/strong>\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>例如：有人从老家寄来很多相橘，家人甚至都吃腻了 而你不想让剩下的橘白自烂掉。\u003c/p>\u003cp>在这种候，请不要直接说：“大家继续吃啊！”\u003c/p>\u003cp>步骤2:揣摩对方的心理\u003c/p>\u003cp>\u003cstrong>请揣摩对方的心理，并根据其平日表理，猜测对方会对你的请求作何想法。\u003c/strong>\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……\u003c/p>\u003cp>如果对方答“No”的可能性很大，就不直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。\u003c/p>\u003cp>“不能光吃柑橘。”这应该就是家人的想法，此时请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。\u003c/p>\u003cp>到了容易感冒的季节，身边就会出现感冒者，家人都很在意这一点。\u003c/p>\u003cp>步骤3:“考虑符合对方利益的措辞”\u003c/p>\u003cp>\u003cstrong>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。\u003c/strong>想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>既然家人不想感冒，就可以对他们说:\u003cstrong>“多吃柑橘就不会感冒了。”\u003c/strong>\u003c/p>\u003cp>这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>变成“Yes”的3个步骤\u003c/strong>\u003c/p>\u003cp>\u003cstrong>步骤1\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不直接说出自己的想法\u003c/strong>\u003c/p>\u003cp>\u003cstrong>步骤2\u003c/strong>\u003c/p>\u003cp>\u003cstrong>揣摩对方的心理\u003c/strong>\u003c/p>\u003cp>\u003cstrong>步骤3\u003c/strong>\u003c/p>\u003cp>\u003cstrong>考虑符合对方利益的措辞\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>我看到小伙伴基本都已经看完了。没有阅读完的也没有关系，下面我会为大家进行详细的讲解。\u003c/p>\u003cp>平时我们与人交谈的时候，有时会不经大脑思考就把自己的想法脱口而出，特别是在向别人提出要求、请求的时候，经常会因为措辞没有技巧而遭到他人拒绝、否定。即便有时候我们的出发点是为他人好，但说出来却引起他人反感，导致原本很愉快的交谈变得不愉快。那么，面对这样的情况我们应该怎么办呢？\u003c/p>\u003cp>佐佐木圭一先生给了我们一个好的方法，只要三步就可以让对方接纳、认同我们的想法和要求，把他人的回答由NO改变成YES。\u003c/p>\u003cp>这三步就是——在不确保别人一定能接受自己的想法前，第一：不直接说出自己的想法；第二，根据你对对方的了解，猜测对方对此的想法；第三，结合对方的利益需求说出自己的想法。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>我是一个说话不太会考虑别人想法的人，所以经常会碰钉子。前两天下雪，孩子放假在家，复习准备考试，晚上我到家她跟我说，她已经复习完了，我直接来了一句“我布置的那套数学卷有没有做呢，没有做就去做一张。”我们家小孩更干脆，她说“我不做”，然后就是不愉快的场面了。\u003c/p>\u003cp>读到这个片段的时候，我就在想，如果当时我在提出让孩子做数学试卷的要求之前，先想一下她对做数学卷子的可能想法，如：她最讨厌做额外的作业，尤其是数学作业，所以她一定会拒绝我。但同时，马上就要期末考试了，她也很希望期末数学能考好。抓住了她有考好数学这个利益需求的心理之后，我就可以这样说：“你上次说，特别希望期末数学能够考好，让你的数学老师刮目相看，那现在刚好有时间，要不要做一张复习卷提高一下呢”这样说，我想效果会好很多。\u003c/p>\u003cp>书中也有很好的例子：大人带孩子外出吃饭，小孩子吃饱了，就在餐厅里跑来跑去，服务员跟家长说：“为了避免打扰其他客人，可否请你们让孩子坐在座位上”，可是家长根本不理。服务员很无奈，找到店长，会说话的店长就说了一句：“刚做好的菜很烫，如果端出来的时候被撞撒了，会给孩子造成很严重的烫伤。可否请你们让孩子回到座位上？”家长立刻都让孩子坐回了原位。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活学习者经验】\u003c/strong>\u003c/p>\u003cp>好，以上是我对这个方法的理解和分享。接下来我想让小伙伴一起来互动一下，为了方便互动，我给大家做一个分组，这边4个人一组，这边3个人一组，这边4个人一组……大家清楚自己的分组了吗？好的。\u003c/p>\u003cp>下面请大家一起来回忆一下，在近阶段你们与他人交流的过程中，有没有出现过自己的请求或者要求被别人否定，让你很生气或者尴尬的情况呢（情绪激活回忆）？如果有的话，当时的情景是怎样呢，请大家把关键词写下来，然后按照分组，在小组内与小伙伴分享交流一下，给大家5分钟的时间……\u003c/p>\u003cp>好了，我看大家交流的很热烈啊，有没有哪位小伙伴愿意来分享一下自己的经历呢？\u003c/p>\u003cp>【小伙伴案例】\u003c/p>\u003cp>旦旦分享：前两天上司给工作，但是必须的帮助没有给到。现在我觉得，上司的利益是不想工作被耽误，我可以以此利益切入，揣摩对方的心理，不直接说自己的想法，让他给我帮助。\u003c/p>\u003cp>【A2催化学习者运用】\u003c/p>\u003cp>小伙伴分享的非常棒。刚刚我发现很多小伙伴都有过想法被别人否定的情况，那么，今天我们学习了这个“结合对方利益需求来表达想法的表达技巧”，以后在表达自己想法和要求时，你会怎么做呢？\u003c/p>\u003cp>现在给大家1分钟的时间思考一下，请写下你们今后会在具体什么时间、什么场景下，如何来应用这个沟通技巧的步骤，也就是写一个运用方案A2，大家注意不要写成决心。\u003c/p>\u003cp>【小伙伴写的A2】\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>好，关于“如何让别人把回答从no变成yes”的方法学习我们就到此结束，感谢各位小伙伴的积极参与，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1518335299000,"updated_at":1518335299000,"ria":true},{"id":4617,"topic":"提出请求的技巧","learn_goal":"TF1-2","remark":"说话不只是一种感觉，还是一门技术，学习说话从掌握提出请求的技巧开始！","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"孙颖","city":"天津市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位小伙伴们大家晚上好，我是今天的拆书家孙颖，我的三个标签：具有8年工作经验的IT从业者，单位公众号运营的初级探索者，一名与宝宝一起成长的宝妈。今天很高兴能和大家在这里一起拆书学习。下面我简单介绍一下接下来的拆书流程，首先我会介绍一下我今天要拆解的书，然后采用拆书帮最著名的RIA读书法的方式一步一步展开今天的分享，后面会有分享讨论环节，希望大家能够积极参与进来。为了接下来更好的学习互动，咱们先分一下组，今天到场的学习者5人，在我同一侧的两个小伙伴为一组，桌子对面的三个小伙伴为一组，共分成两组，一会讨论时会按照分组进行。\r\n我今天给大家带来的书是《所谓情商高 就是会说话》，作者佐佐木圭一，是日本顶级沟通专家、广告鬼才、文案写作大师，在广告策划领域十八年来，曾多次获奖。这本书正是作者在经历无数次尝试和失败之后总结出的说话技巧，书中采用大量实践故事，对比使用技巧前后的区别，通俗易懂，非常具有实用性。","ratings_count":2,"texts":[{"id":7656,"quote":"\u003cp>今天给大家带来的片段是，在本书开篇提到的，关于提出请求的技巧，请大家花1-2分钟，看一下原文片段。看完之后请抬头示意我一下。\u003c/p>\u003cp>《所谓情商高 就是会说话》P7-8\u003c/p>\u003cp>把“No”的回答变成“Yes”，有３个步骤。\u003c/p>\u003cp>\u003cstrong>步骤１：不直接说出自己的想法\u003c/strong>\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤１。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。\u003c/p>\u003cp>在这种时候，请不要直接说：“大家继续吃啊！”\u003c/p>\u003cp>\u003cstrong>步骤２：揣摩对方的心理\u003c/strong>\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。\u003c/p>\u003cp>“不能光吃柑橘”。\u003c/p>\u003cp>这应该就是家人的想法。\u003c/p>\u003cp>此时，请再次忘记自己的请求，想想家人的喜恶，例如:\u003c/p>\u003cp>“不想感冒，没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>\u003cstrong>步骤３：考虑符合对方利益的措辞\u003c/strong>\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>既然家人不想感冒，就可以对他们说：\u003c/p>\u003cp>“多吃柑橘就不会感冒了。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也达到了。\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp>该片段讲解的是“提出请求”的技巧，这里所说的请求，指的是在日常工作、生活中根据需要提出的，并希望对方给予配合的一种需求。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>据统计一个人平均每天会求人22次，当然得到的回答，有的是YES，有的是NO，要想提高请求的成功率，我们需要掌握一定的说话技巧。\u003c/p>\u003cp>比如你想邀请他人会面、或者希望顾客很爽快的购物、又或者想让家人接受自己建议，如果不讲究任何技巧的把心里的话全部说出来，常常得不到想要的结果，甚至会让人反感；如果同样的事情采用正确的说话或者措辞技巧，往往事半功倍，不仅让大家容易接受，还能让人产生愉悦感。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那么我们提出请求到底有怎样的技巧呢？\u003c/p>\u003cp>根据原文中的三个步骤，我根据自己的理解提炼了三个字。1停2想3说。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;1、 停。停顿一下，不要着急去表达自己的想法。\u003c/p>\u003cp>原文中所说的，不要直接说出自己的想法，就是告诉大家有需求时不要着急去表达，需要先停顿下来考虑一下。\u003c/p>\u003cp>2、 想。揣摩对方心理，想一下直接说出请求后对方会有怎样的反应，成功的可能性大还是失败的可能性大，如果成功可能性大，那直接说出自己的想法没有问题，否则就要继续想，对方有怎样的需求，对方的需求和自己的请求的结合点在哪里？比如原文例子中的吃柑橘，大家不喜欢感冒，而柑橘可以有效预防感冒，这就是一个结合点。\u003c/p>\u003cp>3、说。结合自己提出请求的目的，以及对方的利益，采用一定措辞，将自己的想法表达出来。\u003c/p>","interaction":"\u003cp>下面我们进入【A】环节，通过拆页的学习，我们了解了当我们需要别人配合而提出请求时，我们应该怎样做。下面就是想一下自己过去有没有类似的经验呢？\u003c/p>\u003cp>大家在想的过程中，我先举个自己过去很失败的一个例子：\u003c/p>\u003cp>为了鼓励大家多阅读，去年在公司内部建立了图书角，当时希望大家读书写读后感，目的是能够吸引更多的同事借阅图书并参与写读后感。\u003c/p>\u003cp>我当时的表达方法就是：大家读完之后别忘了写读后感啊！结果可想而知，那就是没有结果。\u003c/p>\u003cp>当时就是犯了不假思索直接说的错误，在说之前并没有停下来想一下对方有怎样的需求。\u003c/p>\u003cp>接下来请大家思考一下，在你的工作或生活中有没有遇到过这样的场景，你想让对方做某件事，可是提出来对方却不为所动，或者迟迟不做出行动？\u003c/p>\u003cp>给大家半分钟的思考时间，一会我们找个小伙伴分享一下。\u003c/p>\u003cp>\u003cstrong>分享A：\u003c/strong>之前有人来咨询瑜伽，在简单了解需求之后，比如有人说想要减肥，有人说想要塑形，为了增进彼此的沟通和了解，我希望对方来上一节课体验一下，就会说：改天你可以过来体验一下。然后就没有然后了。\u003c/p>\u003cp>刚才咱们的分享者就是不假思索直接说，没有从用户的需求去寻找结合点，导致大家并不为此买单。下面可以考虑一下采用今天1停2想3说的方法，怎样改进自己的表达方式。\u003c/p>\u003cp>将拆页内容结合自己的经验之后，我想大家都对片段加深了理解，接下来，请大家来尝试使用一下今天的技巧，想象一下你工作或生活中的一个场景，你想达成某个目的，希望获得对方的配合，你应该怎样提请求？\u003c/p>\u003cp>给大家半分钟时间考虑一下，一会我们每组派个代表分享。\u003c/p>\u003cp>\u003cstrong>分享B：\u003c/strong>儿子不喜欢上街去买衣服，以前总是直接的问，你去上街买衣服吗？学了今天的片段之后，以后在跟儿子沟通去买衣服的时候我可以这样做：\u003cbr>\u003c/p>\u003cp>1、停。先不着接去直接表达自己的想法\u003c/p>\u003cp>2、想。想儿子为什么不喜欢上街去买衣服，他会觉得太耽误时间，而且男孩子本身不喜欢逛街。\u003c/p>\u003cp>3、说。咱们去买衣服，可以提前选好一家店，开车直接去，试好买完就回，也不会耽误太多时间。\u003c/p>\u003cp>咱们这位姐姐呢，成功运用了停、想、说的方法，规划了自己的应用，大家是否也都在心里想好自己的应用了呢？\u003c/p>\u003cp>由于时间原因，我今天的讲解部分就基本结束了，大家应该都学会了吧？接下来咱们再一起来回顾一下，提出请求的技巧：（1）停，停顿一下，不要着急去表达自己的想法（2）想，揣摩对方心理，想对方会有怎样的反应，想对方需求和自己请求的结合点；（3）说，采用一定措辞，表达出自己的想法。\u003c/p>\u003cp>最后再次感谢大家的积极配合，今天的分享就到这，希望大家都能有所收获。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1517698790000,"updated_at":1517698790000,"ria":true},{"id":4501,"topic":"一起学说话","learn_goal":"投其所好，轻松让对方说Yes，降低被拒绝的概率","remark":"“良言一句三冬暖，恶语伤人六月寒”，这句出自《增广贤文》的话告诉我们会说话的重要性。其实，我们常常谈论的情商，说到底，就是如何说话的问题。\r\n说话作为一门“技术”活，是可以学习的。想提高自己的情商，一定要学会如何说话。学会好好说话，可以慢慢将可能的“No”变成“Yes”。降低被拒绝的概率。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"豆豆0701","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"各位爱学习的小伙伴们，大家好。非常感谢各位抽出宝贵的时间参加来参加今天的拆书分享活动，我是豆豆，用三个标签介绍下自己：刚入门的拆书家，外企行政人员，1个女儿的妈妈。","ratings_count":1,"texts":[{"id":7516,"quote":"\u003cp>“报歉，这种衬衫只剩这一件了”听到店员这样说,你会怎么想?\u003c/p>\u003cp>“可能会一下子产生是别人挑剩下的吧”“这可能是很多人试穿过”的印象,如果店员换一种说法,例如：“这种衬衫卖得特别快,这是最后一件了”\u003c/p>\u003cp>你又会怎么想?大概会产生“要是流行,我也想买”“最后一件了,不买就没了”的印象。这样的措辞就是成功利用了“投其所好”的突破口,如此一来，拿着衬衫去收银台结帐的人也会很多,传达同样的内容,如果使用不同的措辞,对方的接受方式和行为就会发生变化。\u003c/p>\u003cp>\u003cbr>店员的目的是“希望顾客消费”但不能直接说出来,而是要揣摩顾客的心理,采用“投其所好”的措辞。\u003c/p>","explains":"\u003cp>打招呼+FAB图书介绍：2分钟\u003c/p>\u003cp>【F】&nbsp;\u003c/p>\u003cp>这是一本快速提升沟通能力的书，作者佐佐木圭一，从一个原本不擅长沟通和表达的人，成为拥有自己公司，在日本被称为顶级沟通专家、广告鬼才、方案写作大师，并成为首位获得美国广告大奖“金铅笔奖”的日本人，被视为亚洲最成功的广告策划人，这本书是他成功方法的浓缩。\u003c/p>\u003cp>【A】\u003c/p>\u003cp>本书的优势是什么？实用简单速成。本书的观点：说话如做菜，有谱可循，只要掌握了基本菜谱，任何人都能做出美味佳肴。作者在书中用图文并茂的方式和浅而已懂的案例详细介绍了7个突破口，8个技巧，便于理解容易掌握，拿来就能用。所以本书不光是菜谱，还是一本指南。\u003c/p>\u003cp>&nbsp; 【B】\u003c/p>\u003cp>&nbsp; 大家想一下，在你的生活中是否有这样的经历，想邀请意中人约会，不知道如何开口；想让老公帮 &nbsp; 你做家务，立马被回绝；想让身体弱的父亲参加运动…面对这些问题，本书会给到你解决方案。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong>：各位小伙伴在跟随我完成本次RIA现场学习后，能在面对可能的拒绝时，学会用7个突破口中“投其所好”的方式提出自己的请求，让对方更乐于接受，降低被拒绝的概率。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>发放拆页+【R】阅读原书拆页：2分钟（见现场材料，此处略）\u003c/p>\u003cp>【I】 拆书家讲解引导：3分钟\u003c/p>\u003cp>【What】【Why】\u003c/p>\u003cp>在7个突破口中的第一个突破口就是“投其所好”，按照作者的说法，这个既是最基本的，也是最管用的。只要养成考虑“投其所好”的习惯，就能让对方觉得你连性格都变好了。正因为你会\u003cstrong>主动\u003c/strong>考虑“投其所好”，所以性格是真的变好了。拆页中的例子向我们展示了如何通过‘投其所好’的措辞，让对方高兴地听取自己的请求，将有可能的NO变成YES。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>我们可以从拆页的例子中提炼出三个步骤：\u003c/p>\u003cp>\u003cstrong>1， \u003c/strong>\u003cstrong>不直接说出自己的想法\u003c/strong>\u003cstrong>\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>就像原文中的例子，销售员本来直接的想法是“这种衬衫只剩这一件了”，他没有直接说出这个想法，如果说出来对方可能就不买了….\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感，隐藏自己的想法是把自己的需求隐藏起来。请不要直接说出自己的想法。\u003c/p>\u003cp>\u003cstrong>2， \u003c/strong>\u003cstrong>揣摩对方的心里\u003c/strong>\u003cstrong>\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>还是文中的案例，销售员的目的是希望顾客消费他就是要去揣摩顾客的心理啦，他可能会问自己几个问题：顾客他的需求时什么？如何满足客户的需求…\u003c/p>\u003cp>请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。站在对方的立场考虑。把“NO”变成“YES”的答案就在其中。\u003c/p>\u003cp>3，\u003cstrong>考虑符合对方利益的措辞\u003c/strong>\u003c/p>\u003cp>最后，就要整理出一个符合对方利益的措辞，在原文案例中，销售员就说“这种衬衫卖得特别快，这是最后一件了”，这就是符合对方心理的措辞，对方一听，看来这个衣服很流行啊，就很开心滴买下了。\u003c/p>\u003cp>措辞符合对方的利益，人家自然变得乐意，而你的目的也就达到了。\u003c/p>\u003cp>【自己的例子】\u003c/p>\u003cp>我的双亲那个年代可能物资比较贫乏，所以现在看到打折的东西就买回家，又不舍得仍，家里堆的满满的，每次去都感到压抑。钱还浪费了。我一直想让我父母的环境变得宽敞舒适，扔掉点家中的堆积物，少买点东西。可效果甚微。一次因为家里东西放不下，真好附近的超市收纳箱打折，两老一下买了6个，送到家里因为摆不下，两老开始拌嘴，之后一个气的吃药，一个气的不吃饭，我也被叫去做和事佬。当时正好我遇到这本书，我尝试着运用了片段的三个步骤和父母交流，\u003c/p>\u003cp>\u003cstrong>第一步，不能说出自己真实想法\u003c/strong>，真实想法是什么？扔掉旧东西，少买东西。\u003c/p>\u003cp>\u003cstrong>第二步，揣摩父母的心理\u003c/strong>，父母的心理是什么？健健康康的，和和气气。\u003c/p>\u003cp>\u003cstrong>第三步，投其所好\u003c/strong>。中国人都知道风水重要，知道身体要健康每天需要排出身体的废物，身体的循环出问题了，身体也就出问题了（旧知）。我就和父母说家和身体一样，需要流转，风水就是家中流转的气。东西多了，风水流转不灵，破坏和气，对人的健康会有影响，反之，家中东西少点，风水流转越通畅，不好的东西被带走了，家里一团和气，身体自然好。结果就是，父母将买的收纳箱退了，还理了家，将长年不用的东西扔了不少。后来两老再买东西也会考虑会不会妨碍风水流动，是否影响和气和健康。家里变得干净多了，钱也省了不少。\u003c/p>\u003cp>【预防可能的异议】\u003c/p>\u003cp>可能有的小伙伴会问，这个方法不就是隐藏自己真实的想法，用另一种说辞操纵别人达到自己的目的吗？操纵别人达到不可告人的目的，刻意迎合是拍马屁，有点居心不良，所以是贬义的。而投其所好是站在对方的角度，换一种容易接受的表达方式，内心坦荡，是褒义的。所以表达时还是需要注意恰如其分。\u003c/p>","interaction":"\u003cp>【A2】分步催化：10分钟\u003c/p>\u003cp>【分步催化1】：2分钟\u003c/p>\u003cp>①&nbsp; 拆书家提问设计（逐字稿）：\u003c/p>\u003cp>下面请大家想象一下，到了下个周末，你想要另一半陪你参加一些活动来增进你们的感情，而另一半可能觉得累不想去；或者你想约上闺蜜、好友大吃一顿，对方在减肥，不想陪你吃吃喝喝；或者你希望家人吃早饭或某种素菜，但家人嫌吃早餐太麻烦，素菜口味不好等等。大家结合自己的情况想一想，你的请求会遇上哪些可能被拒绝的场景？请大家想一下，写在便签纸上。\u003c/p>\u003cp>②&nbsp; 学习者案例记录：\u003c/p>\u003cp>&nbsp;&nbsp; 晓便签：老公开始变胖，想让他运动，但老公很懒\u003c/p>\u003cp>&nbsp;&nbsp; 幻雪便签：爸爸总是抽烟，希望为了健康能戒烟\u003c/p>\u003cp>&nbsp;&nbsp; 荣荣便签：让儿子多吃蔬菜\u003c/p>\u003cp>【分步催化2】：8分钟\u003c/p>\u003cp>①&nbsp;&nbsp; 拆书家提问设计（逐字稿）：\u003c/p>\u003cp>好，小伙伴写完了。你正要和你的另一半说，或者给你的闺蜜打电话约吃饭（分享者的例子），你突然想到了今天的拆书---用投其所好的三个步骤，你就停下来问自己，我如何运用这个方法能让对方可能的拒绝变成YES呢？现在我们来分个组，给大家五分钟的时间讨论下，一会请小伙伴分享下。\u003c/p>\u003cp>②&nbsp;&nbsp; 学习者案例记录：\u003c/p>\u003cp>晓分享：\u003c/p>\u003cp>第一步：不直接说出自己的想法：越来越胖，会变得难看，需要运动\u003c/p>\u003cp>第二步：揣摩对方的心里：老公懒，怕辛苦。但是对我很好，愿意陪我\u003c/p>\u003cp>第三步：考虑符合对方利益的措辞：你陪在身边时做什么都特别安心，明早陪我一起跑步哈。\u003c/p>\u003cp>幻雪分享：\u003c/p>\u003cp>第一步：不直接说出自己的想法：抽烟对身体不好，戒烟\u003c/p>\u003cp>第二步：揣摩对方的心里：爸爸特爱打麻将，一打可以打一天，打麻将要健康的身体\u003c/p>\u003cp>第三步：考虑符合对方利益的措辞：爸爸这么爱麻将，说最好能长长远远的打下去，可惜抽烟会让打麻将的时间变短哦。\u003c/p>\u003cp>结束语：非常感谢大家的分享。说话是个与生俱来的能力，希望大家在以后的生活中能运用今天学到的三步骤，和7个突破口中第一个突破口投其所好，让说话成为你的助力，让生活和工作变的更加自如。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1516082206000,"updated_at":1516082206000,"ria":true},{"id":4145,"topic":"教你轻松让对方说 yes","learn_goal":"学习如何投其所好地说话，快速达成一致","remark":"","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"xgm","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"各位爱学习的小伙伴们，大家晚上好。感谢各位能抽出宝贵的时间来参加今天的拆书分享活动，我是熊光铭，用三个标签介绍一下自己：二级拆书家、IT技术工程师、铲屎官。今天给大家分享的主题是：投其所好，教你轻松让对方说 yes。","ratings_count":0,"texts":[{"id":7122,"quote":"\u003cp>（要求1、能够用学习者场景介绍法来介绍一本书。）\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>准备约女神吃饭，如果你直接问，周六有空吗？结果会怎样，除非对方特别主动，否则回答要么是有约了，要么到时再说，这都不是你想要的答案。\u003c/p>\u003cp>你本来看上一件衣服，准备掏钱去买，结果导购说，抱歉这种衬衫只剩这最后一件了，你或许会觉得是别人挑剩下的，于是就不想买了，这也不是导购想要的结果。\u003c/p>\u003cp>有的时候，你本来不想吃某一样食物，结果有人说，这个吃了对皮肤好、养颜，你立马觉得一定要吃下去，虽然你并不喜欢那个口味。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>大家可以思考一下，为什么会出现这种情况，是因为我们诚意不够姑娘不愿出来，还是因为导购说话的方式有问题才导致我们的决定前后发生了变化？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>其实最主要的是一种说话的方式和技巧，如果不去了解和学习，那么将会在面临很多重要的场合或者决定时，失去很多机会，然而机不可失失不再来。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>今天给大家分享的这本书叫做《所谓情商高 就是会说话》，作者是来自日本的佐佐木圭一，作者原本不擅长沟通和表达，在经历无数次尝试和失败后，发现了打动人心的语言奥秘。书中通过7个突破口和8个技巧，向读者展示如何用这些方法技巧来表达，让各位成为说话高手，提高对方按照我们意思来回答的可能性。我今天分享的内容是选自这些技巧和突破口中的一个点——投其所好，帮助各位抓住更多的机会。\u003c/p>\u003cp>（要求2、能够设计更清晰具体的学习目标。）\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>&nbsp; &nbsp; 各位小伙伴在跟随我完成本次学习后，可以在面对可能的拒绝时，学会用“投其所好”（澄清）的方法提出（行为）自己的请求，从而让对方更乐于接受（界定）。\u003cbr>\u003c/p>\u003cp>【R】选自《所谓情商高，就是会说话》P13\u003c/p>\u003cp>\u003cstrong>飞机供餐的鱼剩下很多时，怎样措辞才能顺利调整配量\u003c/strong>\u003c/p>\u003cp>电影《快乐飞行》里曾出现令人不禁点头赞许的巧妙措辞。在该影片中，绫濑遥（líng lài yáo）饰演某航空公司的新人空姐在分配供餐的一幕，由于乘客大多优先选择牛肉，所以导致鱼大量剩余。\u003c/p>\u003cp>就在新人空姐面临重大危机的关头，经验丰富的前辈说道：“像平时一样平均分配！看好了。”然后展现了高超的措辞技巧：“机内供应以优质香草、富含矿物质的天然岩盐和粗制黑胡椒嫩煎而成的白身鱼，以及普通牛肉。”\u003c/p>\u003cp>由于是电影，其中自然存在表演成分，但前辈空姐这样—说，乘客确实会觉得鱼更好吃。后来，当前辈空姐询问乘客的选择时，绝大多数乘客都主动选择了鱼。这里就使用了“投其所好”的“措辞菜谱”。\u003c/p>\u003cp>“对不起，只剩鱼了。”\u003c/p>\u003cp>如果空姐这样说，乘客就会觉得自己简直成了废品回收站，哪里还有吃东西的心情，而像前辈那样说，乘客就会心甘情愿地主动选择鱼。这就是措辞的力量。\u003c/p>","explains":"\u003cp>（要求3、更灵活地搭配R和I，可以选择没有行动建议的拆页来拆书。）\u003c/p>\u003cp>*1、找到混淆概念。\u003c/p>\u003cp>*2、为混淆概念找到合适案例。\u003c/p>\u003cp>*3、给出概念的正确理解，以及⾏动步骤。\u003c/p>\u003cp>4、举⼀个能⼀步⼀步对应上的例⼦。\u003c/p>\u003cp>5、给出步骤中的难点和关键。\u003c/p>\u003cp>好的，大家都读完了原文的片段，那么在这个拆页里，大家有没有发现一些重要的关键词？对，就是投其所好，那先明确一个概念，什么叫“投其所好”。\u003c/p>\u003cp>\u003cstrong>（易混淆的概念）\u003c/strong>在讲这个概念之前要区分一下投其所好不是溜须拍马，拍马屁是为了达到不可告人的目的，刻意去迎合，含有贬义。投其所好是站在对方的角度，换一种容易接受的表达方式，褒义词。\u003c/p>\u003cp>在跟客户领导沟通时，为了能促成项目，暗地托人调查领导的爱好，然后刻意迎合，结果被领导察觉，把项目交给了别的公司。这是不是投其所好？肯定不是，因为太刻意没有把握好度。\u003c/p>\u003cp>如果你看见老公在那抽烟，你说“没事就知道抽烟，都不能帮我干点家务呀”。这算不算投其所好呢，也不算，因为你这样说太直接了，听上去甚至有些责备的意思。\u003c/p>\u003cp>如果跟认识有一段时间的女生吃晚饭，走在大街上，女生突然说今儿还挺冷的，手都凉了，结果你跑去商店买了一双手套给她。这肯定也不是投其所好了，因为女生怎么呀？你们女生都懂。\u003c/p>\u003cp>那到底什么是投其所好呢？投其所好就是用对方当下状态最想听的话来表达的一种方式，但是不能太刻意。具体如何去做呢？\u003c/p>\u003cp>通过分析前辈空姐的说辞可以归纳出说话的三个步骤：\u003c/p>\u003cp>\u003cstrong>1、 \u003c/strong>\u003cstrong>不直接说出你想说的；\u003c/strong>\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。\u003c/p>\u003cp>\u003cstrong>2、 \u003c/strong>\u003cstrong>揣摩对方的喜好、心理\u003c/strong>\u003c/p>\u003cp>揣摩对方的心理，根据其平日表现、平时所关注点，猜测对方对你的请求作何想法。\u003c/p>\u003cp>\u003cstrong>3、 \u003c/strong>\u003cstrong>用符合对方愿意的措辞表达出来。\u003c/strong>\u003c/p>\u003cp>结合一开始你想直接说的内容和对方此刻最想接受的措辞，表达出来。\u003c/p>\u003cp>其实类似的情形在生活中特别常见，记得第一次跟三知书局合作商量用她们场地的时候，她们虽然没有说要求场地费，但要求点饮品和点心，我跟她们商量说饮品和点心有些偏贵，我们活动费用又比较低，看能不能少点或者不点，负责人说顶多打个八五折但是不能少点，也是考虑第一次合作，于是就答应了，最后核算下来我们活动费用收支几乎持平。\u003c/p>\u003cp>第二次再协商用场地的时候，我就没有直接说点饮品和我们活动经费比较少的事，就想一想她们书局现在的情况，因为书局坐落在售楼部二楼，售楼部已卖完房子，所以来这的人很少，她们需要流量和曝光，同时经常发现她们负责人也去参加一些活动，提高知名度，所以宣传是她们关心的，于是我跟负责人聊天时直接让她把书局一些介绍信息发过来，说附到我们活动内容里，单独介绍和宣传一下书局，结果她爽快了发过来，同时还把咱们的活动转到他们自己公众号上，最后我再说能不能提供点开水，我们自己准备水果时，她说没问题！\u003c/p>\u003cp>\u003cstrong>（步骤中的难点和关键）\u003c/strong>通过我的这个案例大家也应该有所发现，其实这里面比较难也是最关键的是第几步呀？对，第二步，揣摩对方的喜好、心理。\u003c/p>\u003cp>\u003cstrong>（适用边界）\u003c/strong>这种方法是不是百分之百能让对方答应你的请求呢？也不是，一方面任何事都也无法保证100%，另一方面还需要在表达的时候注意态度和和方式，恰如其分最好，不能太强制。\u003c/p>","interaction":"\u003cp>成人学习理论告诉我们，如果可以在大脑里模拟一下场景，相当于自己经历了一次，那接下来的时间就交给你们，需要各位做一回编剧，设计一段对话：想象一下未来几天或者几周内，这个小剧本的主角在什么场景下？需要向谁提出什么请求？并且希望得到Ta的肯定回答的情况，其中在表达请求时要用到今天我们学习到的“投其所好”的三个步骤，剧本要包括背景（时间、地点）、人物、动作、对白等。\u003c/p>\u003cp>讨论完或者构思完把摘要写在一张纸上，5分钟后，我会邀请小组内伙伴分享Ta的剧本。\u003c/p>\u003cp>\u003cstrong>一组的小剧本：\u003c/strong>\u003c/p>\u003cp>时间：周日的早上\u003c/p>\u003cp>地点：家里\u003c/p>\u003cp>人物：航航（老公）、豆小燃（老婆）\u003c/p>\u003cp>事件：周日了，老公想一起出去玩，可是还有衣服没有洗，还要做饭，这样时间上有一些冲突，为了能既不耽误做饭也能把衣服洗了，还能一块出去玩。\u003c/p>\u003cp>旁白：星期天早上，用投其所好的方式，商量如何分配家务和外出玩的时间\u003c/p>\u003cp>对白：（目标：让老公帮忙洗衣服，我来做饭，这样分配时间）\u003c/p>\u003cp>豆小燃：航航，星期天了，怎么计划的呀？\u003c/p>\u003cp>航航：出去玩呗，在家呆着无聊。\u003c/p>\u003cp>（思考：如果直接说让老公来洗衣服，很有可能会拒绝，不干。所以思考了下，老公是个小吃货。）\u003c/p>\u003cp>豆小燃：但是，我有一个事跟你商量下，很长时间没有给你做好吃的，你今天想吃什么呀？\u003c/p>\u003cp>航航：糖醋里脊！\u003c/p>\u003cp>豆小燃：呀，昨天还真买了肉，放在冰箱里。你看这样行不行，我做饭需要一个小时的时间，刚好你这段时间也没别的事，帮我把衣服洗一洗，这样等你洗完，好吃的也做好了，这样我们可以早点出去看电影了。\u003c/p>\u003cp>航航：可以呀，我这就去洗，你快点做哈。\u003c/p>\u003cp>豆小燃：好嘞!\u003c/p>\u003cp>【拆书家回应】\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;这个小剧本特别好，而且也不复杂，豆小燃的目标比较明确，想让航航帮忙洗衣服，然后能节约时间，如果直接让航航去洗，很有可能遭到拒绝，所以想到航航比较喜欢吃好吃的，就换一种说辞。最终达到了目标，节约了时间，还增进了两人的感情。\u003c/p>\u003cp>【结束语】\u003cbr>\u003c/p>\u003cp>今天我们一起学习了在说话时，不同的措辞会出现不同的结果，用“投其所好”的措辞，会更容易让对方说yes。方法也比较简单，只需要按照三个小步骤，就能增加更多的机会，希望各位以后能多多使用，使生活、工作变得更加自如，再次感谢各位的参与，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1512116625000,"updated_at":1512116625000,"ria":true},{"id":3941,"topic":"把“No”的回答变成“Yes”的技巧（2过）","learn_goal":"在有困难或需求时，学会用三个步骤提升他人同意自己请求的概率","remark":"说话不只是一种“感觉”，还是一门“技术”！就像烹饪有食谱一样，说话也有它的“秘方”。古往今来，但凡不通说话之道者，都难成大事，而能成事者，一定在语言方面具有其独特的能力。如果能把以前得到的1000次“No”的回答变成“Yes”,难道人生还不会改变吗？来吧，本周六，让我们一起学会说话。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"张诗悦","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"大家好，我是本环节的拆书家张诗悦，诗情画意的诗，赏心悦目的悅，我爸妈给我起这个名字呢就是希望我的人生如诗如画，温暖美好，希望这一次我的拆书也能给在座的各位带来愉悦的心情和小小的收获。那这次要拆的书叫做《所谓的情商高就是会说话》，它的作者是被誉为“亚洲最成功的广告策划人”、 日本的顶级沟通专家、广告鬼才、文案写作大师佐佐木奎一，而这本书呢也是日本深受欢迎的人际沟通课程，世界知名企业员工指定的培训教材。","ratings_count":0,"texts":[{"id":6886,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;这次要拆的原文片段来自于本书的第一章，把“No”变成“Yes”的技巧，刚才我已经把原文拆页发给大家了，现在就正式进入到本次拆书时刻，首先是R环节，阅读原文片段，请各位用两分钟的时间仔细阅读一下原文的内容，完成的伙伴请举手示意我：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 把“No”的回答变成“Yes”，有３个步骤。\u003c/p>\u003cp>\u003cstrong>步骤１：“不直接说出自己的想法\u003c/strong>\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤１。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>　　例如：有人从老家寄来很多柑橘，家人甚至都吃腻了而你不想让剩下的柑橘白白烂掉。在这种时候，请不要直接说：“大家继续吃啊！”\u003c/p>\u003cp>\u003cstrong>步骤２：“揣摩对方的心理\u003c/strong>\u003c/p>\u003cp>　　请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。直接说出请求，对方会作何反应？如果对方回答“Yes的可能性很大，当然可以直接说……如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。”这应该就是家人的想法。此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>\u003cstrong>步骤３：“考虑符合对方利益的措辞”\u003c/strong>\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>&nbsp; &nbsp;既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>&nbsp; 好，所有的小伙伴都已经读完了，那接下来就I环节——拆书家的引导讲解，我会用自己的话来重述一下原文的意思。\u003c/p>\u003cp>&nbsp; 其实原文非常明确啦，跟别人沟通过程中，如果想要别人按照自己的想法去做，有三个步骤，1有话不能直说，因为这样容易引起别人的逆反心理，结果往往会适得其反；2去猜对方的心思，想想对方的性格、喜恶；3站在对方的角度改变措辞，让你的话听起来是为了对方着想，对方就更容易接受。\u003c/p>\u003cp>\u003cstrong>举个例子：\u003c/strong>比如说我现在是和朋友合租，今天六月份的时候跑步崴了脚，结果家里卫生就一个星期都没人打扫，我想让舍友打扫下又不好意思直说，感觉像命令别人，所以对应第一步“有话不能直说”，我就不能直接来句“你去把房间打扫下吧”；那舍友会想你不方便不想打扫，我上班也很辛苦我也不想现在扫啊,而且说不定她压根没觉得家里脏；然后对应第二步我就要去想啊，我舍友是一个什么性格、喜恶？其实她特别在乎别人对她的评价，那分析完这些再对应第三步，要让自己的请求听起来是站在对方的角度着想，所以这个时候我就说了：“亲爱的，今天我妈给我打电话又夸你呢，说你人又勤快心底又善良，我这阵子脚不方便多亏了你，我妈说过两天来看我一定要请你吃饭呢！也真谢谢你，最近家里一脏也都是你主动打扫的，都不用我动手，能和你一起合租我真是太幸运啦！”，这样一来，舍友一听我妈要来还这么夸她，果然没一会自己就把家里打扫了。\u003c/p>\u003cp>\u003cstrong>再比如说：\u003c/strong>我妈身体一直不太好，人也比较胖，我想让她多运动运动，如果我直接来句“妈你晚上去楼下跑跑步呗”，我妈肯定不听，所以按照这个方法第一步，有话不能直说，这时候一定要忍住；那第二步还是要分析妈妈在意什么，她当然最在意的就是我啦，如果我晚上一个人出去，她肯定不放心；所以分析完后第三步站在妈妈的角度改变措辞，我就会说“妈我想去夜跑但害怕不太安全，你能陪我一起跑吗？”这样妈妈又怎么会拒绝呢？\u003c/p>","interaction":"\u003cp>&nbsp; 所以，日常生活中我们去请求别人的情景有很多，接下来我给大家分个组，根据咱们今天现场的人数，两两一组，我们在组内分享一下，你曾经有没有经历过类似情景，不管是你提出请求被拒绝的，还是你恰巧用了我们今天所说的方法成功说服别人的事例都可以。时间是5分钟，也就是一个人两分钟的时间说一下，要求是一件具体的事情，要有明确的时间、地点、人物、事件和感受。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; （小组讨论中）&nbsp;.......\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 好，时间到，哪位伙伴愿意分享一下自己过往的经历？\u003c/p>\u003cp>【A1】高飞：两个月前的一个周末，学习者高飞在家里做晚饭时一不小心给做胡了，想倒掉怕自己的岳母不同意，因为老一辈人都特别节省，于是高飞想了一下，岳母年纪大了比较注意养生，于是他给岳母说：“妈，专家说了，烧糊的饭里面含有致癌物，吃了患癌症的几率会增加，咱还是别省小钱花大钱人还受罪，把这烧糊的饭倒掉吧。”岳母一听就同意了，也没为这件事生气吵架。&nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp;谢谢这位伙伴，他举的是以前一个成功的例子。那现在请大家想一想，根据我们刚才讲的把“No”的回答变成“Yes”的技巧，在我们今后的生活中如何运用，注意一定不是喊口号式的，要有具体的做法、明确的期限以及可衡量的结果哦，可以写在我刚才给大家发的便签上。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; (大家写便签中).......\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;好，大家基本上都完成了，我本次的拆书到这里也全部结束了，希望能在工作和生活中帮助到大家，谢谢各位的配合！\u003c/p>\u003cp>【A2】瑞文的便签：作为公司的HR经理，最近发现前台的小姑娘总是上班玩手机，还时不时的傻笑，经过了解应该是交了男朋友，这是好事没错但不能为此影响工作，所以打算去提醒她一下。学了今天的把“NO”的回答变成“YES”的技巧后，我想了下，首先有话不能直说，我不能来句你上班别玩手机了，二理解她现在的状态，三站在她的角度改变措辞，所以我准备下周一上班的时候给她这样说：“亲爱的，你来公司当前台这段时间表现的都一直非常好，我特别高兴每次我们的客户一进公司，迎接他们的都是你热情的微笑，而不像我去别的公司前台不是在聊天就是在玩手机，像你这样认真对待工作又长得漂亮的姑娘一定会收获一份美好的爱情的。”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1509441734000,"updated_at":1509441734000,"ria":true},{"id":3812,"topic":"如何更有效说服别人","learn_goal":"各位伙伴能够掌握在沟通时能够通过投其所好达到说服他人的目的","remark":"投其所好，了解对方爱好，才能更好说服别人","level":"TF2-3","duration":24,"status":0,"type":0,"chaishujia":{"username":"茶舍小语","city":"烟台市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【拆书目标】各位伙伴你们好！很高兴能与各位伙伴一起做拆书分享，通过本次的拆书分享，各位伙伴能够掌握在沟通时能够通过投其所好达到说服他人的目地这样的一个技巧\r\n今天我们要拆的书是《所谓情商高就是会说话》，【F】这是一本提升沟通能力的书，本书的作者是日本的佐佐木圭一，在日本他被称为是顶级沟通专家、广告鬼才、方案写作大师，并且是首位获得美国广告大奖“金铅笔奖”的日本人。本书中，他详细地介绍了说服他人的七个突破口，八个技巧。\r\n【A】那么这本书有什么特点呢？一个字：“实”，一是实用性。本书的观点是说话就像做菜，是有谱可循的。只要掌握了菜谱，任何人都能做出美味佳肴。”二是实操性。本书图文并茂，在每个章节都是先列出技巧和突破口，然后再用案例说明，简单易理解，容易掌握，是一本拿来用而不是拿来读的书。\r\n【B】回忆一下，你是否有这样的经历，在职场上，一件工作，要请求同事帮忙，可又不知如何开口，面对心仪的女孩，你想请她去吃饭，可你一开口对方拒绝了，面对此类问题，本书都会为你提供解决方案。","ratings_count":0,"texts":[{"id":6737,"quote":"\u003cp>\u003cstrong>《所谓情商高，就是会说话》P11\u003c/strong>\u003cstrong>页——投其所好\u003c/strong>\u003c/p>\u003cp>“报歉，这种衬衫只剩这一件了”\u003c/p>\u003cp>听到店员这样说,你会怎么想?\u003c/p>\u003cp>“可能会一下子产生是别人挑剩下的吧””这可能是很多人试穿过”的印象,如果店员换一种说法,例如:\u003c/p>\u003cp>“这种衬衫卖得特别快,这是最后一件了”\u003c/p>\u003cp>你又会怎么想?大概会产生”要是流行,我也想买””最后一件了,不买就没了”的印象.这样的措辞就是成功利用了”投其所好”的突破口,如此一来,拿着衬衫去收银台结帐的人也会很多,传达同样的内容,如果使用不同的措辞,对方的接受方式和行为就会发生变化.\u003c/p>\u003cp>店员的目的是”希望顾客消费”但不能直接说出来,而是要揣摩顾客的心理,采用”投其所好”的措辞.\u003c/p>\u003cp>下面是几则利用投其所好的实践故事。\u003c/p>\u003cp>飞机供餐的鱼剩下很多时，怎样措辞才能顺利调整配置？电影《快乐飞行》里曾出现令人不禁点头赞许的巧妙措辞，在该影片中，绫濑遥饰演某航空公司的新人空姐，在分配供餐的一幕，由于乘客大多优先选择牛肉，所以导致鱼大量剩余\u003c/p>\u003cp>就在新人空姐面临重大危机的关头，经验丰富的前辈说道：“像平时一样平均分配，看好了”然后展示 了高超的说辞技巧：“机内供应以优质香草、富含矿物质的天然岩盐和粗制黑胡椒嫩煎而成的白身鱼，以及普通牛肉”\u003c/p>\u003cp>由于是电影，其中自然存在表演成分，但前辈空姐这样一说，乘客确定会觉得鱼更好吃，后来，当前辈空姐询问乘客的选择时，绝大多数的乘客都主动选择了鱼，这里就使用了“投其所好“的措辞菜谱\u003c/p>","explains":"\u003cp>在本书中投其所好的例子很多，我们今天的拆页只是选取了一个。我们知道，投其所好是说服他人的一种很好的方法,如何投其所好?我们可以从拆页片断中提炼出三个步骤:\u003c/p>\u003cp>\u003cstrong>【行动步骤\u003c/strong>】首先，隐瞒自己的想法。人们在提出请求时，常常下意识地说出自己心里所想，结果导致自己的请求被拒绝，隐瞒自己的想法是把自己的需求隐藏起来\u003c/p>\u003cp>其次，揣摩对方的心理。如何揣摩？站在对方的角度，考虑对方的需求是什么？ \u003c/p>\u003cp>最后，投其所好，是根据对方喜欢。什么爱好什么，然后找到满足对方心理的措辞，说出来，并打动对方\u003c/p>\u003cp>\u003cstrong>【举例说明\u003c/strong>】举个例子，有一种蔬菜叫小番茄，我们称之为小西红柿，口感特别好，甜甜的，绵绵的，但人们无论怎么喜欢，它仍然是蔬菜，怎么样买出高价格？这个时候，运用片断的三个步骤，第一步，不能说出自己的真实想法，真实想法是什么？想买个好价钱。第二步，揣摩顾客的心理，顾客什么心理？水果比蔬菜价格要高，并且喜欢圣洁的东西。第三步，投其所好，起一个好听的名字，把小番茄改名叫圣女果，然后，把这种小番茄放到水果店里卖，于是，小番茄的身价大增\u003c/p>\u003cp>\u003cstrong>【预防异议\u003c/strong>】也许有的伙伴会提出疑问，按照这三个步骤提出请求是不是太麻烦了？我们试想一下，我们提出请求的目标是什么？是让别人答应你的请求。这就好比一座斜度为45度的高山，你要在山角下开着车到达山顶，是沿着盘山公路开着车到山顶快呢还是沿着山的坡度开着车到达山顶快呢？请求别人像开车是一样的\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3\u003c/strong>\u003cstrong>场景设计\u003c/strong>】有一位博士，智商高，情商低，与一位心仪的女孩谈了一个月的恋爱，女孩子提出了分手，分手时女孩对他说：你根本不懂我的心。原来，那位博士想与女孩约会，挂电话给女孩：“你愿意看电影吗？”女孩说：“不愿意”，然后就没有了然后。\u003c/p>\u003cp>好，现在假若你就是那位博士，今天晚上你想与那位心仪的女孩约会，在前些天你听女孩说过，她以前看过《战狼1》，并且还能记得《战狼1》中的一句台词“犯我中华者，虽远必诛”，所以你约她看最近上影的一部电影“战狼2”，你拿起了电话，向女孩发出了邀请，现在你运用拆页中讲的三个步骤，来说服女孩.\u003c/p>\u003cp>\u003cstrong>【A3\u003c/strong>\u003cstrong>现场指令\u003c/strong>】各位伙伴我们有10分钟的时间，在小组内进行讨论，然后，我们选出两个人，一位扮演博士，一位扮演女孩，用我们今天所学的说服技巧来让女孩愉快地应约。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>王老师扮演博士，孙老师扮演女孩。\u003c/p>\u003cp>王：上个周五我们在一起时，你说过你很喜欢《战狼1》\u003c/p>\u003cp>孙：是的。\u003c/p>\u003cp>王：《战狼2》是《战狼》的第二部，网评这部电影很不错，今天是上演的最后一天，我猜你一定喜欢这部电影，所以我买了两张票，是今天晚上七点四十分的，我陪你看这场电影，可以吧？\u003c/p>\u003cp>孙：好的，我们在哪儿碰面？\u003c/p>\u003cp>王：我们七点半在东风电影院门口吧。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1507382959000,"updated_at":1507382959000,"ria":true},{"id":3689,"topic":"透过表达看思维哟","learn_goal":"破除劣质表达习惯，学会优质","remark":"人的行为意愿，会在很大程度上，受到表达方式的影响。\r\n\r\n      我们以为，说出来的话来自于心中所想，而事实上，说出来的话，并非来自于心中所想，而是来自——习惯性思维模式。一个人的表达方式，其实是他的思维方式。研究表达，也就是研究思维。","level":"TF3-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"羽美人","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"人的行为意愿，会在很大程度上，受到表达方式的影响。\r\n我们以为，说出来的话来自心中所想，而事实上，说出来的话，并非来自于心中所想，而是来自——习惯性思维模式。\r\n一个人的表达方式，其实是他的思维方式。研究表达，也就是研究思维。","ratings_count":0,"texts":[{"id":6600,"quote":"\u003cp>\u003cstrong>打招呼+分组 &nbsp;FAB\u003c/strong>\u003cstrong>图书介绍【\u003c/strong>\u003cstrong>2分钟\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>大家好，我是今天的拆书家，羽美人。今天拆的书目是《所谓情商高，就是会说话》\u003c/p>\u003cp>事件场景：在生活中，大家有没有遇到过这样的场景：当我们想让另一半或者是孩子帮忙时，我们经常会这样说：“去把垃圾扔了”或者“来帮我洗下碗”。可结果呢？就得看对方当时的心情了。得到的回答很可能是“我现在很累，让我歇会儿”，或者“我正在看电视呢，我好累。我正在电脑上跟别人谈事情，等一下”。然后，就没有然后了。\u003c/p>\u003cp>提问：工作和生活中，类似这样的场景都很多，当我们想让对方做什么而对方拒绝时，我们之前是怎么做的？一般而言，我们可能会讲跟对方道理、定规矩、下命令，甚至争吵。但效果和结果怎么样呢？不太好，是不是？\u003c/p>\u003cp>影响：确实，我们的生活，常常会因为这些鸡毛蒜皮的小事而发生争执，甚至上升到互相攻击人品的程度，使得本来就忙碌的生活出现很多埋怨、烦恼和不顺。而这些，其实很多都是是可以避免的。\u003c/p>\u003cp>解决：这本书的作者，原先也是一个不太会说话、情商不高的人，后来他下了一番功夫研究语言艺术，表达规律，使得他在沟通中能够轻松的个对方达成一致、令对方做出改变。作者告诉我们，人的行为意愿，很多时候会受到表达方式的影响，这本书为我们提供了很多非常实用的表达技巧。\u003c/p>\u003cp>今天，我们的学习目标是，在跟随我完成本次RIA现场学习后，学习者能够用“选择的自由”表达技巧解引导对方做出主动的行为改变，如帮忙做家务、陪同看电影、按期交作业等（界定）。\u003c/p>\u003cp>接下来我发一下拆页。\u003c/p>\u003cp>\u003cstrong>R·阅读原书拆页【1分钟】\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 让不愿穿鞋的幼儿下意识穿上鞋的措辞\u003c/p>\u003cp>坂井惠美（化名）有个两岁的女儿。她每天都会送女儿去幼儿园，但女儿不愿穿鞋，她又不能送光着脚的女儿去幼儿园，所以很伤脑筋。\u003c/p>\u003cp>“穿鞋。”\u003c/p>\u003cp>就算她这么说，女儿也根本没有穿鞋的意思，反而跑回房间玩起了积木。迟到是家常便饭。坂井很犯愁。一天，她试着使用了从朋友那里听来的“措辞菜谱”。坂井拿着两双鞋问女儿：\u003c/p>\u003cp>“蓝色的鞋和红色的鞋，你想穿哪双？”\u003c/p>\u003cp>结果女儿用手指着说：“蓝色的鞋！”然后主动开始穿鞋。从女儿的角度来说，她不喜欢被迫穿鞋，而通过自主选择，就变得愿意穿鞋了。这就是利用了“\u003cstrong>选择的自由\u003c/strong>”这一措辞突破口。\u003c/p>\u003cp>从那以后，坂井在育儿时经常使用这样的措辞。不直接说“穿衬衫”，而是问“有花纹的衬衫和有小熊的衬衫，你想穿哪件？”\u003c/p>\u003cp>育儿时使用“措辞菜谱”的好处，不仅在于孩子能变得主动自愿，而且还能自然而然地从妈妈身上学会如何使用“措辞菜谱”。在孩子的生活中，与朋友或老师交谈的场合非常多，而只要掌握了如何措辞，就必然能减少纠纷。\u003c/p>","explains":"\u003cp>\u003cstrong>I环节【5分钟】\u003c/strong>\u003c/p>\u003cp>□3-1要求：讲解引导时，拆书家给出了具体行动建议或者具体步骤；讲解引导时，拆书家举出了案例，并通过概念与匹配例子之间的对比，引出知识点逻辑、步骤和明确边界等。\u003c/p>\u003cp>这个拆页，是一个完整的案例，案例中讲了这个妈妈，她原先让孩子穿鞋，孩子就是不穿。后来，这个妈妈用一种“选择的自由”表达方式，代替了以往命令式的表达方式，非常神奇且轻松地和孩子达成一致，改变了孩子的行为，让孩子主动自愿的开始穿鞋和穿衣服。\u003c/p>\u003cp>\u003cstrong>那么，在这个拆页中，我们先明晰一个概念，什么叫做“选择的自由”？\u003c/strong>\u003c/p>\u003cp>原来妈妈说的是，穿鞋！如果现在改成：你想穿鞋子上学吗？或者说：你想穿什么鞋子上学？\u003c/p>\u003cp>这是选择的自由吗？不是，因为小孩很可能回答：我不想穿鞋，我就是不想穿鞋。\u003c/p>\u003cp>所以，我们可以看出，原书中“选择的自由”这个概念包含两个关键点：\u003c/p>\u003cp>第一个，\u003cstrong>用提问的说话方式代替命令、陈述的句式。\u003c/strong>体现出尊重对方的意见。\u003c/p>\u003cp>第二个，\u003cstrong>提问的同时，一定要给出合适的选择范围。\u003c/strong>不是“你想要穿什么鞋？”，而是“红色的鞋和蓝色的鞋，你想要穿哪一双？”\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学会通过举例与对比帮助学习者明确适用边界条件与关键点：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>那为什么说，掌握了这两个点，这种措辞技巧是有效的呢？还有，这种技巧在哪些场合特别适用呢？\u003c/strong>我给大家举两个例子，大家就清晰了。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>例子1\u003c/strong>\u003c/p>\u003cp>当你需要组织一群人做出集体决定的时候。比如部门聚餐，如果你在群里问：“大家想吃什么？”\u003c/p>\u003cp>基本上所有人都会说：“都行，都可以，听大家的”。\u003c/p>\u003cp>这个时候你问了等于白问，虽然你用了提问的句式，询问了对方的意见，但这并不是“选择的自由”。\u003c/p>\u003cp>而真正“选择的自由”是什么呢？是你提前做好功课，给出几个选项，而且你知道这几个都是大家都比较喜欢的餐厅。\u003c/p>\u003cp>这时候你在群里发一个聚餐意见征集，比如：\u003c/p>\u003cp>聚餐意见征集：\u003c/p>\u003cp>1、XXX餐厅日本料理 &nbsp;\u003c/p>\u003cp>2、新白鹿餐厅 &nbsp;\u003c/p>\u003cp>3、云海肴\u003c/p>\u003cp>告诉大家想选哪个，在群里回复，然后你根据选项的人数统计，不仅可以快速做出决策，而且你分解了自己的压力，因为大家自己选的饭店，就不太会出现吃的时候不满意，埋怨你的情况。\u003c/p>\u003cp>刚才这个例子讲的是集体做决策时，可以运用“选择的自由”。还有一个非常适用的情况是：当我们想要影响对方改变行为的时候，也可以用“选择的自由”。\u003c/p>\u003cp>\u003cstrong>例子2\u003c/strong>\u003c/p>\u003cp>我的一个朋友，她通过“选择的自由”提问方式，让自己不爱打扫卫生的老公主动打扫卫生。\u003c/p>\u003cp>她是怎么运用的呢？\u003c/p>\u003cp>周五的时候，如果她这么跟老公说：我们周末打扫卫生怎么样？或者是用命令的语气说，“打扫卫生！”很有可能他老公会找理由拒绝，比如：“我这周太累了，要不下周末打扫吧”。或者“周末我正好有点事儿，我看家里也挺干净的”。\u003c/p>\u003cp>所以这样的提问方式就不符合“选择的自由”，达不到影响老公做出改变的效果。\u003c/p>\u003cp>所以她是这么问的：“这周我想给家里做个大扫除，你看是周六方便呢？还是周日方便？”\u003c/p>\u003cp>这时候老公就被引导到了选项上了，他就想：我这周确实挺累的，周六想休息一下，要不周日下午吧？\u003c/p>\u003cp>到了周日上午的时候，她这么问：“今天要打扫卫生了，你是打扫浴室呢，还是打扫厨房？”\u003c/p>\u003cp>这时候老公就会想：浴室好像简单一点，厨房油烟脏兮兮的。于是他就会说，那我还是打扫浴室吧。他老公自己做出了选择，还觉得自己赚到了。（大家笑）\u003c/p>\u003cp>到了中午的时候，她再次提问：“你是想午睡起来就打扫呢？还是我们下午看完电影回来，晚饭前打扫呢？”\u003c/p>\u003cp>他老公想着，还是午睡起来就打扫吧，打扫完安心出去看电影。\u003c/p>\u003cp>于是，她就成功的引导不爱做家务的老公自主自愿去打扫浴室去了。（大家笑）\u003c/p>\u003cp>\u003cstrong>好，根据上述两个例子，我们应该对于“自由的选择”这个概念有了更为清晰的理解。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们可以总结出“选择的自由”三个行动步骤：\u003c/strong>\u003c/p>\u003cp>1、表示尊重。把命令句式改成提问句式。（意思就是我尊重对方的意见，询问对方的意见和需求）\u003c/p>\u003cp>2、提前做好功课。（一定要提前做好功课，找出在合适、合理范围内的2、3个可行的选项，而不是提一个开放性的问题，也不是提出非常难的要求。）\u003c/p>\u003cp>3、一层层提问引导。（循循善诱，一层层提问引导，要有耐心）\u003c/p>\u003cp>\u003cstrong>好，方法我们已经讲完了，那这个表达方式背后的思维方式是什么呢？\u003c/strong>\u003c/p>\u003cp>思维方式：话语中体验了对对方的尊重，给对方自主选择权，做足功课，给对方合理的范围，方便他选择；把原先我们习惯的命令式、灌输式的控制性思维，改成了引导式思维。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2【10分钟】 \u003c/strong>\u003c/p>\u003cp>□3-1要求：环节指令清晰，学习者可以根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事。\u003c/p>\u003cp>接下来，我们进入A2环节。这一次呢，我们要编一个小故事。\u003c/p>\u003cp>请大家想一想，在之后的工作和生活中，有哪些场景是可以运用我们今天学到的“选择的自由”这个表达方式呢？\u003c/p>\u003cp>请大家挑选一个可能的场景，编一段小故事。\u003c/p>\u003cp>\u003cstrong>要求：\u003c/strong>\u003c/p>\u003cp>1、故事完整。有人物，有起因、经过、结果。\u003c/p>\u003cp>2、有对话。故事中有你和对方的对话，对话中就使用了“自由选择”这样一个表达方式。\u003c/p>\u003cp>大家可以参考我之前跟大家讲的关于让老公打扫卫生这个案例故事。\u003c/p>\u003cp>我们分一下组，大家也可以互相讨论一下，给大家5分钟的时间，之后我们请每组一个小伙伴来讲讲他的故事。\u003c/p>\u003cp>\u003cstrong>多啦分享：\u003c/strong>\u003c/p>\u003cp>我想让我男朋友陪我去看《三生三世十里桃花》电影。这种电影他一般是不怎么感兴趣的。\u003c/p>\u003cp>我可以用“选择的自由”循循善诱。\u003c/p>\u003cp>我先问：亲爱的，你今天是想在家陪我做家务呢，还是想出去玩溜达一下呢？\u003c/p>\u003cp>他肯定不愿意做家务的，于是他就选择出去玩。\u003c/p>\u003cp>出去了以后，我就问：那你是想去逛街买衣服呢，还是想去电影院看电影呢？\u003c/p>\u003cp>男生一般都不愿意逛街，所以他很有可能就选择去电影院。\u003c/p>\u003cp>到了电影院，因为我已经查过了，那天播放的只有《三生三世》和动画片。\u003c/p>\u003cp>所以，我就问他：你看我们来都来了，现在只有这两部片子，我觉得《三生三世》最近挺火的，可以试试。你看你是想看《三生三世》呢，还是看动画片？\u003c/p>\u003cp>男友虽然对《三生三世》不是很感兴趣，但相对于看动画片，他还是觉得《三生三世》好一点，于是他就说，那还是三生三世吧。\u003c/p>\u003cp>\u003cstrong>拆书家回应：\u003c/strong>哇，很棒的剧本和故事啊！哆啦成功的运用“选择的自由”，一步步让男友主动自愿的陪她看了《三生三世》。很好，还有哪位小伙伴分享的？\u003c/p>\u003cp>\u003cstrong>Shirely分享：\u003c/strong>\u003c/p>\u003cp>小朋友的老师要来家访，我想让老公和我一起提前打扫一下。\u003c/p>\u003cp>我这么说：你看，下周末老师要来家访了，在这之前我们要把家里打扫一下的。你看你是下周四有时间呢，还是周五有时间？周五我可能会回来的比较晚一点点。\u003c/p>\u003cp>他一想周五我回来的晚，就觉得说：那就周四打扫吧。\u003c/p>\u003cp>然后周四我俩到了家以后，我就说：你看，咱俩分个工，是你收拾我来拖地呢？还是你拖地我来收拾？\u003c/p>\u003cp>他说：我来拖地，收拾这东西，太零散了，太细了，我做不了。\u003c/p>\u003cp>然后这个完了，到了打扫卫生间和厨房的时候，其实我不想打扫卫生间。于是我就问他：你看，厨房也是油，卫生间也要擦，你是打扫卫生间呢，还是打扫厨房呢？\u003c/p>\u003cp>他说：哎呀，刷马桶我来，你去打扫厨房吧，厨房太油了我不要去。\u003c/p>\u003cp>这样分工就明确了，我的活也被分担掉了。\u003c/p>\u003cp>\u003cstrong>拆书家回应：\u003c/strong>对，你这个表达的非常好。你是引导他自己做出决定，如果你生硬的要求他就是去打扫卫生间，他可能就不太能接受不太愿意了。\u003c/p>\u003cp>\u003cstrong>雷蒙德分享\u003c/strong>：\u003c/p>\u003cp>我分享一个简单。\u003c/p>\u003cp>部门之间合作时，我希望对方部门那个人下周把我需要的东西给我。\u003c/p>\u003cp>我就给他打电话，说：我需要下周跟您开个会，您下周什么时候有空呢？是周一方便，还是周二方便？\u003c/p>\u003cp>他可能会说：周一不行，还是周二吧。\u003c/p>\u003cp>我说：周二好的，我也可以。那你看是上午还是下午呢？\u003c/p>\u003cp>他可能会看看自己的时间表说：我估计下午三点到四点。\u003c/p>\u003cp>我说：那好，我待会儿就把会议邀请给你发过去。\u003c/p>\u003cp>于是就这样定下来了。\u003c/p>\u003cp>\u003cstrong>结束语\u003c/strong>\u003c/p>\u003cp>好的，非常棒，大家都分享了自己的小剧本。今天这个拆页呢就是介绍了一种表达技巧，大家可以运用“选择的自由”表达技巧解引导对方做出主动的行为改变，如帮忙做家务、陪同看电影、按期交作业等（界定）。\u003c/p>\u003cp>最后我想说的是，“选择的自由”这个表达技巧并不仅仅是一种“话术”，它的背后其实是一种思维方式的转变，把我们过去“命令式的控制性思维”转变为“引发对方自主改变”的引导式思维。\u003c/p>\u003cp>好的，我今天的拆书就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1505726453000,"updated_at":1505726453000,"ria":true},{"id":3620,"topic":" 学习 把“No”变成“Yes”的技巧   ","learn_goal":"一起学习得到别人肯定回答的技巧","remark":"说话不只是一种“感觉”，还是一门“技术”！\r\n就像烹饪有食谱一样，说话也有它的“秘方”。\r\n古往今来，但凡不通说话之道者，都难成大事，而能成事者，一定在语言方面具有其独特的能力。如果能把以前得到的1000次“No”的回答变成“Yes”,难道人生还不会改变吗？来吧，让我们一起会说话。","level":"TF1-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"张诗悦","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"大家好，我是本环节的拆书家张诗悦，诗情画意的诗，赏心悦目的悅，我爸妈给我起这个名字呢就是希望我的人生如诗如画，开心美好，那希望这一次我的TF1-2的升级打怪也能给在座的各位带来愉悦的心情和小小的收获。\r\n 我这次要拆的书叫做《所谓的情商高就是会说话》，它的作者是被誉为“亚洲最成功的广告策划人”、 日本的顶级沟通专家、广告鬼才、文案写作大师佐佐木奎一，而这本书呢也是日本深受欢迎的人际沟通课程，世界知名企业员工指定的培训教材。","ratings_count":0,"texts":[{"id":6521,"quote":"\u003cp>那这次要拆的原文片段来自于本书的第一章，把“No”变成“Yes”的技巧，刚才我已经把原文拆页发给大家了，现在请各位用两分钟的时间阅读一下（完成后请举手示意我）： \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 把“No”的回答变成“Yes”，有３个步骤。\u003c/p>\u003cp>\u003cstrong>步骤１：“不直接说出自己的想法\u003c/strong>\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤１。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>　　例如：有人从老家寄来很多柑橘，家人甚至都吃腻了而你不想让剩下的柑橘白白烂掉。在这种时候，请不要直接说：“大家继续吃啊！”\u003c/p>\u003cp>\u003cstrong>步骤２：“揣摩对方的心理\u003c/strong>\u003c/p>\u003cp>　　请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。直接说出请求，对方会作何反应？如果对方回答“Yes的可能性很大，当然可以直接说……如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。”这应该就是家人的想法。此时，请再次忘记自己的请求，想想家人的喜恶。例如：“不想感冒。”没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>\u003cstrong>步骤３：“考虑符合对方利益的措辞”\u003c/strong>\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>既然家人不想感冒，就可以对他们说：“多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; 好，我看所有小伙伴都读完了，那接下来我用自己的话来重述一下这段话。其实原文非常明确啦，跟别人沟通过程中，如果想要别人按照自己的想法去做，有三个步骤，1有话不能直说，因为这样容易引起别人的逆反心理，结果往往会适得其反；2去猜对方的心思，想想对方的性格、喜恶；3站在对方的角度改变措辞，让你的话听起来是为了对方着想，对方就更容易接受。\u003cstrong>举个例子，\u003c/strong>比如说我想让舍友拖地，对应第一步“有话不能直说”，我就不能直接来句“你去把地拖了吧”；那舍友会想怎么你不去拖，凭什么我干活你在旁边站着；然后对应第二步我就要去想啊，我舍友是什么样的人？其实她也很明事理，但她也不是冤大头啊，不可能什么都让她一个人干呀，也是很看重公平，不能一味让自己吃亏的，那分析完这些再对应第三步，要让自己的请求听起来是站在对方的角度着想，所以这个时候我就应该说：“咱们把屋子打扫一下吧，扫地和拖地你选哪一个”，这样一来，舍友肯定很爽快的就选一个区干了呀；\u003cstrong>再比如说，\u003c/strong>我妈身体一直不太好，人也比较胖，我想让她多运动运动，如果我直接来句“妈你晚上没事去跑跑步呗”，我妈肯定不听，所以按照这个方法第一步，有话不能直说；那第二步还是要分析妈妈在意什么，她当然最在意的就是我啦，如果我晚上一个人出去，她肯定不放心；所以分析完后第三步站在妈妈的角度改变措辞，我就会说“妈我想去夜跑但害怕不太安全，你能陪我一起跑吗？”这样妈妈又怎么会拒绝呢？\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp;&nbsp;所以，日常生活中我们去请求别人的情景有很多，接下来我给大家分个组，我们在组内分享一下，你曾经有没有经历过类似情景，不管是你提出请求被拒绝的，还是你恰巧用了我们今天所说的方法成功说服别人的实例都可以。时间是5分钟，要求要有明确的时间、地点、人物、事件和感受。\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp;好，时间到，哪位伙伴愿意分享一下自己过往的经历？\u003cbr>&nbsp; 暖暖老师的分享：“在工作中让学生做作业，我不会直接给学生说，你们必须在几号之前完成这个作业，而是会去说，现在让你们做得这个作业里面有我们后面要考的知识点，题目是非常相似的，所以请大家认真按时完成，这样学生们为了在考试中取得一个好成绩，就很认真的把作业积极的完成了。”\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;谢谢这位伙伴。那现在请大家想一想，根据我们刚才讲的把“No”的回答变成“Yes”的技巧，在我们今后的生活中如何运用，要有具体的做法、明确的期限以及可衡量的结果哦。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;好，大家基本上都完成了，我本次的拆书到这里也全部结束了，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1504846630000,"updated_at":1504846630000,"ria":true},{"id":3503,"topic":"学习在沟通的时候让对方的回答从NO变成YES的方法","learn_goal":"学习在沟通的时候让对方的回答从NO变成YES的方法","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"宋福珍（豆豆）","city":"郑州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;亲爱的小伙伴们，非常感谢大家来参与我的1-2练级，豆小燃同学已经分组过了，我们继续沿用这种分组的方式，保证大家更好的参与学习之中。\r\n刚刚的自我介绍，大家对我已经知道了，我再啰嗦一遍，我网名是豆豆，本名宋福珍，宋江的宋，幸福的福，珍贵的珍。\r\n现在我给大家讲个故事，在日本有一个毕业与工科的男士，特别不善言辞，毕业之后再求职找工作的过程中、找到工作之后具体的工作中，遇到了很多的困境。我们也可以想象一下，一个不善言辞的人在现代社会中，会遇到怎么样的困境。他经过多次的失败之后，总结出了沟通的七个突破口和八个技巧，然后他把这七个突破口和八个技巧写成了一本书，叫做《所谓情商高，就是会说话》。这个日本人的名字叫做佐佐木圭一，他现在是日本著名的顶尖的广告设计大师，也是日本定级的写作大师和文案大师。今天我要带大家学习的拆页，就是选自于这本书中的一个技巧：把NO变成YES的技巧。现在，请大家阅读拆页，把NO变成YES的技巧，时间是两分钟，读完的小伙伴可以举手示意给我。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":0,"texts":[{"id":6381,"quote":"\u003cp>步骤1：不直接说出自己的想法\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。当然，我们都是凡人，不可能保证所有事都直接说出来，但至少请记住，不要直接说出“这是很重要的请求”之类的话。\u003c/p>\u003cp>步骤2：揣摩对方的心理\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求做何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“yes”的可能性很大，当然可以直接说……\u003c/p>\u003cp>如果对方回答“no”的可能性很大，就不能直接说了请暂时忘记自己的请求，揣测对方的喜怒、性格等因素。把no变成yes的答案就在其中。\u003c/p>\u003cp>步骤3 考虑符合对方利益的措辞\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点 &nbsp; ，就要基于对方的心理来考虑措辞。 \u003cbr>\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系，即使措辞有所改变，只要最终达到目的就行。\u003c/p>","explains":"\u003cp>生活中我们经常会疑问：为什么被拒绝的总是我？为什么受伤的总是我？被拒绝不是因为我们人品不好，大多数时候是因为我们不会说话，错误的把直接当做了坦率、真诚。所谓情商高，就是说话前会过脑子，不会直接赤裸裸的提出自己的请求、要求。如果我们不过脑子直白的提出请求，我们的要求往往会被别人直接PASS了。而所谓会说话，就是懂得以终为始，懂得根据自己要跟对方沟通的目的来决定自己怎么跟对方表达自己的请求，站在对方的角度上，找到让自己和对方都双赢的表达方式，具体来说：\u003c/p>\u003cp>\u003cstrong>第一步\u003c/strong>是“三思而后说”，想好说什么\u003c/p>\u003cp>\u003cstrong>第二步\u003c/strong>是明确说了的后果是什么：即在说话前对自己的请求可能得到的回应做一个评估，看看对方是否可能答应你。\u003c/p>\u003cp>如果你跟对方是哥们，对方对你向来言听计从，对你是有求必应，这种情况下你可以不考虑措辞。如果你不确定对方一定会同意，你就需要慎重对待，认真揣摩了。如果觉得对方可能不同意，这时候就要斟酌说话的方式。\u003c/p>\u003cp>\u003cstrong>第三步\u003c/strong>是想好怎么说：换位思考，找到你的请求跟对方利益的结合点，然后用符合对方利益的方式进行表达。\u003c/p>\u003cp>\u003cstrong>举个例子\u003c/strong>，我们现在生活节奏都很快，很多人是起床困难户，早餐靠对付，街边的包子油条凑合就是一顿早餐了。我以前住的小区门口，有两个卖烧饼夹菜的，左边门口一个，右边门口一个。烧饼夹菜其实没啥技术含量，都是烧饼夹菜，但是左边的小王就是卖不过右边的小李。具体表现是，小王一天顶多卖出去一筐鸡蛋，但是小李每天差不多卖出去三筐鸡蛋。为什么呢？经过观察我发现，小王是这么问的：“你要不要鸡蛋呀？”我自己有时候一忙就说：我不要了。走了。小李是这儿问的：“你们每天上班这么早多辛苦啊，吃个鸡蛋有营养，你是要煎鸡蛋啊，还是煮鸡蛋呀？”大家想一想，为什么小李为什么会能够卖出鸡蛋呢？这就是因为小李没有直接赤裸裸的问：“你要不要鸡蛋”——他的请求很可能被我们拒绝，然后他换了一种站在我们的角度考虑的方式，用了符合我们利益的表达：“你们上班好辛苦，吃个鸡蛋有营养啊，你要煎鸡蛋还是煮鸡蛋？”\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>通过刚刚的讲解，我们已经清楚了，把“NO”变成“YES”适用于当你的请求可能会被对方拒绝的时候，运用刚刚的三个步骤，能够帮助我们把对方的“NO”变成“YES”，接下来请大家思考一下，在自己之前的经历中有哪些是事情是因为不过大脑提请求被拒绝的，或者自己有见过别人无意识运用了这种技巧的情形、事件，在小组内进行分享。每人分享时间1~2分钟，5分钟后我们选出两个小组进行代表分享。\r\n &nbsp;&nbsp; \u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>\u003c/p>\u003cp>人物：a，a公公，a孩子，先生以及其他家人\u003c/p>\u003cp>背景：a与公公同住，a公公负责家里的食材采购和食物制作。A公公习惯购物同一种类数量很多，然后相当长一段时间饭菜品种就固定为一种，单一，营养不均衡。\u003c/p>\u003cp>时间：今年夏天的一天\u003c/p>\u003cp>事件：为避免长期饭菜品种单一带来的营养不均衡，为a孩子身体健康之目的，a打印了食谱，买了烹饪书籍，跟a公公表达了希望公公做饭能够多元化&nbsp; \u003cbr>\u003c/p>\u003cp>结果：公公很生气，给你们做吃的，你们还挑三挑四的。\u003c/p>\u003cp>学以致用，接下来我们来运用这个把no变成yes的技巧，请大家根据学习到的内容，规划一下未来在生活中的运用，这个运用计划要具体、可操作，结果可评估，可衡量。给大家一分钟时间，写个A2出来 ，先写完的小伙伴可以分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>\u003c/p>\u003cp>A找到了和公公的共同利益：孩子的身体健康。A考虑到公公其实是做饭方面的大拿，什么饭菜都能做，只是因为老人买菜买的品种单一所以做得单一，从符合对方利益的角度切入：“爸爸，您看您天天又是买菜又是做饭的，挺辛苦的。以后卖菜的事儿我们来干吧，您会的花样多，多多（孩子）在您的照顾下，营养均衡，一定能够更健康的。”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1503736637000,"updated_at":1565052594000,"ria":true},{"id":3250,"topic":"最短的时间掌握说话技巧，把“NO”变成“YES”","learn_goal":"让大家学会在更好表达请求，提升得到肯定回答的几率","remark":" 一个人平均每天求人22次，当然，有的请求得到的回答是“YES”，有的则是“NO”。如果使用高明的措辞，哪怕至少每天提高一次说“YES”的机会，持续一年，将比一般人得到更多地365次被同意的经历。这样，足以使你的人生发生改变。\r\n  周四晚上，欢迎参加由拆书帮深圳智荟分舵拆书家程煜带拆的活动，同样的内容，改变请求的说辞，来将得到“YES”回答的可能性提高2-3成，让改变积极发生。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"小煜","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"现在开始我的拆书，我还是给大家做一个自我介绍，强化下大家记忆哈。我是今晚的拆书家，程煜。程咬金的“程”，南唐后主，李煜的“煜”，之前父母大概是寄希望自己能文能武，现在成功的养成了能动能静，能癫痫能瘫痪的状态。非常感谢大家今晚来参加我们的拆书活动。今天晚上呢，我们会有一个小组讨论，小组就按我们现在的1/2/3来进行分组。\r\n今天我跟大家分享的书籍是《所谓情商高，就是会说话》。阅读这本书的起因是一位我很崇拜的人说把它看了三遍，于是我上网一查，据说它是“日本深受欢迎的人际沟通课程”。好奇心的驱使下我阅读完了这本书，确实没有让我失望，里面关于对话的技巧十分实用。这本书非常简洁的分为两大部分，第一部分是在表达请求时，如何把回答的“NO”变成“YES”的几率更高,第二部分是如何创造“名言警句”，分为两个部分，其中提出了7个突破口与5个技巧点。今天我跟大家分享第一部分中，如何把回答的“NO”变成“YES”的几率更高，我会再加一个突破口。所以今晚我会分享在表达请求时的3个步骤，以及更好地应用这个步骤的1个突破口。","ratings_count":0,"texts":[{"id":6084,"quote":"\u003cp>把“NO”的回答变成“YES”,有3个步骤。\u003c/p>\u003cp>\u003cstrong>步骤1：不直接说出自己的想法\u003c/strong>\u003c/p>\u003cp>一般来说人都容易不假思索的把脑中的想法直接说出来，然而这样不仅常常事与愿违，而且容易招致反感。请不要直接说出自己的想法，这是步骤一。\u003c/p>\u003cp>\u003cstrong>例如：\u003c/strong>有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉，在这种时候请不要直接说：\u003cem>“大家继续吃啊”\u003c/em>。\u003c/p>\u003cp>\u003cstrong>步骤2：揣摩对方的心理\u003c/strong>\u003c/p>\u003cp>请揣摩对方的心理，并根据其平时表现，猜测对方会对你的请求作何想法，直接说出请求对方会作何反应。如果待对方回答yes的可能性很大，当然可以直接说。如果对方回答no的可能性很大，就不能直接说了，请暂时忘记自己的请求。揣测对方的喜恶、性格等因素，把“NO”变成“YES”的答案就在其中。\u003c/p>\u003cp>\u003cstrong>例如：\u003c/strong>请试着揣测吃腻了柑橘的家人的心理。\u003cem>“不能光吃柑橘”\u003c/em>，这应该是家人的想法，因此，请再次忘记自己的请求，想想家人的喜恶，例如不想感冒。没有人愿意生病，到了容易感冒的季节，家人都很在意这一点。\u003c/p>\u003cp>\u003cstrong>步骤3：考虑符合对方利益的措辞\u003c/strong>\u003c/p>\u003cp>请提出请求的时候，要让对方的利益和自己的利益趋于一致。想达到这一点，就要基于对方的心理来考虑措辞关键在于要创造符合对方利益的上下文关系，即使措辞有所改变，只要最终达到目的就行了。\u003c/p>\u003cp>\u003cstrong>例如：\u003c/strong>既然家人不想感冒，就可以对他们说\u003cem>“多吃柑橘就不会感冒了”\u003c/em>，这样的措辞符合对方的利益，家人就会变得了一只柑橘，你的目的就达到了。\u003c/p>\u003cp>\u003cstrong>实现3步骤的突破口之：投其所好\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这是最基本的，也是最管用的；\u003c/strong>\u003c/p>\u003cp>\u003cem>“抱歉，这种衬衫只剩这一件了。”\u003c/em>听到店员这样说你会怎么想，可能一下子产生是别人挑剩下的吧，恐怕有很多人试穿过的印象.如果店员换一种说法，例如：\u003cem>“这种衬衫卖的特别快，这是最后一件了”\u003c/em>。你又会怎么想，大概是产生，要是流行我也想买最后一件了，不买就没了的印象。传达同样的内容，使用不同的措辞，对方的接受方式和行为就会发生变化。\u003c/p>\u003cp>店员的目的是希望顾客消费，但不能直接说出来，而是要揣摩顾客的心理，采用投其所好的措辞。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>好的，大家阅读得差不多了。接下来我为大家对原文进行解读。首先我先为大家界定一下我们这个片段所使用的范围和情景，它是在我们要去表达请求时，对方回复“好”而非“不好”的几率的提升。\u003cstrong>我们首先界定这个表达请求是什么？\u003c/strong>在这里我们把希望对方按照自己的想法来实现自己的目标，都算做是表达请求。原文给我们的方法是，\u003cstrong>首先要委婉地表达自己的请求，\u003c/strong>而不是赤裸裸地请求；不能是你直接脱了衣服站在别人前面，可能就把人吓跑了。第二\u003cstrong>是揣摩对方心理\u003c/strong>、他的喜恶、性格；我说什么样的话他可能欣然接受，我说什么样的话是戳到了他的痛点。第三\u003cstrong>是用符合对方利益的角度进行表述，\u003c/strong>让对方感觉我们是站在他的角度进行思考。为了更好地应用这3个步骤，作者在原书中提出了7个突破点，在这里我给大家分享其中最基础也是最实用的一个。\u003c/p>\u003cp>从片段我们可以看到，这个突破点叫做\u003cstrong>“投其所好”\u003c/strong>。顾名思义，就是迎合别人的喜好，站在对方的角度思考问题，戳能让对方可能更开心更能接受的点。比如原文中有举一个例子，店员卖衣服的时候，她的点是，人人都想买到好的，性价比高或者说是相对珍贵的衣服。所以店员在营销的时候说“这种衬衫卖得特别快，只剩最后一件了”而不是“没货了，这种衬衫就这一件”那这样是不是会引导人思考为什么卖得快？是不是大家都认同？是不是因为很好才会卖得这么快？\u003c/p>\u003cp>我给大家举个例子，生活中的例子，比如我\u003cstrong>想约男神吃饭，第一：\u003c/strong>我不能直接提出请求，说“一起吃顿饭吧”;\u003cstrong>第二：\u003c/strong>我会揣摩对方心思，作为男神可能经常受到邀请，他好像喜欢美食，他会不会对美食的追求更高，会不会更喜欢有新意。那\u003cstrong>第三步\u003c/strong>我可以这样说“我看到深圳美食部落新推出了一家餐厅，他的评价非常高，环境设计很有创意，要不要一起去？”我这么贴心地迎合他的请求，这样邀约成功率会不会更高？\u003c/p>\u003cp>当我们表达请求的时候，考虑到“投其所好”，久而久之，和你沟通的人都会觉得你的性格都变好了。所以，自古套路得人心，刚刚给大家分享的是一个如何用套路来提升得到肯定回答的几率。它分为3个步骤，第一：不赤裸裸地提出请求；第二，揣摩对方的心理；第三，从符合对方利益的角度进行表述。另外我们这里有一个突破口叫做“投其所好”。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>那么，请大家思考下，在我们过往的生活中，是怎样给人提出请求的呢？请在组内分享相对比较失败的请求的经历。请注意，这里是过往请求中，一个相对失败的经历。我们提出了请求，却没有达到预期地目的。我给大家4分钟时间，小组完成分享可提前举手示意我。稍后我们请一位小伙伴上台给大家进行分享。\u003c/strong>\u003cstrong>\u003cbr>学习者\u003c/strong>：比较深刻的失败经历是，我爸年纪大了，身体不太好，还是喜欢喝酒。我经常请求他少喝酒甚至戒酒，但是这个请求也有4/5年了，每次和他沟通都比较失败。\u003c/p>\u003cp>\u003cstrong>拆书家回复：\u003c/strong>非常谢谢，这是我们生活中一个比较常见的例子，我希望我们家人在做什么的时候，可能经常由于各种原因不了了之。\u003cbr>\u003cstrong>学习者：\u003c/strong>是出于关怀的目的。\u003cbr>\u003cstrong>拆书家回复：\u003c/strong>对对，出于非常善意的目的。其实这本书呢，不只是介绍了1个点，如果可以的话，您可以阅读下这本书，月就能找到您需要的方法。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>据调查，一个人平均每天需要提出22次请求，请大家思考，在接下来的工作生活中，在需求提出请求的时候，如何运用今天所学的3个步骤和1个技巧，进行一个更好措辞表达呢？麻烦馨裕帮我发下便签纸，给到大家一个模板，麻烦大家花一分钟的时间写在便签上面。模板是：先写时间，第二事件是什么。时间是：我会在什么时候做；然后写事件，这是个什么背景，第三是措辞：我会怎样跟人沟通这个事情。\u003c/p>\u003cp>\u003cstrong>总结：\u003c/strong>看大家都写得非常的认真，由于时间关系，我就不请大家来上台分享了。说话其实不只是一种“感觉”，更是一种“技术”。我们没法一蹴而就，但可以通过不断练习去完善去成长，希望今天的拆书片段对大家有所帮助，之后我们也可以再多多交流，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1500442483000,"updated_at":1500442667000,"ria":true},{"id":3242,"topic":"把“No”变成“Yes”的技巧之“非你不可”","learn_goal":"掌握会说话的技巧","remark":"情商高的人都很会说话，掌握了说话技巧能够更好开拓你的人生，向着自己的梦想更快的迈进。本次介绍的说话技巧很实用，能够更容易的说服别人，让别人同意你的观点，实现想要的结果。这个技巧就是：“非你不可”。主要有三个步骤：1、不直接说出你的想法；2、揣摩对方的心理；3、考虑符合对方利益的措辞。是不是很心动，心动不如行动，赶快来参加吧！","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"追逐1","city":"合肥"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"自我介绍 1min。大家好，我是追逐。今天是我大喜的日子，第一次拆书，然后还有我的入帮仪式，非常激动，也非常高兴。人生有很多美好的事情值得我们去追逐，拆书帮就是其中一个。\r\n我是一名企业内训师，在合肥生活工作，因为工作原因将在北京工作生活一段时间。也正是这次机会让得以参加拆书帮的线下活动，经历了RIA训练营的磨练，完成了两次线下分享活动，终于正式入帮了。\r\n我也算是比较爱读书的人，买了很多书，也看了很多书，但是收获不大，加入拆书帮，是很明智的选择，相信会有很大的收获。\r\n今后我将会和拆书帮的小伙伴一起，拆书、学习、成长，去追逐人生中更多的美好，谢谢。","ratings_count":0,"texts":[{"id":6075,"quote":"\u003cp>下面给大家1分钟的时间阅读拆页，重点理解文章的三个步骤。看完的小伙伴请抬头示意。\u003c/p>","explains":"\u003cp>拆书帮介绍 2min\u003c/p>\u003cp>拆书，是一种读书方法。如何你读书还是一页一页的从头读到尾，当你看到最后一页的时候，能够记住的内容可能非常少。读书本身可以修身养性，但只有把书中的知识用起来，这才是最高效的读书方法。拆书，就是这样一种读书方法，通过拆书学习，甚至可以达到参加几万块培训的效果。拆书提倡将书中的知识关联你的经验，激活你的旧知识，改变你未来的行动，将知识转化为生产力。\u003c/p>\u003cp>拆书帮是一个公益组织，由拆书爱好者组成，在全国很多城市都有分舵。拆书帮里有拆书家和学习者。拆书家正式入帮成为了会员，根据掌握拆书水平的高低分为一级、二级和三级3个级别。学习者是参与拆书活动的参与者。每次活动由拆书家指导学习者进行拆书学习，一起讨论交流练习，共同学习书中的实用知识，帮助学习者改变认知，成为更好的自己。\u003c/p>\u003cp>[R] 1min&nbsp;下面给大家1分钟的时间阅读拆页，重点理解文章的三个步骤。看完的小伙伴请抬头示意。\u003c/p>\u003cp>[I] 3min&nbsp;\u003c/p>\u003cp>从心理学的角度来分析，人是非常自恋的动物，在内心深处都认为自己是独一无二的，在某些方面比其他人做的好。这也是为什么几乎所有的人都喜欢听好话，喜欢戴高帽。如果有人说自己最讨厌别人拍自己马屁，其实不是他真的这么认为，可能是你没有找到合适的角度去拍马屁而已。\u003c/p>\u003cp>今天我们学习的说话技巧—“非你不可”，就是增强别人的被认可欲，让他们感受到独一无二的对待，一定程度上满足他们的虚荣心，这样更容易引发好感，建立信任，双方沟通起来更加顺畅。“非你不可”，就是告诉对方：别人不行，你才是被选中的人。\u003c/p>\u003cp>一般人都喜欢非你不可的特殊感，听到这样的话，会产生优越感，从而乐于回应对方。在商业市场中，很多商家会推出贵宾卡，VIP限量卡，私人定制，甚至私房菜馆、预约服务等等，这些商品的推出都是为了满足客户心底的优越感，而且效果非常好。把这个技巧应用到说话中，同样有效。\u003c/p>\u003cp>&nbsp; &nbsp; 具体操作起来有三个步骤：第一步，想要对方去做某事，不要直接说出来。比如要求别人聚会，不要直接说“去喝酒吧”；第二步，揣摩对方的心理，1是不想参加公司的这种聚会，2如果这个聚会自己是主角，或者自己在聚会中很特别，能受到很多关注，这样就很愿意参加；第三步，考虑符合对方利益的措施，比如“这次聚会你不来就不热闹了，不少同事说只有你去他们才愿意参加”，如果这样说的话对方参加聚会的可能性会非常高。\u003c/p>","interaction":"\u003cp>[A1] 3min\u003c/p>\u003cp>我家里使用很多家电都是在A公司买的。了解到只要符合条件就可以免费更换，我打电话问客服售后维修情况，A公司的客服并没有像下面这样说：“我们会免费为您更换。”\u003c/p>\u003cp>作为客户，如何享受到免费服务已经很开心了，可对方是这样说的“我们只为一直支持本公司的于先生您免费更换。”\u003c/p>\u003cp>听到对方这样说，我就非常开心。原本是对故障投诉，可是客服这样说，反而使我产生了“享受到独一无二的服务”的良好感觉，仿佛只有自己占了便宜，于是感觉A公司确实不错。\u003c/p>\u003cp>这就是沟通中的技巧，让对方感受的特别之处，享受到特别待遇，“非你不可”的突破口就是这么有效。这就是语言的魅力，说对了一句话，可以省去很多麻烦。“攻城为下，攻心为上”，说话一定要说到对方的心里去。\u003c/p>\u003cp>有一次，我把这件事说给同事听，同事则说“我换机器时，对方也是这么说的。”\u003c/p>\u003cp>我就上网查了一下，发现A公司的客服对所有人都这样说的，网上很多人留言“A公司的客服特棒了。”\u003c/p>\u003cp>这个技巧对很多人都有用。在互联网时代，有了好的口碑就会迅速传开，而差评自然也是如此。\u003c/p>\u003cp>&nbsp; &nbsp; 所以卖商品不仅是做广告，营业员和客服的交流沟通能力同样重要。就像海底捞火锅，它的味道肯定不是最好的，但客户对它的评价可能是最高的。因为他们服务很细致，关键是服务员说话也很有技巧。\u003c/p>\u003cp>&nbsp; &nbsp; [A2] 2min\u003c/p>\u003cp>这个说话技巧应用的范围非常广。请大家想一想，以前请同事帮忙，或者约朋友吃饭、逛街、聚会时等，有没有被拒绝的场景。试着用这个技巧可能会有不一样的收获。\u003c/p>\u003cp>举个例子，每次拆书活动，如果我们都会邀请拆书家来做观察者或主持等。以前我们一般会这样做，某某时间开展拆书活动，请大家报名。或者问某位拆书家有没有时间，来参加拆书活动。\u003c/p>\u003cp>如果采用书中的技巧，可以这样说“小明，周四的活动主题你以前也拆过，非常有经验，如果你能来主持肯定会非常精彩。今晚还有张强、王亮等小伙伴在，都非常期待你过去，你不去的话就不热闹了”。如果这样说的话，除非特殊情况，一般都不会拒绝的。\u003c/p>\u003cp>&nbsp; &nbsp; 总结 0.5min\u003c/p>\u003cp>&nbsp; &nbsp; 这就是我本次分享的内容，主要拆解了“非你不可”的说话技巧，有三个步骤，我们一起回顾一下：1、想要对方去做某事，不要直接说出来；2、揣摩对方的心理；3、考虑符合对方利益的措施。希望对大家有帮助，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1500359015000,"updated_at":1500361210000,"ria":true},{"id":3189,"topic":"把NO变成YES的技巧","learn_goal":"学会通过三个步骤，让自己的请求得到更多的YES回答","remark":"","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"吴迪","city":"南京"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"开场：大家好，感谢大家参与我的TF3-2拆书家定级。首先我们作一个分组：我左手边的苏、荣荣和韩菡为第一组，我右手边的青青、佐佑和薏米为第二组。【学习目标】通过本次的RIA带拆，我们可以学会通过三个步骤，让自己的请求得到更多的YES回答。\r\n【图书介绍】\r\n【事件场景】 亲爱的小伙伴们，根据统计，我们平均每天要向别人提出20多次请求，比如帮我带个快餐，帮忙致电一下客户，请加快一下事件的处理流程等等。这其中有的请求会得到肯定答复，而有的则会被拒绝。\r\n【提问】你有没有想过我们的请求能否被答应 其实并不仅仅取决于被请求者？我们自己的言辞也在其中起着很大的作用。\r\n【影响】假设使用高明的措辞，每天至少能把一次“No”的回答变成“Yes”。那么仅以一天来看，或许并没有明显的变化，但这样的情况如果持续一年，就能改变365次，三年就是1000次以上。如果能把以前得到的1000次“No”的回答变成“Yes”，这足以改变我们的人生。\r\n【解决】《所谓情商高，就是会说话》这本书里提供了简明扼要的三个步骤，帮助我们提高请求得到YES回答的几率，每个人都能从中获益，一起来学学吧。","ratings_count":0,"texts":[{"id":6013,"quote":"\u003cp>首先有几道量表题请大家自测一下，每道题最低1分，最高6分。与自己的实际情况越是贴切，分就越高；越是背离呢，分越低。\u003c/p>\u003cp>【A1】量表题\u003c/p>\u003cp>（越符合分越高，1-6分，统计得分）\u003cbr>\u003c/p>\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>量表题讲解：\u003c/p>\u003cp>刚刚的量表题主要是为了测试一下大家有没有意识到 向别人提出请求的结果 其实是由双方共同决定的，以及有没有理解到让别人愿意答应你的请求的关键。\u003c/p>\u003cp>如果你的分数在16分以上，那么今天的课对你一定会有帮助。\u003c/p>\u003cp>下面我给大家3分钟时间，阅读一下我今天的带拆片段。小伙伴们请仔细阅读，看完后给我一个示意。\u003c/p>\u003cp>【R】原文片段\u003c/p>\u003cp>老实说，阅读本书，并不能使以前所有“No”的回答都变成“Yes”，但它确实能提高可能性。根据我的经验，如果原来的可能性为0，那么本书应该能帮助你提高到2～3成；如果原来的可能性为5成，那么本书就能帮助提高到7～8成。\u003c/p>\u003cp>……\u003c/p>\u003cp>一个人平均每天会求人22次。当然，有的请求得到的回答是“Yes”，有的则是“No”。打个比方，假设使用高明的措辞，每天至少能把一次“No”的回答变成“Yes”。那么仅以一天来看，或许并没有明显的变化，但这样的情况如果持续一年，就能改变365次，三年就是1000次以上。如果能把以前得到的1000次“No”的回答变成“Yes”，难道人生还不会改变吗？\u003c/p>\u003cp>……\u003c/p>\u003cp>把“No”的回答变成“Yes”，有3个步骤。\u003c/p>\u003cp>步骤1：“不直接说出自己的想法”\u003c/p>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。这就是步骤1。\u003c/p>\u003cp>当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求！”之类的话。\u003c/p>\u003cp>例如：有人从老家寄来很多柑橘，家人甚至都吃腻了，而你不想让剩下的柑橘白白烂掉。\u003c/p>\u003cp>在这种时候，请不要直接说：\u003c/p>\u003cp>“大家继续吃啊！”\u003c/p>\u003cp>步骤2：“揣摩对方的心理”\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说……\u003c/p>\u003cp>如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把“No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>请试着揣测吃腻了柑橘的家人的心理。\u003c/p>\u003cp>“不能光吃柑橘。”\u003c/p>\u003cp>这应该就是家人的想法。\u003c/p>\u003cp>此时，请再次忘记自己的请求，想想家人的喜恶。例如：\u003c/p>\u003cp>“不想感冒。”\u003c/p>\u003cp>没人愿意生病。\u003c/p>\u003cp>到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>步骤3：“考虑符合对方利益的措辞”\u003c/p>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系。即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>既然家人不想感冒，就可以对他们说：\u003c/p>\u003cp>“多吃柑橘就不会感冒了。”\u003c/p>\u003cp>这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>【I】讲解引导\u003c/p>\u003cp>我们在工作生活中，总是免不了向别人提出请求，除了那些比较小的、别人一定会帮忙的请求；大部分请求我们提出之前并不确定是否能得到肯定回复。有时我们会被拒绝，这时我们往往会归咎于“自己面子不够大”或者“对方现在可能心情不太好”等等原因，但我们有没有想过，只需要改变一下措辞，就能有效地让自己的需求更多地得到肯定答复。\u003c/p>\u003cp>【what】所谓把NO变成YES，就是通过妥善的措辞，提高自己的请求得到肯定答复的几率。\u003c/p>\u003cp>【why】大家可不要小看言辞的力量，运用得好能解决大麻烦。举个例子，在一架航班上，供应两种飞机餐，牛肉和鱼肉。由于之前的乘客大多选择牛肉，导致剩下的大部分是鱼肉了。这时新人空姐如果直接说“对不起，只剩鱼肉了”，乘客就会非常不满意，认为自己被剥夺了选择权，甚至会引发投诉。值此关头，有经验的前辈空姐说：“本机供应以优质香草、富含矿物质的天然岩盐和粗制黑胡椒嫩煎而成的鱼肉，以及普通牛肉”。乘客纷纷选择鱼肉，一场危机消于无形。（举例子）\u003c/p>\u003cp>【how】所以，把NO变成YES\u003c/p>\u003col>\u003cli>\u003cp>不直接说出自己的想法。空姐没有直接说“只有鱼肉了”\u003c/p>\u003c/li>\u003cli>\u003cp>揣摩对方的心理。乘客希望自己有选择权，能享受更好的飞机餐。\u003c/p>\u003c/li>\u003cli>\u003cp>考虑符合对方利益的措辞。“给乘客嫩煎的鱼肉，更好的飞机餐”。\u003c/p>\u003c/li>\u003c/ol>\u003cp>荣荣，请你来说一下这三个步骤之间是什么关系好吗？并列、递进，抑或是因果关系？\u003c/p>\u003cp>（荣荣：应该是递进关系）\u003c/p>\u003cp>对，是递进关系。\u003c/p>\u003cp>这三个步骤应当说是非常的简明扼要的，我想请问一下小伙伴有没有注意到一个关键词。这个词在三个步骤中重复了两次，是哪个词？\u003c/p>\u003cp>（对方）\u003c/p>\u003cp>非常好，有好几位小伙伴异口同声地说出来了——对方。\u003c/p>\u003cp>对了，这正是这三个看似浅显的步骤之中蕴含的深意。只有真正从对方的角度出发，为对方的利益考虑，对方才愿意为你把NO变成YES。\u003c/p>\u003cp>我还想问大家一个问题，片段中的这样的做法，你会觉得是一种不诚恳吗？或者说是算计对方吗？（用提问的方式做异议预防，如果回答是不诚恳，用苏格拉底式提问化解；如果回答不是，顺势详述）\u003c/p>\u003cp>有没有小伙伴想分享一下自己的看法？\u003c/p>\u003cp>我们请韩菡来分享一下。\u003c/p>\u003cp>（韩菡：我觉得不是。这只是换了一种表达，让别人觉得更舒服）\u003c/p>\u003cp>好的，这并不是不诚恳。关键点其实就在于我们刚刚分析的，你的出发点是为了对方，考虑的是对方的利益。\u003c/p>\u003cp>关于这个有一个非常好的例子，苏格拉底和他的学生讨论，问在战场上迷惑敌人是不是正义的。\u003c/p>\u003cp>学生说是正义，但欺骗朋友就不行。\u003c/p>\u003cp>苏格拉底接着问，战争濒临绝境；将领说援军马上就到，因此打了胜仗，但其实没有援军，这是不是正义？\u003c/p>\u003cp>学生说请允许我收回刚刚的话。（笑）\u003c/p>","interaction":"\u003cp>【A3】\u003c/p>\u003cp>亲爱的小伙伴们，通过I环节的分享，相信大家对于“把NO变成YES”都有了一些了解。\u003c/p>\u003cp>下面我给出一个场景，假设你是一家餐厅的值班经理。有一桌有两个淘气的孩子，时不时跑来跑去，大声喧哗甚至于尖叫。一点不考虑别的顾客的感受。她们的妈妈呢也不管。现在有顾客向你提出了抗议，要求出面干涉。\u003c/p>\u003cp>通常的做法是直接跟妈妈说，您的孩子影响到其它顾客了，请让他们回到座位安静地坐下好吗？但可以肯定这没有为孩子的妈妈考虑，所以不是最好的办法，而且得到YES回复的可能性也不能保证，怎样提高肯定答复的可能性呢？\u003c/p>\u003cp>你用刚刚学到的三个步骤，可以怎么做？\u003c/p>\u003cp>下面我想请大家按照之前的分组，考虑一个解决方案。我给大家3分钟的时间，稍后我们请1-2组 代表给大家做一个现场的分享。\u003c/p>\u003cp>好的，我们请薏米来说一下你们这组的解决方案。\u003c/p>\u003cp>薏米：我们的诉求是希望那两位孩子的妈妈把他们带回自己的桌子安静地坐下，按照今天学习的步骤，咱们就不直接说了。（笑）\u003c/p>\u003cp>然后要考虑妈妈的心理，我们这组想到一个妈妈的需求是确保孩子的安全。（吴迪：非常好，抓到了“安全”这个关键词）\u003c/p>\u003cp>所以我们打算这么说：“这位女士您好，你的孩子在过道上跑来跑去；过道呢并不宽敞，而且我们的服务人员上菜也会频繁地经过，有很多菜是刚出锅的，还有一些是热汤。万一洒到您的孩子身上就不好了，您看是不是可以让您的孩子回到桌边呢？这样会比较安全”。\u003c/p>\u003cp>非常好，这个解决方案可以说很完美，对于三个步骤的体现也很到位。感谢薏米的分享。\u003c/p>\u003cp>下面我们进入今天的A2环节。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>【事后复盘的A2】\u003c/p>\u003cp>即使你在理智上认同了应该用三步法提出请求。但由于这不是你的习惯，你还是会忍不住直接提出请求。所以，事后复盘的方法可以帮助你更有效地把这个拆页拆为己用。接下来的两三周里，请你刻意地留心自己向别人提出请求的场景，特别是别人拒绝你的场景，把你的请求记录下来，然后试着想想如果用三步法应该如何做？有机会再作一次尝试。\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>青青：想让女儿帮忙整理书架，如果直接说多半是会被拒绝的。以前也有过失败的例子。\u003c/p>\u003cp>经过考虑之后，这次没有直接说，而是想想女儿有什么需求。她可能希望被尊重，被当作大人。\u003c/p>\u003cp>所以，改变了措辞。说“有一些漫画、童话、绘本、少儿文学都不知道怎么分类呢，也许只有你才能把它们分好类吧？”\u003c/p>\u003cp>果然女儿很开心地来帮忙了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1499956418000,"updated_at":1499956418000,"ria":true},{"id":2846,"topic":"如何将对方“NO\"的回答变成”YES“的回答","learn_goal":"通过三个步骤去说服别人达成自己的目标","remark":"如何将对方“NO\"的回答变成”YES“的回答！这里有三个步骤，第一不直接说出自己的想法第二揣摩对方的心理第三考虑符合对方利益的措辞。","level":"TF1-1","duration":12,"status":0,"type":0,"chaishujia":{"username":"茶舍小语","city":"烟台市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【自我介绍】各位伙伴，你们好！\r\n我是吕守玉，关于我个人，可以用三个关键词来概括：第一个词是阅读：我相信阅读能改变人生，这也是我加入拆书帮的初衷，现在读书已经是我生活中的一部分，每年读书在50本以上。第二个词是写作，业余时间也喜欢写一些自己喜欢东西，作为自己读书的输出，并且与苏平老师合写的《打造有吸引力的学习型社群已经由机械工业出版社出版。第三个词是分享，我现在在一家企业做培训与管理工作，同时也在一个公益性的组织中国培训师沙龙担任轮值CEO\r\n【拆书帮介绍】不知各位伙伴是否有过这样的经历：书看不完，看完了记不住，记住了用不上？怎么办？好，今天我向各位伙伴介绍拆书与拆书帮。\r\n什么是拆书呢？拆书是读书的一种方法，通过这种方法，可以让学习者学以致用，也就是说将书中的知识拆为己用，拆书的一大核心是RIA便签读书法。\r\n什么是拆书帮呢？拆书帮是以学习者为中心，将知识转化为能力，它有两种形式，一种是一个人 拆书帮，自己是学习者，自己是拆书家，另一种是一群人的拆书帮，有一位拆书家，有一群学习者，无论何种形式，都是通过阅读、引导促进、拆为己有三个核心环节将知识转化为能力的.\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":0,"texts":[{"id":5623,"quote":"\u003cp>\u003cstrong>把NO的回答变成“YES”，有三个步骤”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>步骤1\u003c/strong>：不直接说出自己的想法\u003c/p>\u003cp>一般来说，人都是容易不假思索地把脑中的想法直接说出来的，然而，这样不仅常常事与愿违，而且很容易招致反感，请不要直接说出自己的想法，这就是步骤1\u003c/p>\u003cp>\u003cstrong>步骤2\u003c/strong>：揣摩对方的心理\u003c/p>\u003cp>请揣摩对方的心理，并根据其平日里的表现，猜测对方会对你的请求作何想法，直接说出请求，对方会作何反应？如果对方回答YES的可能性大，那当然可以直接说，如果对方回答NO的可能性大，就不能直接说了，请暂时忘记自己的请求，揣测对方的喜恶，性格等因素，把NO变成YES的答案就在其中了\u003c/p>\u003cp>\u003cstrong>步骤3\u003c/strong>：考虑符合对方利益的措辞\u003c/p>\u003cp>提出 的请求要让对方的利益与自己的利益趋于一致，相达到这一点，就要基于对方的考虑措辞\u003c/p>\u003cp>关键在于，要创造符合对方利益的上下文关系，即使措辞有所改变，只要最终达成目的就行。\u003c/p>","explains":"\u003cp>我们知道，在日常的工作与生活当中，我们需要经常向别人提出请求的，有人做过一个统计，一位正常的人一天之中向别人提出的请求平均次数是15次，那么一年之中向别人提出的请求的次数就是五千多次，我们先不讨论这个统计数字准确不准确，但说明了一个问题，那就是向别人提出请求是经常的事，而当你提出请求遭到别人的拒绝也是经常的事，那么怎么能让别人答应你的请求呢？三个步骤：\u003c/p>\u003cp>第一步：不要说出你的真实想法，为什么？你的真实想法与别人的利益没有半毛钱的关系，你表达出真实的想法会引起别人的反感。举个例子，星期天，你到图书馆看书，而一位母亲带着5岁的小男孩也来到了图书馆，那位小男孩特别调皮，在图书馆里跑来跑去，大喊大叫，你是不是感觉这个小男孩真讨厌，它影响了你的学习？这时你如果把你的真实想法说出来，对那位母亲说：你孩子太讨厌了，影响到我的学习了。结果会怎么样？我不说各位伙伴也明白了。好，这就是第一步，不要说出自己真实的想法\u003c/p>\u003cp>第二步：换位思考，揣摩一下对方的心理。我们还以刚才的故事为例，孩子在图书馆跑来跑去，如果你是孩子的母亲，你最担心的是什么？担心孩子摔倒。这就是对方的心理\u003c/p>\u003cp>第三步，从对方的利益出发，提出请求。在刚才的例子中，你可以这样说：图书馆的地面很滑，孩子在这儿跑来跑去，很容易摔倒，你是否让孩子坐下，找一本他喜欢的书让他读。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>\u003c/p>\u003cp>下面谈一下我经历的一件事\u003c/p>\u003cp>太太吃饭很挑食，尤其是对一些她没有吃过的菜肴，常常是敬而远之，上个周的周六，一位朋友送了一些蚕蛹，中午我就做了一道菜，干煸蚕蛹，菜做好后，太太看了看，一点都没有吃，我就对太太说：这么多的蚕蛹，我一个人又吃不了，你不吃会浪费掉的。太太看了我一眼对我说：我是猪呀，你吃剩了的东西让我吃。\u003c/p>\u003cp>现在反思一下，我的请求是让太太吃蚕蛹，不要造成浪费，但我在请求的过程中犯了三个错误，第一直接表达了自己的想法，第二没有揣摩对方的心理，没有考虑到太太喜欢什么，厌恶什么。第三我的请求没有与对方的利益相结合，如果现在复盘的话，我会这样向太太请求：昨天我看了一个讲座，讲座里说人到中年都需要补肾，而补肾的最好食品就是蚕蛹，所以，你要多吃一点.\u003c/p>\u003cp>\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>好，最后一点，谈一下对这个知识点的应用\u003c/p>\u003cp>我所在的公司是为银行提供安保服务的，到6月30号，我们与中国银行的合作合同就要到期了，合同到期后进行下一年度的合同续签，服务费用会增加，增加的原因是人工成本的增长，所以在谈判中我要分三步：\u003c/p>\u003cp>第一步确定自己的真实想法，然后把自己的真实想法隐藏起来，我的想法是要保证我公司的利润，就必需增加服务费，但我不能把自己的真实想法告诉对方.\u003c/p>\u003cp>第二步，揣摩对方的心理。在合同谈判前，我必须先揣摩对方的心理，对方的心理是在保证服务质量的前提下服务费用越低越好。\u003c/p>\u003cp>第三步：在谈判中我的增加服务费的请求必须与对方的利益相关联。所以在谈判中我可以这样提出请求：严格按服务标准提高服务质量是我们双方共同的追求，但如果人工成本不增加，必然会造成员工离职率的增高，而员工的频繁更换必然会造成服务质量的下降，所以为了我们的共同目标，下一年的服务费用经测算会增加10%\u003c/p>\u003cp>好，以上是我今天的分享，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1496819303000,"updated_at":1556800682000,"ria":true},{"id":2475,"topic":"3步骤，让对方的回答从“NO”变成“YES”","learn_goal":"学会说服别人答应请求的3个步骤，降低拒绝的概率","remark":"一个人平均每天会求人22次。有的请求得到的答复是“YES”而有的则是“NO”。与意中人交谈、工作中的简报、家人的日常生活、就业面试等等，在这些人生重要的时刻，利用有效的措辞表达，就很有可能使对方的回答从“NO”变成“YES”!So easy，使用这三个步骤就可以了！ ","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"燕丽娜","city":"北京市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"大家好，我是燕丽娜，今晚我的拆书级别是2-1，拆解的片段来自于书籍《所谓高情商就是好好说话》。在跟随我完成本次RIA现场学习后，大家能够在请求别人时不直接说出自己的想法，而是能够使用符合双方利益一致的措辞来与对方沟通，降低拒绝的概率。\r\n【图书介绍】\r\n《所谓高情商就是好好说话》这本书的作者是佐佐木圭一，是日本顶级沟通专家、广告鬼才、文案写作大师。讲述了修炼说话能力，提高自己的说话水平的策略和方法—— “7个突破口”和“8个技巧”。\r\n这本书是沟通类图书中深受大众喜欢的一本书，也非常畅销，文中列举了非常多的沟通实例，专注实操方法论，很使用。\r\n你有没有用了最真诚的语言表达请求别人帮你做件事情，依然被对方被拒绝的经历？这本书能增加你说服别人答应你请求的成功几率。你知道一篇阅读10W+的文案是怎么做到的吗？这本书能让你掌握“语言的法则”。如果你想自己的演讲打动人心，这本书也能给你很多启发。","ratings_count":0,"texts":[{"id":5183,"quote":null,"explains":"\u003cp>不管我们的能力有多么强大，免不了要请求别人或者拜托别人做某件事情。对方是否能答应你的请求，很大程度上取决于你的措辞，你的语言表达方式，是否能够基于对方的心理，使用符合双方利益一致的措辞来与对方沟通。通过有效的语言表达提高对方答应你的几率。\u003c/p>\u003cp>如果不能用高明的措辞，容易招致对方的反感，让对方答应你请求的可能性就更低了。很多人在请求别人的时候常见的几种措辞都是不妥当的，要么直接说出自己的想法；要么不考虑对方的心理；\u003c/p>\u003cp>比较好的表达请求别人的方法是：\u003c/p>\u003cp>第一步：不把自己的想法或者请求直接说出来\u003c/p>\u003cp>第二步，面对我的请求，思考对方会怎么想？\u003c/p>\u003cp>第三步，使用双方利益一致的语言表达自己的请求\u003c/p>\u003cp>在《快乐飞行》这部电影中，有这样一个片段，某航空公司的新人空姐，在分配供餐的时候犯难了，由于很多乘客选择了牛肉，导致鱼肉大量剩余。经验丰富的前辈就展示了高超的措辞表达技巧，她是这样说的：“机内供应优质香草、富含矿物质的天然岩盐和粗制黑胡椒嫩煎而成的白身鱼，以及普通牛肉”。这样一说，乘客会觉得鱼肉更好吃，果然很多乘客就主动选择了鱼肉。如果直接说出“对不起，只剩下鱼了”，乘客觉得自己成了废品回收站，前辈空姐没有直接这样说，而是在揣摩了对方的心理—希望吃到优质食物，之后使用了双方利益一致的语言表达，甚是高明。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验(显像提问)\u003c/strong>\u003c/p>\u003cp>想想自己在过去的一个月中，你请求别人去做一件事情，因为你措辞不够高明，你说给对方听，对方拒绝了你。也许是请求你的家人让你独自旅行，也许是请求你的同事接受你的方案；也许是拜托他一件事情，当你走到他的面前，表达了你的请求，对方却决绝了，Say NO?具体是什么事情，你当时是怎么说的？你的原话是什么？我们三人一组，请小伙伴分别在组内依次分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>\u003c/p>\u003cp>王玉琼：（邀约小伙伴陪自己去看电影）最近新出了一个电影《速度与激情8》，我们一起去看吧！（对方以不感兴趣为由拒绝了我）\u003c/p>\u003cp>\u003cstrong>【A1+】(反思加工)\u003c/strong>\u003c/p>\u003cp>那么，如果再给你一次重新表达的机会，运用刚刚学到的方法，不直接说出你的想法，思考一下当时对方是怎么想的，这件事情对对方有哪些好处，并基于对方的心理和这些好处编写一段新的说辞。请你们在小组内分享一下，每个人2分钟时间。\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>\u003c/p>\u003cp>王玉琼：小伙伴拒绝和我一起去看《速度与激情8》可能是不了解电影背景，担心不好看。基于这样的分析，利用今天学习的内容，我重新编写的说辞是“《速度与激情》这部电影已经拍摄到第8集了，电影不仅特别精彩，去看看里面的名车也是很好的哦！”\u003c/p>\u003cp>好的，今天很高兴跟小伙伴们分享了关于如何说服对方答应请求的小知识，我们再总结一下说服别人的3步骤，第一步，不把自己的想法直接说出来\u003c/p>\u003cp>第二步，面对我的请求，思考对方会怎么想？\u003c/p>\u003cp>第三步，使用双方利益一致的语言表达自己的请求。希望大家今后可以在工作生活中实践应用起来。那么今天的拆书学习就到这里了。谢谢大家。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1493040754000,"updated_at":1493043094000},{"id":1808,"topic":"好好说话","learn_goal":"学习说话之道","remark":"想知道怎样走入客户的心吗？\r\n想知道如何邀约心仪的异性吗？\r\n一句恰到好处的话语可以将No改成Yes!\r\n会说话更是情商高的表现!\r\n如何把握说话的场合和时机？\r\n如何参透说话的精髓？\r\n让我们一起演练说话之道。","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"植聪","city":"海口市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"大家好，我是木木兔，是一个爱生活爱读书有情调的妹子。今天给大家带来书是《所谓情商高，就是会说话》。这本书告诉我们，说话不只是一种感觉，还可以是一门技术。作者通过自己多年来掌握的语言措辞技巧告诉大家如何修炼说话能力，提高自己的说话水平。本书收录了大量的生活故事，这些故事的主人翁最初都处在无计可施的困境中，然后运用技巧改变措辞，扭转了不利局面。这本书能让我们用最短的时间掌握作者经历过无数次尝试和失败才总结出的说话技巧。","ratings_count":0,"texts":[{"id":4395,"quote":"\u003cp>&nbsp;让No变成Yes的说话技巧\u003c/p>\u003cul>\u003cli>\u003cp>步骤一：“不直接说出自己的想法”\u003c/p>\u003c/li>\u003c/ul>\u003cp>一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。\u003c/p>\u003cul>\u003cli>\u003cp>步骤二：“揣摩对方的心理”\u003c/p>\u003c/li>\u003c/ul>\u003cp>请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。\u003c/p>\u003cp>直接说出请求，对方会作何反应？\u003c/p>\u003cp>如果对方回答Yes的可能性很大，当然可以直接说。\u003c/p>\u003cp>如果对方回答No的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。\u003c/p>\u003cul>\u003cli>\u003cp>步骤三：“考虑符合对方利益的措辞”\u003c/p>\u003c/li>\u003c/ul>\u003cp>提出的请求，要让“对方的利益”和“自己的利益”趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。关键在于，要创造符合对方利益的情景。\u003c/p>","explains":"\u003cp>今天我们学习说话的三个步骤，请大家花一分钟时间阅读片段。\u003c/p>\u003cp>片段告诉我们要想让别人答应我们的要求，我们应该在对方的立场上考虑对方的心理需求，而不是直接说出我们的需求。商家在销售的时候，往往会给商品起一个好听的名字。\u003c/p>\u003cp>&nbsp;一个好的名字会让商品的销量大增，用的就是揣摩消费者心理的方法。比如，圣女果，其实我们都知道它就是一种小番茄。但是番茄虽然好吃，但是卖不价钱，我们不会花十几块钱去买一斤番茄。这个时候，用片段的步骤，不直接说出真相，不能直接说‘小番茄’。第二步揣摩对方心理，水果比蔬菜高级。第三步，起一个好听的名字，‘圣女果’然后把它放在水果店里买。\u003c/p>","interaction":"\u003cp>场景：\u003c/p>\u003cp>小陈在拆书帮遇到了心仪的姑娘小杨，小杨是个很受欢迎的女孩，经常有人请她吃饭，但大都被她拒绝了。小陈一直不知如何开口。现在小陈想单独约小杨共进晚餐。他应该如何邀约呢？利用我们今天学习的三个步骤讨论出小陈邀约的说辞，然后编写剧本进行角色扮演。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1484054234000,"updated_at":1484054234000,"ria":true},{"id":1477,"topic":"把“No”的回答变为“Yes”","learn_goal":"顺利通过3-3","remark":"本书的作者是佐佐木圭一，他是日本顶级的沟通专家。他通过他自己多年来掌握的语言措辞技巧来告诉大家如何修炼说话的能力。书中运用了大量的举例子和事例的方式将说话技巧很巧妙地展示出来。让我们很容易的去掌握。同时，也让我们能够在沟通中，修炼“术”的路上，也渐渐懂得了“道”~让我们一起来兼修“道”与“术”吧！！！\r\n","level":"TF3-2","duration":60,"status":0,"type":0,"chaishujia":{"username":"陈庆","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是陈庆！大家也可以叫我大庆。今天我拆的书籍是《所谓高情商，就是会说话》，这本书通过三个步骤和七个突破口结合大量生活中的事例，让我们能够更好的掌握如何通过措辞技巧达到目的。接下来我用场景法介绍这本书。\r\n【事件场景】身为职场人士的你，每天在工作场所忙忙碌碌，想要去提升自己，希望能通过领导进行交流来发现自己，无奈领导也很忙;身为父母的你，面对孩子的叛逆，想要去引导孩子;身为学生的你，想要去问一位严肃的老师期末考试的范围。等等我们可能遭到别人拒绝的情况。\r\n【提问】当你遇到这类情况，你会如何跟对方去表达呢？表达效果怎么样呢？\r\n 学习者:在反复地思考后，会跟对方说明。效果还不错;直接表达，效果很差！\r\n【影响】其实这类事情对我们的影响还挺大的，因为如果这类事情处理不好，我们就处理不好与孩子之间的关系，不能更好的发现自己。\r\n【解决】这本书通过三个步骤，7种方式夹杂大量生活实例，让我们学会如何通过措辞来扭转被拒绝的局面，使我们的沟通高效。","ratings_count":0,"texts":[{"id":4017,"quote":"\u003cp>\u003cstrong>&nbsp;把“No”的回答变成“Yes”，有3个步骤。\u003c/strong>\u003c/p>\u003cp>&nbsp;步骤1：不直接说出自己的想法。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;一般来说，人都容易不假思索地把脑中的想法直接说出来。然而，这样不仅常常事与愿违，而且很容易招致反感。请不要直接说出自己的想法。当然，我们都是凡人，不可能保证所有事都不直接说出来，但至少请记住，不要直接说出“这是很重要的请求”之类的话。\u003c/p>\u003cp>&nbsp;步骤2:揣摩对方的心理。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;请揣摩对方的心理，并根据其平日表现，猜测对方会对你的请求作何想法。直接说出请求，对方会作何反应？如果对方回答“Yes”的可能性很大，当然可以直接说·····如果对方回答“No”的可能性很大，就不能直接说了。请暂时忘记自己的请求，揣测对方的喜恶、性格等因素。把&quot;No”变成“Yes”的答案就在其中。\u003c/p>\u003cp>&nbsp;步骤3:考虑符合对方利益的措辞。\u003c/p>\u003cp>&nbsp; &nbsp;提出的请求，要让“对方的利益”和自己的利益。趋于一致。想达到这一点，就要基于对方的心理来考虑措辞。关键在于，要创造符合对方利益的上下文关系，即使措辞有所改变，只要最终达成目的就行。\u003c/p>\u003cp>&nbsp; &nbsp;案例:有人从老家寄来很多柑橘，家人基至都吃腻了，而你不想让剩下的柑橘白白烂掉。在这种时候，请不要直接说:“大家继续吃啊!”\u003c/p>\u003cp>&nbsp; &nbsp;请试着揣测吃腻了柑橘的家人的心理。“不能光吃柑橘。&quot;这应该就是家人的想法。此时、请再次忘记自己的请求，想想家人的喜恶。例如:“不想感冒。”没人愿意生病。到了容易感冒的季节，身边就会出现感冒患者，家人都很在意这一点。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;既然家人不想感冒，就可以对他们说&quot;多吃柑橘就不会感冒了。”这样的措辞符合对方的利益，家人就会变得乐意吃柑橘，而你的目的也就达到了。\u003c/p>","explains":"\u003cp>在生活中，我们被他人拒绝的事情实而有之。有时是一些客观的原因，无法避免，但大多时候，被拒绝跟我们的表达是息息相关的。我们往往会急于表达自己内心中的想法，没有将对方放在心中比较重要的位置，从而导致对话中止，而我们的目的又没有达到的情况。而在原文的事例中，通过措辞，达到了让家人吃柑橘的目的。也让我们深刻地体会到了:为对方考虑的重要性大家看了原文之后呢！也知道了把“No”的回答变为“Yes”的三个步骤。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【步骤】\u003c/strong>1.不要直接说出自己的想法。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 2.揣摩对方的心理。【暂时忘掉自己的请求，揣测对方的喜恶，性格等】\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 3.符合对方利益的措辞。【自己和对方利益趋于一致】\u003c/p>\u003cp>这三个步骤体现了“三思而后行”，但是在同时也体现了沟通的根本，\u003cstrong>【互动】\u003c/strong>大家从事例中读懂了沟通的根本吗？哪位小伙伴能为我们说一下沟通的根本？(为对方考虑，尊重)我们能够通过对话，既使对方感到尊重，也能是自己达到目的，何乐而不为呢？\u003c/p>\u003cp>\u003cstrong>【适用范围】\u003c/strong>在我们的生活中，不是每一次的沟通都必须使用把“No”的回答变为“Yes”的三个步骤，在直接表达能够得到别人的肯定回答时，即可直接表达。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>一位男士想邀请一位美女一起吃饭，但因为认识不久，害怕被拒绝。于是他就苦思冥想我怎么做才能请她与我共进美餐呢？他想他不能直接表达，这个女孩子不喜欢路途遥远的地方，还喜欢浪漫，喜欢安静的环境。于是他这样表达的:“最近刚开了一家法国餐厅，评价特别好，且距离这也不远，现在客人也不多，我们一起去吧！”男士对美女表达之后，美女就同意了与他一起共进美餐。\u003c/p>\u003cp>【预防性讲解】你可能会有这样的疑问，每次跟别人通过这三部去表达，多麻烦呀！特别是当场面对面沟通，很有可能沟通不顺畅，因为考虑还需要时间。别担心这个问题，在刚开始我们运用的过程中，可能会比较难。因为还没有形成习惯式的方式，多使用几次就好了。即使在面对面的沟通中，我们也能自如地运用。\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>有人物角色，起因经过结果，对话】接下来进入情景应用，请大家编出一段通过把“no&quot;”的回答变为“Yes”的故事。几百字即可，设计背景，人物，情节变化和当时的对话等，有起因，经过和结果。故事其中要体现出今天我们学习的三部曲。把小故事摘写在一张纸上，时间为六分钟。六分钟后我们请伙伴来分享小故事剧本。\u003c/p>\u003cp>&nbsp; 人物：陈姐和少侠姐\u003c/p>\u003cp>&nbsp; 背景：认识一段时间，邀请已经被拒绝。\u003c/p>\u003cp>&nbsp; 少侠刚入职场，觉得风格相似。想邀请陈姐一起去逛街，但是陈姐说：不确定，我最近挺忙的。了解了少侠说为什么想要一起逛街。\u003c/p>\u003cp>少侠姐说：“陈姐，我最近刚入职场，平时买衣服没有形成风格，你的穿衣风格挺好的，穿衣也挺有范的，想请您给我一些指导。本周六，您有时间吗？”\u003c/p>\u003cp>陈 &nbsp;姐：“本周六有啊！什么时间呢？”\u003c/p>\u003cp>少侠姐：“时间随您！”\u003c/p>\u003cp>陈 姐:“本周六下午2点，钟楼U型地下通道！到时候见！”\u003c/p>\u003cp>少侠姐 ：“一定 一定相约！”\u003c/p>\u003cp>职场人士：本周活动需要你（同事）来主持，但是前面因为轮岗制，本周活动本来不该你来做。\u003c/p>\u003cp>表达如下：“前几周一直由你在策划和主持，这次活动比较重要，你可以借助这次活动来展示自己。我也知道之前你已经工作了一段时间了，你的主持风格和策划能力被大家认可，像政府这样的活动与我们对接，领导会直接出席。你的能力被大家认可，你能作为本次的策划吗？”\u003c/p>\u003cp>“可以！”\u003c/p>\u003cp>“那本周六下午2点相约讨论相关事宜！”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":4018,"quote":"\u003cp>请仔细阅读下列自测题中的每一项，结合自己平时在生活中的表达，给自己打一个分。(1分为很少，6分为很多)，并且给自己算一个总分。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1.我在表达的时候，有替对方着想。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp; 2&nbsp;&nbsp; 3&nbsp;&nbsp; 4&nbsp;&nbsp; 5&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.我在请求别人帮助之时，会主动说谢谢。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp; 2&nbsp;&nbsp; 3&nbsp;&nbsp; 4&nbsp;&nbsp; 5&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.我在和队友或家人发生矛盾时，会用团队意识解决问题。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp; 2&nbsp;&nbsp; 3&nbsp;&nbsp; 4&nbsp;&nbsp; 5&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4.我在跟人交流时，会用封闭式的提问来达到自己谈话的目的。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp; 2&nbsp;&nbsp; 3&nbsp;&nbsp; 4&nbsp;&nbsp; 5&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5.当别人气馁时，我会通过认可别人给别人信心。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp; 2&nbsp;&nbsp; 3&nbsp;&nbsp; 4&nbsp;&nbsp; 5&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>6.我在跟别人沟通时，会强调对方的不可或缺性。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp; 2&nbsp;&nbsp; 3&nbsp;&nbsp; 4&nbsp;&nbsp; 5&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>7.我在警示或请求别人时，会运用对方所担心的达到谈话的目的。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp; 2&nbsp;&nbsp; 3&nbsp;&nbsp; 4&nbsp;&nbsp; 5&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>把“No”变成“Yes”的“7突破口”\u003c/strong>\u003c/p>\u003cp>1.投其所好【店员的目的是“希望顾客消费”，但是不要直接说出来，而是要揣摩顾客的心里。】\u003c/p>\u003cp>x“这种衬衫只剩这一件了。”\u003c/p>\u003cp>@“这种衬衫卖得别快，这是最后一件了。”\u003c/p>\u003cp>2.儆其所恶【明确警示对方:你觉得不错的东西，其实存在着看不见的坏处。】\u003c/p>\u003cp>x“请勿触碰展品。”\u003c/p>\u003cp>0“涂有药品，请勿触。”\u003c/p>\u003cp>3.选择的自由【面对两个乃至更多的选项，一般人都会下意识的做出选择。】\u003c/p>\u003cp>&nbsp;x“要不要来份甜点?”\u003c/p>\u003cp>0&quot;芒果布丁和抹茶冰激凌，您要哪种?”\u003c/p>\u003cp>4.被认可欲【也可以解释为心理学上的“尊重需求”，即“一个人能做出与他人的期待相应的成果”。】\u003c/p>\u003cp>x“你把窗户擦擦!”\u003c/p>\u003cp>0“”你能够到高的地方，能把窗户擦得更亮。拜托了。”\u003c/p>\u003cp>5.非你不可。【让对方乐意，并且感觉不可或缺。】\u003c/p>\u003cp>x“去喝酒吧?”\u003c/p>\u003cp>0“只有你务必得出席啊。”\u003c/p>\u003cp>6.团队化【能使对方产生团队意识，即使是麻烦的请求也会乐于接受他。】\u003c/p>\u003cp>x“你也来组织酒会吧。”\u003c/p>\u003cp>0.“咱们一起组织酒会吧。”\u003c/p>\u003cp>7.感谢【能让对方隐约产生信赖意识，从而难以轻易拒绝】\u003c/p>\u003cp>x“请把这桌子搬走。”\u003c/p>\u003cp>0&quot;请把这桌子搬走。谢谢啊。”\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","explains":"\u003cp>在自测题当中的题目都是与把“No”的回答变为“Yes”的技巧。如果你的得分为(1-24分)，说明你在生活中，运用这些技巧不多，说明你可能需要先了解这些技巧，然后才能更好的加以运用;如果你的得分为(24-35)，说明这些技巧你在生活当中运用次数频繁，但是还需要进一步掌握;如果你的得分为(36-42分)说明这些技巧你已经运用多次。不管你掌握得到底如何，今天我带领大家从一个新的起点开始学习。\u003c/p>\u003cp>\u003cstrong>道和术，道是本质，生活的长期过程中形成的。术：一种方法，我们具体实现的方法。【提问】\u003c/strong>那请大家回忆一下第一个片段三个步骤是什么呢？(1.不要直接说出自己的想法。2.揣摩对方的心理。【暂时忘掉自己的请求，揣测对方的喜恶，性格等。&nbsp; 3.符合对方利益的措辞。【自己和对方利益趋于一致】)这是沟通中的道还是术呢？(这也是术，道是在其中体现的对吗？)第一个片段中的三个方法中也体现了道。揣摩对方的心理，符合对方利益的措辞都是道德体现，那就是为对方着想。基本的是尊重。\u003c/p>\u003cp>那么我们该怎么样去运用原文的方式呢！\u003c/p>\u003cp>【步骤】1.前两个步骤如第一个片段中相同。2.通过适当运用文中方法在措辞中体现出来。\u003c/p>\u003cp>【案例】一个公司开会出勤率很低，新上任的总经理，要求小李和小王认真落实好:后天会议出勤率全员到齐。小李提出了一个点子:给公司全员发短信不仅说明会议地点，会议人员时，而且还提供免费牛排午餐。小王认为这个点子非常好，到后面可以稍微更改:提供免费午餐，黑椒牛排和西凉牛排，你要哪一种？而公司全员也都回复了要吃那种口味的牛排！\u003c/p>\u003cp>这个案例中就运用了拆页中的“选择的自由”，从而使沟通更高效了，小李和小王也能提前更好的向老板汇报了。\u003c/p>\u003cp>可能你会有这样的疑问：哪个方式是最好的？因为大家都想用万能的方法，简单已、易掌握。\u003c/p>\u003cp>如果我们不按照这样的方式去做的话，可能还会存在一定的问题。比方说：你想和一个不太熟悉的人去做什么，但是这个时候用到“我们”可能就不是很适合了，但是在我们与对方是朋友的概况下可能更合适！\u003c/p>\u003cp>适用范围：方式适合你的场景，更适合你的表达。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】\u003c/strong>在我们的工作和学习生活中，你有没有被别人拒绝的情况，这个问题的本质是什么?\u003cbr>\u003c/p>\u003cp>案例:徐贵 乐拆队 &nbsp;和队友交流一起拆书，被拒绝。说是忙，时则不忙。\u003c/p>\u003cp>&nbsp;本质：缺少沟通，没有关心，没有建立很好的关系。\u003c/p>\u003cp>有那些可以解决的方案和思路来改善被别人拒绝的情况?讨论解决的方案。\u003c/p>\u003cp>&nbsp; 徐贵 &nbsp;了解大家的动态，解决他生活中的问题，形成凝聚力，表达中用团队化和非你不可。\u003c/p>\u003cp>\u003cstrong>【A2找人分享】\u003c/strong>请你在未来的一周内找机会跟别人分享【把“No”的回答变为“Yes”】的沟通之法，并且加以举例说明，让对方能更好的理解，分享完最好能加上案例中的问题，让对方运用你分享的方法，寻求案例中解决之法。想想你有哪些点分享，哪些事例能够更有力地证实你的分享。你分享得越多，你掌握得也会越熟练。\u003c/p>\u003cp>&nbsp; &nbsp;现场记录：少侠姐：分享给妈妈，因为与弟弟之间有鸿沟。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 分享道和术：尊重，换位思考的方式，考虑被认可的欲望。家里的男子汉，运用非你不可。多去表达感谢，让他感受温暖。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 学习者：分享给大舅。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 道：从表弟性格出发，让舅舅去了解他。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 术：非你不可，认识到自身的重要性。\u003c/p>\u003cp>【结语】我们既然会对他人提出了请求，就不希望被他人拒绝。因为我们都希望能够达到目的。今天大家通过我的拆解学习了把“no的回答变为“Yes””这一主题，希望大家在遇到可能被他人拒绝的情况下时，能够运用我今天所分享的三个步骤和7种方式。使自己能达到目的同时，也能尊重他人。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}},{"id":4019,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1480428819000,"updated_at":1480428819000,"ria":true}]};